# ═══════════════════════════════════════════════════════════════════════
#  RATE LIMITING — защита от флуда
# ═══════════════════════════════════════════════════════════════════════
import time as _time
from collections import defaultdict as _defaultdict

class RateLimiter:
    """Простой in-memory rate limiter: скользящее окно в 60 секунд."""
    def __init__(self):
        self._msg:  dict = _defaultdict(list)
        self._cb:   dict = _defaultdict(list)

    def _clean(self, store: dict, user_id: int, window: int = 60):
        now = _time.monotonic()
        store[user_id] = [t for t in store[user_id] if now - t < window]

    def check_message(self, user_id: int) -> bool:
        """True = разрешено, False = заблокировано."""
        self._clean(self._msg, user_id)
        if len(self._msg[user_id]) >= RATE_LIMIT_MESSAGES:
            return False
        self._msg[user_id].append(_time.monotonic())
        return True

    def check_callback(self, user_id: int) -> bool:
        self._clean(self._cb, user_id)
        if len(self._cb[user_id]) >= RATE_LIMIT_CALLBACKS:
            return False
        self._cb[user_id].append(_time.monotonic())
        return True

_rate_limiter = RateLimiter()

# Кеш проверок подписки: user_id -> (monotonic_time, subscribed).
# get_chat_member — сетевой запрос к API Telegram, на каждое сообщение его
# дёргать дорого. Кешируем результат на 5 минут.
_subscription_cache: dict = {}
_SUB_CHECK_TTL = 300

async def check_subscription_cached(user_id: int, context, force: bool = False) -> bool:
    now = _time.monotonic()
    cached = _subscription_cache.get(user_id)
    if not force and cached and now - cached[0] < _SUB_CHECK_TTL:
        return cached[1]
    if not (context and context.bot):
        logger.warning(f"check_subscription_cached: нет context.bot, блокируем user={user_id}")
        _subscription_cache[user_id] = (now, False)
        return False
    errors = 0
    member = None
    try:
        member = await context.bot.get_chat_member(chat_id=ADMIN_CHANNEL_ID, user_id=user_id)
    except Exception as e:
        member = None
        errors += 1
        logger.error(f"check_subscription: get_chat_member error user={user_id}: {e}")
    if member is None:
        # Не смогли проверить (бот не админ канала и т.п.) — НЕ пускаем.
        # Кешируем недолго (30 сек), чтобы не дёргать API на каждое сообщение,
        # но чтобы после починки прав подписка быстро заработала.
        logger.warning(f"check_subscription: не удалось проверить user={user_id} — блокируем доступ")
        _subscription_cache[user_id] = (now, False)
        return False
    _subscription_cache[user_id] = (now, member.status in ['member', 'administrator', 'creator'])
    return _subscription_cache[user_id][1]

async def rate_limit_middleware(update, context):
    """PTB pre-процессор: rate limit + проверка подписки на канал."""
    user = update.effective_user
    if not user:
        return
    if update.callback_query:
        logger.info(f"CALLBACK_DATA: {update.callback_query.data!r} user={user.id}")

    # ── Rate limit ──────────────────────────────────────────────────────────
    if update.message:
        if not _rate_limiter.check_message(user.id):
            try:
                await update.message.reply_text(f"{EM_DOT} Слишком много запросов. Подождите немного.")
            except Exception:
                pass
            return
    elif update.callback_query:
        if not _rate_limiter.check_callback(user.id):
            try:
                await update.callback_query.answer(f"{EM_DOT} Слишком быстро — подождите секунду.", show_alert=False)
            except Exception:
                pass
            return

    # ── Проверка подписки на канал ──────────────────────────────────────────
    user_data = db.get_user(user.id)
    if user_data and user_data.get("subscribed"):
        return

    subscribed = await check_subscription(user.id, context)
    if subscribed:
        db.update_user(user.id, subscribed=1)
        return

    # Не подписан — пускаем только /start и кнопку проверки
    cb_data = update.callback_query.data if update.callback_query else ""
    msg_text = update.message.text if update.message else ""

    if msg_text == "/start" or cb_data == "check_subscription":
        return

    if update.callback_query:
        try:
            await update.callback_query.answer("Сначала подпишитесь на канал", show_alert=True)
        except Exception:
            pass
        return

    if update.message:
        ch_url = EMAIL_TG_CHANNEL_URL
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton(EM_ARROW_R + " Подписаться", url=ch_url)],
            [InlineKeyboardButton("✅ Я подписался", callback_data="check_subscription")],
        ])
        try:
            await update.message.reply_text(
                f"Для доступа к боту подпишитесь на наш канал:\n{ch_url}",
                reply_markup=keyboard,
            )
        except Exception:
            pass
        return

