def _safe_cb(prefix: str, text: str) -> str:
    """Обрезает text чтобы prefix+text не превышал 64 байта (лимит Telegram callback_data)."""
    max_bytes = 64 - len(prefix.encode('utf-8'))
    encoded = text.encode('utf-8')
    if len(encoded) <= max_bytes:
        return prefix + text
    return prefix + encoded[:max_bytes].decode('utf-8', errors='ignore')

