# Функция для получения московского времени
def get_moscow_time():
    """Возвращает текущее время в московском часовом поясе"""
    return datetime.now(ZoneInfo('Europe/Moscow'))



def _safe_isoparse(value: str):
    """Парсит ISO-дату, добавляет московский timezone если отсутствует."""
    try:
        dt = datetime.fromisoformat(value)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=ZoneInfo('Europe/Moscow'))
        return dt
    except Exception:
        return datetime.min.replace(tzinfo=ZoneInfo('Europe/Moscow'))


def fmt_date(raw: str) -> str:
    if not raw: return ''
    MONTHS = ['янв','фев','мар','апр','мая','июн','июл','авг','сен','окт','ноя','дек']
    try:
        dt = datetime.strptime(raw[:10], '%Y-%m-%d')
        return f"{dt.day} {MONTHS[dt.month-1]} {dt.year}"
    except Exception:
        return raw[:10]

def fmt_datetime(raw: str) -> str:
    if not raw: return ''
    MONTHS = ['янв','фев','мар','апр','мая','июн','июл','авг','сен','окт','ноя','дек']
    try:
        dt = datetime.strptime(raw[:16].replace('T',' '), '%Y-%m-%d %H:%M')
        return f"{dt.day} {MONTHS[dt.month-1]} {dt.year}, {dt.hour:02d}:{dt.minute:02d}"
    except Exception:
        return raw[:16]

def plural_ads(n: int) -> str:
    if 11 <= n % 100 <= 19: return f"{n} объявлений"
    r = n % 10
    if r == 1:       return f"{n} объявление"
    if 2 <= r <= 4:  return f"{n} объявления"
    return f"{n} объявлений"

def get_anon_id(user_data: dict) -> str:
    """Возвращает @username или имя пользователя"""
    if user_data:
        username = user_data.get('username')
        if username and username.strip('? ') and username not in ('None', ''):
            return f"@{username}"
        first_name = user_data.get('first_name')
        if first_name and first_name.strip('? ') and first_name not in ('None', ''):
            return first_name
        if user_data.get('user_id'):
            return f"ID {user_data['user_id']}"
    return 'Пользователь'

_ANON_CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"  # без похожих 0/O, 1/I

def ensure_anon_id(user_id: int) -> str:
    """
    Возвращает постоянный анонимный код пользователя (вроде "MKSNRT") для
    списка "Мои диалоги" — если его ещё нет, генерирует и сохраняет один
    раз навсегда. Раньше эта колонка нигде не заполнялась, поэтому часть
    диалогов показывала "??????" вместо кода.
    """
    import random
    user_data = db.get_user(user_id)
    existing = (user_data or {}).get('anon_id')
    # У части пользователей в колонке anon_id уже лежит СТАРОЕ значение
    # "??????" — буквальная заглушка, записанная ещё какой-то ранней
    # версией кода до того, как появилась нормальная генерация кода.
    # Раз это непустая строка — простая проверка "if existing" считает её
    # валидной и никогда не перегенерирует, поэтому такие пользователи
    # были обречены показывать "??????" вечно. Явно исключаем этот
    # легаси-плейсхолдер, чтобы для него код всё-таки сгенерировался.
    if existing and existing != '??????':
        return existing

    cursor = db.conn.cursor()
    for _attempt in range(10):
        code = ''.join(random.choices(_ANON_CODE_ALPHABET, k=6))
        cursor.execute("SELECT 1 FROM users WHERE anon_id = ?", (code,))
        if cursor.fetchone() is None:
            try:
                cursor.execute("UPDATE users SET anon_id = ? WHERE user_id = ?", (code, user_id))
                db.conn.commit()
                return code
            except Exception:
                pass
    # Крайне маловероятный случай (10 коллизий подряд) — используем код на
    # основе ID, чтобы хоть что-то стабильное показать вместо "??????"
    fallback = f"U{user_id % 100000}"
    try:
        cursor.execute("UPDATE users SET anon_id = ? WHERE user_id = ?", (fallback, user_id))
        db.conn.commit()
    except Exception:
        pass
    return fallback

# ── Тарифные функции ──────────────────────────────────────────────────────────
_TARIFF_NORMALIZE = {
    'Free': 'Free', 'free': 'Free',
    'Premium': 'Premium', 'premium': 'Premium',
}

def normalize_tariff(raw: str) -> str:
    return _TARIFF_NORMALIZE.get(raw or 'Free', 'Free')

def is_premium(user_id: int) -> bool:
    user = db.get_user(user_id)
    if not user:
        return False
    if normalize_tariff(user.get('tariff', 'Free')) != 'Premium':
        return False
    end_str = user.get('tariff_end_date')
    if not end_str:
        return False
    try:
        end = datetime.fromisoformat(end_str)
        if end > get_moscow_time():
            return True
    except Exception:
        pass
    db.update_user(user_id, tariff='Free', tariff_end_date=None)
    return False

def get_tariff_info(user_id: int) -> dict:
    if is_premium(user_id):
        tariff = 'Premium'
    else:
        tariff = 'Free'
    return {**TARIFFS[tariff], "key": tariff}


def compute_premium_extension(user_id: int) -> str:
    """
    Считает новую дату окончания ПОЛКА ПЛЮС при (продлении) покупке.
    Если у пользователя уже есть активная подписка — новые SUBSCRIPTION_DAYS
    дней добавляются К оставшемуся сроку (реальное продление), а не
    затирают его текущей датой + 30 дней (что раньше происходило и
    выглядело так, будто повторная покупка ничего не даёт при уже активной
    подписке).
    """
    from datetime import timedelta as _td
    base_dt = get_moscow_time()
    try:
        user_row = db.get_user(user_id)
        existing_end_str = user_row.get('tariff_end_date') if user_row else None
        if existing_end_str:
            existing_end_dt = datetime.fromisoformat(existing_end_str)
            if existing_end_dt > base_dt:
                base_dt = existing_end_dt
    except Exception:
        pass
    end_date_dt = base_dt.replace(hour=23, minute=59, second=59) + _td(days=SUBSCRIPTION_DAYS)
    return end_date_dt.isoformat()

def get_daily_enhance_limit(user_id: int) -> int:
    return get_tariff_info(user_id).get('daily_enhance', 1)

# Разовый пробный доступ к Premium-функциям для Free-пользователей.
# feature -> имя колонки в users с флагом "уже использован ли пробник".
TRIAL_FEATURES = {
    "rembg":        "trial_rembg_used",
    "enhance":      "trial_enhance_used",
    "photo_search": "trial_photo_search_used",
    "ai_gen":       "trial_ai_gen_used",
}

def check_and_consume_trial(user_id: int, feature: str) -> bool:
    """
    Если у Free-пользователя ещё не использован пробник конкретной
    Premium-функции — списывает его и возвращает True (можно один раз
    воспользоваться функцией бесплатно). Если пробник уже использован —
    возвращает False, дальше действует обычный лимит тарифа.
    Ничего не проверяет насчёт тарифа — вызывающий код сам решает,
    когда обращаться к пробнику (обычно когда обычный дневной лимит
    уже исчерпан).
    """
    col = TRIAL_FEATURES.get(feature)
    if not col:
        return False
    user_data = db.get_user(user_id)
    if not user_data:
        return False
    if (user_data.get(col) or 0) >= 1:
        return False
    db.update_user(user_id, **{col: 1})
    return True

