def format_date_ru(iso_str: str) -> str:
    """ISO-дата -> "16 августа 2026, 23:59" для человекочитаемых уведомлений."""
    try:
        dt = datetime.fromisoformat(iso_str)
        return f"{dt.day} {_MONTHS_RU_GENITIVE[dt.month - 1]} {dt.year}, {dt.strftime('%H:%M')}"
    except Exception:
        return iso_str

