def fmt_rub(amount) -> str:
    ""f"12345 {EM_ARROW_R} '12 345'"""
    try:
        return f"{int(amount):,}".replace(",", "\u00a0")
    except (TypeError, ValueError):
        return str(amount)

def _strip_cat(cat: str) -> str:
    return cat.lstrip(chr(183)).lstrip(chr(46)).strip()

def format_ad_caption(ad: dict) -> str:
    title = _html.escape(ad.get('title', '') or '')
    desc = _html.escape(ad.get('description', '') or '')
    price = ad.get('price', 0) or 0
    condition = ad.get('condition', '')
    city = _html.escape(ad.get('city', '') or '')
    category = _strip_cat(_html.escape(ad.get('category', '') or ''))
    delivery = ad.get('delivery', '')

    lines = [f"<b>{title}</b>", ""]
    if desc:
        lines.append(f"{desc}")
        lines.append("")
    if price:
        lines.append(f"<b>{fmt_rub(price)} \u20bd</b>")
    if condition:
        lines.append(f"{EM_DOT} Состояние: {condition}")
    if category:
        lines.append(f"{EM_DOT} Категория: {category}")
    if city:
        lines.append(f"{EM_DOT} {city}")
    if delivery:
        lines.append(f"{EM_DOT} Доставка: {'есть' if delivery == 'yes' else 'нет'}")
    lines.append("")
    return "\n".join(lines)

async def safe_answer(query, text: str = "", show_alert: bool = False):
    """query.answer() с игнором ошибки истёкшего timeout (>10 сек или двойной вызов)."""
    try:
        await query.answer(text, show_alert=show_alert)
    except Exception as _e:
        if "query" not in str(_e).lower() and "timeout" not in str(_e).lower() and "invalid" not in str(_e).lower():
            raise

async def safe_edit_message(query, text, keyboard=None, parse_mode=ParseMode.HTML):
    """Безопасное редактирование сообщения с проверкой типа"""
    try:
        if query.message.photo:
            await query.message.delete()
            if keyboard:
                await query.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=parse_mode)
            else:
                await query.message.reply_text(text, parse_mode=parse_mode)
        else:
            if keyboard:
                await query.edit_message_text(text=text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=parse_mode)
            else:
                await query.edit_message_text(text=text, parse_mode=parse_mode)
    except Exception as e:
        logger.error(f"Ошибка при редактировании сообщения: {e}")
        if keyboard:
            await query.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=parse_mode)
        else:
            await query.message.reply_text(text, parse_mode=parse_mode)

async def safe_edit_caption(query, caption, keyboard=None):
    """Безопасное редактирование подписи к фото"""
    try:
        if query.message.photo:
            if keyboard:
                await query.edit_message_caption(caption=caption, reply_markup=InlineKeyboardMarkup(keyboard))
            else:
                await query.edit_message_caption(caption=caption)
        else:
            # Если нет фото, редактируем текст
            if keyboard:
                await query.edit_message_text(text=caption, reply_markup=InlineKeyboardMarkup(keyboard))
            else:
                await query.edit_message_text(text=caption)
    except Exception as e:
        logger.error(f"Ошибка при редактировании подписи: {e}")
        # В случае ошибки отправляем новое сообщение
        if keyboard:
            await query.message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard))
        else:
            await query.message.reply_text(caption)


