def generate_verification_code(length: int = 6) -> str:
    import secrets
    return str(secrets.randbelow(10 ** length)).zfill(length)

# Баннер-шапка письма и иконки соцсетей для футера.
# Всё встраивается в письмо как inline-вложения (Content-ID), а не как внешние
# ссылки на картинки — так они гарантированно видны во всех почтовых
# клиентах, включая те, что блокируют подгрузку внешних изображений.
_EMAIL_ASSETS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets")
_EMAIL_BANNER_CID = "polka_banner"
_EMAIL_SOCIAL_TG_CID = "social_telegram"
_EMAIL_SOCIAL_MAX_CID = "social_max"
_email_asset_cache: Dict[str, bytes] = {}

def _load_email_asset(filename: str) -> Optional[bytes]:
    if filename not in _email_asset_cache:
        path = os.path.join(_EMAIL_ASSETS_DIR, filename)
        try:
            with open(path, "rb") as f:
                _email_asset_cache[filename] = f.read()
        except Exception as e:
            logger.warning(f"Не удалось загрузить изображение письма ({path}): {e}")
            _email_asset_cache[filename] = b""
    return _email_asset_cache[filename] or None

def _load_email_banner() -> Optional[bytes]:
    return _load_email_asset("polka_banner.jpg")

