# ── Поисковые утилиты ─────────────────────────────────────────────────────────

_TRANSLIT_RU_EN = {
    'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e',
    'ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m',
    'н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u',
    'ф':'f','х':'h','ц':'ts','ч':'ch','ш':'sh','щ':'sch',
    'ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya',
}

_TRANSLIT_EN_RU = {
    'a':'а','b':'б','c':'к','d':'д','e':'е','f':'ф','g':'г',
    'h':'х','i':'и','j':'дж','k':'к','l':'л','m':'м','n':'н',
    'o':'о','p':'п','q':'к','r':'р','s':'с','t':'т','u':'у',
    'v':'в','w':'в','x':'кс','y':'й','z':'з',
}


def _stem_ru(word: str) -> str:
    """
    Простой стеммер для русских слов — обрезает падежные/глагольные окончания.
    Позволяет «ноутбуки» → «ноутбук», «кроссовки» → «кроссовк» и т.д.
    """
    if len(word) < 5:
        return word
    # Упорядочены по убыванию длины — жадный захват
    suffixes = [
        'ающего','ующего','ающему','ующему',
        'ающих','ующих','ающим','ующим',
        'ающий','ующий','ающая','ующая',
        'ающие','ующие','ающую','ующую',
        'овать','евать','ивать','ывать',
        'ающий','ующий','ьного','ьному',
        'ьными','ьными',
        'ением','аниям','аниях',
        'ьного','ьному',
        'овых','евых','ами','ями','ого','его','ому','ему',
        'ым','им','ых','их','ую','юю','ая','яя','ые','ие',
        'ий','ый','ей','ам','ям','ах','ях','ой',
        'ть','ет','ут','ют','ят','ат',
        'ил','ила','или','ило',
        'ов','ев','ом','ах','ам',
        'ок','ек','ик',
        'ка','ки','ку','ке',
        'а','и','е','у','ю','я',
    ]
    for sfx in sorted(suffixes, key=len, reverse=True):
        if word.endswith(sfx) and len(word) - len(sfx) >= 3:
            return word[:-len(sfx)]
    return word


def _levenshtein(a: str, b: str) -> int:
    """Расстояние Левенштейна (только для коротких слов, быстро)."""
    if abs(len(a) - len(b)) > 2:
        return 99
    if len(a) < len(b):
        a, b = b, a
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a):
        curr = [i + 1]
        for j, cb in enumerate(b):
            curr.append(min(prev[j + 1] + 1, curr[j] + 1,
                            prev[j] + (0 if ca == cb else 1)))
        prev = curr
    return prev[-1]


def _normalize_query(q: str) -> list:
    """
    Возвращает список поисковых термов для запроса q:
    - исходный запрос целиком
    - транслитерация (ru→en и en→ru)
    - все слова по отдельности
    - стемминг каждого слова (русские окончания)
    - синонимы из SEARCH_SYNONYMS (для слова и его стема)
    - транслитерация каждого слова
    Убирает стоп-слова и слова короче 2 символов.
    """
    STOP_WORDS = {'в','на','с','из','по','за','к','у','о','и','а','но','не',
                  'это','то','для','при','как','так','что','или','от','до',
                  'за','из','под','над','без','между','через','про','со'}

    q = q.lower().strip()
    if not q:
        return []

    terms = set()
    terms.add(q)

    # Транслитерация ru→en
    t_en = q
    for ru, en in _TRANSLIT_RU_EN.items():
        t_en = t_en.replace(ru, en)
    if t_en != q:
        terms.add(t_en)

    # Транслитерация en→ru
    t_ru = q
    for en, ru in _TRANSLIT_EN_RU.items():
        t_ru = t_ru.replace(en, ru)
    if t_ru != q:
        terms.add(t_ru)

    # Отдельные слова запроса
    words = [w for w in q.split() if len(w) >= 2 and w not in STOP_WORDS]
    for word in words:
        terms.add(word)

        # Синонимы исходного слова
        if word in SEARCH_SYNONYMS:
            terms.update(SEARCH_SYNONYMS[word])

        # Стемминг
        stem = _stem_ru(word)
        if stem != word and len(stem) >= 3:
            terms.add(stem)
            # Синонимы стема
            if stem in SEARCH_SYNONYMS:
                terms.update(SEARCH_SYNONYMS[stem])

        # Транслитерация слова
        w_en = word
        for ru, en in _TRANSLIT_RU_EN.items():
            w_en = w_en.replace(ru, en)
        if w_en != word:
            terms.add(w_en)
            # Синонимы транслитерации
            if w_en in SEARCH_SYNONYMS:
                terms.update(SEARCH_SYNONYMS[w_en])

    # Убираем пустые и слишком короткие
    return [t for t in terms if len(t) >= 2]


def _build_fts_conditions(search_terms: list) -> tuple:
    """
    Строит SQL WHERE условия и параметры для поиска по нескольким термам.
    Возвращает (conditions_list, params_list).
    Использует search_index для основного поиска (быстро) +
    title для точных совпадений (релевантность).
    Каждый терм ищется с LIKE '%term%' — это покрывает подстроки (айфон → айфоны).
    """
    conditions = []
    params = []
    for term in search_terms:
        like = f"%{term}%"
        conditions.append(
            "(search_index LIKE ? OR title LIKE ?)"
        )
        params.extend([like, like])
    return conditions, params


def _build_fts_match_score_sql(search_terms: list, table_alias: str = "") -> tuple:
    """
    Дополнительное выражение для подсчёта кол-ва совпавших термов (relevance score).
    Чем больше термов совпало — тем выше в выдаче.
    Возвращает (score_sql, params_list).
    """
    prefix = f"{table_alias}." if table_alias else ""
    parts = []
    params = []
    for term in search_terms:
        like = f"%{term}%"
        # +2 если совпало в title, +1 если только в search_index
        parts.append(
            f"(CASE WHEN {prefix}title LIKE ? THEN 2 ELSE 0 END + "
            f"CASE WHEN {prefix}search_index LIKE ? THEN 1 ELSE 0 END)"
        )
        params.extend([like, like])
    if not parts:
        return "0", []
    return "(" + " + ".join(parts) + ")", params

