# ═══════════════════════════════════════════════════════════════════════
#  MAX PLATFORM API — кросс-постинг в месенджер Макс
# ═══════════════════════════════════════════════════════════════════════

class MaxClient:
    """Лёгкий клиент для MAX API (отправка сообщений/фото в каналы MAX)."""
    def __init__(self, token: str):
        self.token = token
        self.api_base = MAX_API_BASE.rstrip("/")
        self._session: Optional[aiohttp.ClientSession] = None

    async def _get_session(self) -> aiohttp.ClientSession:
        if self._session is None or self._session.closed:
            self._session = aiohttp.ClientSession(
                headers={"Authorization": self.token},
                connector=aiohttp.TCPConnector(ssl=False),
            )
        return self._session

    @staticmethod
    def _normalize_response(resp) -> dict:
        """
        Реальный ответ MAX API НЕ содержит поля "ok" (это не Telegram) —
        либо голый объект результата, либо {"result": ...}, либо ошибка
        вида {"code": ..., "message": ...}. Раньше _request отдавал сырой
        ответ как есть, а все send_* методы проверяли resp.get("ok") —
        которого там никогда не было, поэтому проверка успеха ВСЕГДА
        была ложной, даже когда сообщение реально доходило до MAX.
        Логика 1-в-1 повторяет уже проверенную _normalize_response из
        max_compat.py.
        """
        if resp is None:
            return {"ok": False, "error": "empty response"}
        if isinstance(resp, dict):
            if "ok" in resp:
                return resp
            if "error" in resp:
                return {"ok": False, "error": resp["error"]}
            if "result" in resp:
                return {"ok": True, **resp}
            if "code" in resp and "message" in resp and "result" not in resp:
                return {"ok": False, "error": f"{resp['code']}: {resp['message']}"}
            return {"ok": True, "result": resp}
        return {"ok": True, "result": resp}

    async def _request(self, method: str, path: str, **kwargs) -> dict:
        session = await self._get_session()
        url = f"{self.api_base}{path}"
        async with session.request(method, url, **kwargs) as r:
            try:
                raw = await r.json()
            except Exception:
                raw = {"error": await r.text()}
            result = self._normalize_response(raw)
            # Раньше ошибки от MAX API нигде не логировались — при сбое
            # (неверный токен, неверный chat_id/user_id, лимиты и т.п.)
            # запрос просто "тихо" возвращал falsy результат без единой
            # строчки в логах, из-за чего кросс-постинг TG→MAX было
            # невозможно диагностировать даже по логам.
            if r.status != 200 or result.get("ok") is False:
                logger.warning(f"MaxClient: {method} {path} -> HTTP {r.status}, raw={raw}, normalized={result}")
            return result

    def _resolve_chat_params(self, chat_id) -> dict:
        cid = str(chat_id)
        # ID каналов/групп в MAX (как и в Telegram) — отрицательные числа,
        # например MAX_CHANNEL_ID="-76101625559782". Раньше сюда попадал
        # только случай с "@username", а отрицательный числовой ID канала
        # уходил как user_id — из-за этого кросс-постинг объявлений
        # из TG в канал MAX молча не работал (MAX API не находил такого
        # "пользователя"). Логика приведена в соответствие с проверенной
        # реализацией в max_compat.py (_chat_params).
        if cid.startswith("@") or cid.startswith("-"):
            return {"chat_id": cid.lstrip("@")}
        return {"user_id": cid}

    def _make_attachments(self, reply_markup) -> list:
        """Конвертирует InlineKeyboardMarkup в MAX attachments."""
        if reply_markup is None:
            return []
        data = reply_markup.to_dict() if hasattr(reply_markup, "to_dict") else reply_markup
        ikb = data.get("inline_keyboard")
        if not ikb:
            return []
        buttons = []
        for row in ikb:
            max_row = []
            for btn in row:
                if "url" in btn:
                    max_row.append({"type": "link", "text": btn["text"], "url": btn["url"]})
                else:
                    cb = btn.get("callback_data", "")
                    if isinstance(cb, str):
                        cb = cb.encode("utf-8")[:64].decode("utf-8", errors="ignore")
                    max_row.append({"type": "callback", "text": btn["text"], "payload": cb})
            buttons.append(max_row)
        return [{"type": "inline_keyboard", "payload": {"buttons": buttons}}]

    async def upload_photo(self, photo_data: bytes, filename: str = "image.jpg") -> Optional[dict]:
        resp = await self._request("POST", f"/uploads?type=image")
        upload_result = resp.get("result") if isinstance(resp.get("result"), dict) else resp
        upload_url = upload_result.get("url") if isinstance(upload_result, dict) else None
        if not upload_url:
            return None
        session = await self._get_session()
        form = aiohttp.FormData()
        form.add_field("data", photo_data, filename=filename)
        try:
            async with session.post(upload_url, data=form, timeout=aiohttp.ClientTimeout(total=30)) as r:
                if r.status >= 400:
                    return None
                return await r.json()
        except Exception:
            return None

    async def send_message(self, chat_id, text: str, parse_mode: str = None, reply_markup=None) -> Optional[int]:
        attachments = self._make_attachments(reply_markup)
        body = {"text": text}
        if parse_mode and parse_mode.lower() == "html":
            body["format"] = "html"
        if attachments:
            body["attachments"] = attachments
        body = _strip_none(body)
        params = self._resolve_chat_params(chat_id)
        resp = await self._request("POST", "/messages", json=body, params=params)
        if resp.get("ok") and resp.get("result"):
            return resp["result"].get("message_id") or resp["result"].get("id")
        return None

    async def delete_message(self, chat_id, message_id) -> bool:
        """Удаляет сообщение в MAX (используется при снятии/удалении
        объявления, кросс-опубликованного из TG в канал MAX)."""
        params = self._resolve_chat_params(chat_id)
        resp = await self._request("DELETE", f"/messages/{message_id}", params=params)
        return resp.get("ok", False)

    async def get_channel_messages(self, chat_id, limit: int = 50) -> Optional[list]:
        """Возвращает последние сообщения канала MAX: GET /messages.
        Нужен для поиска поста объявления по заголовку, когда
        max_channel_message_id не сохранился в БД при публикации."""
        params = self._resolve_chat_params(chat_id)
        params["limit"] = max(int(limit), 1)
        resp = await self._request("GET", "/messages", params=params)
        if resp.get("ok") and resp.get("result"):
            arr = resp["result"]
            if isinstance(arr, dict):
                arr = arr.get("messages", [])
            return arr if isinstance(arr, list) else None
        return None

    async def get_message(self, chat_id, message_id) -> Optional[dict]:
        """Возвращает сообщение MAX по его mid (например mid.ffff...).
        Используется для чтения реальных просмотров поста (stat.views)."""
        params = self._resolve_chat_params(chat_id)
        resp = await self._request("GET", f"/messages/{message_id}", params=params)
        if resp.get("ok") and resp.get("result"):
            return resp["result"]
        return None

    async def send_photo(self, chat_id, photo_data: bytes, caption: str = None,
                         parse_mode: str = None, reply_markup=None) -> Optional[int]:
        uploaded = await self.upload_photo(photo_data)
        if not uploaded:
            return None
        attachments = [{"type": "image", "payload": uploaded}]
        rm_att = self._make_attachments(reply_markup)
        if rm_att:
            attachments.extend(rm_att)
        body = {"text": caption or "", "attachments": attachments}
        if parse_mode and parse_mode.lower() == "html":
            body["format"] = "html"
        body = _strip_none(body)
        params = self._resolve_chat_params(chat_id)
        resp = await self._request("POST", "/messages", json=body, params=params)
        if resp.get("ok") and resp.get("result"):
            return resp["result"].get("message_id") or resp["result"].get("id")
        return None

    async def send_media_group(self, chat_id, photos_data: list, caption: str = None,
                               parse_mode: str = None, reply_markup=None) -> Optional[int]:
        all_attachments = []
        for photo_data in photos_data:
            uploaded = await self.upload_photo(photo_data)
            if uploaded:
                all_attachments.append({"type": "image", "payload": uploaded})
        if not all_attachments:
            return await self.send_message(chat_id, caption or "", parse_mode, reply_markup)
        rm_att = self._make_attachments(reply_markup)
        if rm_att:
            all_attachments.extend(rm_att)
        body = {"text": caption or "", "attachments": all_attachments}
        if parse_mode and parse_mode.lower() == "html":
            body["format"] = "html"
        body = _strip_none(body)
        params = self._resolve_chat_params(chat_id)
        resp = await self._request("POST", "/messages", json=body, params=params)
        if resp.get("ok") and resp.get("result"):
            return resp["result"].get("message_id") or resp["result"].get("id")
        return None

max_client: Optional[MaxClient] = MaxClient(MAX_BOT_TOKEN) if MAX_BOT_TOKEN else None

# ═══════════════════════════════════════════════════════════════════════
#  CRYPTO BOT API — автоматическая оплата криптой через @CryptoBot
# ═══════════════════════════════════════════════════════════════════════

import aiohttp as _aiohttp

class CryptoBotAPI:
    """
    Обёртка над Crypto Pay API (https://pay.crypt.bot/api).
    Документация: https://help.crypt.bot/crypto-pay-api
    """
    BASE_URL = "https://pay.crypt.bot/api"

    def __init__(self, token: str):
        self.token   = token
        self.headers = {"Crypto-Pay-API-Token": token}

    async def get_me(self) -> dict:
        """Проверяет токен и возвращает информацию о приложении."""
        async with _aiohttp.ClientSession() as s:
            async with s.get(f"{self.BASE_URL}/getMe", headers=self.headers) as r:
                return await r.json()

    async def create_invoice(
        self,
        amount: float,
        asset: str = "USDT",
        description: str = "",
        payload: str = "",
        paid_btn_name: str = "callback",
        paid_btn_url: str  = "",
        expires_in: int    = 3600,        # счёт живёт 1 час
    ) -> dict:
        """
        Создаёт платёжный счёт. Возвращает словарь с ключами:
            result.invoice_id, result.pay_url, result.status, ...
        """
        body = {
            "asset":          asset,
            "amount":         f"{amount:.2f}",
            "description":    description,
            "payload":        payload,
            "paid_btn_name":  paid_btn_name,
            "allow_comments": False,
            "allow_anonymous": True,
            "expires_in":     expires_in,
        }
        if paid_btn_url:
            body["paid_btn_url"] = paid_btn_url
        async with _aiohttp.ClientSession() as s:
            async with s.post(
                f"{self.BASE_URL}/createInvoice",
                headers=self.headers,
                json=body,
            ) as r:
                return await r.json()

    async def get_invoice(self, invoice_id: int) -> dict:
        """Возвращает статус конкретного счёта (active / paid / expired)."""
        async with _aiohttp.ClientSession() as s:
            async with s.get(
                f"{self.BASE_URL}/getInvoices",
                headers=self.headers,
                params={"invoice_ids": str(invoice_id)},
            ) as r:
                return await r.json()

    async def set_webhook(self, url: str) -> dict:
        """Регистрирует URL вебхука для уведомлений об оплате."""
        async with _aiohttp.ClientSession() as s:
            async with s.post(
                f"{self.BASE_URL}/setWebhook",
                headers=self.headers,
                json={"url": url},
            ) as r:
                return await r.json()


# Глобальный экземпляр (используется по всему файлу)
crypto_bot_api: Optional[CryptoBotAPI] = (
    CryptoBotAPI(CRYPTO_BOT_TOKEN) if CRYPTO_BOT_TOKEN else None
)


def _get_usdt_price(plan: str, discount: int, rub_price: int) -> float:
    """
    Возвращает сумму в USDT для счёта.
    Порядок приоритетов:
    Возвращает сумму в USDT для счёта через курс CRYPTO_RUB_TO_USDT.
    """
    return round(rub_price * CRYPTO_RUB_TO_USDT, 2)


async def create_crypto_invoice(
    user_id: int,
    plan: str,
    tariff_label: str,
    rub_price: int,
    discount: int = 0,
    promo_code: str = "",
    asset: str = "USDT",
) -> Optional[dict]:
    """
    Создаёт счёт в Crypto Bot и сохраняет в таблицу crypto_invoices.
    rub_price — уже итоговая цена (после скидки).
    Возвращает dict с ключами invoice_id, pay_url, amount_usdt — либо None при ошибке.
    """
    if not crypto_bot_api:
        return None
    try:
        usdt_amount = _get_usdt_price(plan, discount, rub_price)
        promo_note  = f" (промокод {promo_code} −{discount}%)" if promo_code and discount else ""
        payload_str = f"{user_id}:{plan}:{tariff_label}:{rub_price}:{promo_code}"
        desc        = f"Подписка Полка — {tariff_label} ({rub_price} ₽){promo_note}"

        resp = await crypto_bot_api.create_invoice(
            amount      = usdt_amount,
            asset       = asset,
            description = desc,
            payload     = payload_str,
            paid_btn_name = "callback",
            paid_btn_url  = f"{SERVER_URL}/cryptobot/paid",
        )

        if not resp.get("ok"):
            logger.error(f"CryptoBot createInvoice error: {resp}")
            return None

        result  = resp["result"]
        inv_id  = result["invoice_id"]
        pay_url = result["pay_url"]
        created = get_moscow_time().isoformat()

        cursor = db.conn.cursor()
        cursor.execute(
            """INSERT OR REPLACE INTO crypto_invoices
               (invoice_id, user_id, plan, tariff, amount_rub, amount_crypto,
                asset, status, payload, pay_url, promo_code, promo_discount, created_at)
               VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (inv_id, user_id, plan, tariff_label, rub_price,
             str(usdt_amount), asset, "active", payload_str,
             pay_url, promo_code or "", discount, created),
        )
        db.conn.commit()
        return {"invoice_id": inv_id, "pay_url": pay_url, "amount_usdt": usdt_amount}
    except Exception as e:
        logger.error(f"create_crypto_invoice error: {e}", exc_info=True)
        return None


