    # ========== МЕТОДЫ ДЛЯ ПРОМОКОДОВ ==========
    
    def create_promocode(self, code: str, discount: int, duration: int, max_uses: int, expires_at: str = None, service_type: str = 'all'):
        """Создание нового промокода. service_type: 'all', 'sub', 'pin'"""
        cursor = self.conn.cursor()
        try:
            cursor.execute('''
                INSERT INTO promocodes (code, discount_percent, duration_days, max_uses, created_at, expires_at, is_active, service_type)
                VALUES (?, ?, ?, ?, ?, ?, 1, ?)
            ''', (code.upper(), discount, duration, max_uses, get_moscow_time().isoformat(), expires_at, service_type))
            self.conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False
    
    def get_promocode(self, code: str):
        """Получение промокода. Проверяет активность, срок и лимит использований."""
        try:
            cursor = self.conn.cursor()
            cursor.execute('''
                SELECT p.id, p.code, p.discount_percent, p.duration_days, p.max_uses,
                       COUNT(pu.id) AS current_uses, p.expires_at, p.is_active
                FROM promocodes p
                LEFT JOIN promocode_uses pu ON pu.promocode_id = p.id
                WHERE p.code = ? AND p.is_active = 1
                GROUP BY p.id
            ''', (code.upper(),))
            result = cursor.fetchone()
        except sqlite3.OperationalError as e:
            logger.warning(f"Таблица promocodes отсутствует: {e}")
            self.create_tables()
            return None

        if not result:
            return None

        promo_dict = dict(result)

        # Проверка срока действия
        if promo_dict['expires_at']:
            try:
                expires_dt = datetime.fromisoformat(promo_dict['expires_at'])
                now = get_moscow_time()
                expires_naive = expires_dt.replace(tzinfo=None) if expires_dt.tzinfo else expires_dt
                now_naive    = now.replace(tzinfo=None) if now.tzinfo else now
                if now_naive > expires_naive:
                    return None
            except Exception:
                pass

        # Проверка лимита использований (реальный счётчик из JOIN)
        if promo_dict['current_uses'] >= promo_dict['max_uses']:
            return None

        return promo_dict
    
    def check_promocode_used(self, promo_id: int, user_id: int):
        """Проверка, использовал ли пользователь промокод"""
        try:
            cursor = self.conn.cursor()
            cursor.execute('''
                SELECT id FROM promocode_uses WHERE promocode_id = ? AND user_id = ?
            ''', (promo_id, user_id))
            return cursor.fetchone() is not None
        except sqlite3.OperationalError as e:
            logger.warning(f"Таблица promocode_uses отсутствует при проверке использования: {e}")
            self.create_tables()
            return False
        except Exception as e:
            logger.error(f"Ошибка при проверке использования промокода: {e}")
            return False
    
    def use_promocode(self, promo_id: int, user_id: int):
        """Использование промокода – безопасно, с перехватом ошибок БД."""
        try:
            if self.check_promocode_used(promo_id, user_id):
                return False

            cursor = self.conn.cursor()
            cursor.execute('UPDATE promocodes SET current_uses = current_uses + 1 WHERE id = ?', (promo_id,))
            cursor.execute('''
                INSERT INTO promocode_uses (promocode_id, user_id, used_at)
                VALUES (?, ?, ?)
            ''', (promo_id, user_id, get_moscow_time().isoformat()))
            self.conn.commit()
            return True
        except sqlite3.OperationalError as e:
            # Если таблицы ещё нет – создаём принудительно
            logger.warning(f"Ошибка при использовании промокода (возможно, отсутствуют таблицы): {e}")
            self.create_tables()  # повторно создаёт недостающие таблицы
            # Повторяем операцию
            try:
                if self.check_promocode_used(promo_id, user_id):
                    return False
                cursor = self.conn.cursor()
                cursor.execute('UPDATE promocodes SET current_uses = current_uses + 1 WHERE id = ?', (promo_id,))
                cursor.execute('''
                    INSERT INTO promocode_uses (promocode_id, user_id, used_at)
                    VALUES (?, ?, ?)
                ''', (promo_id, user_id, get_moscow_time().isoformat()))
                self.conn.commit()
                return True
            except Exception as retry_error:
                logger.error(f"Повторная ошибка в use_promocode: {retry_error}", exc_info=True)
                return False
        except Exception as e:
            logger.error(f"Неожиданная ошибка в use_promocode: {e}", exc_info=True)
            return False
    
    def get_all_promocodes(self):
        """Получение всех промокодов с реальным счётчиком использований из promocode_uses."""
        cursor = self.conn.cursor()
        cursor.execute('''
            SELECT p.code, p.discount_percent, p.duration_days, p.max_uses,
                   COUNT(pu.id) AS current_uses,
                   p.expires_at, p.is_active, p.service_type
            FROM promocodes p
            LEFT JOIN promocode_uses pu ON pu.promocode_id = p.id
            GROUP BY p.id
            ORDER BY p.created_at DESC
        ''')
        return [dict(row) for row in cursor.fetchall()]
    
    def deactivate_promocode(self, code: str):
        """Деактивация промокода"""
        cursor = self.conn.cursor()
        cursor.execute('UPDATE promocodes SET is_active = 0 WHERE code = ?', (code.upper(),))
        self.conn.commit()
    
    def calculate_discounted_price(self, original_price: int, discount_percent: int) -> int:
        """Расчёт цены со скидкой"""
        return int(original_price * (100 - discount_percent) / 100)
    
