    def log_ad_view_daily(self, ad_id: int, platform: str = 'tg'):
        """Фиксируем просмотр в дневной таблице (с разбивкой по платформе)"""
        cursor = self.conn.cursor()
        today = get_moscow_time().date().isoformat()
        try:
            cursor.execute('''
                INSERT INTO ad_views_daily (ad_id, date, platform, views) VALUES (?, ?, ?, 1)
                ON CONFLICT(ad_id, date, platform) DO UPDATE SET views = views + 1
            ''', (ad_id, today, platform))
            self.conn.commit()
        except Exception as e:
            logger.error(f"log_ad_view_daily error: {e}")

    def get_ad_views_totals(self, ad_id: int) -> Dict:
        """Полные просмотры объявления за всё время, с разбивкой по площадкам"""
        cursor = self.conn.cursor()
        cursor.execute(
            "SELECT platform, SUM(views) FROM ad_views_daily WHERE ad_id = ? GROUP BY platform",
            (ad_id,)
        )
        rows = [dict(r) for r in cursor.fetchall()]
        result = {'views': 0, 'tg': 0, 'max': 0}
        for r in rows:
            p = (r.get('platform') or 'tg').lower()
            if p not in ('tg', 'max'):
                p = 'tg'
            result[p] = result.get(p, 0) + (r['SUM(views)'] or 0)
            result['views'] += (r['SUM(views)'] or 0)
        return result

    def get_ad_views_chart(self, ad_id: int, days: int = 14) -> List[Dict]:
        """Возвращает данные просмотров за последние N дней, с разбивкой TG/MAX"""
        cursor = self.conn.cursor()
        today = get_moscow_time().date()
        start_date = (today - timedelta(days=days - 1)).isoformat()  # граница по московскому времени
        cursor.execute('''
            SELECT date, platform, views FROM ad_views_daily
            WHERE ad_id = ? AND date >= ?
            ORDER BY date ASC
        ''', (ad_id, start_date))
        rows = [dict(r) for r in cursor.fetchall()]
        # Заполняем пропуски нулями, суммируем по платформам за каждый день
        by_date = {}
        for r in rows:
            d = r['date']
            entry = by_date.setdefault(d, {'tg': 0, 'max': 0})
            entry[r.get('platform') or 'tg'] = entry.get(r.get('platform') or 'tg', 0) + r['views']
        result = []
        for i in range(days):
            d = (today - timedelta(days=days - 1 - i)).isoformat()
            entry = by_date.get(d, {'tg': 0, 'max': 0})
            views_tg = entry.get('tg', 0)
            views_max = entry.get('max', 0)
            result.append({
                'date': d,
                'views': views_tg + views_max,
                'views_tg': views_tg,
                'views_max': views_max,
            })
        return result


