    desc      = (ad.get('description') or '')[:300]
    # Хэштег только для реального города из списка
    import re as _re
    coord_match = _re.match(r'📍\s*([\d.]+),\s*([\d.]+)', city)
    city_for_tag = '' if coord_match else (city if city in ALLOWED_CITIES else '')
    city_ch   = CITY_CHANNELS.get(city_for_tag, '') or CITY_CHANNELS.get(city, '')
    hashtag   = f"#{city_for_tag.replace(' ', '').replace('-', '')}" if city_for_tag else ""

    # Строка местоположения
    geo_str   = ad.get('_geo', '')
    address   = (ad.get('address') or '').strip()
    if coord_match:
        lat, lon = coord_match.group(1), coord_match.group(2)
        map_link = f"<a href=\"https://yandex.ru/maps/?pt={lon},{lat}&z=16\">на карте</a>"
        city_line = f"Местоположение: {map_link}"
    elif address and city:
        import urllib.parse as _up
        q = _up.quote_plus(f"{address}, {city}, Удмуртия")
        map_link = f"<a href=\"https://yandex.ru/maps/?text={q}\">на карте</a>"
        city_line = f"Местоположение: {address}, {city} · {map_link}"
    elif city:
        q = city.replace(' ', '+')
        map_link = f"<a href=\"https://yandex.ru/maps/?text={q},+Удмуртия\">на карте</a>"
        city_line = f"Местоположение: {city} · {map_link}"
    else:
        city_line = ""

    # ── Текст поста ──────────────────────────────────────────────────────
    category  = (ad.get('category') or '').strip()
    condition = (ad.get('condition') or '').strip()
    cat_tag   = f"#{category.lstrip(chr(183)).lstrip(chr(46)).strip().replace(' ', '').replace('-', '').replace('·', '')}" if category else ""
    tags_parts = [t for t in [hashtag, cat_tag] if t]
    _is_urgent = (bool(ad.get('urgent_until')) and
                  ad['urgent_until'] > get_moscow_time().isoformat())
    _urgent_tag = "  ! СРОЧНО" if _is_urgent else ""

    # Ссылка на городской канал
    if city_ch:
        city_ch_url  = f"https://t.me/{city_ch.lstrip('@')}"
        city_ch_line = f"<a href=\"{city_ch_url}\">Объявления в городе {city_for_tag or city}</a>"
    else:
        city_ch_line = ""

    channel_text = f"<b>{ad['title']}</b>{_urgent_tag}\n"
    if desc:
        channel_text += f"\n<b>Описание:</b> {desc}\n"
    channel_text += f"<b>Цена:</b> {price_fmt} ₽\n"
    if condition:
        channel_text += f"<b>Состояние:</b> {condition}\n"
    if ad.get('size'):
        channel_text += f"<b>Размер:</b> {ad['size']}\n"
    if city_line:
        # city_line уже содержит "Местоположение: ..." — берём только содержимое после двоеточия
        city_line_content = city_line.split("Местоположение: ", 1)[-1]
        channel_text += f"<b>Местоположение:</b> {city_line_content}\n"
    channel_text += f"<b>Продавец:</b> {seller_name}{verified_tag}{rating_tag}\n"
    if city_ch_line:
        channel_text += f"{city_ch_line}\n"
    if tags_parts:
        channel_text += f"\n{'  '.join(tags_parts)}"
    channel_text += f"\n\n<a href=\"https://t.me/{BOT_VPN}\">Не работает Telegram? Открыть бот</a>"

    def _make_keyboard(for_city_channel: bool = False) -> list:
        # Одинаковые кнопки для основного и городского каналов (броня убрана)
        rows = [
            [InlineKeyboardButton("· Написать продавцу", url=f"https://t.me/{BOT_USERNAME}?start=contact_{ad_id}"),
             InlineKeyboardButton("♡ В избранное",       url=f"https://t.me/{BOT_USERNAME}?start=favorite_{ad_id}")],
            [InlineKeyboardButton("+ Разместить объявление", url=f"https://t.me/{BOT_USERNAME}?start=new_ad")],
        ]
        return rows

    async def _enhance_photo(file_id: str) -> Optional[bytes]:
        """Скачивает фото, улучшает через Pillow (без OpenCV — экономия RAM).

        OpenCV fastNlMeansDenoisingColored потребляет 300–500 МБ на одно фото,
        что приводит к OOM на хостинге. Pillow UnsharpMask — лёгкая альтернатива.
        """
        try:
            from PIL import Image as _PILImg, ImageEnhance, ImageFilter
            import io as _io

            tg_file = await context.bot.get_file(file_id)
            buf_in = _io.BytesIO()
            await tg_file.download_to_memory(buf_in)
            buf_in.seek(0)

            pil_img = _PILImg.open(buf_in).convert("RGB")

            # Ограничиваем размер: не даём разрастись в RAM
            MAX_SIDE = 1280
            w, h = pil_img.size
            if max(w, h) > MAX_SIDE:
                scale = MAX_SIDE / max(w, h)
                pil_img = pil_img.resize((int(w * scale), int(h * scale)), _PILImg.LANCZOS)
            elif max(w, h) < 800:
                scale = 800 / max(w, h)
                pil_img = pil_img.resize((int(w * scale), int(h * scale)), _PILImg.LANCZOS)

            # Контраст, яркость, насыщенность
            pil_img = ImageEnhance.Contrast(pil_img).enhance(1.15)
            pil_img = ImageEnhance.Brightness(pil_img).enhance(1.05)
            pil_img = ImageEnhance.Color(pil_img).enhance(1.1)

            # Резкость — Pillow UnsharpMask (~0 MB overhead, аналог OpenCV sharpening)
            pil_img = pil_img.filter(ImageFilter.UnsharpMask(radius=1.5, percent=120, threshold=3))

            buf_out = _io.BytesIO()
            pil_img.save(buf_out, format="JPEG", quality=88, optimize=True)
            buf_out.seek(0)
            return buf_out.read()

        except Exception as e:
            logger.warning(f"Ошибка улучшения фото {file_id}: {e}")
            return None

    async def _get_enhanced_photos() -> list:
        """Возвращает список улучшенных фото (bytes) или оригинальных file_id."""
        enhanced = []
        for fid in (ad['photos'] or []):
            data = await _enhance_photo(fid)
            enhanced.append(data if data else fid)
        return enhanced

    async def _resolve_photos(photo_refs: list) -> list:
        """Скачивает фото по URL (MAX Platform), file_id TG оставляет как есть.
        Возвращает список, где каждый элемент — bytes (скачанное фото) или TG file_id (строка,
        начинающаяся с 'AgAC'). Неразрешимые MAX-фото удаляются."""
        import json as _json

        def _extract_url(photo_ref: str) -> Optional[str]:
            """Пытается извлечь URL из MAX upload JSON или вернуть ref как есть."""
            if photo_ref.startswith(('http://', 'https://')):
                return photo_ref
            try:
                payload = _json.loads(photo_ref)
                if isinstance(payload, dict):
                    inner = payload.get("result") if isinstance(payload.get("result"), dict) else payload
                    photos_dict = inner.get("photos")
                    if isinstance(photos_dict, dict):
                        for v in photos_dict.values():
                            if isinstance(v, dict):
                                for k in ("url", "file_path", "filePath", "link", "download_url"):
                                    val = v.get(k)
                                    if val and isinstance(val, str) and val.startswith("http"):
                                        return val
                    for k in ("url", "file_path", "filePath", "link", "download_url"):
                        val = inner.get(k)
                        if val and isinstance(val, str) and val.startswith("http"):
                            return val
            except (_json.JSONDecodeError, TypeError):
                pass
            return None

        def _is_tg_file_id(s: str) -> bool:
            """Признак TG file_id: не URL, не JSON — значит file_id."""
            if s.startswith(('http://', 'https://')):
                return False
            try:
                _json.loads(s)
                return False  # JSON — это MAX upload payload
            except Exception:
                pass
            return True

        url_refs = [(i, ref) for i, ref in enumerate(photo_refs)
                     if isinstance(ref, str) and _extract_url(ref)]
        if url_refs:
            try:
                async with aiohttp.ClientSession() as session:
                    for i, ref in url_refs:
                        url = _extract_url(ref) or ref
                        try:
                            async with session.get(url, timeout=aiohttp.ClientTimeout(total=30)) as resp:
                                if resp.status == 200:
                                    photo_refs[i] = await resp.read()
                        except Exception:
                            pass
            except Exception:
                pass

        if _max_bot_module is not None:
            for i, ref in enumerate(photo_refs):
                if isinstance(ref, str):
                    try:
                        data = await _max_bot_module.bot.get_photo_bytes(ref)
                        if data:
                            photo_refs[i] = data
                    except Exception:
                        pass

        # Удаляем неразрешимые MAX-фото (остались JSON-строками — не TG file_id)
        photo_refs = [p for p in photo_refs
                      if not isinstance(p, str) or _is_tg_file_id(p)]

        return photo_refs

    async def _send_to(chat_id: str, kbd: list, photos: list = None) -> Optional[int]:
        """Отправляет пост в указанный канал, возвращает message_id. До 3 попыток."""
        _photos = photos if photos is not None else (ad['photos'] or [])
        if _photos:
            _photos = await _resolve_photos(list(_photos))
        for attempt in range(3):
            try:
                if _photos:
                    if len(_photos) > 1:
                        media_group = [InputMediaPhoto(media=_photos[0], caption=channel_text, parse_mode=ParseMode.HTML)]
                        for photo in _photos[1:]:
                            media_group.append(InputMediaPhoto(media=photo))
                        msgs = await context.bot.send_media_group(chat_id=chat_id, media=media_group)
                        mid = msgs[0].message_id
                        # ВАЖНО: кнопки отправляем отдельно и НЕ бросаем исключение наверх,
                        # чтобы сбой этого вызова не вызвал повторную отправку медиагруппы
                        try:
                            await context.bot.send_message(chat_id=chat_id, text="Выберите действие:",
                                                           reply_markup=InlineKeyboardMarkup(kbd))
                        except Exception as _kbd_err:
                            logger.warning(f"Не удалось отправить кнопки в {chat_id}: {_kbd_err}")
                    else:
                        msg = await context.bot.send_photo(chat_id=chat_id, photo=_photos[0],
                                                           caption=channel_text, parse_mode=ParseMode.HTML,
                                                           reply_markup=InlineKeyboardMarkup(kbd))
                        mid = msg.message_id
                else:
                    msg = await context.bot.send_message(chat_id=chat_id, text=channel_text,
                                                         parse_mode=ParseMode.HTML,
                                                         reply_markup=InlineKeyboardMarkup(kbd))
                    mid = msg.message_id
                return mid
            except Exception as e:
                logger.warning(f"Попытка {attempt+1}/3 — не удалось опубликовать #{ad_id} в {chat_id}: {e}")
                if attempt < 2:
                    await asyncio.sleep(3)
        logger.error(f"Все 3 попытки публикации #{ad_id} в {chat_id} провалились")
        return None

    try:
        # Фото публикуем как есть — улучшение отключено (потребляет слишком много RAM)
        # Основной канал
        message_id = await _send_to(ADMIN_CHANNEL_ID, _make_keyboard(for_city_channel=False),
                                    photos=None)

        # Сохраняем channel_message_id основного канала в БД —
        # без этого delete_ad_from_channel не сможет удалить пост из основного канала
        if message_id:
            db.update_ad(ad_id, channel_message_id=message_id)
            logger.info(f"Объявление {ad_id} опубликовано в основной канал, message_id={message_id}")

        # Городской канал (если есть)
        if city_ch:
            city_msg_id = await _send_to(city_ch, _make_keyboard(for_city_channel=True),
                                         photos=None)
            if city_msg_id:
                db.update_ad(ad_id, city_channel_id=city_ch, city_channel_message_id=city_msg_id)
                logger.info(f"Объявление {ad_id} опубликовано в городской канал {city_ch}")
            else:
                for admin_id in ADMIN_USER_IDS:
                    try:
                        await context.bot.send_message(chat_id=admin_id,
                            text=f"{EM_DOT} Объявление #{ad_id} не попало в городской канал {city_ch}")
                    except Exception:
                        pass

        # ── Кросс-постинг в MAX канал ──────────────────────────────────────────
        # skip_max_crosspost=True означает, что объявление и так родом из MAX
        # (сюда попало через api_max_publish_webhook только чтобы появиться
        # в Telegram-канале) — повторный кросс-пост туда не нужен и не может
        # сработать, т.к. ad['photos'] в этом случае содержит не Telegram
        # file_id, а идентификаторы фото из MAX (context.bot.get_file упадёт).
        if not skip_max_crosspost and not (max_client and MAX_CHANNEL_ID):
            logger.warning(
                f"TG→MAX cross-post ad #{ad_id} пропущен: "
                f"max_client={'есть' if max_client else 'НЕТ (пуст MAX_BOT_TOKEN?)'}, "
                f"MAX_CHANNEL_ID={'задан' if MAX_CHANNEL_ID else 'НЕ задан'}"
            )
        if max_client and MAX_CHANNEL_ID and not skip_max_crosspost:
            try:
                max_text = f"<b>{ad['title']}</b>{_urgent_tag}\n"
                if desc:
                    max_text += f"\n<b>Описание:</b> {desc}\n"
                max_text += f"<b>Цена:</b> {price_fmt} ₽\n"
                if condition:
                    max_text += f"<b>Состояние:</b> {condition}\n"
                if ad.get('size'):
                    max_text += f"<b>Размер:</b> {ad['size']}\n"
                if city_line:
                    max_text += f"<b>Местоположение:</b> {city_line.split('Местоположение: ', 1)[-1]}\n"
                max_text += f"<b>Продавец:</b> {seller_name}{verified_tag}{rating_tag}\n"
                if tags_parts:
                    max_text += f"\n{'  '.join(tags_parts)}"
                max_text += f"\n\n<a href=\"{MAX_PUBLIC_URL}\">Открыть бот в MAX</a>"

                max_kbd = InlineKeyboardMarkup([
                    [InlineKeyboardButton("· Написать продавцу", url=f"{MAX_PUBLIC_URL}?start=ad_{ad_id}"),
                     InlineKeyboardButton("♡ В избранное", url=f"{MAX_PUBLIC_URL}?start=favorite_{ad_id}")],
                    [InlineKeyboardButton("+ Разместить объявление", url=MAX_PUBLIC_URL)],
                ])

                max_photos = ad.get('photos') or []
                max_photos_data = []
                for fid in max_photos[:5]:
                    try:
                        file = await context.bot.get_file(fid)
                        data = await file.download_as_bytearray()
                        max_photos_data.append(bytes(data))
                    except Exception:
                        pass

                if len(max_photos_data) > 1:
                    max_msg_id = await max_client.send_media_group(
                        MAX_CHANNEL_ID, max_photos_data, caption=max_text,
                        parse_mode="html", reply_markup=max_kbd,
                    )
                elif max_photos_data:
                    max_msg_id = await max_client.send_photo(
                        MAX_CHANNEL_ID, max_photos_data[0], caption=max_text,
                        parse_mode="html", reply_markup=max_kbd,
                    )
                else:
                    max_msg_id = await max_client.send_message(
                        MAX_CHANNEL_ID, max_text, parse_mode="html", reply_markup=max_kbd,
                    )
                if max_msg_id:
                    logger.info(f"Объявление {ad_id} опубликовано в MAX канал, msg_id={max_msg_id}")
                    db.update_ad(ad_id, max_channel_message_id=str(max_msg_id))
                else:
                    logger.warning(f"Не удалось опубликовать #{ad_id} в MAX канал")
            except Exception as _max_e:
                logger.error(f"MAX cross-post error #{ad_id}: {_max_e}", exc_info=True)

        db.log_action(ad['user_id'], "ad_published", f"Ad ID: {ad_id}, Channel message: {message_id}")
        return message_id

    except Exception as e:
        import traceback
        logger.error(f"Ошибка публикации объявления {ad_id}: {e}\n{traceback.format_exc()}")
        for admin_id in ADMIN_USER_IDS:
            try:
                await context.bot.send_message(chat_id=admin_id,
                    text=f"{EM_DOT} Не удалось опубликовать объявление #{ad_id}\n\nОшибка: {e}")
            except Exception:
                pass
        return None


