# ══════════════════════════════════════════════════════════════════════
#  PayAnyWay СБП — генерация ссылки и обработка вебхука
# ══════════════════════════════════════════════════════════════════════

def _paw_signature(*parts) -> str:
    """MD5-подпись PayAnyWay: конкатенируем строки и считаем MD5."""
    raw = "".join(str(p) for p in parts)
    return hashlib.md5(raw.encode("utf-8")).hexdigest()


def _paw_response_signature(result_code: str, order_id: str) -> str:
    """
    Подпись ОТВЕТА на уведомление об оплате (обязательна по протоколу МОНЕТА.РУ):
    MNT_SIGNATURE = MD5(MNT_RESULT_CODE + MNT_ID + MNT_TRANSACTION_ID + Код_целостности)
    Без неё PayAnyWay не считает ответ технически корректным и не подтверждает
    получение уведомления — платёж «зависает» на стороне PayAnyWay.
    """
    raw = f"{result_code}{PAW_MNT_ID}{order_id}{PAW_INTEGRITY_CODE}"
    return hashlib.md5(raw.encode("utf-8")).hexdigest()


def create_payanyway_pin_url(user_id: int, ad_id: int, pin_type: str,
                              pin_hours: int, amount_rub: int,
                              promo_code: str = "") -> tuple:
    """
    Создаёт ссылку на оплату СБП через PayAnyWay и сохраняет счёт в БД.
    Возвращает (pay_url, order_id).
    """
    import urllib.parse
    order_id   = f"pin_{ad_id}_{pin_hours}h_{user_id}_{uuid.uuid4().hex[:8]}"
    amount_str = f"{amount_rub:.2f}"

    # Подпись: MNT_ID + MNT_TRANSACTION_ID + MNT_AMOUNT + MNT_CURRENCY_CODE
    #          + MNT_SUBSCRIBER_ID (пусто) + MNT_TEST_MODE + MNT_INTEGRITY_CODE
    sig = _paw_signature(
        PAW_MNT_ID, order_id, amount_str, "RUB",
        "", PAW_TEST_MODE, PAW_INTEGRITY_CODE
    )

    params = {
        "MNT_ID":             PAW_MNT_ID,
        "MNT_TRANSACTION_ID": order_id,
        "MNT_AMOUNT":         amount_str,
        "MNT_CURRENCY_CODE":  "RUB",
        "MNT_TEST_MODE":      str(PAW_TEST_MODE),
        "MNT_SIGNATURE":      sig,
        "MNT_DESCRIPTION":    f"Закреп объявления #{ad_id} на {pin_hours}ч",
        "paymentSystem.unitId": PAW_SBP_UNIT_ID,
        "MNT_CALLBACK_URL":   f"{SERVER_URL}/api/payanyway",
        "MNT_SUCCESS_URL":    f"{SERVER_URL}/api/payanyway/success",
        "MNT_FAIL_URL":       f"{SERVER_URL}/api/payanyway/fail",
        "version":            "v3",
        "followup":           "true",
        "javascriptEnabled":  "true",
    }

    pay_url = PAW_PAYMENT_URL + "?" + urllib.parse.urlencode(params)

    # Сохраняем в БД
    db.save_paw_invoice(order_id, user_id, ad_id, pin_type, pin_hours, amount_rub, promo_code)
    logger.info(f"PAW invoice created: order={order_id} amount={amount_str} "
                f"callback={params['MNT_CALLBACK_URL']} success={params['MNT_SUCCESS_URL']}")

    return pay_url, order_id


def create_payanyway_subscription_url(user_id: int, amount_rub: int = None, promo_code: str = "") -> tuple:
    """Создаёт ссылку на оплату подписки ПОЛКА ПЛЮС через PayAnyWay + сохраняет счёт."""
    if amount_rub is None:
        amount_rub = get_price(PRICE_KEY_SUBSCRIPTION, SUBSCRIPTION_PRICE)
    import urllib.parse as _up
    order_id   = f"sub_{user_id}_{uuid.uuid4().hex[:8]}"
    amount_str = f"{amount_rub:.2f}"
    sig = _paw_signature(PAW_MNT_ID, order_id, amount_str, "RUB", "", PAW_TEST_MODE, PAW_INTEGRITY_CODE)
    params = {
        "MNT_ID": PAW_MNT_ID, "MNT_TRANSACTION_ID": order_id,
        "MNT_AMOUNT": amount_str, "MNT_CURRENCY_CODE": "RUB",
        "MNT_TEST_MODE": str(PAW_TEST_MODE), "MNT_SIGNATURE": sig,
        "MNT_DESCRIPTION": f"ПОЛКА ПЛЮС — 30 дней ({user_id})",
        "paymentSystem.unitId": PAW_SBP_UNIT_ID,
        "MNT_CALLBACK_URL": f"{SERVER_URL}/api/payanyway",
        "MNT_SUCCESS_URL":  f"{SERVER_URL}/api/payanyway/success",
        "MNT_FAIL_URL":     f"{SERVER_URL}/api/payanyway/fail",
        "version":            "v3",
        "followup":           "true",
        "javascriptEnabled":  "true",
    }
    pay_url = PAW_PAYMENT_URL + "?" + _up.urlencode(params)
    db.save_paw_invoice(order_id, user_id, ad_id=0, pin_type="sub", pin_hours=0, amount_rub=amount_rub, promo_code=promo_code)
    logger.info(f"PAW invoice created: order={order_id} amount={amount_str} "
                f"callback={params['MNT_CALLBACK_URL']} success={params['MNT_SUCCESS_URL']}")
    return pay_url, order_id


async def _process_paw_paid_sub(order_id: str, bot):
    """Активирует подписку ПОЛКА ПЛЮС после оплаты через PayAnyWay."""
    if not db.mark_paw_invoice_paid(order_id):
        logger.info(f"PAW sub: invoice {order_id} already processed")
        return False
    inv = db.get_paw_invoice(order_id)
    if not inv:
        logger.error(f"PAW sub: invoice {order_id} not found")
        return False
    user_id = inv["user_id"]
    promo = inv.get("promo_code", "")
    if promo:
        try:
            _promo = db.get_promocode(promo)
            if _promo:
                db.use_promocode(_promo["id"], user_id)
        except Exception as _pre:
            logger.warning(f"PAW sub promo use: {_pre}")
    from datetime import timedelta as _td
    end_date = compute_premium_extension(user_id)
    db.update_user(user_id, tariff='Premium', tariff_end_date=end_date,
                   daily_ads_count=0, photo_search_count=0, ai_gen_count=0)
    logger.info(f"PAW sub: Premium activated/extended for user={user_id} until {end_date}")

    # Реферальное вознаграждение — раньше начислялось ТОЛЬКО при ручном
    # подтверждении платежа админом по скриншоту (устаревший способ
    # оплаты), а через автоматическую оплату PayAnyWay/CryptoBot вообще
    # не начислялось, хотя это сейчас основной способ оплаты подписки.
    try:
        amount_paid = inv.get("amount_rub") or get_price(PRICE_KEY_SUBSCRIPTION, SUBSCRIPTION_PRICE)
        db.process_referral_reward(user_id, amount_paid)
    except Exception as _rre:
        logger.warning(f"PAW sub: referral reward error for user={user_id}: {_rre}")
    try:
        await bot.send_message(
            chat_id=user_id,
            text=f"{EM_OK} <b>ПОЛКА ПЛЮС активен!</b>\n\n"
                 f"Действует до: <b>{format_date_ru(end_date)}</b> (МСК)\n"
                 f"Срок действия: {SUBSCRIPTION_DAYS} дней.\n"
                 f"• До {TARIFFS['Premium']['daily_ads']} объявлений в день\n"
                 f"• До {TARIFFS['Premium']['photo_limit']} фото на объявление\n"
                 f"• AI-улучшение и удаление фона без лимита\n"
                 f"• Авто-подъём в топ каждые {TARIFFS['Premium']['auto_bump_interval']}ч\n"
                 f"• Поиск по фото — до {TARIFFS['Premium']['daily_search']} раз в день\n\n"
                 f"Спасибо за поддержку!",
            parse_mode=ParseMode.HTML,
        )
    except Exception as _e:
        logger.warning(f"PAW sub notify user: {_e}")
    return True


async def _process_paw_paid_pin(order_id: str, bot, job_queue=None):
    """
    Активирует закреп объявления после успешной оплаты через PayAnyWay.
    Вызывается из вебхука.
    """
    # Помечаем как оплаченный (идемпотентно)
    if not db.mark_paw_invoice_paid(order_id):
        logger.info(f"PAW: invoice {order_id} already processed")
        return False

    inv = db.get_paw_invoice(order_id)
    if not inv:
        logger.error(f"PAW: invoice {order_id} not found after mark_paid")
        return False

    user_id   = inv["user_id"]
    ad_id     = inv["ad_id"]
    pin_type  = inv["pin_type"]
    pin_hours = inv["pin_hours"]
    amount    = inv["amount_rub"]
    promo     = inv.get("promo_code", "")

    ad = db.get_ad(ad_id)
    if not ad:
        logger.error(f"PAW: ad {ad_id} not found")
        return False

    # Обновляем pinned_until в БД — если закреп уже активен (купили ещё
    # закреп, пока текущий не истёк), прибавляем оплаченные часы К ОСТАТКУ,
    # а не затираем его текущим временем + новые часы (иначе уже
    # оплаченное и оставшееся время закрепа просто сгорает — та же ошибка,
    # что раньше была с продлением подписки).
    now_msk = get_moscow_time()
    base_dt = now_msk
    existing_field = 'pinned_until_city' if pin_type.startswith("city") else 'pinned_until'
    existing_val = ad.get(existing_field)
    if existing_val:
        try:
            existing_dt = _safe_isoparse(existing_val)
            if existing_dt and existing_dt > now_msk:
                base_dt = existing_dt
        except Exception:
            pass
    pinned_until = (base_dt + timedelta(hours=pin_hours)).isoformat()
    # Определяем целевой канал
    city = (ad.get("city") or "").strip()
    if pin_type.startswith("city"):
        target_chat = CITY_CHANNELS.get(city, ADMIN_CHANNEL_ID)
        ch_label    = f"{city} (городской канал)"
    else:
        target_chat = ADMIN_CHANNEL_ID
        ch_label    = "Основной канал"

    db.conn.execute(
        "UPDATE ads SET pinned_until=?, pinned_chat_id=? WHERE id=?" if not pin_type.startswith("city") else
        "UPDATE ads SET pinned_until_city=?, pinned_chat_id_city=? WHERE id=?",
        (pinned_until, str(target_chat), ad_id)
    )
    db.conn.commit()

    # Закрепляем сообщение в канале
    # Для городского канала используем city_channel_message_id, для основного — channel_message_id
    _pin_ok  = False
    _pin_err = ""
    if pin_type.startswith("city"):
        _msg_id_to_pin = ad.get("city_channel_message_id")
    else:
        _msg_id_to_pin = ad.get("channel_message_id")

    if _msg_id_to_pin:
        try:
            await bot.pin_chat_message(
                chat_id=target_chat,
                message_id=_msg_id_to_pin,
                disable_notification=True
            )
            if job_queue:
                # Планируем открепление на реальный момент истечения
                # (pinned_until), а не просто "через pin_hours от сейчас" —
                # если закреп был продлён поверх ещё активного, эти два
                # значения расходятся, и без этого объявление открепится
                # раньше времени, за которое уже заплатили.
                delay = _safe_isoparse(pinned_until) - now_msk
                if delay.total_seconds() < 0:
                    delay = timedelta(seconds=5)
                job_queue.run_once(
                    unpin_ad_callback,
                    when=delay,
                    data={"ad_id": ad_id, "message_id": _msg_id_to_pin,
                          "chat_id": target_chat},
                    name=f"unpin_ad_{ad_id}_{'city' if pin_type.startswith('city') else 'main'}"
                )
            _pin_ok = True
        except Exception as _pe:
            _pin_err = str(_pe)
            logger.error(f"PAW pin error: {_pe}")
    else:
        _pin_err = "message_id отсутствует — объявление не опубликовано в целевом канале"

    # Уведомление пользователю
    try:
        pinned_until_dt = _safe_isoparse(pinned_until)
        pinned_until_fmt = pinned_until[:16].replace("T", "T")
        await bot.send_message(
            chat_id=user_id,
            text=(
                f"✦ Объявление закреплено!\n\n"
                f"<b>{ad['title'][:60]}</b>\n\n"
                f"Осталось: <b>{pin_hours} ч</b>\n"
                f"До: {pinned_until[:16]}"
            ),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(EM_ARROW_L + " К объявлению",
                                     callback_data=f"view_my_ad:{ad_id}")
            ]])
        )
    except Exception as _e:
        logger.warning(f"PAW pin notify user: {_e}")

    # Уведомление администраторам
    try:
        await _notify_admins_pin(
            bot, ad_id, user_id, pin_hours, ch_label, amount,
            success=_pin_ok, method="paw",
            error_msg=_pin_err if not _pin_ok else ""
        )
    except Exception as _ne:
        logger.warning(f"PAW _notify_admins_pin: {_ne}")

    # Промокод
    if promo:
        try:
            _promo = db.get_promocode(promo)
            if _promo:
                db.use_promocode(_promo["id"], user_id)
        except Exception as _pre:
            logger.warning(f"PAW promo use: {_pre}")

    logger.info(f"PAW: закреп активирован ad={ad_id} user={user_id} {pin_hours}ч")
    return True


async def api_payanyway_webhook(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """
    POST /api/payanyway
    Принимает уведомления от PayAnyWay об успешной оплате.
    Документация: https://payanyway.ru/info/w/ru/public/merchant/api
    """
    try:
        if request.method == "POST":
            data = await request.post()
        else:
            data = request.rel_url.query  # GET: параметры в URL
    except Exception as _e:
        logger.error(f"PAW webhook read error: {_e}")
        return aiohttp_web.Response(status=400, text="Bad request")

    mnt_id      = data.get("MNT_ID", "")
    order_id    = data.get("MNT_TRANSACTION_ID", "")
    operation   = data.get("MNT_OPERATION_ID", "")
    amount      = data.get("MNT_AMOUNT", "")
    currency    = data.get("MNT_CURRENCY_CODE", "RUB")
    subscriber  = data.get("MNT_SUBSCRIBER_ID", "")
    test_mode   = data.get("MNT_TEST_MODE", "0")
    signature   = data.get("MNT_SIGNATURE", "")

    logger.info(f"PAW webhook: order={order_id} amount={amount} op={operation}")

    # Проверка подписи
    expected_sig = _paw_signature(
        mnt_id, order_id, operation, amount, currency,
        "", test_mode, PAW_INTEGRITY_CODE
    )
    if not hmac.compare_digest(expected_sig.lower(), signature.lower()):
        logger.warning(f"PAW webhook: invalid signature order={order_id}")
        fail_sig = _paw_response_signature("500", order_id)
        return aiohttp_web.Response(
            status=200,
            text=(
                "<?xml version='1.0' encoding='utf-8'?>"
                "<MNT_RESPONSE><MNT_ID>" + PAW_MNT_ID + "</MNT_ID>"
                "<MNT_TRANSACTION_ID>" + order_id + "</MNT_TRANSACTION_ID>"
                "<MNT_RESULT_CODE>500</MNT_RESULT_CODE>"
                "<MNT_DESCRIPTION>Invalid signature</MNT_DESCRIPTION>"
                f"<MNT_SIGNATURE>{fail_sig}</MNT_SIGNATURE>"
                "</MNT_RESPONSE>"
            ),
            content_type="application/xml"
        )

    # Обработка в зависимости от типа и платформы (TG / MAX)
    if "_max_" in order_id:
        # Заказ сделан через MAX-бота, но физически вебхук пришёл на сервер
        # TG-бота (единственный порт, открытый наружу) — передаём обработку
        # в модуль MAX-бота, чтобы уведомление и закреп ушли через MAX Bot API.
        await _dispatch_max_paw_order(order_id)
    elif order_id.startswith("sub_"):
        bot = _bot_app_ref.bot if _bot_app_ref else None
        if bot:
            try:
                await _process_paw_paid_sub(order_id, bot)
            except Exception as _pe:
                logger.error(f"PAW _process_paw_paid_sub: {_pe}", exc_info=True)
        else:
            logger.error("PAW webhook: bot reference not available")
    elif order_id.startswith("pin_"):
        bot = _bot_app_ref.bot if _bot_app_ref else None
        jq  = _bot_app_ref.job_queue if _bot_app_ref else None
        if bot:
            try:
                await _process_paw_paid_pin(order_id, bot, job_queue=jq)
            except Exception as _pe:
                logger.error(f"PAW _process_paw_paid_pin: {_pe}", exc_info=True)
        else:
            logger.error("PAW webhook: bot reference not available")

    # PayAnyWay ожидает XML-ответ с кодом 200 И корректной подписью MNT_SIGNATURE
    ok_sig = _paw_response_signature("200", order_id)
    xml_ok = (
        "<?xml version='1.0' encoding='utf-8'?>"
        "<MNT_RESPONSE>"
        f"<MNT_ID>{PAW_MNT_ID}</MNT_ID>"
        f"<MNT_TRANSACTION_ID>{order_id}</MNT_TRANSACTION_ID>"
        "<MNT_RESULT_CODE>200</MNT_RESULT_CODE>"
        "<MNT_DESCRIPTION>OK</MNT_DESCRIPTION>"
        f"<MNT_SIGNATURE>{ok_sig}</MNT_SIGNATURE>"
        "</MNT_RESPONSE>"
    )
    return aiohttp_web.Response(text=xml_ok, content_type="application/xml")


async def api_payanyway_success(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """
    GET /api/payanyway/success — страница после оплаты через PayAnyWay.
    Это редирект браузера пользователя, а не серверный вебхук — основной
    источник активации это api_payanyway_webhook. Здесь активация играет
    роль подстраховки (на случай сетевых задержек серверного уведомления),
    поэтому если PayAnyWay передаёт MNT_SIGNATURE и в этом редиректе —
    проверяем её; если нет — полагаемся на то, что order_id непредсказуем
    (случайный hex) и что запись в БД идемпотентна (mark_paw_invoice_paid
    срабатывает только один раз).
    """
    q = request.rel_url.query
    order_id = q.get("MNT_TRANSACTION_ID", "")

    if order_id:
        redirect_sig = q.get("MNT_SIGNATURE", "")
        sig_ok = True
        if redirect_sig:
            expected = _paw_signature(
                q.get("MNT_ID", PAW_MNT_ID), order_id, q.get("MNT_OPERATION_ID", ""),
                q.get("MNT_AMOUNT", ""), q.get("MNT_CURRENCY_CODE", "RUB"),
                "", q.get("MNT_TEST_MODE", "0"), PAW_INTEGRITY_CODE
            )
            sig_ok = hmac.compare_digest(expected.lower(), redirect_sig.lower())
            if not sig_ok:
                logger.warning(f"PAW success: invalid signature in redirect for order={order_id}")

        if sig_ok:
            if "_max_" in order_id:
                await _dispatch_max_paw_order(order_id)
            else:
                bot = _bot_app_ref.bot if _bot_app_ref else None
                jq  = _bot_app_ref.job_queue if _bot_app_ref else None
                if bot:
                    try:
                        if order_id.startswith("sub_"):
                            await _process_paw_paid_sub(order_id, bot)
                        elif order_id.startswith("pin_"):
                            await _process_paw_paid_pin(order_id, bot, job_queue=jq)
                    except Exception as _pe:
                        logger.error(f"PAW success process error: {_pe}", exc_info=True)
    html = (
        "<!DOCTYPE html><html><head><meta charset='utf-8'>"
        "<title>Оплата получена</title>"
        "<meta name='viewport' content='width=device-width,initial-scale=1'>"
        "<style>body{font-family:sans-serif;text-align:center;padding:60px 20px;}"
        "h2{color:#27ae60;} a{color:#2980b9;}</style></head>"
        f"<body><h2>{EM_OK} Оплата получена!</h2>"
        "<p>Готово! Оплата проведена, всё включено автоматически.</p>"
        f"<p><a href='https://t.me/{BOT_USERNAME}'>{EM_ARROW_L} Вернуться в бот</a></p>"
        "</body></html>"
    )
    return aiohttp_web.Response(text=html, content_type="text/html")


async def api_payanyway_fail(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/payanyway/fail — страница при ошибке оплаты через PayAnyWay."""
    html = (
        "<!DOCTYPE html><html><head><meta charset='utf-8'>"
        "<title>Ошибка оплаты</title>"
        "<meta name='viewport' content='width=device-width,initial-scale=1'>"
        "<style>body{font-family:sans-serif;text-align:center;padding:60px 20px;}"
        "h2{color:#e74c3c;} a{color:#2980b9;}</style></head>"
        f"<body><h2>{EM_FAIL} Ошибка оплаты</h2>"
        "<p>Платёж не прошёл. Попробуйте снова или напишите в поддержку.</p>"
        f"<p><a href='https://t.me/{BOT_USERNAME}'>{EM_ARROW_L} Вернуться в бот</a></p>"
        "</body></html>"
    )
    return aiohttp_web.Response(text=html, content_type="text/html")


async def api_max_publish_webhook(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/max-publish — вызывается MAX-ботом после публикации объявления."""
    peer = request.remote or request.headers.get("X-Forwarded-For", "?")
    try:
        body = await request.json()
        ad_id = body.get("ad_id")
        token = body.get("token", "")
        logger.info(f"MAX→TG webhook: received from {peer}, ad_id={ad_id}, token={'✓' if token else '✗'}, body={body}")

        if token != MAX_BOT_TOKEN:
            logger.warning(f"MAX→TG webhook: invalid token from {peer}, got={token[:20]}..., expected={MAX_BOT_TOKEN[:20]}...")
            return aiohttp_web.json_response({"ok": False, "error": "invalid token"}, status=403)

        if not ad_id:
            logger.warning(f"MAX→TG webhook: missing ad_id from {peer}")
            return aiohttp_web.json_response({"ok": False, "error": "no ad_id"}, status=400)

        ad = db.get_ad(ad_id)
        if not ad:
            logger.warning(f"MAX→TG webhook: ad #{ad_id} not found in DB")
            return aiohttp_web.json_response({"ok": False, "error": "ad not found"}, status=404)
        logger.info(f"MAX→TG webhook: ad #{ad_id} found, status={ad['status']}, title={ad['title'][:40]}")

        app_ref = _bot_app_ref
        if not app_ref:
            logger.error(f"MAX→TG webhook: _bot_app_ref is None — bot not initialized")
            return aiohttp_web.json_response({"ok": False, "error": "bot not ready"}, status=503)

        fake_update = object()
        fake_context = type("FakeCtx", (), {"bot": app_ref.bot})()
        logger.info(f"MAX→TG webhook: calling publish_ad_to_channel(#{ad_id})...")
        result = await publish_ad_to_channel(ad_id, fake_context, skip_max_crosspost=True)
        if result:
            logger.info(f"MAX→TG cross-post: ad #{ad_id} published to Telegram channel, message_id={result}")
        else:
            logger.warning(f"MAX→TG cross-post: ad #{ad_id} publish_ad_to_channel returned None")
        return aiohttp_web.json_response({"ok": True, "message_id": result})
    except Exception as e:
        logger.error(f"MAX→TG webhook error: {e}", exc_info=True)
        return aiohttp_web.json_response({"ok": False, "error": str(e)})


async def pin_ad_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Меню закрепа — выбор объявления"""
    query = update.callback_query
    await safe_answer(query, )

    user = update.effective_user
    all_ads = db.get_user_ads(user.id)
    active_ads = [ad for ad in all_ads if ad['status'] == 'active']

    if not active_ads:
        await safe_edit_message(query,
            "У вас нет активных объявлений для закрепления.",
            [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="profile")]]
        )
        return

    moscow_now = get_moscow_time()
    text = (
        f"Закрепление объявления\n\n"
        f"Закреп держит объявление в топе на <b>24 часа</b>.\n"
        f"{EM_DOT} Основной канал (вся Удмуртия) — <b>{get_price(PRICE_KEY_PIN_RF, PIN_PRICE)} ₽</b>\n"
        f"{EM_DOT} Городской канал — <b>от 49 ₽/сутки</b> (зависит от аудитории)\n\n"
        f"Выберите объявление:"
    )
    keyboard = []
    for ad in active_ads[:10]:
        is_pinned = ad.get('pinned_until') and datetime.fromisoformat(ad['pinned_until']) > moscow_now
        prefix = f"{EM_DIAMOND} " if is_pinned else ""
        keyboard.append([InlineKeyboardButton(
            f"{prefix}{ad['title'][:40]} | {ad['price']} ₽",
            callback_data=f"pin_ad:{ad['id']}"
        )])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="profile")])
    await safe_edit_message(query, text, keyboard, parse_mode="HTML")


async def pin_ad(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Шаг 1: выбор канала для закрепа"""
    query = update.callback_query
    await safe_answer(query, )

    ad_id = int(query.data.split(":")[1])
    user  = update.effective_user
    ad    = db.get_ad(ad_id)

    if not ad or ad['user_id'] != user.id:
        await safe_edit_message(query, "Объявление не найдено")
        return

    # ── Проверка: объявление должно быть опубликовано в канале ───────────────────
    if not ad.get('channel_message_id') and not ad.get('city_channel_message_id'):
        ad_status = ad.get('status', 'unknown')
        status_hint = {
            'moderation': 'Объявление ещё на модерации — дождитесь одобрения.',
            'rejected':   'Объявление было отклонено модератором.',
            'inactive':   'Объявление снято с публикации.',
        }.get(ad_status, 'Объявление не опубликовано в канале.')
        await safe_edit_message(
            query,
            f"{EM_FAIL} Закрепление недоступно\n\n"
            f"<b>{ad['title']}</b>\n\n"
            f"{status_hint}\n\n"
            f"Закрепление возможно только для активных объявлений в канале.",
            [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data=f"view_my_ad:{ad_id}")]],
            parse_mode=ParseMode.HTML
        )
        return

    # Строим список каналов — показываем оба варианта независимо от текущего закрепа
    moscow_now  = get_moscow_time()
    main_chat_id = str(ADMIN_CHANNEL_ID)

    # Статус основного закрепа
    main_pinned = (ad.get('pinned_until') and _safe_isoparse(ad['pinned_until']) > moscow_now)
    city_pinned = (ad.get('pinned_until_city') and _safe_isoparse(ad['pinned_until_city']) > moscow_now)

    pin_status_lines = []
    if main_pinned:
        dt = _safe_isoparse(ad['pinned_until'])
        rem = dt - moscow_now
        h, m = int(rem.total_seconds()//3600), int((rem.total_seconds()%3600)//60)
        pin_status_lines.append(f"{EM_OK} Основной канал — закреплено, осталось <b>{h}ч {m}мин</b>")
    if city_pinned:
        dt = _safe_isoparse(ad['pinned_until_city'])
        rem = dt - moscow_now
        h, m = int(rem.total_seconds()//3600), int((rem.total_seconds()%3600)//60)
        pin_status_lines.append(f"{EM_OK} Городской канал — закреплено, осталось <b>{h}ч {m}мин</b>")

    keyboard = []
    # Основной канал
    main_label = f"{EM_DIAMOND} Основной канал — уже закреплён" if main_pinned else f"{EM_DOT} Основной канал — вся Удмуртия"
    keyboard.append([InlineKeyboardButton(main_label, callback_data=f"pin_choose_dur:rf:{ad_id}")])

    # Городской канал
    ad_city = (ad.get('city') or '').strip()
    if ad_city and ad_city in CITY_CHANNELS:
        city_ch = CITY_CHANNELS[ad_city]
        city_label = f"{EM_DIAMOND} {ad_city} — уже закреплён" if city_pinned else f"{EM_DOT} {ad_city} ({city_ch})"
        keyboard.append([InlineKeyboardButton(city_label, callback_data=f"pin_choose_dur:city_{ad_city}:{ad_id}")])

    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="pin_ad_menu")])

    status_block = "\n".join(pin_status_lines)
    status_text = f"\n\n{status_block}" if status_block else ""

    await safe_edit_message(query,
        f"{EM_DOT} Закрепление: <b>{ad['title']}</b>{status_text}\n\n"
        f"Объявление будет первым в выбранном канале всё время закрепа.\n\n"
        f"<b>Выберите канал:</b>",
        keyboard, parse_mode="HTML"
    )


async def pin_choose_duration(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Шаг 2: выбор длительности закрепа"""
    query = update.callback_query
    await safe_answer(query, )

    # pin_choose_dur:rf:ad_id  или  pin_choose_dur:city_Ижевск:ad_id
    parts    = query.data.split(":")  # ['pin_choose_dur', 'rf', 'ad_id']
    pin_type = parts[1]               # 'rf' или 'city_Ижевск'
    ad_id    = int(parts[2])
    user     = update.effective_user
    ad       = db.get_ad(ad_id)

    if not ad or ad['user_id'] != user.id:
        await safe_edit_message(query, "Объявление не найдено")
        return

    # Определяем канал и базовую цену
    if pin_type == "rf":
        base_price  = get_price(PRICE_KEY_PIN_RF, PIN_PRICE)
        channel_label = "Основной канал (вся Удмуртия)"
    else:
        city_name   = pin_type[5:]  # убираем 'city_'
        city_ch     = CITY_CHANNELS.get(city_name, '')
        base_price, _ = get_city_pin_price(city_ch) if city_ch else (79, None)
        channel_label = f"{city_name} ({city_ch})"

    PIN_PACKAGES = [
        (24,  base_price,              "24 часа"),
        (72,  round(base_price * 1.8), "3 дня"),
        (168, round(base_price * 3.5), "7 дней"),
    ]

    keyboard = []
    for _hours, _price, _label in PIN_PACKAGES:
        keyboard.append([InlineKeyboardButton(
            f"{EM_DOT} {_label} — {_price} ₽",
            callback_data=f"pin_pay:{pin_type}:{ad_id}:{_hours}"
        )])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data=f"pin_ad:{ad_id}")])

    await safe_edit_message(query,
        f"{EM_DOT} Закрепление: <b>{ad['title']}</b>\n\n"
        f"Канал: <b>{channel_label}</b>\n\n"
        f"<b>Выберите длительность:</b>",
        keyboard, parse_mode="HTML"
    )


async def pin_pay(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Экран оплаты закрепа (РФ или город)"""
    query = update.callback_query
    await safe_answer(query, )

    parts    = query.data.split(":")  # pin_pay:rf:ad_id:hours
    pin_type = parts[1]
    ad_id    = int(parts[2])
    pin_hours = int(parts[3]) if len(parts) > 3 else 24
    user    = update.effective_user
    ad      = db.get_ad(ad_id)

    if not ad or ad['user_id'] != user.id:
        await safe_edit_message(query, "Объявление не найдено")
        return

    if pin_type == "rf":
        base_price    = get_price(PRICE_KEY_PIN_RF, PIN_PRICE)
        channel_label = "Основной канал (вся Удмуртия)"
        plan_key      = f"pin_{ad_id}_{pin_hours}h"
    else:
        # pin_type вида 'city_Ижевск'
        city_name     = pin_type[5:] if pin_type.startswith("city_") else (ad.get('city') or '').strip()
        city_ch       = CITY_CHANNELS.get(city_name, '')
        base_price, _ = get_city_pin_price(city_ch) if city_ch else (79, None)
        channel_label = f"{city_name} ({city_ch})" if city_ch else city_name
        plan_key      = f"pinc_{ad_id}_{pin_hours}h"
    # Итоговая цена с учётом длительности
    duration_multipliers = {24: 1.0, 72: 1.8, 168: 3.5}
    price = round(base_price * duration_multipliers.get(pin_hours, 1.0))

    # ── Автоматически применяем сохранённый промокод ─────────────────────────
    # Если пользователь ввёл промокод из главного меню (общий случай),
    # он сохраняется в context.user_data['promo_code']. Здесь применяем его
    # к цене и показываем ссылки уже со скидкой — без необходимости вводить
    # промокод повторно на странице оплаты.
    saved_promo_code = context.user_data.get('promo_code')
    applied_promo_discount = 0
    applied_promo_label = ""
    if saved_promo_code:
        _saved_promo = db.get_promocode(saved_promo_code)
        if _saved_promo and not db.check_promocode_used(_saved_promo['id'], user.id):
            applied_promo_discount = _saved_promo['discount_percent']
            applied_promo_label    = saved_promo_code
            price_before = price
            price = round(price * (1 - applied_promo_discount / 100))
            logger.info(
                f"pin_pay: автоприменение промокода {saved_promo_code} "
                f"({applied_promo_discount}%) для user {user.id}: "
                f"{price_before} ₽ → {price} ₽"
            )


    crypto_url = ''  # будет заменён на pay_url из CryptoBot инвойса ниже
    pin_invoice_data = None

    # ── Создаём крипто-счёт Crypto Bot для закрепа ───────────────────────────
    if crypto_bot_api:
        try:
            pin_invoice_data = await create_pin_crypto_invoice(
                user_id   = user.id,
                ad_id     = ad_id,
                pin_type  = pin_type,
                price_rub = price,
                pin_hours = pin_hours,
                promo_code=applied_promo_label or "",
            )
            if pin_invoice_data:
                crypto_url = pin_invoice_data["pay_url"]
        except Exception as _ce:
            logger.error(f"pin_pay crypto invoice error: {_ce}")

    # ── Создаём ссылку PayAnyWay СБП (с комиссией 5%) ───────────────────────
    crypto_price_with_fee = round(price * 1.03)
    sbp_price_with_fee = round(price * 1.05)

    paw_url, paw_order_id = create_payanyway_pin_url(
        user_id   = user.id,
        ad_id     = ad_id,
        pin_type  = pin_type,
        pin_hours = pin_hours,
        amount_rub= sbp_price_with_fee,
        promo_code= applied_promo_label or "",
    )

    context.user_data['pinning_ad_id']   = ad_id
    context.user_data['pinning_type']    = pin_type
    context.user_data['pinning_price']   = price
    context.user_data['pinning_hours']   = pin_hours
    if pin_invoice_data:
        context.user_data['pin_crypto_invoice_id'] = pin_invoice_data["invoice_id"]

    confirm_cb = f"pin_confirm:{pin_type}:{ad_id}"
    usdt_hint  = f"\n≈ {pin_invoice_data['amount_usdt']} USDT" if pin_invoice_data else ""

    keyboard = []
    # Кнопка СБП (PayAnyWay) — главный способ оплаты
    keyboard.append([InlineKeyboardButton(
        f"→ СБП — {sbp_price_with_fee} ₽", url=paw_url
    )])
    # Кнопка крипты
    if crypto_url:
        keyboard.append([InlineKeyboardButton(
            EM_DIAMOND + " USDT", url=crypto_url
        )])
    # Кнопка проверки крипто-оплаты (если инвойс создан)
    _pin_crypto_inv_id = pin_invoice_data["invoice_id"] if pin_invoice_data else 0
    if _pin_crypto_inv_id:
        keyboard.append([InlineKeyboardButton(
            EM_REFRESH + " Я оплатил криптой — проверить",
            callback_data=f"check_payment:{_pin_crypto_inv_id}"
        )])
    if not applied_promo_label:
        keyboard.append([InlineKeyboardButton(EM_DOT + " Ввести промокод", callback_data="enter_promo")])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data=f"pin_ad:{ad_id}")])

    usdt_note = f"\nUSDT: <b>{crypto_price_with_fee} ₽</b>{usdt_hint}" if crypto_url else ""
    sbp_note  = f"\nСБП: <b>{sbp_price_with_fee} ₽</b>"

    # Строка о скидке (если промокод применён)
    promo_line = (
        f"\n{EM_OK} Промокод <b>{applied_promo_label}</b> — скидка <b>{applied_promo_discount}%</b>"
        if applied_promo_label else ""
    )

    # Длительность → человекочитаемо
    _dur_label = {24: "24 часа", 72: "3 дня", 168: "7 дней"}.get(pin_hours, f"{pin_hours}ч")

    await safe_edit_message(query,
        f"Закрепление объявления\n\n"
        f"<b>{ad['title']}</b>\n"
        f"Канал: {channel_label}\n"
        f"Длительность: <b>{_dur_label}</b>\n\n"
        f"Стоимость: <b>{price} ₽</b>{sbp_note}{usdt_note}"
        f"{promo_line}\n\n"
        f"→ Нажмите «Оплатить СБП» — вас перенаправит в банк.\n"
        f"{EM_OK} Закреп активируется <b>автоматически</b> сразу после оплаты.",
        keyboard, parse_mode="HTML"
    )


