async def admin_pin_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Админ подтверждает закреп"""
    query = update.callback_query
    await safe_answer(query, )
    parts    = query.data.split(":")
    # Формат: admin_pin_confirm:rf:ad_id:user_id  или  admin_pin_confirm:city:ad_id:user_id
    pin_type = parts[1]
    ad_id    = int(parts[2])
    user_id  = int(parts[3])
    ad       = db.get_ad(ad_id)
    if not ad:
        await safe_answer(query, "Объявление не найдено", show_alert=True)
        return

    _pin_hours = context.user_data.get('pinning_hours', 24)
    _now_msk = get_moscow_time()
    _base_dt = _now_msk
    _existing_field = 'pinned_until_city' if pin_type == "city" else 'pinned_until'
    _existing_val = ad.get(_existing_field)
    if _existing_val:
        try:
            _existing_dt = _safe_isoparse(_existing_val)
            if _existing_dt and _existing_dt > _now_msk:
                _base_dt = _existing_dt
        except Exception:
            pass
    pinned_until = (_base_dt + timedelta(hours=_pin_hours)).isoformat()
    cursor = db.conn.cursor()

    # Определяем канал для закрепления
    if pin_type == "city":
        city         = (ad.get('city') or '').strip()
        target_chat  = CITY_CHANNELS.get(city, ADMIN_CHANNEL_ID)
        ch_label     = f"{city} (городской канал)"
    else:
        target_chat  = ADMIN_CHANNEL_ID
        ch_label     = "Основной канал (вся Удмуртия)"

    if pin_type == "city":
        cursor.execute("UPDATE ads SET pinned_until_city=?, pinned_chat_id_city=? WHERE id=?", (pinned_until, str(target_chat), ad_id))
    else:
        cursor.execute("UPDATE ads SET pinned_until=?, pinned_chat_id=? WHERE id=?", (pinned_until, str(target_chat), ad_id))
    db.conn.commit()

    # Закрепляем в канале
    if pin_type == "city":
        _msg_id_to_pin = ad.get('city_channel_message_id')
    else:
        _msg_id_to_pin = ad.get('channel_message_id')

    _job_suffix = "city" if pin_type == "city" else "main"
    if _msg_id_to_pin:
        try:
            await context.bot.pin_chat_message(
                chat_id=target_chat,
                message_id=_msg_id_to_pin,
                disable_notification=True
            )
            context.job_queue.run_once(
                unpin_ad_callback,
                when=timedelta(hours=_pin_hours),
                data={'ad_id': ad_id, 'message_id': _msg_id_to_pin, 'chat_id': target_chat, 'pin_type': pin_type},
                name=f"unpin_ad_{ad_id}_{_job_suffix}"
            )
        except Exception as e:
            logger.error(f"pin channel error: {e}")

    await query.edit_message_caption(
        caption=query.message.caption + f"\n\n{EM_DOT} Закреп подтверждён",
        reply_markup=None
    )
    try:
        await context.bot.send_message(
            chat_id=user_id,
            text=(
                f"Закреп подтверждён\n\n"
                f"<b>{ad['title']}</b>\n"
                f"Канал: {ch_label}\n"
                f"Объявление закреплено на {_pin_hours} ч."
            ),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_my_ad:{ad_id}")
            ]])
        )
    except Exception:
        pass


