async def show_main_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    user_data = db.get_user(user.id)

    # Mini App base URL (задается в .env / Amvera)
    MINIAPP_URL = os.environ.get("MINIAPP_URL", "https://mini.polka.local")

    def _mbtn(text, cb):
        """Кнопка главного меню с синим стилем (Bot API 9.4)."""
        return InlineKeyboardButton(text, callback_data=cb, style="primary")

    def _wbtn(text, path):
        """Кнопка открытия Mini App. HashRouter: путь через /#/"""
        return InlineKeyboardButton(text, web_app=WebAppInfo(url=f"{MINIAPP_URL}/#{path}"))

    # ТЗ §6: пользовательские функции живут в Mini App — главное действие
    # меню бота это "Открыть Полку". Старые callback-handlers (create_ad,
    # search, my_ads, favorites, profile) НЕ удалены и работают как fallback.
    keyboard = [
        [_wbtn("Открыть Полку", "/")],
        # Главное для перекупа: задать, что ловить, и смотреть находки
        [_wbtn("Что ловить",    "/hunt"),
         _wbtn("Находки",       "/")],
        [_wbtn("Разместить",    "/create"),
         _wbtn("Мои объявления", "/my")],
        [_wbtn("Избранное",     "/favorites"),
         _wbtn("Сообщения",     "/chats")],
        [_wbtn("Профиль",       "/profile"),
         # Возврат в это же меню: нужно, когда человек ушёл вглубь
         # какого-то сценария и хочет вернуться
         _mbtn("В меню",        "back_to_menu")],
    ]

    cursor = db.conn.cursor()
    cursor.execute("SELECT COUNT(*) FROM ads WHERE user_id=? AND status='active'", (user.id,))
    active_ads = cursor.fetchone()[0]
    if active_ads:
        ads_hint = f"У вас {active_ads} активных объявлений"
    else:
        ads_hint = "Разместите первое — это займёт 30 секунд"
    text = (
        f"<b>Полка — площадка объявлений Удмуртии</b>\n\n"
        f"Привет, {user.first_name}! {ads_hint}.\n\n"
        f"Лента, поиск, размещение и сообщения — в приложении "
        f"по кнопке «Открыть Полку»."
    )
    
    markup = InlineKeyboardMarkup(keyboard)
    if update.message:
        try:
            await update.message.reply_photo(photo=BANNERS["welcome"], caption=text, reply_markup=markup, parse_mode="HTML")
        except Exception:
            await update.message.reply_text(text, reply_markup=markup, parse_mode="HTML")
    else:
        try:
            await update.callback_query.message.reply_photo(photo=BANNERS["welcome"], caption=text, reply_markup=markup, parse_mode="HTML")
        except Exception:
            await update.callback_query.message.reply_text(text, reply_markup=markup, parse_mode="HTML")
        try:
            await update.callback_query.delete_message()
        except Exception:
            pass

    return States.MAIN_MENU

# Мои объявления с кнопкой снять с публикации
async def my_ads(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    context.user_data['_nav_back'] = 'my_ads'
    context.user_data.pop('last_search', None)
    
    try:
        user = update.effective_user
        
        # Получаем все объявления пользователя - ОБНОВЛЯЕМ ДАННЫЕ КАЖДЫЙ РАЗ
        all_ads = db.get_user_ads(user.id)
        active_ads = [ad for ad in all_ads if ad['status'] == 'active']
        moderation_ads = [ad for ad in all_ads if ad['status'] == 'moderation']
        inactive_ads = [ad for ad in all_ads if ad['status'] == 'inactive']
        
        # Считаем общее количество просмотров ТОЛЬКО активных объявлений
        cursor = db.conn.cursor()
        cursor.execute("SELECT SUM(views) FROM ads WHERE user_id = ? AND status = 'active'", (user.id,))
        total_views = cursor.fetchone()[0] or 0
        
        # Реальные просмотры постов каналов (TG web + MAX)
        try:
            live_total = await get_live_views_sum(active_ads)
            if live_total > total_views:
                total_views = live_total
        except Exception as e:
            logger.warning(f"my_ads live views: {e}")
        
        text = "Мои объявления\n\n"
        
        if not all_ads:
            text += "У вас пока нет объявлений.\n\nСоздайте первое объявление!"
            keyboard = [
                [InlineKeyboardButton("+ Разместить объявление", callback_data="create_ad")],
                [InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]
            ]
        else:
            text += "Статистика:\n"
            text += f"Активных: {len(active_ads)}\n"
            text += f"В архиве: {len(inactive_ads)}\n"
            text += f"Просмотров: {total_views}\n"
            
            if moderation_ads:
                text += f"{EM_DOT} На модерации: {len(moderation_ads)}\n"
            
            keyboard = [
                [InlineKeyboardButton(f"{EM_ARROW_R} Активные ({len(active_ads)})", callback_data="my_ads_active")],
                [InlineKeyboardButton(f"{EM_ARROW_R} Архив ({len(inactive_ads)})", callback_data="my_ads_archive")],
            ]
            
            if moderation_ads:
                keyboard.append([InlineKeyboardButton(f"{EM_DOT} На модерации ({len(moderation_ads)})", callback_data="show_moderation_ads")])
            
            keyboard.append([InlineKeyboardButton("+ Разместить объявление", callback_data="create_ad")])
            keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")])
        
        await safe_edit_message(query, text, keyboard)
    except Exception as e:
        logger.error(f"Ошибка в my_ads: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить объявления. Попробуйте ещё раз.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
        except Exception:
            pass
async def my_ads_active(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Показывает список активных объявлений"""
    query = update.callback_query
    await safe_answer(query, )
    
    try:
        user = update.effective_user
        
        # Получаем активные объявления
        all_ads = db.get_user_ads(user.id)
        active_ads = [ad for ad in all_ads if ad['status'] == 'active']
        
        if not active_ads:
            text = "Активных объявлений нет."
            keyboard = [[InlineKeyboardButton(EM_ARROW_L + " Мои объявления", callback_data="my_ads")]]
        else:
            text = f"Активные объявления: {len(active_ads)}\n\n"

            # Реальные просмотры постов каналов (TG web + MAX) по каждому объявлению
            live_views = {}
            try:
                for ad in active_ads:
                    live = await get_live_channel_views(ad)
                    live_sum = (live.get('tg') or 0) + (live.get('max') or 0)
                    live_views[ad['id']] = max(int(ad.get('views', 0) or 0), live_sum)
            except Exception as e:
                logger.warning(f"my_ads_active live views: {e}")

            for i, ad in enumerate(active_ads, 1):
                pinned = f"{EM_DIAMOND} " if ad.get('pinned_until') else ""
                views  = live_views.get(ad['id'], ad.get('views', 0))
                tip    = " · ↑ поднять?" if views < 5 and not ad.get('pinned_until') else ""
                text += f"{i}. {pinned}{ad['title']}\n"
                text += f" {ad['price']} ₽ · {views} просм{tip}\n\n"

            keyboard = []
            for ad in active_ads:
                title_short = ad['title'][:30] + "..." if len(ad['title']) > 30 else ad['title']
                keyboard.append([
                    InlineKeyboardButton(
                        f"{title_short} {EM_DOT} {live_views.get(ad['id'], ad.get('views', 0))} просм.",
                        callback_data=f"view_my_ad:{ad['id']}"
                    )
                ])
            
            keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Мои объявления", callback_data="my_ads")])
        
        await safe_edit_message(query, text, keyboard)
    except Exception as e:
        logger.error(f"Ошибка в my_ads_active: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить объявления.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="my_ads")]])
        except Exception:
            pass
