async def view_my_ad(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    # Сбрасываем состояние редактирования поля (если пользователь нажал «К объявлению»)
    context.user_data.pop("editing_ad_id", None)
    context.user_data.pop("editing_field", None)
    ad_id = int(query.data.split(":")[1])
    user = update.effective_user
    
    ad = db.get_ad(ad_id)
    if not ad or ad['user_id'] != user.id:
        await safe_edit_message(query, "Объявление не найдено или нет доступа")
        return
    
    status_label = AD_STATUS_LABELS.get(ad['status'], ad['status'])
    pinned_str = ""
    _now = get_moscow_time()
    _pin_parts = []
    if ad.get('pinned_until'):
        try:
            _dt = datetime.fromisoformat(ad['pinned_until'])
            if _dt > _now:
                _rem = _dt - _now
                _h = int(_rem.total_seconds() // 3600)
                _m = int((_rem.total_seconds() % 3600) // 60)
                _pin_parts.append(f"{EM_DIAMOND} Основной канал: осталось <b>{_h}ч {_m}мин</b>")
        except Exception:
            pass
    if ad.get('pinned_until_city'):
        try:
            _dt2 = datetime.fromisoformat(ad['pinned_until_city'])
            if _dt2 > _now:
                _rem2 = _dt2 - _now
                _h2 = int(_rem2.total_seconds() // 3600)
                _m2 = int((_rem2.total_seconds() % 3600) // 60)
                _city = (ad.get('city') or 'городской').strip()
                _pin_parts.append(f"{EM_DIAMOND} {_city}: осталось <b>{_h2}ч {_m2}мин</b>")
        except Exception:
            pass
    if _pin_parts:
        pinned_str = "\n" + "\n".join(_pin_parts)
    views = ad.get('views', 0)
    # Реальные просмотры поста в каналах (TG web + MAX)
    try:
        live = await get_live_channel_views(ad)
        live_sum = (live.get('tg') or 0) + (live.get('max') or 0)
        if live_sum > views:
            views = live_sum
    except Exception as e:
        logger.warning(f"view_my_ad live views ad {ad_id}: {e}")
    contact_clicks = db.get_ad_contact_clicks(ad_id)

    expires_str = ""
    auto_renew_str = ""
    if ad.get('expires_at'):
        expires_str = f"\nДействует до: {ad['expires_at'][:10]}"
        auto_renew_str = f" {EM_REFRESH} Автопродление: {'вкл.' if ad.get('auto_renew') else 'выкл.'}"

    text = (
        f"<b>{ad['title']}</b>\n\n"
        f"Цена: <b>{ad['price']} ₽</b>\n"
        f"Категория: {ad['category']}\n"
        f"Город: {ad.get('city') or '—'}\n"
        f"Статус: {status_label}{pinned_str}{expires_str}{auto_renew_str}\n\n"
        f"Просмотров: {views} {EM_DOT} Обращений: {contact_clicks}\n"
        f"Опубликовано: {ad['created_at'][:10]}\n\n"
        f"{ad['description'][:200]}{'...' if len(ad.get('description','')) > 200 else ''}\n\n"
        f"Контакт: {ad['contact_info']}"
    )
    
    keyboard = []

    if ad['status'] == 'active':
        keyboard.append([
            InlineKeyboardButton("✦ Закрепить", callback_data=f"pin_ad:{ad_id}"),
        ])
        keyboard.append([
            InlineKeyboardButton(EM_ARROW_R + " Поделиться", callback_data=f"share_ad:{ad_id}"),
            InlineKeyboardButton(EM_DOT + " Аналитика",      callback_data=f"ad_analytics:{ad_id}"),
        ])
        keyboard.append([
            InlineKeyboardButton(EM_FAIL + " Снять",       callback_data=f"deactivate_ad:{ad_id}"),
            InlineKeyboardButton(EM_DOT + " Редактировать", callback_data=f"edit_ad:{ad_id}"),
        ])
    elif ad['status'] == 'inactive':
        keyboard.append([
            InlineKeyboardButton(EM_OK + " Опубликовать снова", callback_data=f"reactivate_ad:{ad_id}"),
            InlineKeyboardButton(EM_FAIL + " Удалить", callback_data=f"delete_ad_completely:{ad_id}")
        ])
        keyboard.append([
            InlineKeyboardButton("+ Дублировать", callback_data=f"duplicate_ad:{ad_id}")
        ])
    
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Мои объявления", callback_data="my_ads")])
    
    if ad['photos']:
        try:
            if len(ad['photos']) == 1:
                resolved = await resolve_ad_photo(ad['photos'][0])
                if resolved is None:
                    raise ValueError("Фото недоступно (не удалось разрешить ссылку)")
                await query.message.reply_photo(
                    photo=resolved,
                    caption=text,
                    reply_markup=InlineKeyboardMarkup(keyboard),
                    parse_mode=ParseMode.HTML
                )
                await query.delete_message()
            else:
                resolved_photos = [await resolve_ad_photo(p) for p in ad['photos']]
                resolved_photos = [p for p in resolved_photos if p is not None]
                if not resolved_photos:
                    raise ValueError("Фото недоступны (не удалось разрешить ссылки)")
                media_group = [InputMediaPhoto(
                    media=resolved_photos[0], caption=text, parse_mode=ParseMode.HTML
                )]
                for photo in resolved_photos[1:]:
                    media_group.append(InputMediaPhoto(photo))
                await query.message.reply_media_group(media=media_group)
                await query.message.reply_text(
                    "Управление объявлением:",
                    reply_markup=InlineKeyboardMarkup(keyboard)
                )
                await query.delete_message()
        except Exception as e:
            logger.error(f"view_my_ad photo error: {e}")
            await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    else:
        await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)

async def deactivate_ad_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    try:
        parts = query.data.split(":")
        ad_id = int(parts[1])
        confirmed = len(parts) > 2 and parts[2] == "confirmed"
        user = update.effective_user
        
        ad = db.get_ad(ad_id)
        if not ad or ad['user_id'] != user.id:
            await safe_edit_message(query, "Объявление не найдено или нет доступа")
            return

        # Если объявление закреплено — показываем предупреждение и ждём подтверждения
        if not confirmed and ad.get('pinned_until'):
            try:
                pinned_until = datetime.fromisoformat(ad['pinned_until'])
                if pinned_until > get_moscow_time():
                    remaining = pinned_until - get_moscow_time()
                    h = int(remaining.total_seconds() // 3600)
                    m = int((remaining.total_seconds() % 3600) // 60)
                    await safe_edit_message(query,
                        f"{EM_WARN} <b>Внимание!</b>\n\n"
                        f"Объявление «<b>{ad['title']}</b>» сейчас закреплено — осталось <b>{h}ч {m}мин</b>.\n\n"
                        f"При снятии объявления закреп будет удалён автоматически. "
                        f"Средства за закрепление не возвращаются.\n\n"
                        f"Вы уверены, что хотите снять объявление?",
                        [
                            [InlineKeyboardButton(EM_OK + " Да, снять",    callback_data=f"deactivate_ad:{ad_id}:confirmed")],
                            [InlineKeyboardButton(EM_FAIL + " Отмена",     callback_data=f"view_my_ad:{ad_id}")],
                        ],
                        parse_mode="HTML"
                    )
                    return
            except Exception:
                pass

        # Пытаемся удалить сообщение из канала
        deleted_from_channel = await delete_ad_from_channel(ad_id, context)
        
        # Деактивируем объявление в базе
        success = db.deactivate_ad(ad_id)
        
        if success:
            text = "Объявление снято с публикации.\n\n"
            if deleted_from_channel:
                text += "Сообщение удалено из канала."
            else:
                text += "Не удалось удалить сообщение из канала, но объявление скрыто из поиска."
            
            await safe_edit_message(query, text)
            db.log_action(user.id, "ad_deactivated", f"Ad ID: {ad_id}")
        else:
            await safe_edit_message(query, "Не удалось снять объявление с публикации")
        
        await my_ads(update, context)
    except Exception as e:
        logger.error(f"Ошибка в deactivate_ad_handler: {e}")
        try:
            await safe_edit_message(query, "Не удалось снять объявление. Попробуйте ещё раз.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="my_ads")]])
        except Exception:
            pass
async def delete_ad_completely(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    parts = query.data.split(":")
    ad_id = int(parts[1])
    confirmed = len(parts) > 2 and parts[2] == "confirmed"
    user = update.effective_user
    
    ad = db.get_ad(ad_id)
    if not ad or ad['user_id'] != user.id:
        await safe_edit_message(query, "Объявление не найдено или нет доступа")
        return

    # Если объявление закреплено — показываем предупреждение и ждём подтверждения
    if not confirmed and ad.get('pinned_until'):
        try:
            pinned_until = datetime.fromisoformat(ad['pinned_until'])
            if pinned_until > get_moscow_time():
                remaining = pinned_until - get_moscow_time()
                h = int(remaining.total_seconds() // 3600)
                m = int((remaining.total_seconds() % 3600) // 60)
                await safe_edit_message(query,
                    f"{EM_WARN} <b>Внимание!</b>\n\n"
                    f"Объявление «<b>{ad['title']}</b>» сейчас закреплено — осталось <b>{h}ч {m}мин</b>.\n\n"
                    f"При удалении объявления закреп будет снят автоматически. "
                    f"Средства за закрепление не возвращаются.\n\n"
                    f"Вы уверены, что хотите удалить объявление?",
                    [
                        [InlineKeyboardButton(EM_OK + " Да, удалить",  callback_data=f"delete_ad_completely:{ad_id}:confirmed")],
                        [InlineKeyboardButton(EM_FAIL + " Отмена",     callback_data=f"view_my_ad:{ad_id}")],
                    ],
                    parse_mode="HTML"
                )
                return
        except Exception:
            pass

    # Удаляем из канала все сообщения (включая медиагруппу)
    if ad.get('channel_message_id'):
        try:
            message_id = ad['channel_message_id']
            # Пытаемся удалить до 10 последовательных сообщений
            for i in range(10):
                try:
                    await context.bot.delete_message(
                        chat_id=ADMIN_CHANNEL_ID, 
                        message_id=message_id + i
                    )
                except Exception as _e:
                    if i > 0:
                        break
        except Exception as e:
            logger.error(f"Не удалось удалить сообщение из канала: {e}")
    
    # Удаляем из избранного
    cursor = db.conn.cursor()
    cursor.execute("DELETE FROM favorites WHERE ad_id = ?", (ad_id,))
    
    # Удаляем объявление из базы данных
    cursor.execute("DELETE FROM ads WHERE id = ?", (ad_id,))
    db.conn.commit()
    
    await safe_edit_message(query, "Объявление удалено")
    db.log_action(user.id, "ad_deleted_completely", f"Ad ID: {ad_id}")
    
    await my_ads(update, context)

async def reactivate_ad(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    try:
        ad_id = int(query.data.split(":")[1])
        user = update.effective_user
        
        ad = db.get_ad(ad_id)
        if not ad or ad['user_id'] != user.id:
            await safe_edit_message(query, "Объявление не найдено или нет доступа")
            return
        
        # Отправляем объявление на повторную модерацию
        db.update_ad(ad_id, status='moderation', channel_message_id=None)
        await safe_edit_message(query,
            f"{EM_OK} Объявление отправлено на модерацию.\n"
            "После проверки оно появится в канале.")
        db.log_action(user.id, "ad_reactivated_pending", f"Ad ID: {ad_id}")
        # Уведомляем админов
        for admin_id in ADMIN_USER_IDS:
            try:
                await context.bot.send_message(
                    chat_id=admin_id,
                    text=(f"{EM_WARN} Объявление #{ad_id} повторно выставлено — требует модерации.\n"
                          f"Название: {ad.get('title', '')}"),
                    reply_markup=InlineKeyboardMarkup([[
                        InlineKeyboardButton(EM_OK + " Модерация", callback_data="admin_moderation")
                    ]])
                )
            except Exception as _e:
                logger.warning(f"Не удалось уведомить админа {admin_id}: {_e}")
        
        await my_ads(update, context)
    except Exception as e:
        logger.error(f"Ошибка в reactivate_ad: {e}")
        try:
            await safe_edit_message(query, "Не удалось опубликовать объявление. Попробуйте ещё раз.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="my_ads")]])
        except Exception:
            pass

# Избранное - УЛУЧШЕННОЕ UX
async def favorites(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    user = update.effective_user
    # Запоминаем: кнопка «← Назад» из объявления должна вернуть сюда
    context.user_data['_nav_back'] = 'favorites'
    context.user_data.pop('last_search', None)
    
    cursor = db.conn.cursor()
    # ОБНОВЛЯЕМ ДАННЫЕ КАЖДЫЙ РАЗ - проверяем актуальность избранного
    cursor.execute('''
        SELECT a.* FROM ads a
        JOIN favorites f ON a.id = f.ad_id
        WHERE f.user_id = ? AND a.status = 'active'
        ORDER BY f.added_at DESC
        LIMIT 20
    ''', (user.id,))
    
    favorite_ads = cursor.fetchall()
    
    # Также подсчитываем общее количество избранных (включая неактивные, для статистики)
    cursor.execute('SELECT COUNT(*) FROM favorites WHERE user_id = ?', (user.id,))
    total_favorites = cursor.fetchone()[0]
    
    if not favorite_ads:
        text = "<b>Избранных объявлений пока нет</b>\n\nДобавляйте объявления в избранное при просмотре."
        keyboard = [
            [InlineKeyboardButton(EM_DOT + " Поиск", callback_data="search")],
            [InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]
        ]
    else:
        text = f"<b>Избранное:</b> {len(favorite_ads)} объявлений\n\n"
        
        # Формируем текст с превью как в поиске
        for i, ad_tuple in enumerate(favorite_ads, 1):
            # Преобразуем tuple в словарь
            ad = {
                'id': ad_tuple[0],
                'title': ad_tuple[2],
                'price': ad_tuple[4],
                'category': ad_tuple[7] if len(ad_tuple) > 7 else 'Другое'
            }
            text += f"<b>{ad['title']}</b>\n{ad['price']} ₽ {EM_DOT} {ad['category']}\n\n"
        
        # Формируем кнопки для просмотра объявлений
        keyboard = []
        for i, ad_tuple in enumerate(favorite_ads, 1):
            ad_id = ad_tuple[0]
            ad_title = ad_tuple[2]
            ad_price = ad_tuple[4]
            title_short = ad_title[:25] + "..." if len(ad_title) > 25 else ad_title
            keyboard.append([InlineKeyboardButton(
                f"{title_short} — {ad_price} ₽",
                callback_data=f"view_ad:{ad_id}"
            )])
        
        keyboard.append([InlineKeyboardButton(EM_DOT + " Поиск", callback_data="search")])
        keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")])
    
    try:
        await query.message.reply_photo(
                photo=BANNERS["favorites"],
            caption=text,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.HTML
        )
        await query.delete_message()
    except Exception:
        await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)

