async def compute_photo_hash(bot, file_id: str) -> Optional[str]:
    """
    Скачивает фото из Telegram и вычисляет комбинированный хэш:
    pHash (16x16=256 бит) — основной, устойчив к сжатию и небольшим правкам.
    Возвращает строку 'phash:XXXX' для хранения в БД.
    """
    if not IMAGEHASH_AVAILABLE:
        return None
    try:
        tg_file = await bot.get_file(file_id)
        buf = _io.BytesIO()
        await tg_file.download_to_memory(buf)
        buf.seek(0)
        img = Image.open(buf).convert("RGB")
        ph = imagehash.phash(img, hash_size=16)       # 256-bit pHash
        return str(ph)
    except Exception as e:
        logger.error(f"compute_photo_hash error: {e}")
        return None


async def compute_photo_hashes_multi(bot, file_id: str) -> dict:
    """
    Вычисляет несколько типов хэшей для одного фото:
    - phash: perceptual hash (устойчив к ресайзу, JPEG-артефактам)
    - ahash: average hash (быстрый, простой)
    - dhash: difference hash (устойчив к яркости)
    Возвращает {'phash': str, 'ahash': str, 'dhash': str} или {}.
    """
    if not IMAGEHASH_AVAILABLE:
        return {}
    try:
        tg_file = await bot.get_file(file_id)
        buf = _io.BytesIO()
        await tg_file.download_to_memory(buf)
        buf.seek(0)
        img = Image.open(buf).convert("RGB")
        return {
            'phash': str(imagehash.phash(img, hash_size=16)),
            'ahash': str(imagehash.average_hash(img, hash_size=16)),
            'dhash': str(imagehash.dhash(img, hash_size=16)),
        }
    except Exception as e:
        logger.error(f"compute_photo_hashes_multi error: {e}")
        return {}


async def extract_photo_tags_hf(bot, file_id: str) -> list:
    """
    Извлекает теги из фото через Groq Vision API (халявный, без пополнений).
    Ключ: GROQ_API_KEY в переменных окружения (получить: console.groq.com/keys).
    """
    api_key = os.environ.get("GROQ_API_KEY", "") or os.environ.get("CLODEX_API_KEY", "")
    if not api_key:
        logger.info("GROQ_API_KEY не задан — теги недоступны")
        return []
    logger.info(f"extract_photo_tags Groq Vision: file_id={file_id[:20]}")
    try:
        tg_file = await bot.get_file(file_id)
        buf = _io.BytesIO()
        await tg_file.download_to_memory(buf)
        image_bytes = buf.getvalue()
        image_b64 = _base64.b64encode(image_bytes).decode()

        import aiohttp as _aiohttp
        groq_model = os.environ.get("GROQ_VISION_MODEL", "qwen/qwen3.6-27b")
        payload = {
            "model": groq_model,
            "max_tokens": 200,
            "messages": [{
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": (
                            "Посмотри на фото и назови 5-8 ключевых слов на русском языке "
                            "которые описывают товар на изображении. "
                            "Это нужно для поиска похожих объявлений на маркетплейсе. "
                            "Отвечай ТОЛЬКО словами через запятую, без пояснений. "
                            "Например: кроссовки, Nike, спортивная обувь, белые, размер"
                        )
                    },
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": f"data:image/jpeg;base64,{image_b64}"
                        }
                    }
                ]
            }]
        }

        async with _aiohttp.ClientSession() as session:
            async with session.post(
                "https://api.groq.com/openai/v1/chat/completions",
                json=payload,
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "content-type": "application/json",
                    "User-Agent": "Mozilla/5.0",
                },
                timeout=_aiohttp.ClientTimeout(total=90)
            ) as resp:
                if resp.status != 200:
                    logger.warning(f"Groq Vision error {resp.status}: {await resp.text()}")
                    return []
                data = await resp.json()

        text = _strip_think(data.get("choices", [{}])[0].get("message", {}).get("content", ""))
        logger.info(f"Groq Vision tags: {text[:100]}")
        tags = [t.strip().lower() for t in text.split(",") if t.strip()]
        return tags[:10]

    except Exception as e:
        logger.error(f"extract_photo_tags Groq Vision error: {e}")
        return []

def phash_distance(h1: str, h2: str) -> int:
    """Расстояние Хэмминга между двумя pHash строками."""
    if not IMAGEHASH_AVAILABLE or not h1 or not h2:
        return 999
    try:
        return imagehash.hex_to_hash(h1) - imagehash.hex_to_hash(h2)
    except Exception:
        return 999
# CLIP EMBEDDING — через HF Inference API (без torch, без локальной модели)
# ─────────────────────────────────────────────────────────────────────────────

import struct as _struct
import math as _math

CLIP_HF_MODEL = "radames/blip_image_embeddings"  # единственная модель с image embeddings на HF Inference API
HF_API_TOKEN  = os.environ.get("HF_API_TOKEN", "")  # только из переменных окружения


async def get_clip_embedding_hf(bot, file_id: str):
    """CLIP embedding отключён — HuggingFace недоступен с Amvera."""
    return None


def _cosine_sim(v1, v2):
    """Косинусное сходство двух нормализованных векторов (pure Python)."""
    return sum(a * b for a, b in zip(v1, v2))

def _emb_to_bytes(emb):
    """Сериализует список float в bytes."""
    return _struct.pack(f"{len(emb)}f", *emb)

def _bytes_to_emb(b):
    """Десериализует bytes в список float."""
    if not b:
        return None
    n = len(b) // 4
    return list(_struct.unpack(f"{n}f", b))


def find_similar_ads_by_embedding(query_emb, limit=10):
    """Ищет похожие объявления по CLIP-эмбеддингу."""
    cursor = db.conn.cursor()
    cursor.execute(
        "SELECT id, title, price, city, photos, clip_embedding FROM ads "
        "WHERE status='active' AND clip_embedding IS NOT NULL"
    )
    results = []
    for row in cursor.fetchall():
        db_emb = _bytes_to_emb(row["clip_embedding"])
        if db_emb is None:
            continue
        sim = _cosine_sim(query_emb, db_emb)
        r = dict(row)
        r["similarity"] = sim
        r["_match"] = f"{int(sim*100)}% совпадение"
        results.append(r)
    results.sort(key=lambda x: x["similarity"], reverse=True)
    return results[:limit]


def find_duplicate_ads_by_hash(image_hash, max_distance=5):
    """Ищет дубликаты по pHash."""
    if not IMAGEHASH_AVAILABLE:
        return []
    cursor = db.conn.cursor()
    cursor.execute("SELECT id, title, photo_hash FROM ads WHERE photo_hash IS NOT NULL AND status != 'deleted'")
    duplicates = []
    for row in cursor.fetchall():
        try:
            dist = imagehash.hex_to_hash(image_hash) - imagehash.hex_to_hash(row["photo_hash"])
            if dist <= max_distance:
                duplicates.append({"id": row["id"], "title": row["title"], "distance": dist})
        except Exception:
            pass
    duplicates.sort(key=lambda x: x["distance"])
    return duplicates


# CLIP EMBEDDING — через HF Inference API (без torch, без локальной модели)


def _combined_hash_distance(query_hashes: dict, ad_hash_str: str) -> int:
    """
    Вычисляет минимальное расстояние между хэшем запроса и хэшем объявления.
    Поддерживает старый формат (просто строка phash) и новый.
    Берём минимум из phash и ahash если оба доступны — это даёт
    лучшую устойчивость к разным условиям съёмки.
    """
    if not ad_hash_str:
        return 999
    # Все хэши запроса
    q_phash = query_hashes.get('phash', '')
    q_ahash = query_hashes.get('ahash', '')
    q_dhash = query_hashes.get('dhash', '')

    distances = []
    # Объявление хранит только phash (старый формат) или строку
    ad_ph = ad_hash_str  # legacy: просто строка phash

    if q_phash and ad_ph:
        distances.append(phash_distance(q_phash, ad_ph))
    if q_ahash and ad_ph:
        distances.append(phash_distance(q_ahash, ad_ph))
    if q_dhash and ad_ph:
        distances.append(phash_distance(q_dhash, ad_ph))

    return min(distances) if distances else 999


def search_by_photo_hash(photo_hash: str, threshold: int = 20, limit: int = 30,
                          query_hashes: dict = None) -> List[Dict]:
    """
    Ищет объявления с похожим фото по хэшу.
    - threshold=20 из 256 бит (~8% разницы) — находит похожие фото,
      снятые с другого угла или при другом освещении.
    - query_hashes: словарь {'phash','ahash','dhash'} для multi-hash сравнения.
      Если не передан — используется только photo_hash как phash.
    Сходство считается как процент совпадения бит (100% = идентично).
    """
    if query_hashes is None:
        query_hashes = {'phash': photo_hash}

    cursor = db.conn.cursor()
    cursor.execute(
        "SELECT * FROM ads WHERE status='active' AND photo_hash IS NOT NULL"
    )
    candidates = []
    for row in cursor.fetchall():
        ad = dict(row)
        dist = _combined_hash_distance(query_hashes, ad["photo_hash"])
        if dist <= threshold:
            similarity = round((1 - dist / 256) * 100)
            ad["_similarity"] = similarity
            ad["_hash_dist"] = dist
            ad["photos"] = json.loads(ad["photos"]) if ad["photos"] else []
            candidates.append(ad)
    # Сортируем по похожести (desc), потом по дате
    candidates.sort(key=lambda x: (-x["_similarity"], x.get("created_at", "")))
    return candidates[:limit]



