def check_photo_search_limit(user_id: int) -> tuple:
    """
    Проверяет лимиты поиска по фото для пользователя.
    Возвращает (allowed: bool, reason: str | None).
    reason — текст для пользователя если не allowed.
    """
    user_data = db.get_user(user_id)
    if not user_data:
        return False, "Пользователь не найден."

    tariff = normalize_tariff(user_data.get("tariff", "Free"))
    limits = PHOTO_SEARCH_LIMITS.get(tariff, PHOTO_SEARCH_LIMITS["Free"])
    now = get_moscow_time()
    today = now.date().isoformat()

    # ── Кулдаун между запросами ───────────────────────────────────────
    last_at_str = user_data.get("photo_search_last_at")
    if last_at_str:
        try:
            last_at = datetime.fromisoformat(last_at_str)
            elapsed = (now - last_at).total_seconds()
            if elapsed < limits["cooldown"]:
                wait = int(limits["cooldown"] - elapsed) + 1
                return False, f"Нельзя искать так часто. Подождите ещё {wait} сек. и попробуйте снова."
        except (ValueError, TypeError):
            pass

    # ── Дневной лимит ─────────────────────────────────────────────────
    if limits["daily"] == 0:
        if check_and_consume_trial(user_id, "photo_search"):
            return True, "TRIAL"
        return False, "Лимит исчерпан. Узнайте о ПОЛКА ПЛЮС ↓"
    reset_date = user_data.get("photo_search_reset_date", "")
    count = user_data.get("photo_search_count", 0) or 0

    # Сброс счётчика в новый день
    if reset_date != today:
        db.update_user(user_id, photo_search_count=0, photo_search_reset_date=today)
        count = 0

    if count >= limits["daily"]:
        return False, f"На сегодня поиск по фото исчерпан ({limits['daily']} раза в день). Возвращайтесь завтра!"

    return True, None


def record_photo_search(user_id: int):
    """Фиксирует использование поиска по фото: обновляет счётчик и время."""
    user_data = db.get_user(user_id)
    if not user_data:
        return
    today = get_moscow_time().date().isoformat()
    reset_date = user_data.get("photo_search_reset_date", "")
    count = user_data.get("photo_search_count", 0) or 0
    if reset_date != today:
        count = 0
    db.update_user(
        user_id,
        photo_search_count=count + 1,
        photo_search_reset_date=today,
        photo_search_last_at=get_moscow_time().isoformat()
    )


async def handle_search_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Получаем фото от пользователя и ищем похожие объявления."""
    logger.info(f"handle_search_photo: user={update.effective_user.id}, has_photo={bool(update.message and update.message.photo)}")

    if not update.message or not update.message.photo:
        await update.message.reply_text(
            "Пожалуйста, отправьте фото (не файл).",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="search")
            ]])
        )
        return States.SEARCH_PHOTO

    # Проверяем лимиты
    user_id = update.effective_user.id
    allowed, reason = check_photo_search_limit(user_id)
    if not allowed:
        keyboard = [[InlineKeyboardButton("✦ ПОЛКА ПЛЮС", callback_data="subscription_info")]]
        keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="search")])
        await update.message.reply_text(
            reason,
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
        return States.SEARCH_PHOTO

    if reason == "TRIAL":
        await update.message.reply_text(
            "✦ Это ваша бесплатная пробная попытка поиска по фото! "
            "Дальше — по подписке ПОЛКА ПЛЮС."
        )

    msg = await update.message.reply_text("Анализирую фото...")

    record_photo_search(user_id)

    file_id = update.message.photo[-1].file_id
    bot     = context.bot

    # ── 1. CLIP эмбеддинг — основной поиск ──────────────────────────────────
    query_emb  = await get_clip_embedding_hf(bot, file_id)
    results_clip = find_similar_ads_by_embedding(query_emb, limit=10) if query_emb is not None else []

    # ── 2. pHash — дополнительный поиск по визуальному сходству ─────────────
    query_hashes = await compute_photo_hashes_multi(bot, file_id)
    photo_hash   = query_hashes.get('phash') or await compute_photo_hash(bot, file_id)

    results_hash = []
    if photo_hash:
        results_strict = search_by_photo_hash(photo_hash, threshold=10, limit=10, query_hashes=query_hashes)
        results_soft   = search_by_photo_hash(photo_hash, threshold=25, limit=20, query_hashes=query_hashes)
        strict_ids = {a["id"] for a in results_strict}
        results_hash = results_strict + [a for a in results_soft if a["id"] not in strict_ids]

    # ── 3. Теги через Groq Vision + фолбэк на describe_photo_gpt ─────────
    tags = await extract_photo_tags_hf(bot, file_id)
    gpt_desc, gpt_tags, gpt_category = ("", [], "")
    if not tags:
        logger.info("handle_search_photo: extract_photo_tags_hf пуст, пробуем describe_photo_gpt")
        photo_data = None
        try:
            tg_file = await bot.get_file(file_id)
            buf = _io.BytesIO()
            await tg_file.download_to_memory(buf)
            photo_data = buf.getvalue()
        except Exception:
            pass
        if photo_data:
            gpt_desc, gpt_tags, gpt_category = await describe_photo_gpt(photo_data)
            logger.info(f"handle_search_photo: gpt_desc={gpt_desc[:60]}, gpt_tags={gpt_tags}, gpt_category={gpt_category}")
    else:
        gpt_tags = tags
        gpt_category = ""

    search_tags = tags or gpt_tags
    search_category = gpt_category

    # ── 4. FTS5 по тегам (заголовок/описание) ──────────────────────────────
    results_tags = []
    if search_tags:
        tag_query = " ".join(search_tags[:5])
        cat_filter = {"category": search_category} if search_category and search_category != "другое" else {}
        results_tags = search_ads_fts(tag_query, limit=20, filters=cat_filter)

    # ── 5. Поиск по photo_tags (теги, сохранённые при создании объявления) ──
    results_photo_tags = []
    if search_tags:
        like_clauses = []
        params = []
        for t in search_tags[:5]:
            like_clauses.append("photo_tags LIKE ?")
            params.append(f'%"{t}"%')
        if like_clauses:
            cursor = db.conn.execute(
                f"SELECT * FROM ads WHERE status='active' AND photo_tags IS NOT NULL "
                f"AND photo_tags != '' AND ({' OR '.join(like_clauses)}) "
                f"ORDER BY created_at DESC LIMIT 20",
                params
            )
            rows = cursor.fetchall()
            scored = []
            for row in rows:
                ad = dict(row)
                try:
                    stored_tags = set(json.loads(ad["photo_tags"]))
                except Exception:
                    stored_tags = set()
                match_count = len(stored_tags & set(search_tags))
                if match_count > 0:
                    ad["_tag_match"] = match_count
                    try:
                        ad["photos"] = json.loads(ad["photos"]) if ad["photos"] else []
                    except Exception:
                        ad["photos"] = []
                    scored.append(ad)
            scored.sort(key=lambda x: -x["_tag_match"])
            results_photo_tags = scored[:15]

    # ── Собираем все результаты со скорами ─────────────────────────────────
    scored = []

    def _add_tagged(ads, base_score, match_label):
        for ad in ads:
            tag_count = ad.get("_tag_match", 1)
            rank_boost = 1000 - min(ad.get("rank", 0), 999)
            ad["_score"] = base_score * tag_count + rank_boost
            ad["_match"] = match_label
            scored.append(ad)

    def _add_sim(ads, base_score, field, match_label):
        for ad in ads:
            sim = ad.get(field, 0)
            if isinstance(sim, float) and 0 <= sim <= 1:
                ad["_score"] = base_score + int(sim * 100)
            elif isinstance(sim, int):
                ad["_score"] = base_score + sim
            else:
                ad["_score"] = base_score
            ad["_match"] = match_label
            scored.append(ad)

    # FTS5 AND (все теги) → фото_tags → FTS5 OR → CLIP → pHash
    _add_tagged(results_tags, 1000, "Точно по фото")
    _add_tagged(results_photo_tags, 800, "Похожие теги")
    _add_sim(results_clip, 300, "similarity", "Визуально похоже")
    _add_sim(results_hash, 100, "_similarity", "Похожее изображение")

    # Дедупликация
    seen_ids = set()
    combined = []
    for ad in sorted(scored, key=lambda x: -x["_score"]):
        if ad["id"] not in seen_ids:
            seen_ids.add(ad["id"])
            combined.append(ad)

    # ── Fallback: каждый тег отдельно (если вообще ничего не нашли) ─────────
    if not combined and search_tags:
        for tag in search_tags[:5]:
            for ad in search_ads_fts(tag, limit=10):
                if ad["id"] not in seen_ids:
                    ad["_score"] = 60
                    ad["_match"] = f"По теме «{tag}»"
                    combined.append(ad)
                    seen_ids.add(ad["id"])
            for row in db.conn.execute(
                "SELECT * FROM ads WHERE status='active' AND photo_tags LIKE ? LIMIT 10",
                (f'%"{tag}"%',)
            ):
                ad = dict(row)
                if ad["id"] not in seen_ids:
                    try:
                        ad["photos"] = json.loads(ad["photos"]) if ad["photos"] else []
                    except Exception:
                        ad["photos"] = []
                    ad["_score"] = 40
                    ad["_match"] = f"По теме «{tag}»"
                    combined.append(ad)
                    seen_ids.add(ad["id"])
            for row in db.conn.execute(
                "SELECT * FROM ads WHERE status='active' AND (title LIKE ? OR description LIKE ?) LIMIT 10",
                (f'%{tag}%', f'%{tag}%')
            ):
                ad = dict(row)
                if ad["id"] not in seen_ids:
                    try:
                        ad["photos"] = json.loads(ad["photos"]) if ad["photos"] else []
                    except Exception:
                        ad["photos"] = []
                    ad["_score"] = 20
                    ad["_match"] = f"По теме «{tag}»"
                    combined.append(ad)
                    seen_ids.add(ad["id"])
            if combined:
                break

    try:
        await msg.delete()
    except Exception:
        pass

    # Убираем флаг ожидания фото
    context.user_data.pop('awaiting_search_photo', None)

    if not combined:
        tag_str = ", ".join(search_tags[:5]) if search_tags else ""
        parts = []
        if tag_str:
            parts.append(f"На фото:\n<blockquote>{tag_str}</blockquote>")
        if search_category and search_category != "другое":
            parts.append(f"Категория: {search_category}")
        hint = "\n".join(parts) + "\n\n" if parts else ""
        if not IMAGEHASH_AVAILABLE:
            hint += "Поиск по визуальному сходству недоступен — попробуйте поиск по тексту."
        else:
            hint += "Попробуйте сделать фото чётче или воспользуйтесь поиском по тексту."
        await update.message.reply_text(
            f"По этому фото ничего не найдено.\n\n{hint}",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(EM_DOT + " Поиск по тексту", callback_data="search"),
            ]])
        )
        return States.MAIN_MENU

    # ── Показываем результаты ─────────────────────────────────────────────
    tag_str = ", ".join(search_tags[:5]) if search_tags else ""
    hint_parts = []
    if tag_str:
        hint_parts.append(f"На фото:\n<blockquote>{tag_str}</blockquote>")
    if search_category and search_category != "другое":
        hint_parts.append(f"Категория: {search_category}")
    hint_line = "\n".join(hint_parts) + "\n\n" if hint_parts else ""

    count = min(len(combined), 10)
    word = "нашёл" if count == 1 else "нашёл"
    text = f"{hint_line}Вот что я {word}:\n\n"

    keyboard = []
    moscow_now = get_moscow_time().isoformat()
    for ad in combined[:10]:
        pinned = f"{EM_DIAMOND} " if ad.get("pinned_until") and ad["pinned_until"] > moscow_now else ""
        title_short = ad["title"][:26] + "…" if len(ad["title"]) > 26 else ad["title"]
        text += f"{pinned}{ad['title']} — {ad['price']} ₽\n"
        keyboard.append([InlineKeyboardButton(
            f"{pinned}{title_short} — {ad['price']} ₽",
            callback_data=f"view_ad:{ad['id']}"
        )])

    keyboard.append([
        InlineKeyboardButton(EM_DOT + " Поиск по тексту", callback_data="search"),
        InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu"),
    ])

    await update.message.reply_text(
        text, parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(keyboard)
    )
    context.user_data.pop("awaiting_search_photo", None)
    return States.SEARCH_QUERY



async def search_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Главный экран поиска"""
    query = update.callback_query
    if query:
        try:
            await safe_answer(query)
        except Exception:
            pass

    for k in ('sf_query','sf_category','sf_price_min','sf_price_max',
              'sf_city','sf_condition','sf_delivery','sf_sort','sf_page',
              'awaiting_search_photo'):
        context.user_data.pop(k, None)

    # Ручной поиск приоритетнее активного чата: следующий текст — это запрос,
    # а не сообщение в чат покупателю (иначе запрос уходит как релей в чат).
    context.user_data['awaiting_search'] = True
    context.user_data.pop('active_chat', None)

    user_id = update.effective_user.id
    history = db.get_search_history(user_id)

    text = (
        "<b>Поиск</b>\n\n"
        "Введите название товара, бренд или ключевые слова:\n"
        "<i>Например: iPhone 13, Nike Air, диван кожаный</i>"
    )

    keyboard = [
        [InlineKeyboardButton(EM_DOT + " Поиск по фото", callback_data="search_by_photo")],
    ]
    if history:
        keyboard.append([InlineKeyboardButton(EM_DOT + " История поиска", callback_data="search_history")])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")])

    markup  = InlineKeyboardMarkup(keyboard)
    banner  = BANNERS.get("search", "")

    async def _send_new(target_msg):
        if banner:
            try:
                await target_msg.reply_photo(photo=banner, caption=text,
                                             reply_markup=markup, parse_mode=ParseMode.HTML)
                return True
            except Exception:
                pass
        try:
            await target_msg.reply_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
            return True
        except Exception:
            return False

    if query:
        sent = await _send_new(query.message)
        if sent:
            try:
                await query.delete_message()
            except Exception:
                pass
        else:
            await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    else:
        await _send_new(update.message)

    context.user_data['search_page'] = 0
    return States.SEARCH_QUERY


async def search_quick_repeat(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Повторить поиск из истории по кнопке sq:"""
    query = update.callback_query
    await safe_answer(query, )
    search_text = query.data[3:]  # strip "sq:"
    context.user_data['sf_query'] = search_text
    context.user_data['sf_page'] = 0
    await _do_search_and_show(update, context, edit=True)
    return States.SEARCH_QUERY


async def handle_search(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь ввёл текстовый запрос"""
    query_text = update.message.text.strip()
    if not query_text:
        return States.SEARCH_QUERY

    context.user_data['sf_query'] = query_text
    context.user_data['sf_page'] = 0
    db.add_search_history(update.effective_user.id, query_text)

    # Умное предложение категории — если категория ещё не выбрана
    if not context.user_data.get('sf_category'):
        suggested = _smart_suggest_category(query_text)
        if suggested:
            context.user_data['_sf_suggested_cat'] = suggested
            await update.message.reply_text(
                f"Похоже, вы ищете в категории <b>{suggested}</b>.\n"
                f"Применить для более точного поиска?",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(f"{EM_OK} Да, искать в «{suggested}»",
                                          callback_data=f"sf_suggest_apply:{suggested}"),
                     InlineKeyboardButton(EM_DOT + " Нет, все категории",
                                          callback_data="sf_suggest_skip")],
                ])
            )
            return States.SEARCH_QUERY

    await _do_search_and_show(update, context, edit=False)
    return States.SEARCH_QUERY


async def sf_suggest_apply(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь принял предложенную категорию"""
    query = update.callback_query
    await safe_answer(query, )
    cat = query.data.split(":", 1)[1]
    context.user_data['sf_category'] = cat
    context.user_data.pop('_sf_suggested_cat', None)
    context.user_data['sf_page'] = 0
    await _do_search_and_show(update, context, edit=True)
    return States.SEARCH_QUERY

async def sf_suggest_skip(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь отказался от предложенной категории"""
    query = update.callback_query
    await safe_answer(query, )
    context.user_data.pop('_sf_suggested_cat', None)
    context.user_data['sf_page'] = 0
    await _do_search_and_show(update, context, edit=True)
    return States.SEARCH_QUERY


async def _do_search_and_show(update: Update, context: ContextTypes.DEFAULT_TYPE, edit: bool = False):
    """Ядро: выполнить поиск и показать результаты"""
    f = await _get_search_filters(context)
    page = f['page']
    limit_per_page = 8

    all_results = db.search_ads_filtered(
        query=f['query'],
        category=f['category'],
        price_min=f['price_min'],
        price_max=f['price_max'],
        city=f['city'],
        condition=f['condition'],
        delivery=f['delivery'],
        sort_by=f['sort_by'],
        limit=200,
    )

    total = len(all_results)
    total_pages = max(1, (total + limit_per_page - 1) // limit_per_page)
    page = min(page, total_pages - 1)
    context.user_data['sf_page'] = page
    results = all_results[page * limit_per_page:(page + 1) * limit_per_page]

    SORT_LABELS = {
        'date_desc':  'Сначала новые',
        'date_asc':   'Сначала старые',
        'price_asc':  'Дешевле',
        'price_desc': 'Дороже',
        'views_desc': 'Популярные',
    }

    query_label = f['query'] or '(все товары)'
    filters_str = _filters_label(f)
    sort_label = SORT_LABELS.get(f['sort_by'], 'Сначала новые')

    if total == 0:
        text = (
            f"<b>«{query_label}»</b>\n\n"
            f"Ничего не найдено\n\n"
            "Попробуйте изменить запрос или сбросить фильтры.\n"
            "Можем уведомить, когда появится похожий товар."
        )
        keyboard = []
        if filters_str:
            keyboard.append([InlineKeyboardButton(EM_FAIL + " Сбросить фильтры", callback_data="sf_reset")])
        keyboard += [
            [InlineKeyboardButton(EM_DIAMOND + " Уведомить о появлении", callback_data=_safe_cb("save_search:", f['query']))],
            [InlineKeyboardButton(EM_DOT + " Новый поиск", callback_data="search"),
             InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]
        ]
    else:
        header = f"<b>«{query_label}»</b> — {total} объявл."
        if filters_str:
            header += f"\n<i>{filters_str}</i>"
        if total_pages > 1:
            header += f" {EM_DOT}  стр. {page+1}/{total_pages}"
        header += "\n\n"

        text = header

        # Подготовка данных верификации продавцов (один запрос, а не на каждой итерации)
        seller_ids = {ad['user_id'] for ad in results}
        verification_cache = {}
        for sid in seller_ids:
            v = db.get_verification(sid)
            verification_cache[sid] = v

        for ad in results:
            pinned = f"{EM_DIAMOND} " if ad.get('pinned_until') else ""
            verify = verification_cache.get(ad['user_id'])
            badge  = f"{EM_OK} " if verify and verify.get('status') == 'verified' else ""
            city_s = f" {EM_DOT} {ad['city']}" if ad.get('city') else ""
            cond_s = f" {EM_DOT} {ad.get('condition','')}" if ad.get('condition') else ""
            # Используем хранимые views — не дёргаем сеть на каждом поиске
            views_s = f" {EM_DOT} {ad.get('views',0)} просм."
            price_f = fmt_rub(ad['price'])
            text += (
                f"{pinned}{badge}<b>{ad['title']}</b>\n"
                f"<b>{price_f} ₽</b>{city_s}{cond_s}{views_s}\n\n"
            )

        keyboard = []
        for ad in results:
            verify = db.get_verification(ad['user_id'])
            badge  = f"{EM_OK}" if verify and verify.get('status') == 'verified' else ""
            price_f = fmt_rub(ad['price'])
            short = ad['title'][:30] + "…" if len(ad['title']) > 30 else ad['title']
            keyboard.append([InlineKeyboardButton(
                f"{badge} {short} — {price_f} ₽",
                callback_data=f"view_ad:{ad['id']}"
            )])

        # Пагинация
        pag = []
        if page > 0:
            pag.append(InlineKeyboardButton(f"{EM_ARROW_L}", callback_data="sf_page_prev"))
        pag.append(InlineKeyboardButton(f"{page+1}/{total_pages}", callback_data="sf_noop"))
        if page < total_pages - 1:
            pag.append(InlineKeyboardButton(f"{EM_ARROW_R}", callback_data="sf_page_next"))
        if len(pag) > 1:
            keyboard.append(pag)

        # Строка быстрых фильтров
        keyboard.append([
            InlineKeyboardButton(f"Фильтры" + (" ●" if filters_str else ""), callback_data="sf_menu"),
            InlineKeyboardButton(f"{sort_label}", callback_data="sf_sort_menu"),
        ])
        if f['query']:
            keyboard.append([
                InlineKeyboardButton(EM_DIAMOND + " Сохранить поиск", callback_data=_safe_cb("save_search:", f['query'])),
                InlineKeyboardButton(EM_FAIL + " Сбросить", callback_data="sf_reset"),
            ])
        keyboard.append([
            InlineKeyboardButton(EM_DOT + " Новый поиск", callback_data="search"),
            InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu"),
        ])

    if edit and update.callback_query:
        context.user_data['_nav_back'] = 'sf_apply'
        await safe_edit_message(update.callback_query, text, keyboard, parse_mode=ParseMode.HTML)
    else:
        context.user_data['_nav_back'] = 'sf_apply'
        msg = update.message or (update.callback_query.message if update.callback_query else None)
        if msg:
            await msg.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)


# ─── Обработчики кнопок фильтров ────────────────────────────────────

async def sf_page_prev(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    context.user_data['sf_page'] = max(0, context.user_data.get('sf_page', 0) - 1)
    await _do_search_and_show(update, context, edit=True)
    return States.SEARCH_QUERY

async def sf_page_next(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    context.user_data['sf_page'] = context.user_data.get('sf_page', 0) + 1
    await _do_search_and_show(update, context, edit=True)
    return States.SEARCH_QUERY

async def sf_noop(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.callback_query.answer()

async def sf_reset(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, "Фильтры сброшены")
    for k in ('sf_category','sf_price_min','sf_price_max','sf_city',
              'sf_condition','sf_delivery','sf_sort'):
        context.user_data.pop(k, None)
    context.user_data['sf_page'] = 0
    await _do_search_and_show(update, context, edit=True)
    return States.SEARCH_QUERY

