def _smart_suggest_category(query_text: str) -> str:
    """Угадывает наиболее вероятную категорию по тексту запроса. Пустая строка — нет совпадений."""
    q = query_text.lower()
    for keywords, cat in _QUERY_CATEGORY_HINTS:
        if any(kw in q for kw in keywords):
            return cat
    return ''


