# ─── Вспомогательная функция сборки клавиатуры sf_menu ───────────────────────

def _build_sf_keyboard(f: dict) -> list:
    """
    Формирует клавиатуру главного экрана фильтров.
    Активные значения отображаются прямо на кнопке ({EM_OK} / текущий выбор).
    """
    cond     = f.get('condition', '')
    delivery = f.get('delivery', '')
    cat      = f.get('category', '')
    city     = f.get('city', '')
    pmin     = f.get('price_min', 0)
    pmax     = f.get('price_max', 0)
    sort_val = f.get('sort_by', 'date_desc')

    SORT_LABELS = {
        'date_desc':  'Новые',
        'date_asc':   'Старые',
        'price_asc':  'Дешевле',
        'price_desc': 'Дороже',
        'views_desc': 'Популярные',
    }

    # Кнопка категории — показываем текущий выбор
    cat_btn  = f"{EM_OK} {cat}" if cat else f"{EM_DOT} Категория: все"
    city_btn = f"{EM_OK} {city}" if city else f"{EM_DOT} Город: все"

    # Кнопка цены — показываем текущий диапазон
    if pmin and pmax:
        price_btn = f"{EM_OK} {fmt_rub(pmin)}–{fmt_rub(pmax)} ₽"
    elif pmin:
        price_btn = f"{EM_OK} от {fmt_rub(pmin)} ₽"
    elif pmax:
        price_btn = f"{EM_OK} до {fmt_rub(pmax)} ₽"
    else:
        price_btn = f"{EM_DOT} Цена: любая"

    sort_btn = f"↕ {SORT_LABELS.get(sort_val, 'Новые')}"

    # Состояние — inline-переключатель: выделяем активное
    cond_new  = (f"{EM_OK} Новое" if cond == 'new'  else f"{EM_DOT} Новое")
    cond_used = (f"{EM_OK} Б/у"   if cond == 'used' else f"{EM_DOT} Б/у")
    cond_any  = (f"{EM_OK} Любое" if cond == ''     else f"{EM_DOT} Любое")

    # Доставка — toggle
    del_btn = (f"{EM_OK} Есть доставка" if delivery == 'yes' else f"{EM_DOT} Есть доставка")

    keyboard = [
        # Категория и город
        [InlineKeyboardButton(cat_btn,  callback_data="sf_cat_menu"),
         InlineKeyboardButton(city_btn, callback_data="sf_city_menu")],
        # Цена
        [InlineKeyboardButton(price_btn, callback_data="sf_price_range"),
         InlineKeyboardButton(sort_btn,  callback_data="sf_sort_menu")],
        # Состояние
        [InlineKeyboardButton(cond_new,  callback_data="sf_cond:new"),
         InlineKeyboardButton(cond_used, callback_data="sf_cond:used"),
         InlineKeyboardButton(cond_any,  callback_data="sf_cond:")],
        # Доставка
        [InlineKeyboardButton(del_btn, callback_data="sf_delivery:yes")],
        # Управление
        [InlineKeyboardButton(EM_FAIL + " Сбросить", callback_data="sf_reset"),
         InlineKeyboardButton(EM_OK + " Применить", callback_data="sf_apply")],
    ]
    return keyboard


def _build_sf_text(f: dict) -> str:
    """Заголовок панели фильтров с кратким статусом активных настроек."""
    lines = ["<b>Фильтры поиска</b>"]
    active = []
    if f.get('category'):   active.append(f"Категория: {f['category']}")
    if f.get('city'):        active.append(f"Город: {f['city']}")
    pmin, pmax = f.get('price_min', 0), f.get('price_max', 0)
    if pmin or pmax:
        rng = f"{fmt_rub(pmin) if pmin else '0'}–{fmt_rub(pmax) if pmax else '∞'} ₽"
        active.append(f"Цена: {rng}")
    cond_map = {'new': 'Новое', 'used': 'Б/у'}
    if f.get('condition') in cond_map: active.append(f"Состояние: {cond_map[f['condition']]}")
    if f.get('delivery') == 'yes':     active.append("С доставкой")
    if active:
        lines.append("\n<i>Активно: " + f" {EM_DOT} ".join(active) + "</i>")
    else:
        lines.append("\n<i>Фильтры не заданы — показываются все результаты</i>")
    return "\n".join(lines)


# ─── Главное меню фильтров ───────────────────────────────────────────────────

async def sf_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Умная панель фильтров — всё в одном экране"""
    query = update.callback_query
    await safe_answer(query, )
    f = await _get_search_filters(context)
    text = _build_sf_text(f)
    keyboard = _build_sf_keyboard(f)
    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    return States.SEARCH_QUERY


# ─── Категория с галочкой ────────────────────────────────────────────────────

async def sf_cat_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Выбор категории — активная выделена галочкой"""
    query = update.callback_query
    await safe_answer(query, )
    current = context.user_data.get('sf_category', '')
    keyboard = []
    row = []
    for label, val in SEARCH_CATEGORIES:
        check = f"{EM_OK} " if val == current else ""
        row.append(InlineKeyboardButton(f"{check}{label}", callback_data=f"sf_cat:{val}"))
        if len(row) == 2:
            keyboard.append(row); row = []
    if row: keyboard.append(row)
    all_check = f"{EM_OK} " if not current else ""
    keyboard.append([InlineKeyboardButton(f"{all_check}Все категории", callback_data="sf_cat:all")])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Фильтры", callback_data="sf_menu")])
    await safe_edit_message(query, "<b>Выберите категорию:</b>", keyboard, parse_mode=ParseMode.HTML)
    return States.SEARCH_QUERY

async def sf_set_cat(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    val = query.data.split(":", 1)[1]
    context.user_data['sf_category'] = '' if val == 'all' else val
    context.user_data['sf_page'] = 0
    await sf_menu(update, context)
    return States.SEARCH_QUERY


# ─── Город с галочкой + ввод своего ─────────────────────────────────────────

_SF_POPULAR_CITIES = ALLOWED_CITIES_SORTED

async def sf_city_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Выбор города — популярные + галочки + ввод своего"""
    query = update.callback_query
    await safe_answer(query, )
    current = context.user_data.get('sf_city', '')
    keyboard = []
    row = []
    for city in _SF_POPULAR_CITIES:
        check = f"{EM_OK} " if city == current else ""
        row.append(InlineKeyboardButton(f"{check}{city}", callback_data=f"sf_city:{city}"))
        if len(row) == 2:
            keyboard.append(row); row = []
    if row: keyboard.append(row)
    all_check = f"{EM_OK} " if not current else ""
    keyboard.append([InlineKeyboardButton(f"{all_check}Все города", callback_data="sf_city:all")])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Фильтры", callback_data="sf_menu")])

    hint = f"\nТекущий выбор: <b>{current}</b>" if current else ""
    await safe_edit_message(
        query,
        f"<b>Выберите город:</b>{hint}",
        keyboard,
        parse_mode=ParseMode.HTML
    )
    return States.SEARCH_QUERY

