async def sf_city_custom_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь хочет ввести город вручную"""
    query = update.callback_query
    await safe_answer(query, )
    context.user_data['sf_awaiting_city'] = True
    await safe_edit_message(
        query,
        "<b>Введите название вашего города:</b>\n\n<i>Например: Самара, Воронеж, Иркутск</i>",
        [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="sf_city_menu")]],
        parse_mode=ParseMode.HTML
    )
    return States.SEARCH_CITY_FILTER

async def sf_city_custom_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Автодополнение города в фильтре поиска."""
    if not context.user_data.get('sf_awaiting_city'):
        return States.SEARCH_QUERY
    city = update.message.text.strip()

    # Точное совпадение — применяем фильтр
    matched = next((c for c in ALLOWED_CITIES_SORTED if c.lower() == city.lower()), None)
    if matched:
        context.user_data.pop('sf_awaiting_city', None)
        context.user_data['sf_city'] = matched
        context.user_data['sf_page'] = 0
        await update.message.reply_text(f"{EM_OK} Город <b>{matched}</b> выбран", parse_mode=ParseMode.HTML)
        await _do_search_and_show(update, context, edit=False)
        return States.SEARCH_QUERY

    # Иначе — подсказки
    keyboard = _city_suggest_keyboard(city)
    keyboard_with_back = keyboard[:-1] + [
        [InlineKeyboardButton(EM_ARROW_L + " К списку городов", callback_data="sf_city_menu")]
    ]
    await update.message.reply_text(
        f"Ищу: «<b>{city}</b>»\n\nВыберите из подсказок или уточните название:",
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(keyboard_with_back)
    )
    return States.SEARCH_CITY_FILTER


