# ─── Цена — быстрые диапазоны + ввод вручную ─────────────────────────────────

async def sf_price_range(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Меню выбора ценового диапазона — пресеты + ввод вручную"""
    query = update.callback_query
    await safe_answer(query, )
    pmin = context.user_data.get('sf_price_min', 0)
    pmax = context.user_data.get('sf_price_max', 0)

    keyboard = []
    for label, lo, hi in _PRICE_PRESETS:
        # Помечаем галочкой если пресет точно совпадает
        active = (lo == pmin and hi == pmax)
        check = f"{EM_OK} " if active else ""
        keyboard.append([InlineKeyboardButton(f"{check}{label}", callback_data=f"sf_price_preset:{lo}:{hi}")])

    keyboard.append([InlineKeyboardButton(EM_DOT + " Ввести свою цену (от)", callback_data="sf_price_from"),
                     InlineKeyboardButton(EM_DOT + " Ввести свою цену (до)", callback_data="sf_price_to")])
    keyboard.append([InlineKeyboardButton(EM_FAIL + " Сбросить цену", callback_data="sf_price_preset:0:0")])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Фильтры", callback_data="sf_menu")])

    cur = ""
    if pmin or pmax:
        cur = f"\n<i>Сейчас: {fmt_rub(pmin) if pmin else '0'}–{fmt_rub(pmax) if pmax else '∞'} ₽</i>"

    await safe_edit_message(
        query,
        f"<b>Ценовой диапазон:</b>{cur}",
        keyboard,
        parse_mode=ParseMode.HTML
    )
    return States.SEARCH_QUERY

