async def handle_search_seller_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Обрабатывает текстовый ввод для поиска продавца"""
    if not context.user_data.get("awaiting_seller_search"):
        return
    context.user_data.pop("awaiting_seller_search", None)
    query_text = update.message.text.strip().lstrip("@")
    user_id = update.effective_user.id
    cursor = db.conn.cursor()
    cursor.execute(
        """SELECT user_id, first_name, username FROM users
           WHERE (username LIKE ? OR first_name LIKE ?) AND user_id != ?
           LIMIT 10""",
        (f"%{query_text}%", f"%{query_text}%", user_id)
    )
    results = cursor.fetchall()
    if not results:
        keyboard = [
            [InlineKeyboardButton(EM_REFRESH + " Попробовать снова", callback_data="search_seller")],
            [InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="favorite_sellers")]
        ]
        await update.message.reply_text(
            "Продавец не найден. Попробуйте другой запрос.",
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
        return
    text = f"Найдено продавцов: {len(results)}\n\n"
    keyboard = []
    for row in results:
        sid, fname, uname = row[0], row[1], row[2]
        label = f"{fname} (@{uname})" if uname else fname
        already = db.is_favorite_seller(user_id, sid)
        fav_label = f"{EM_OK} В избранном" if already else "В избранное"
        fav_cb = f"unfav_seller:{sid}" if already else f"fav_seller:{sid}"
        keyboard.append([
            InlineKeyboardButton(f"{label}", callback_data=f"seller_reviews:{sid}"),
            InlineKeyboardButton(fav_label, callback_data=fav_cb)
        ])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="favorite_sellers")])
    await update.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard))


# Профиль
async def show_profile(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )

    user = update.effective_user
    try:
        user_data = db.get_user(user.id)
        if not user_data:
            await safe_edit_message(query, "Пользователь не найден")
            return

        cursor = db.conn.cursor()
        moscow_now = get_moscow_time().isoformat()

        cursor.execute("SELECT COUNT(*) FROM ads WHERE user_id = ? AND status = 'active'", (user.id,))
        active_ads = cursor.fetchone()[0]

        cursor.execute("SELECT COUNT(*) FROM ads WHERE user_id = ? AND pinned_until IS NOT NULL AND pinned_until > ?", (user.id, moscow_now))
        pinned_ads = cursor.fetchone()[0]

        cursor.execute("SELECT SUM(views) FROM ads WHERE user_id = ? AND status = 'active'", (user.id,))
        total_views = cursor.fetchone()[0] or 0

        # Реальные просмотры постов каналов (TG web + MAX)
        try:
            active_ad_rows = db.get_user_ads(user.id)
            active_ad_rows = [a for a in active_ad_rows if a['status'] == 'active']
            live_total = await get_live_views_sum(active_ad_rows)
            if live_total > total_views:
                total_views = live_total
        except Exception as e:
            logger.warning(f"profile live views: {e}")

        cursor.execute('''
            SELECT COUNT(*) FROM favorites f
            JOIN ads a ON f.ad_id = a.id
            WHERE f.user_id = ? AND a.status = 'active'
        ''', (user.id,))
        favorites_count = cursor.fetchone()[0]

        seller_rating = db.get_seller_rating(user.id)
        rating_str = ""
        if seller_rating['count'] > 0:
            stars = "★" * round(seller_rating['avg'])
            rating_str = f"\n{stars} {seller_rating['avg']} ({seller_rating['count']} отзывов)"

        verify = db.get_verification(user.id)
        is_verified = verify and verify.get('status') == 'verified'
        is_pending  = verify and verify.get('status') == 'pending'
        verify_str  = "  ✓ Верифицирован" if is_verified else ""

        if is_verified:
            verify_block = f"\n✓ <b>Верифицированный продавец</b>\nПокупатели видят ваш значок и доверяют вам больше.\n"
        elif is_pending:
            verify_block = f"\n· <b>Верификация на проверке</b> — ответ придёт в течение 24 часов.\n"
        else:
            verify_block = ""

        tariff_info = get_tariff_info(user.id)
        tariff_key = tariff_info['key']
        ads_used = user_data.get('daily_ads_count', 0) or 0
        edits_used = db.get_daily_photo_edits(user.id)
        search_used = user_data.get('photo_search_count', 0) or 0
        ai_gen_used = user_data.get('ai_gen_count', 0) or 0
        ads_max = tariff_info['daily_ads']
        edits_max = tariff_info.get('daily_enhance', 3)
        search_max = tariff_info.get('daily_search', 1)
        ai_gen_max = tariff_info.get('daily_ai_gen', 1)
        if search_max == 0 and search_used > 0:
            db.update_user(user.id, photo_search_count=0)
            search_used = 0
        if ai_gen_max == 0 and ai_gen_used > 0:
            db.update_user(user.id, ai_gen_count=0)
            ai_gen_used = 0
        text = (
            f"<b>{user.first_name}</b>{verify_str}\n"
            f"{'@' + user.username if user.username else ''}\n\n"
            f"На платформе с {user_data['registration_date'][:10]}\n"
            f"{verify_block}\n"
            f"Статистика:\n"
            f"• Активных объявлений: {active_ads}\n"
            f"• Закреплено: {pinned_ads}\n"
            f"• Всего просмотров: {total_views}\n"
            f"• Добавили в избранное: {favorites_count} раз"
            f"{rating_str}\n\n"
            f"<b>Лимиты на сегодня:</b>\n"
            f"• Объявления: {ads_used}/{ads_max}\n"
            f"• AI-обработка фото: {edits_used}/{edits_max}\n"
            f"• Поиск по фото: {search_used}/{search_max}\n"
            f"• AI-генерация: {ai_gen_used}/{ai_gen_max}\n"
        )
        if tariff_key == 'Premium':
            end_str = user_data.get('tariff_end_date', '')[:10]
            text += f"\n✦ <b>ПОЛКА ПЛЮС</b> — до {end_str}"
        else:
            text += f"\n· Тариф: Бесплатно"
        keyboard = []
        keyboard.append([InlineKeyboardButton("✦ ПОЛКА ПЛЮС", callback_data="subscription_info")])
        keyboard.append([InlineKeyboardButton("✦ Закрепить объявление", callback_data="pin_ad_menu")])
        if not is_verified:
            if is_pending:
                keyboard.append([InlineKeyboardButton("· Верификация (на проверке)", callback_data="verify_seller")])
            else:
                keyboard.append([InlineKeyboardButton("✦ Верификация продавца", callback_data="verify_seller")])
        keyboard.append([InlineKeyboardButton(f"{EM_ARROW_R} Мои диалоги", callback_data="my_chats")])
        keyboard.append([InlineKeyboardButton(EM_DOT + " Пригласить друга", callback_data="referral_share")])
        keyboard.append([InlineKeyboardButton(f"{EM_ARROW_L} Назад", callback_data="back_to_menu")])

        markup = InlineKeyboardMarkup(keyboard)
        # Отправляем как документ для сохранения качества
        try:
            await query.message.reply_photo(
                photo=BANNERS["profile"],
                caption=text,
                reply_markup=markup,
                parse_mode=ParseMode.HTML
            )
            await query.delete_message()
        except Exception:
            await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)

    except Exception as e:
        logger.error(f"Ошибка в show_profile: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить профиль. Попробуйте ещё раз.",
                [[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
        except Exception:
            pass

    return States.MAIN_MENU


async def subscription_info(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Информация о подписке ПОЛКА ПЛЮС и кнопка оплаты"""
    query = update.callback_query
    await safe_answer(query)
    user = update.effective_user
    user_data = db.get_user(user.id)
    if not user_data:
        await safe_edit_message(query, "Пользователь не найден")
        return
    is_prem = is_premium(user.id)
    context.user_data['promo_source'] = 'subscription'
    promo_code = context.user_data.pop('promo_code', None)
    promo_discount = context.user_data.pop('promo_discount', 0)
    promo_plan = context.user_data.get('promo_plan', 'all')
    if promo_code and promo_discount > 0 and promo_plan not in ('all', 'sub'):
        promo_code = None
        promo_discount = 0
