async def show_similar_ads(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query)
    try:
        ad_id = int(query.data.split(':')[1])
    except (IndexError, ValueError):
        await safe_edit_message(query, "Ошибка: не указано объявление.")
        return
    ad = db.get_ad(ad_id)
    if not ad or ad['status'] != 'active':
        await safe_edit_message(query, "Объявление не найдено.")
        return
    await safe_edit_message(query, f"{EM_DOT} Ищу похожие объявления...")
    keywords = await _llm_similar_keywords(ad)
    results = search_ads_fts(keywords, limit=15)
    results = [a for a in results if a['id'] != ad_id and a['status'] == 'active'][:8]
    if not results:
        await safe_edit_message(query,
            "Похожих объявлений не найдено.",
            [[InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_ad:{ad_id}")]]
        )
        return
    text = f"<b>{EM_DOT} Похожие на «{ad['title'][:30]}»:</b>\n\n"
    keyboard = []
    for i, a in enumerate(results, 1):
        title_short = a['title'][:28] + "..." if len(a['title']) > 28 else a['title']
        text += f"{i}. {a['title']}\n{a['price']} ₽ {EM_DOT} {a.get('city','')}\n\n"
        keyboard.append([InlineKeyboardButton(
            f"{title_short} — {a['price']} ₽",
            callback_data=f"view_ad:{a['id']}"
        )])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_ad:{ad_id}")])
    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)


