async def create_ad_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    user = update.effective_user

    # Проверяем бан
    if db.is_banned(user.id):
        await safe_answer(query, "Аккаунт заблокирован за нарушение правил.", show_alert=True)
        return ConversationHandler.END

    subscribed = await check_subscription(user.id, context)
    if not subscribed:
        try: await query.message.delete()
        except: pass
        await context.bot.send_message(user.id, "Сначала подпишитесь на канал!",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(EM_ARROW_R + " Подписаться", url=EMAIL_TG_CHANNEL_URL)],
                [InlineKeyboardButton(EM_OK + " Я подписался", callback_data="check_subscription")],
                [InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]]))
        return ConversationHandler.END

    db.ensure_daily_ads_fresh(user.id)
    user_data = db.get_user(user.id)
    tariff = normalize_tariff(user_data['tariff'])

    if tariff == 'Free' and user_data.get('daily_ads_count', 0) >= TARIFFS['Free']['daily_ads']:
        try: await query.message.delete()
        except: pass
        await context.bot.send_message(user.id,
            f"Дневной лимит исчерпан\n\nДоступно {TARIFFS['Free']['daily_ads']} объявления в день. Попробуйте завтра.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")],
            ]))
        return ConversationHandler.END

    # Сброс старых данных
    context.user_data.pop('creating_ad', None)
    context.user_data.pop('photo_limit', None)
    context.user_data['creating_ad'] = {
        'user_id': user.id, 'photos': [], 'title': '',
        'description': '', 'price': 0, 'category': '',
        'contact_info': '', 'delivery_list': [],
    }
    # Сохраняем черновик для напоминания о брошенном объявлении
    db.save_abandoned_draft(user.id, 'started')

    keyboard = [
        [InlineKeyboardButton("· Аренда жилья",         callback_data="cad_cat:rent"),
         InlineKeyboardButton("· Продажа жилья",        callback_data="cad_cat:realty")],
        [InlineKeyboardButton("· Вакансии",              callback_data="cad_cat:jobs"),
         InlineKeyboardButton("· Подработки",            callback_data="cad_cat:gigs")],
        [InlineKeyboardButton(EM_DOT + " Техника",        callback_data="cad_cat:tech"),
         InlineKeyboardButton(EM_DOT + " Одежда",        callback_data="cad_cat:clothes")],
        [InlineKeyboardButton(EM_DOT + " Обувь",         callback_data="cad_cat:shoes"),
         InlineKeyboardButton(EM_DOT + " Прочие вещи",   callback_data="cad_cat:other")],
        [InlineKeyboardButton(EM_FAIL + " Отмена",        callback_data="cancel")],
    ]
    try: await query.delete_message()
    except: pass
    tariff_label = TARIFF_LABELS.get(tariff, tariff)
    try:
        await query.message.reply_photo(
                photo=BANNERS["create_ad"],
            caption=f"<b>Новое объявление</b>  {_ad_progress(1)}\n\n<b>Категория:</b>",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.HTML
        )
    except Exception:
        await query.message.reply_text(
            f"<b>Новое объявление</b>  {_ad_progress(1)}\n\n<b>Категория:</b>",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.HTML
        )
    return States.CREATE_AD_CATEGORY


async def create_ad_category(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    cat_map = {
        "cad_cat:rent":    "· Аренда жилья",
        "cad_cat:realty":  "· Продажа жилья",
        "cad_cat:jobs":    "· Вакансии",
        "cad_cat:gigs":    "· Подработки",
        "cad_cat:tech":    f"{EM_DOT} Техника",
        "cad_cat:clothes": f"{EM_DOT} Одежда",
        "cad_cat:shoes":   f"{EM_DOT} Обувь",
        "cad_cat:other":   f"{EM_DOT} Прочие вещи",
    }
    # Поддержка старых колбэков
    old_map = {
        "category_clothes": f"{EM_DOT} Одежда",
        "category_shoes":   f"{EM_DOT} Обувь",
        "category_tech":    f"{EM_DOT} Техника",
        "category_other":   f"{EM_DOT} Прочие вещи",
    }
    category = cat_map.get(query.data) or old_map.get(query.data, f"{EM_DOT} Прочие вещи")
    context.user_data['creating_ad']['category'] = category
    context.user_data['creating_ad']['is_legit'] = False

    # Определяем флоу по категории
    if category in ('· Аренда жилья', '· Продажа жилья'):
        flow = 'realty'
        title_hint = 'ул. Баумана 12, 2-комн. квартира'
        title_label = 'Адрес или краткое описание объекта'
    elif category in ('· Вакансии', '· Подработки'):
        flow = 'jobs'
        title_hint = 'Менеджер по продажам, Водитель, Сборка мебели'
        title_label = 'Название должности или задания'
    else:
        flow = 'goods'
        title_hint = CATEGORY_EXAMPLES.get(category, 'Название товара')
        title_label = 'Название товара — коротко и понятно'

    context.user_data['creating_ad']['_flow'] = flow

    await safe_edit_message(query,
        f"<b>{title_label}</b>  {_ad_progress(2)}\n\n"
        f"Категория: {category}\n\n"
        f"<i>Пример: {title_hint}</i>",
        [[InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")]])
    return States.CREATE_AD_TITLE


async def create_ad_title(update: Update, context: ContextTypes.DEFAULT_TYPE):
    title = update.message.text.strip()
    if len(title) < 3:
        await update.message.reply_text("Название слишком короткое. Введите ещё раз:")
        return States.CREATE_AD_TITLE

    context.user_data['creating_ad']['title'] = title
    flow = context.user_data['creating_ad'].get('_flow', 'goods')

    if flow == 'realty':
        return await _ask_rooms(update.message, context)
    elif flow == 'jobs':
        return await _ask_employment(update.message, context)
    else:
        category = context.user_data['creating_ad'].get('category', '')
        # Состояние только для техники и прочего
        needs_condition = any(x in category.lower() for x in ['техника', 'прочие'])
        needs_size      = any(x in category.lower() for x in ['одежда', 'обувь'])
        if needs_condition:
            keyboard = []
            row = []
            for label, val in CONDITION_OPTIONS:
                row.append(InlineKeyboardButton(label, callback_data=f"cad_cond:{val}"))
                if len(row) == 2:
                    keyboard.append(row); row = []
            if row: keyboard.append(row)
            keyboard.append([InlineKeyboardButton(EM_DOT + " Пропустить", callback_data="cad_cond:skip")])
            keyboard.append([InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")])
            await update.message.reply_text(
                f"<b>Состояние товара</b>  {_ad_progress(3)}\n\n"
                f"<b>{title}</b>\n\nВыберите состояние:",
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode=ParseMode.HTML
            )
            return States.CREATE_AD_CONDITION
        elif needs_size:
            return await _ask_size(update.message, context)
        else:
            return await _ask_city(update.message, context)


