async def create_ad_area(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not context.user_data.get('creating_ad', {}).get('_awaiting_area'):
        return States.CREATE_AD_AREA
    text = update.message.text.strip().replace(',', '.')
    try:
        area = float(text)
        if area <= 0: raise ValueError
    except ValueError:
        await update.message.reply_text(f"{EM_FAIL} Введите число, например: 45")
        return States.CREATE_AD_AREA
    context.user_data['creating_ad']['size'] = f"{area} м²"
    context.user_data['creating_ad'].pop('_awaiting_area', None)
    category = context.user_data['creating_ad'].get('category', '')
    is_rental = category == '· Аренда жилья'
    keyboard = [
        [InlineKeyboardButton("1/5",  callback_data="cad_floor:1/5"),
         InlineKeyboardButton("2/5",  callback_data="cad_floor:2/5"),
         InlineKeyboardButton("3/5",  callback_data="cad_floor:3/5")],
        [InlineKeyboardButton("5/9",  callback_data="cad_floor:5/9"),
         InlineKeyboardButton("7/9",  callback_data="cad_floor:7/9"),
         InlineKeyboardButton("9/9",  callback_data="cad_floor:9/9")],
        [InlineKeyboardButton("3/10", callback_data="cad_floor:3/10"),
         InlineKeyboardButton("8/16", callback_data="cad_floor:8/16"),
         InlineKeyboardButton("Частный дом", callback_data="cad_floor:частный дом")],
        [InlineKeyboardButton(EM_DOT + " Написать свой", callback_data="cad_floor:custom")],
        [InlineKeyboardButton(EM_DOT + " Пропустить", callback_data="cad_floor:skip")],
        [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")],
    ]
    await update.message.reply_text(
        f"<b>Этаж / этажность</b>  {_ad_progress(5)}\n\nВыберите или напишите (этаж/всего этажей):",
        reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    return States.CREATE_AD_FLOOR


async def create_ad_floor(update: Update, context: ContextTypes.DEFAULT_TYPE):
    cad = context.user_data['creating_ad']
    if update.callback_query:
        query = update.callback_query
        await safe_answer(query, )
        val = query.data.split(":", 1)[1]
        if val == 'custom':
            await safe_edit_message(query,
                f"<b>Этаж / этажность</b>\n\nВведите в формате: <i>3/9</i>",
                [[InlineKeyboardButton(EM_DOT + " Пропустить", callback_data="cad_floor:skip"),
                  InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")]])
            cad['_awaiting_floor'] = True
            return States.CREATE_AD_FLOOR
        cad['delivery'] = '' if val == 'skip' else f"Этаж: {val}"
    else:
        if not cad.get('_awaiting_floor'):
            return States.CREATE_AD_FLOOR
        cad['delivery'] = f"Этаж: {update.message.text.strip()}"
        cad.pop('_awaiting_floor', None)
    return await _ask_city(update.callback_query or update.message, context)


