def _city_keyboard():
    keyboard = []
    row = []
    for c in ALLOWED_CITIES_SORTED:
        row.append(InlineKeyboardButton(c, callback_data=f"cad_city:{c}"))
        if len(row) == 2:
            keyboard.append(row); row = []
    if row: keyboard.append(row)
    keyboard.append([InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")])
    return keyboard


def _city_suggest_keyboard(query: str = "") -> list:
    """
    Все города из CITY_CHANNELS кнопками по 2 в ряд.
    Плюс кнопка «Другой город» для ручного ввода.
    Если query задан — фильтруем по совпадению.
    """
    # Фиксированный порядок: сначала крупные города, потом остальные по алфавиту
    ordered = [
        "Ижевск", "Воткинск", "Сарапул", "Глазов", "Можга",
        "Камбарка", "Балезино", "Игра", "Ува", "Кизнер",
        "Якшур-Бодья", "Малая Пурга", "Дебёсы", "Алнаши", "Вавож",
        "Грахово", "Каракулино", "Селты", "Сюмси", "Шаркан", "Юкаменское",
    ]
    # Дополняем если вдруг что-то пропустили
    for c in ALLOWED_CITIES_SORTED:
        if c not in ordered:
            ordered.append(c)

    q = query.strip().lower()
    matches = [c for c in ordered if c in ALLOWED_CITIES] if not q else               [c for c in ordered if q in c.lower() and c in ALLOWED_CITIES]

    if not matches and q:
        return [
            [InlineKeyboardButton(f"· Сохранить «{query[:30]}»", callback_data=f"cad_city_custom:{query[:60]}")],
            [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")],
        ]

    keyboard = []
    row = []
    for c in matches:
        row.append(InlineKeyboardButton(c, callback_data=f"cad_city:{c}"))
        if len(row) == 2:
            keyboard.append(row); row = []
    if row:
        keyboard.append(row)
    # Кнопка для любого другого города
    keyboard.append([InlineKeyboardButton("· Другой город — написать", callback_data="cad_city_input")])
    keyboard.append([InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")])
    return keyboard


async def _ask_city(query_or_msg, context):
    # Выставляем флаг — чтобы текстовый диспетчер знал что ждём город
    if 'creating_ad' not in context.user_data:
        context.user_data['creating_ad'] = {}
    context.user_data['creating_ad']['_awaiting_city'] = True

    keyboard = _city_suggest_keyboard()

    text = (
        f"+ <b>Город</b>  {_ad_progress(4)}\n\n"
        f"Выберите свой город. Если города нет в списке — нажмите «Другой город»:"
    )
    if hasattr(query_or_msg, 'edit_message_text'):
        await safe_edit_message(query_or_msg, text, keyboard, parse_mode=ParseMode.HTML)
    else:
        await query_or_msg.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    return States.CREATE_AD_CITY


