async def create_ad_address_skip(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь пропустил ввод адреса."""
    query = update.callback_query
    await safe_answer(query, )
    context.user_data['creating_ad'].pop('_awaiting_address', None)
    flow = context.user_data['creating_ad'].get('_flow', 'goods')
    if flow in ('realty', 'jobs'):
        return await _ask_price_step(query, context)
    return await _ask_price(query, context)


async def create_ad_address_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь ввёл адрес текстом."""
    address = update.message.text.strip()
    city = context.user_data['creating_ad'].get('city', '')
    context.user_data['creating_ad']['address'] = address
    context.user_data['creating_ad'].pop('_awaiting_address', None)
    # Показываем ссылку на карту
    import urllib.parse as _urlparse
    full_addr = f"{address}, {city}, Удмуртия" if city else f"{address}, Удмуртия"
    map_query = _urlparse.quote_plus(full_addr)
    map_url = f"https://yandex.ru/maps/?text={map_query}"
    await update.message.reply_text(
        f"{EM_OK} Адрес сохранён: <b>{address}</b>\n"
        f"<a href=\"{map_url}\">Посмотреть на карте</a>",
        parse_mode=ParseMode.HTML,
        disable_web_page_preview=True,
    )
    flow = context.user_data['creating_ad'].get('_flow', 'goods')
    if flow in ('realty', 'jobs'):
        return await _ask_price_step(update.message, context)
    return await _ask_price(update.message, context)


def _delivery_keyboard(selected: list) -> list:
    keyboard = []
    row = []
    for label, val in DELIVERY_OPTIONS:
        check = f"{EM_OK} " if val in selected else ""
        cb = f"cad_dlv:{val}"
        row.append(InlineKeyboardButton(f"{check}{label}", callback_data=cb))
        if len(row) == 2:
            keyboard.append(row); row = []
    if row: keyboard.append(row)
    if selected:
        keyboard.append([InlineKeyboardButton(f"{EM_OK} Готово ({len(selected)} выбрано)", callback_data="cad_dlv:done")])
    keyboard.append([InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")])
    return keyboard


async def _ask_delivery(query_or_msg, context):
    selected = context.user_data['creating_ad'].get('delivery_list', [])
    keyboard = _delivery_keyboard(selected)
    text = (f"+ <b>Доставка</b>  {_ad_progress(5)}\n\n"
            "Выберите один или несколько способов доставки.\n"
            "Нажмите ещё раз чтобы снять выбор:")
    if hasattr(query_or_msg, 'edit_message_text'):
        await safe_edit_message(query_or_msg, text, keyboard, parse_mode=ParseMode.HTML)
    else:
        await query_or_msg.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    return States.CREATE_AD_DELIVERY


async def create_ad_delivery(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Тогл кнопок доставки + обработка 'Другое' и 'Готово'"""
    query = update.callback_query
    await safe_answer(query, )
    val = query.data.split(":", 1)[1]
    selected = context.user_data['creating_ad'].setdefault('delivery_list', [])

    if val == 'done':
        if not selected:
            await safe_answer(query, "Выберите хотя бы один способ доставки", show_alert=True)
            return States.CREATE_AD_DELIVERY
        # Собираем строку доставки
        context.user_data['creating_ad']['delivery'] = ', '.join(selected)
        return await _ask_price(query, context)

    if val == 'custom':
        await safe_edit_message(query,
            f"+ <b>Укажите способ доставки</b>\n\nНапишите название курьерской службы или способа:",
            [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="cad_dlv_back")]])
        return States.CREATE_AD_DELIVERY_CUSTOM

    # Тогл
    if val in selected:
        selected.remove(val)
    else:
        selected.append(val)

    keyboard = _delivery_keyboard(selected)
    text = (f"+ <b>Доставка</b>  {_ad_progress(5)}\n\n"
            "Выберите один или несколько способов.\n"
            "Нажмите ещё раз чтобы снять:")
    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    return States.CREATE_AD_DELIVERY


async def create_ad_delivery_custom(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь написал свой способ доставки"""
    if update.callback_query:
        # Кнопка «Назад»
        await update.callback_query.answer()
        return await _ask_price(update.callback_query, context)
    custom = update.message.text.strip()
    context.user_data['creating_ad'].setdefault('delivery_list', []).append(custom)
    return await _ask_price(update.message, context)


async def _ask_price_step(query_or_msg, context):
    """Умный запрос цены — подсказка зависит от категории."""
    context.user_data['creating_ad']['_awaiting_price'] = True
    flow     = context.user_data['creating_ad'].get('_flow', 'goods')
    category = context.user_data['creating_ad'].get('category', '')

    if flow == 'realty':
        if 'аренда' in category.lower():
            hint = "Введите ежемесячную арендную плату:\n<i>Например: 15000</i>"
        else:
            hint = "Введите стоимость объекта:\n<i>Например: 2500000</i>"
    elif flow == 'jobs':
        if 'подработки' in category.lower():
            hint = "Введите оплату за задачу:\n<i>Например: 3000. Можно написать 0 — по договорённости</i>"
        else:
            hint = "Введите зарплату (₽/мес):\n<i>Например: 50000. Напишите 0 — по договорённости</i>"
    else:
        hint = "Введите цену в рублях:\n<i>Только число, например: 2500</i>"

    text = f"+ <b>Цена</b>  {_ad_progress(6)}\n\n{hint}"
    kb = [[InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")]]
    if hasattr(query_or_msg, 'edit_message_text'):
        await safe_edit_message(query_or_msg, text, kb, parse_mode=ParseMode.HTML)
    else:
        await query_or_msg.reply_text(text, reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML)
    return States.CREATE_AD_PRICE


