async def create_ad_price(update: Update, context: ContextTypes.DEFAULT_TYPE):
    price_text = update.message.text.strip().replace(' ','').replace('₽','').replace('руб','').replace('р','')
    try:
        price = int(price_text)
        if price <= 0: raise ValueError
    except ValueError:
        await update.message.reply_text(f"{EM_FAIL} Введите число больше нуля, например: 2500")
        return States.CREATE_AD_PRICE  # возвращаем в то же состояние

    context.user_data['creating_ad']['price'] = price
    context.user_data['creating_ad'].pop('_awaiting_price', None)

    user_data = db.get_user(update.effective_user.id)
    tariff = normalize_tariff((user_data or {}).get('tariff', 'Free'))
    photo_limit = TARIFFS.get(tariff, TARIFFS['Free']).get('photo_limit', 10)
    context.user_data['photo_limit'] = photo_limit

    # Описание
    context.user_data['creating_ad']['_awaiting_description'] = True
    category = context.user_data['creating_ad'].get('category', '')
    cat_hint = CATEGORY_DESC_HINTS.get(category, '')
    cat_hint_text = f"\n\n{cat_hint}" if cat_hint else "\n\n<i>Расскажите подробнее — состояние, история, особенности</i>"
    desc_hint = (
        f"+ <b>Описание</b>  {_ad_progress(6)}\n"
        f"{cat_hint_text}"
    )
    skip_keyboard = [
        [InlineKeyboardButton("✦ Сгенерировать описание", callback_data="cad_desc:ai_gen")],
        [InlineKeyboardButton(EM_DOT + " Пропустить", callback_data="cad_desc:skip")],
        [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")],
    ]

    await update.message.reply_text(
        desc_hint,
        reply_markup=InlineKeyboardMarkup(skip_keyboard),
        parse_mode=ParseMode.HTML
    )
    return States.CREATE_AD_DESCRIPTION_OPT


async def create_ad_description_opt(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Необязательное описание + ИИ генерация"""
    # Защита от потери контекста при перезапуске бота
    if not context.user_data.get('creating_ad'):
        msg = update.callback_query.message if update.callback_query else update.message
        await msg.reply_text(
            f"{EM_FAIL} Сессия создания объявления истекла из-за перезапуска бота.\n\n"
            "Пожалуйста, начните создание заново — нажмите «+ Разместить».",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("+ Разместить", callback_data="create_ad")
            ]])
        )
        return States.MAIN_MENU

    if update.callback_query:
        await update.callback_query.answer()
        cb_data = update.callback_query.data

        if cb_data == "cad_desc:ai_gen":
            # Проверяем дневной лимит генераций
            user_id = update.effective_user.id
            tariff_info = get_tariff_info(user_id)
            ai_limit = tariff_info.get('daily_ai_gen', 1)
            user_data = db.get_user(user_id)
            today = get_moscow_time().strftime("%Y-%m-%d")
            ai_count = user_data.get('ai_gen_count', 0) or 0
            reset_date = user_data.get('ai_gen_reset_date', '')
            if reset_date != today:
                ai_count = 0
                db.update_user(user_id, ai_gen_count=0, ai_gen_reset_date=today)
            _ai_trial_used_now = False
            if ai_count >= ai_limit:
                if check_and_consume_trial(user_id, "ai_gen"):
                    _ai_trial_used_now = True
                else:
                    await safe_edit_message(update.callback_query,
                        f"{EM_FAIL} Лимит AI-генераций исчерпан ({ai_limit}/день).\n"
                        f"✦ ПОЛКА ПЛЮС — до {TARIFFS['Premium']['daily_ai_gen']} генераций в день.",
                        [[InlineKeyboardButton("✦ ПОЛКА ПЛЮС", callback_data="subscription_info")]]
                    )
                    return States.CREATE_AD_DESCRIPTION_OPT
            else:
                db.update_user(user_id, ai_gen_count=ai_count + 1)

            ad = context.user_data.get('creating_ad', {})
            title    = ad.get('title', '')
            category = ad.get('category', '')
            condition = ad.get('condition', '')
            price    = ad.get('price', 0)

            await update.callback_query.edit_message_text(
                ("✦ Бесплатная пробная генерация! Дальше — по подписке ПОЛКА ПЛЮС.\n\n" if _ai_trial_used_now else "")
                + "✦ Генерирую описание...", parse_mode=ParseMode.HTML)

            flow = context.user_data['creating_ad'].get('_flow', 'goods')
            prompt = (
                f"Напиши описание для объявления о продаже.\n"
                f"Товар: {title}\n"
                f"Категория: {category}\n"
                f"Состояние: {condition or 'не указано'}\n"
                f"Цена: {price} ₽\n\n"
                f"Правила:\n"
                f"- 2-3 предложения, живой язык\n"
                f"- Не используй: отличный вариант, не упустите, звоните, пишите, торг, срочно, идеальное состояние\n"
                f"- Не начинай с 'Продаю'\n"
                f"- Напиши только текст описания, без заголовков"
            )
            generated = await _llm_completion(
                messages=[{"role": "user", "content": prompt}],
                max_tokens=300, temperature=0.8,
            )

            if not generated:
                _flow_fb = context.user_data.get('creating_ad', {}).get('_flow', 'goods')
                if _flow_fb == 'jobs':
                    _fmt = condition or 'гибкий график'
                    _pay = f"{price} ₽" if price else 'по договорённости'
                    generated = (
                        f"Ищу человека на {title.lower()}. "
                        f"Формат: {_fmt.lower()}, оплата {_pay}. "
                        f"Подробности в личку."
                    )
                elif _flow_fb == 'realty':
                    _price_str = f", {price} ₽" if price else ""
                    generated = (
                        f"{title}{_price_str}. "
                        f"{condition or 'Состояние хорошее'}. "
                        f"Показ по договорённости."
                    )
                else:
                    _cond_str = f" — {condition.lower()}" if condition else ""
                    _price_str = f", {price} ₽" if price else ""
                    generated = (
                        f"{title}{_cond_str}. "
                        f"Состояние рабочее, без нареканий{_price_str}. "
                        f"Подробности в личке."
                    )

            # Сохраняем сгенерированный текст во временное хранилище
            context.user_data['_ai_desc_draft'] = generated

            keyboard = [
                [InlineKeyboardButton("✓ Вставить", callback_data="cad_desc:ai_insert")],
                [InlineKeyboardButton("↺ Ещё раз",  callback_data="cad_desc:ai_gen")],
                [InlineKeyboardButton(EM_DOT + " Написать своё", callback_data="cad_desc:manual")],
                [InlineKeyboardButton(EM_DOT + " Пропустить",    callback_data="cad_desc:skip")],
            ]
            await update.callback_query.message.reply_text(
                f"✦ <b>Сгенерированное описание:</b>\n\n{generated}",
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode=ParseMode.HTML
            )
            return States.CREATE_AD_DESCRIPTION_OPT

        elif cb_data == "cad_desc:ai_insert":
            generated = context.user_data.pop('_ai_desc_draft', '')
            context.user_data['creating_ad']['description'] = generated

        elif cb_data == "cad_desc:manual":
            # Просим написать вручную
            await update.callback_query.edit_message_text(
                f"+ <b>Описание</b>\n\nНапишите описание товара:",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(EM_DOT + " Пропустить", callback_data="cad_desc:skip")]
                ])
            )
            return States.CREATE_AD_DESCRIPTION_OPT

        elif cb_data == "cad_desc:template":
            context.user_data['creating_ad']['description'] = ''
        else:
            context.user_data['creating_ad']['description'] = ''
    else:
        context.user_data['creating_ad']['description'] = update.message.text.strip()

    context.user_data['creating_ad'].pop('_awaiting_description', None)
    return await _ask_photos(update, context)


