async def handle_photos(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message.photo:
        return States.CREATE_AD_CONTACTS
    photo = update.message.photo[-1].file_id
    if 'creating_ad' not in context.user_data:
        return States.CREATE_AD_CONTACTS
    ad = context.user_data['creating_ad']
    photo_limit = context.user_data.get('photo_limit', 10)

    if len(ad['photos']) < photo_limit:
        ad['photos'].append(photo)
        photo_idx = len(ad['photos']) - 1
        remaining = photo_limit - len(ad['photos'])
        if remaining > 0:
            text = (f"{EM_OK} Фото {len(ad['photos'])}/{photo_limit}\n\n"
                    "Добавьте ещё или нажмите <b>Далее</b>:")
        else:
            text = f"{EM_OK} Все {photo_limit} фото добавлены. Нажмите <b>Далее</b>:"

        kbd = [
            [InlineKeyboardButton(EM_DIAMOND + " Отредактировать изображение", callback_data=f"edit_photo_menu:{photo_idx}")],
            [InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="next_step")],
            [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")],
        ]

        await update.message.reply_text(text,
            reply_markup=InlineKeyboardMarkup(kbd),
            parse_mode=ParseMode.HTML)
    else:
        await update.message.reply_text(
            f"{EM_FAIL} Лимит {photo_limit} фото достигнут. Нажмите <b>Далее</b>:",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="next_step")]]),
            parse_mode=ParseMode.HTML)
    return States.CREATE_AD_CONTACTS


async def rembg_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Удаляет фон у выбранного фото (Photoroom API или локальная rembg)."""
    query = update.callback_query

    # ВАЖНО: callback_query можно ответить только ОДИН раз — повторный
    # query.answer() Telegram отклоняет с ошибкой вида "query is too old /
    # query id is invalid", а safe_answer() такие ошибки молча глотает
    # (ищет "query"/"invalid" в тексте). Раньше здесь СНАЧАЛА показывался
    # тост "⏳ Удаляю фон…", а потом — если лимит исчерпан — второй алерт
    # с текстом лимита. Для Free-тарифа (daily_enhance=0) лимит исчерпан
    # ВСЕГДА, то есть второй alert должен был показаться на каждое
    # нажатие — но он проглатывался как "двойной ответ", и пользователь
    # не видел вообще ничего ни на Free, ни после исчерпания лимита на
    # Premium. Порядок исправлен: сначала проверяем лимит и отвечаем один
    # раз тем сообщением, которое реально нужно показать.
    if not PHOTOROOM_API_KEY and not REMBG_AVAILABLE:
        await safe_answer(query, "Функция недоступна", show_alert=True)
        return

    used = db.get_daily_photo_edits(query.from_user.id)
    daily_limit = get_daily_enhance_limit(query.from_user.id)
    _trial_used_now = False
    if used >= daily_limit:
        if check_and_consume_trial(query.from_user.id, "rembg"):
            _trial_used_now = True
        else:
            hint = f" Оформите ПОЛКА ПЛЮС — 199 ₽/мес, лимит {TARIFFS['Premium']['daily_enhance']}/день." if not get_tariff_info(query.from_user.id)['key'] == 'Premium' else ""
            await safe_answer(query,
                f"{EM_FAIL} Лимит обработки фото исчерпан ({daily_limit}/день).{hint}"
                f"\nЛимит обновится завтра в 00:00.",
                show_alert=True
            )
            return

    if _trial_used_now:
        await safe_answer(query, "✦ Бесплатная пробная попытка! Дальше — по подписке ПОЛКА ПЛЮС.", show_alert=True)
    else:
        await safe_answer(query, "⏳ Удаляю фон…", show_alert=False)

    ad = context.user_data.get('creating_ad')
    if not ad:
        await safe_answer(query, "Данные потеряны. Начните заново.", show_alert=True)
        return

    try:
        photo_idx = int(query.data.split(":")[1])
    except (IndexError, ValueError):
        await safe_answer(query, "Ошибка. Попробуйте ещё раз.", show_alert=True)
        return

    if photo_idx >= len(ad.get('photos', [])):
        await safe_answer(query, "Фото не найдено.", show_alert=True)
        return

    file_id = ad['photos'][photo_idx]

    prev_edit = context.user_data.pop('_last_edit_menu_msg_id', None)
    if prev_edit:
        try:
            await context.bot.delete_message(chat_id=query.message.chat.id, message_id=prev_edit)
        except Exception:
            pass

    try:
        if isinstance(file_id, (bytes, bytearray)):
            input_bytes = bytes(file_id)
        else:
            photo_cache = ad.get('_photo_cache') or {}
            input_bytes = photo_cache.get(photo_idx)
            if input_bytes is None:
                file_obj = await context.bot.get_file(file_id)
                buf_in = _io.BytesIO()
                await file_obj.download_to_memory(buf_in)
                input_bytes = buf_in.getvalue()

        import aiohttp as _aiohttp
        png_bytes = None

        if PHOTOROOM_API_KEY:
            try:
                timeout = _aiohttp.ClientTimeout(total=60)
                async with _aiohttp.ClientSession(timeout=timeout) as session:
                    form = _aiohttp.FormData()
                    form.add_field('image_file', input_bytes, filename='photo.jpg', content_type='image/jpeg')
                    async with session.post(
                        'https://sdk.photoroom.com/v1/segment',
                        data=form,
                        headers={'x-api-key': PHOTOROOM_API_KEY},
                    ) as resp:
                        if resp.status == 200:
                            png_bytes = await resp.read()
                        else:
                            err_text = await resp.text()
                            logger.warning(f"photoroom error {resp.status}: {err_text}")
            except Exception as _pe:
                logger.warning(f"photoroom exception: {_pe}")

        if png_bytes is None and REMBG_AVAILABLE:
            _sess = _get_rembg_session()
            if _sess:
                png_bytes = _sess.remove(input_bytes)

        if png_bytes is None:
            raise Exception("Все способы удаления фона не сработали")

        img_out = _PILImage.open(_io.BytesIO(png_bytes)).convert("RGBA")
        white = _PILImage.new("RGBA", img_out.size, (255, 255, 255, 255))
        white.paste(img_out, mask=img_out.split()[3])
        final = white.convert("RGB")
        buf_out = _io.BytesIO()
        final.save(buf_out, format="JPEG", quality=92)
        buf_out.seek(0)

        from telegram import InputFile
        sent = await query.message.reply_photo(
            photo=InputFile(buf_out, filename="no_bg.jpg"),
            caption=(
                f"{EM_OK} Фон удалён! Фото {photo_idx+1} заменено.\n\n"
                "Добавьте ещё фото или нажмите <b>Далее</b>."
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(EM_DIAMOND + " Редактировать ещё", callback_data=f"edit_photo_menu:{photo_idx}")],
                [InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="next_step")],
                [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")],
            ])
        )
        ad['photos'][photo_idx] = sent.photo[-1].file_id
        db.log_action(query.from_user.id, 'rembg_used', f'photo_idx:{photo_idx}')

    except Exception as e:
        logger.error(f"rembg error: {e}", exc_info=True)
        await query.message.reply_text(
            f"{EM_FAIL} Не удалось удалить фон: {e}\n\nПродолжайте без удаления фона.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="next_step")],
            ])
        )


