async def _enhance_with_hf(image_bytes: bytes) -> bytes | None:
    """Улучшает фото через Hugging Face Inference API (Real-ESRGAN)."""
    model = "philz1337x/Real-ESRGAN"
    url = f"https://api-inference.huggingface.co/models/{model}"
    try:
        headers = {"Content-Type": "application/octet-stream"}
        if HF_API_TOKEN:
            headers["Authorization"] = f"Bearer {HF_API_TOKEN}"
        import aiohttp as _aiohttp
        import ssl as _ssl_hf
        async with _aiohttp.ClientSession(
            connector=_aiohttp.TCPConnector(ssl=_ssl_hf._create_unverified_context())
        ) as s:
            async with s.post(url, data=image_bytes, headers=headers,
                              timeout=_aiohttp.ClientTimeout(total=120)) as r:
                if r.status == 200:
                    data = await r.read()
                    if len(data) > 1000:
                        logger.info(f"_enhance_with_hf: success ({len(data)} bytes)")
                        return data
                    logger.warning(f"_enhance_with_hf: response too small ({len(data)} bytes)")
                else:
                    logger.warning(f"_enhance_with_hf: HTTP {r.status}")
    except Exception as e:
        logger.warning(f"_enhance_with_hf: {e}")
    return None

async def _enhance_photo_standalone(file_id, bot) -> bytes | None:
    """Скачивает фото, улучшает через HF Real-ESRGAN → Pillow fallback."""
    try:
        from PIL import Image as _PILImg, ImageEnhance, ImageFilter
        import io as _io

        if isinstance(file_id, (bytes, bytearray)):
            photo_data = bytes(file_id)
        else:
            tg_file = await bot.get_file(file_id)
            buf_in = _io.BytesIO()
            await tg_file.download_to_memory(buf_in)
            buf_in.seek(0)
            photo_data = buf_in.read()

        hf_result = await _enhance_with_hf(photo_data)
        if hf_result:
            return hf_result

        # Pillow fallback
        buf_in = _io.BytesIO(photo_data)
        pil_img = _PILImg.open(buf_in).convert("RGB")
        MAX_SIDE = 1280
        w, h = pil_img.size
        if max(w, h) > MAX_SIDE:
            scale = MAX_SIDE / max(w, h)
            pil_img = pil_img.resize((int(w * scale), int(h * scale)), _PILImg.LANCZOS)
        elif max(w, h) < 800:
            scale = 800 / max(w, h)
            pil_img = pil_img.resize((int(w * scale), int(h * scale)), _PILImg.LANCZOS)
        pil_img = ImageEnhance.Contrast(pil_img).enhance(1.15)
        pil_img = ImageEnhance.Brightness(pil_img).enhance(1.05)
        pil_img = ImageEnhance.Color(pil_img).enhance(1.1)
        pil_img = pil_img.filter(ImageFilter.UnsharpMask(radius=1.5, percent=120, threshold=3))
        buf_out = _io.BytesIO()
        pil_img.save(buf_out, format="JPEG", quality=88, optimize=True)
        buf_out.seek(0)
        return buf_out.read()
    except Exception as e:
        logger.warning(f"_enhance_photo_standalone error: {e}")
        return None


async def enhance_photo_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Улучшает качество выбранного фото объявления по кнопке пользователя."""
    query = update.callback_query

    # См. подробный комментарий в rembg_handler — тот же баг с двойным
    # query.answer(): проверяем лимит ДО первого ответа, а не после.
    used = db.get_daily_photo_edits(query.from_user.id)
    daily_limit = get_daily_enhance_limit(query.from_user.id)
    _trial_used_now = False
    if used >= daily_limit:
        if check_and_consume_trial(query.from_user.id, "enhance"):
            _trial_used_now = True
        else:
            hint = f" Оформите ПОЛКА ПЛЮС — 199 ₽/мес, лимит {TARIFFS['Premium']['daily_enhance']}/день." if not get_tariff_info(query.from_user.id)['key'] == 'Premium' else ""
            await safe_answer(query,
                f"{EM_FAIL} Лимит обработки фото исчерпан ({daily_limit}/день).{hint}"
                f"\nЛимит обновится завтра в 00:00.",
                show_alert=True
            )
            return

    if _trial_used_now:
        await safe_answer(query, "✦ Бесплатная пробная попытка! Дальше — по подписке ПОЛКА ПЛЮС.", show_alert=True)
    else:
        await safe_answer(query, "⏳ Улучшаю фото…", show_alert=False)

    ad = context.user_data.get('creating_ad')
    if not ad:
        await safe_answer(query, "Данные потеряны. Начните заново.", show_alert=True)
        return

    try:
        photo_idx = int(query.data.split(":")[1])
    except (IndexError, ValueError):
        await safe_answer(query, "Ошибка. Попробуйте ещё раз.", show_alert=True)
        return

    if photo_idx >= len(ad.get('photos', [])):
        await safe_answer(query, "Фото не найдено.", show_alert=True)
        return

    file_id = ad['photos'][photo_idx]
    enhanced_bytes = await _enhance_photo_standalone(file_id, context.bot)

    if not enhanced_bytes:
        await query.message.reply_text(
            f"{EM_FAIL} Не удалось улучшить фото. Продолжайте без улучшения.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="next_step")],
            ])
        )
        return

    from telegram import InputFile
    sent = await query.message.reply_photo(
        photo=InputFile(_io.BytesIO(enhanced_bytes), filename="enhanced.jpg"),
        caption=(
            f"{EM_OK} Фото {photo_idx+1} улучшено! Контраст, резкость и яркость повышены.\n\n"
            "Добавьте ещё фото или нажмите <b>Далее</b>."
        ),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton(EM_DIAMOND + " Редактировать ещё", callback_data=f"edit_photo_menu:{photo_idx}")],
            [InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="next_step")],
            [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="cancel")],
        ])
    )
    ad['photos'][photo_idx] = sent.photo[-1].file_id
    db.log_action(query.from_user.id, 'enhance_used', f'photo_idx:{photo_idx}')


