async def handle_cad_edit_preview_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Принимает новое значение поля и возвращает на превью."""
    field = context.user_data.pop('_preview_editing_field', None)
    if not field:
        return
    new_value = update.message.text.strip()
    if field == 'price':
        if not new_value.isdigit() or int(new_value) <= 0:
            await update.message.reply_text(f"{EM_FAIL} Цена — число больше 0. Попробуйте ещё раз:")
            context.user_data['_preview_editing_field'] = field
            return
    context.user_data.setdefault('creating_ad', {})[field] = new_value
    await _show_preview(update.message, context)

