async def create_ad_city_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Ввод города или адреса. Точное совпадение → сохраняем город.
    Частичное → подсказки. Произвольный текст (адрес) → сохраняем как есть."""
    text = update.message.text.strip()

    # 1. Точное совпадение с городом из списка
    matched = next((c for c in ALLOWED_CITIES_SORTED if c.lower() == text.lower()), None)
    if matched:
        context.user_data['creating_ad']['city'] = matched
        context.user_data['creating_ad'].pop('_awaiting_city', None)
        return await _ask_address(update.message, context)

    # 2. Есть похожие города → подсказки
    q = text.lower()
    starts   = [c for c in ALLOWED_CITIES_SORTED if c.lower().startswith(q)]
    contains = [c for c in ALLOWED_CITIES_SORTED if q in c.lower() and c not in starts]
    suggestions = (starts + contains)[:6]
    if suggestions:
        keyboard = _city_suggest_keyboard(text)
        keyboard.insert(-1, [InlineKeyboardButton(
            f"· Сохранить как «{text[:30]}»", callback_data=f"cad_city_custom:{text[:60]}"
        )])
        await update.message.reply_text(
            f"Ищу: «<b>{text}</b>»\n\nВыберите город или сохраните введённый текст как адрес:",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
        return States.CREATE_AD_CITY

    # 3. Не похоже на город — сохраняем как адрес и показываем карту
    context.user_data['creating_ad']['city'] = text
    context.user_data['creating_ad'].pop('_awaiting_city', None)
    # Формируем ссылку на карту для введённого адреса
    import urllib.parse as _urlparse
    map_query = _urlparse.quote_plus(f"{text}, Удмуртия")
    map_url = f"https://yandex.ru/maps/?text={map_query}"
    await update.message.reply_text(
        f"✓ Адрес сохранён: <b>{text}</b>\n"
        f"<a href=\"{map_url}\">Посмотреть на карте</a>",
        parse_mode=ParseMode.HTML,
        disable_web_page_preview=True,
        reply_markup=ReplyKeyboardRemove()
    )
    flow = context.user_data['creating_ad'].get('_flow', 'goods')
    if flow in ('realty', 'jobs'):
        return await _ask_price_step(update.message, context)
    return await _ask_price(update.message, context)


