async def handle_promo_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Обрабатывает текстовый ввод промокода"""
    try:
        if not context.user_data.get('waiting_promo'):
            return None
        code = update.message.text.strip().upper()
        context.user_data.pop('waiting_promo', None)
        user_id = update.effective_user.id

        promo = db.get_promocode(code)
        if not promo:
            # Проверим — может промокод существует но истёк или исчерпан
            cursor = db.conn.cursor()
            cursor.execute("SELECT code, current_uses, max_uses, expires_at, is_active FROM promocodes WHERE code = ?", (code,))
            raw = cursor.fetchone()
            if raw:
                # Считаем реальное количество использований
                _cur = db.conn.cursor()
                _cur.execute("SELECT COUNT(*) FROM promocode_uses WHERE promocode_id = ?", (raw['id'],))
                _real_uses = _cur.fetchone()[0]
                if not raw['is_active']:
                    reason = "промокод деактивирован"
                elif _real_uses >= raw['max_uses']:
                    reason = f"лимит использований исчерпан ({_real_uses}/{raw['max_uses']})"
                elif raw['expires_at'] and raw['expires_at'] < get_moscow_time().isoformat():
                    reason = "срок действия истёк"
                else:
                    reason = "недоступен"
                err_text = f"{EM_FAIL} Промокод <b>{code}</b> недействителен: {reason}."
            else:
                err_text = f"{EM_FAIL} Промокод <b>{code}</b> не найден.\n\nПроверьте правильность написания."
            await update.message.reply_text(
                err_text,
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
            )
            return States.MAIN_MENU

        # ── Проверка: уже использовал этот промокод ──────────────────────────
        if db.check_promocode_used(promo['id'], user_id):
            await update.message.reply_text(
                f"{EM_FAIL} Вы уже использовали промокод <b>{code}</b>.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
            )
            return States.MAIN_MENU

        discount = promo['discount_percent']
        service_type = promo.get('service_type', 'all')
        context.user_data['promo_code']     = code
        context.user_data['promo_discount'] = discount
        context.user_data['promo_plan']     = service_type
        context.user_data['promo_id']       = promo['id']

        # ── Определяем контекст ввода промокода ──────────────────────────────
        promo_source = context.user_data.get('promo_source', '')

        # ── Если промокод вводился со страницы оплаты закрепа ────────────────
        ad_id     = context.user_data.get('pinning_ad_id')
        pin_type  = context.user_data.get('pinning_type', 'rf')
        pin_price = context.user_data.get('pinning_price', PIN_PRICE)
        pin_hours = context.user_data.get('pinning_hours', 24)

        if ad_id and promo_source != 'subscription':
            if service_type not in ('all', 'pin'):
                st_labels = {'sub': 'ПОЛКА ПЛЮС', 'pin': 'закреп', 'all': 'все услуги'}
                await update.message.reply_text(
                    f"{EM_FAIL} Промокод <b>{code}</b> действует только на {st_labels.get(service_type, service_type)}.\n"
                    f"Он не подходит для оплаты закрепа.",
                    parse_mode=ParseMode.HTML,
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
                )
                return States.MAIN_MENU
            ad = db.get_ad(ad_id)
            discounted_price = round(pin_price * (1 - discount / 100))
            context.user_data['pinning_price'] = discounted_price  # сохраняем скидочную цену

            # Промокод фиксируется только после реальной оплаты


            pin_invoice_data = None
            crypto_url = ''
            if crypto_bot_api:
                try:
                    pin_invoice_data = await create_pin_crypto_invoice(
                        user_id=user_id, ad_id=ad_id,
                        pin_type=pin_type, price_rub=discounted_price, pin_hours=pin_hours,
                        promo_code=code,
                    )
                    if pin_invoice_data:
                        crypto_url = pin_invoice_data["pay_url"]
                        context.user_data['pin_crypto_invoice_id'] = pin_invoice_data["invoice_id"]
                except Exception as _ce:
                    logger.warning(f"promo pin crypto: {_ce}")

            # ── PayAnyWay СБП со скидкой ──────────────────────────────────────
            _dur_label = {24: "24 часа", 72: "3 дня", 168: "7 дней"}.get(pin_hours, f"{pin_hours}ч")
            sbp_discounted = round(discounted_price * 1.05)

            paw_url_promo, _ = create_payanyway_pin_url(
                user_id=user_id, ad_id=ad_id,
                pin_type=pin_type, pin_hours=pin_hours,
                amount_rub=sbp_discounted, promo_code=code,
            )
            crypto_discounted = round(discounted_price * 1.03)
            keyboard = []
            keyboard.append([InlineKeyboardButton(
                f"→ СБП — {sbp_discounted} ₽", url=paw_url_promo
            )])
            if crypto_url:
                keyboard.append([InlineKeyboardButton(
                    EM_DIAMOND + " Оплатить криптой (USDT, +3%)", url=crypto_url
                )])
            keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")])

            usdt_hint = f"\n≈ {pin_invoice_data['amount_usdt']} USDT" if pin_invoice_data else ""
            ad_title = _html.escape(ad['title'][:40]) if ad else f"#{ad_id}"
            await update.message.reply_text(
                f"{EM_OK} Промокод <b>{code}</b> применён!\n\n"
                f"Скидка: <b>{discount}%</b>\n"
                f"✦ Закрепить «{ad_title}»: <s>{pin_price} ₽</s> → <b>{discounted_price} ₽</b>\n"
                f"СБП (с комиссией 5%): <b>{sbp_discounted} ₽</b>\n"
                f"Крипта (с комиссией 3%): <b>{crypto_discounted} ₽</b>{usdt_hint}\n"
                f"Длительность: <b>{_dur_label}</b>\n\n"
                f"→ Нажмите «Оплатить СБП» — вас перенаправит в банк.\n"
                f"{EM_OK} Закреп активируется <b>автоматически</b> после оплаты.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(keyboard)
            )
            return States.MAIN_MENU

        # ── Общий случай: промокод введён вне конкретного платежа ────────────
        # Промокод сохранён в context.user_data — при открытии страницы оплаты
        # закрепа или подписки он будет применён АВТОМАТИЧЕСКИ.
        if promo_source == 'subscription':
            if service_type not in ('all', 'sub'):
                st_labels = {'sub': 'ПОЛКА ПЛЮС', 'pin': 'закреп', 'all': 'все услуги'}
                await update.message.reply_text(
                    f"{EM_FAIL} Промокод <b>{code}</b> действует только на {st_labels.get(service_type, service_type)}.\n"
                    f"Он не подходит для оплаты ПОЛКА ПЛЮС.",
                    parse_mode=ParseMode.HTML,
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
                )
                return States.MAIN_MENU
            base_price = get_price(PRICE_KEY_SUBSCRIPTION, SUBSCRIPTION_PRICE)
            discounted_price = round(base_price * (1 - discount / 100))
            sbp_price = round(discounted_price * 1.05)
            await update.message.reply_text(
                f"{EM_OK} Промокод <b>{code}</b> действителен!\n\n"
                f"Скидка: <b>{discount}%</b>\n"
                f"✦ ПОЛКА ПЛЮС: <s>{base_price} ₽</s> {EM_ARROW_R} <b>{discounted_price} ₽</b>\n"
                f"СБП (с комиссией 5%): <b>{sbp_price} ₽</b>\n\n"
                f"Нажмите «Оплатить СБП» на странице подписки — скидка применится автоматически.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(EM_ARROW_L + " Назад к подписке", callback_data="subscription_info")],
                    [InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]
                ])
            )
        else:
            st_labels = {'sub': 'ПОЛКА ПЛЮС', 'pin': 'закреп', 'all': 'все услуги'}
            st_label = st_labels.get(service_type, service_type)
            text_parts = [f"{EM_OK} Промокод <b>{code}</b> действителен!\n\nСкидка: <b>{discount}%</b>\n\n"]
            keyboard_buttons = []
            if service_type in ('all', 'pin'):
                pin_price_rf   = get_price(PRICE_KEY_PIN_RF, PIN_PRICE)
                pin_price_city = get_price(PRICE_KEY_PIN_CITY_BASE, 79)
                pin_final_rf   = round(pin_price_rf * (1 - discount / 100))
                pin_final_city = round(pin_price_city * (1 - discount / 100))
                text_parts.append(f"✦ Закреп Основного канала: <s>{pin_price_rf} ₽</s> {EM_ARROW_R} <b>{pin_final_rf} ₽</b>\n")
                text_parts.append(f"✦ Закреп городской: <s>{pin_price_city} ₽</s> {EM_ARROW_R} <b>{pin_final_city} ₽</b>\n")
                keyboard_buttons.append(InlineKeyboardButton("✦ Мои объявления", callback_data="my_ads"))
            if service_type in ('all', 'sub'):
                sub_price = get_price(PRICE_KEY_SUBSCRIPTION, SUBSCRIPTION_PRICE)
                sub_final = round(sub_price * (1 - discount / 100))
                text_parts.append(f"✦ ПОЛКА ПЛЮС: <s>{sub_price} ₽</s> {EM_ARROW_R} <b>{sub_final} ₽</b>\n")
                keyboard_buttons.append(InlineKeyboardButton("✦ ПОЛКА ПЛЮС", callback_data="subscription_info"))
            text_parts.append("\nПерейдите к оплате — скидка применится автоматически.")
            keyboard = [[btn] for btn in keyboard_buttons]
            keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")])
            await update.message.reply_text(
                "".join(text_parts),
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(keyboard)
            )
        return States.MAIN_MENU
    except Exception as e:
        logger.error(f"handle_promo_text: {e}", exc_info=True)
        context.user_data.pop("waiting_promo", None)
        try:
            await update.message.reply_text(
                f"{EM_FAIL} Не удалось проверить промокод. Попробуйте ещё раз.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
            )
        except Exception:
            pass


