async def reindex_photos_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Команда /reindex — пересчитывает pHash для всех активных объявлений без хэша."""
    user = update.effective_user
    if not await is_admin(user.id):
        return
    cursor = db.conn.cursor()
    cursor.execute(
        "SELECT id, photos FROM ads WHERE status='active' AND (photo_hash IS NULL OR photo_hash='') AND photos IS NOT NULL"
    )
    ads = cursor.fetchall()
    if not ads:
        await update.message.reply_text("Все объявления уже проиндексированы.")
        return
    msg = await update.message.reply_text(f"Индексирую {len(ads)} объявлений...")
    done = 0
    for ad in ads:
        try:
            photos = json.loads(ad["photos"]) if isinstance(ad["photos"], str) else ad["photos"]
            if photos:
                await _index_ad_photo(ad["id"], photos[0], context.bot)
                done += 1
        except Exception as e:
            logger.warning(f"reindex ad={ad['id']}: {e}")
    await msg.edit_text(f"Готово. Проиндексировано {done}/{len(ads)} объявлений.")

async def _recover_database(notify=None):
    """Восстановление повреждённой SQLite: копирует данные в новый файл,
    заменяет старый, удаляет WAL/SHM, завершает процесс для перезапуска."""
    if notify:
        await notify("Восстанавливаю базу данных...")
    loop = asyncio.get_running_loop()
    try:
        result = await loop.run_in_executor(None, _recover_db_sync)
    except Exception as e:
        logger.error(f"_recover_database error: {e}")
        if notify:
            try:
                await notify(f"Ошибка восстановления БД: {e}")
            except Exception:
                pass
        return
    if not result["ok"]:
        if notify:
            await notify(f"Восстановление не удалось.\nСкопировано таблиц: {', '.join(result['tables'])}")
        return
    if notify:
        await notify(f"База восстановлена ✓\nСтарый файл: {result['backup']}\nСкопировано: {', '.join(result['tables'])}\n\nПерезапускаю бота...")
    logger.info(f"Recovery OK — перезапуск процесса, таблицы: {result['tables']}")
    os._exit(0)

def _recover_db_sync():
    """Синхронное копирование данных в новый SQLite-файл (выполняется в потоке)."""
    import shutil
    db_path = os.environ.get("DB_PATH", "/data/polka.db")
    backup_path = db_path + ".corrupted"
    recovered_path = db_path + ".recovered"

    src_conn = sqlite3.connect(db_path, timeout=30)
    cur = src_conn.cursor()
    cur.execute("SELECT name, sql FROM sqlite_master WHERE type='table' AND sql IS NOT NULL")
    tables = cur.fetchall()

    if os.path.exists(recovered_path):
        os.remove(recovered_path)
    dst_conn = sqlite3.connect(recovered_path, timeout=30)
    dst_cur = dst_conn.cursor()

    ok_tables = []
    for name, create_sql in tables:
        try:
            dst_cur.execute(create_sql)
        except Exception:
            continue
        try:
            rcur = src_conn.cursor()
            rcur.execute(f'SELECT * FROM "{name}"')
            col_count = len(rcur.description)
            placeholders = ",".join(["?"] * col_count)
            rows = 0
            while True:
                try:
                    row = rcur.fetchone()
                except sqlite3.DatabaseError:
                    break
                if row is None:
                    break
                try:
                    dst_cur.execute(f'INSERT INTO "{name}" VALUES ({placeholders})', row)
                    rows += 1
                except Exception:
                    pass
            dst_conn.commit()
            ok_tables.append(f"{name}({rows})")
        except Exception:
            ok_tables.append(f"{name}(0)")

    cur.execute("SELECT name, sql, tbl_name FROM sqlite_master WHERE type='index' AND sql IS NOT NULL")
    for idx_name, idx_sql, tbl_name in cur.fetchall():
        for ot in tables:
            if ot[0] == tbl_name:
                try:
                    dst_cur.execute(idx_sql)
                except Exception:
                    pass
                break
    dst_conn.commit()
    src_conn.close()
    dst_conn.close()

    check_conn = sqlite3.connect(recovered_path, timeout=30)
    check_cur = check_conn.cursor()
    check_cur.execute("PRAGMA integrity_check")
    check_result = check_cur.fetchall()
    ok = len(check_result) == 1 and check_result[0][0] == "ok"
    check_conn.close()

    if not ok:
        logger.error(f"Recovery FAILED: integrity_check failed, tables: {ok_tables}")
        return {"ok": False, "tables": ok_tables}

    shutil.copy2(db_path, backup_path)
    shutil.move(recovered_path, db_path)
    for ext in ('-wal', '-shm'):
        try:
            os.remove(db_path + ext)
        except FileNotFoundError:
            pass
    return {"ok": True, "tables": ok_tables, "backup": backup_path}

async def recover_db_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    if not await is_admin(user.id):
        return
    msg = await update.message.reply_text("Восстанавливаю базу данных...")
    try:
        await _recover_database(notify=lambda t: context.bot.edit_message_text(chat_id=msg.chat.id, message_id=msg.message_id, text=t))
    except Exception as e:
        logger.error(f"recover_db error: {e}")
        try:
            await msg.edit_text(f"Ошибка восстановления: {e}")
        except Exception:
            pass

async def grant_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Выдача лимитов пользователю (/grant user_id [service] [amount])"""
    user = update.effective_user
    if not await is_admin(user.id):
        await update.message.reply_text(f"{EM_FAIL} У вас нет доступа")
        return
    args = context.args
    if not args:
        await update.message.reply_text(
            "Использование:\n"
            f"/grant <user_id> — информация о лимитах\n"
            f"/grant <user_id> photo_search [count] — установить photo_search_count (по умолч. 0)\n"
            f"/grant <user_id> daily_ads [count] — установить daily_ads_count (по умолч. 0)\n"
            f"/grant <user_id> ai_gen [count] — установить ai_gen_count (по умолч. 0)\n"
            f"/grant <user_id> photo_edit — сбросить сегодняшние обработки фото\n"
            f"/grant <user_id> premium <days> — продлить подписку на N дней"
        )
        return
    try:
        target_id = int(args[0])
    except (ValueError, IndexError):
        await update.message.reply_text(f"{EM_FAIL} Некорректный user_id")
        return
    user_data = db.get_user(target_id)
    if not user_data:
        await update.message.reply_text(f"{EM_FAIL} Пользователь {target_id} не найден.")
        return
    if len(args) == 1:
        today = get_moscow_time().strftime("%Y-%m-%d")
        cursor = db.conn.cursor()
        cursor.execute("SELECT COUNT(*) FROM logs WHERE user_id=? AND action IN ('rembg_used','enhance_used') AND date(created_at)=?", (target_id, today))
        edits_today = cursor.fetchone()[0]
        tariff_info = get_tariff_info(target_id)
        end_date = user_data.get('tariff_end_date') or '—'
        text = (
            f"👤 Пользователь: {target_id}\n"
            f"• Тариф: {user_data.get('tariff', 'Free')}\n"
            f"• Подписка до: {end_date}\n"
            f"• photo_search_count: {user_data.get('photo_search_count', 0)}\n"
            f"• daily_ads_count: {user_data.get('daily_ads_count', 0)}\n"
            f"• ai_gen_count: {user_data.get('ai_gen_count', 0)}\n"
            f"• photo_edits сегодня: {edits_today}\n"
            f"• Лимит поиска: {tariff_info.get('daily_search', 0)}/день\n"
            f"• Лимит объявлений: {tariff_info.get('daily_ads', 0)}/день\n"
            f"• Лимит AI-генераций: {tariff_info.get('daily_ai_gen', 0)}/день\n"
            f"• Лимит обработок: {tariff_info.get('daily_enhance', 0)}/день"
        )
        await update.message.reply_text(text)
        return
    service = args[1].lower()
    amount = int(args[2]) if len(args) > 2 else 0
    if service == "photo_search":
        db.update_user(target_id, photo_search_count=amount,
                       photo_search_reset_date=get_moscow_time().strftime("%Y-%m-%d"))
        await update.message.reply_text(f"{EM_OK} photo_search_count = {amount} для {target_id}")
        try:
            await context.bot.send_message(target_id, f"Вам начислено {amount} поисков по фото")
        except Exception:
            pass
    elif service == "daily_ads":
        db.update_user(target_id, daily_ads_count=amount,
                       last_daily_reset=get_moscow_time().strftime("%Y-%m-%d"))
        await update.message.reply_text(f"{EM_OK} daily_ads_count = {amount} для {target_id}")
        try:
            await context.bot.send_message(target_id, f"Вам начислено {amount} объявлений")
        except Exception:
            pass
    elif service == "ai_gen":
        db.update_user(target_id, ai_gen_count=amount,
                       ai_gen_reset_date=get_moscow_time().strftime("%Y-%m-%d"))
        await update.message.reply_text(f"{EM_OK} ai_gen_count = {amount} для {target_id}")
        try:
            await context.bot.send_message(target_id, f"Вам начислено {amount} AI-генераций")
        except Exception:
            pass
    elif service == "photo_edit":
        cursor = db.conn.cursor()
        today = get_moscow_time().strftime("%Y-%m-%d")
        cursor.execute("DELETE FROM logs WHERE user_id=? AND action IN ('rembg_used','enhance_used') AND date(created_at)=?", (target_id, today))
        db.conn.commit()
        await update.message.reply_text(f"{EM_OK} Обработки фото за сегодня сброшены для {target_id}")
    elif service == "premium":
        if amount <= 0:
            await update.message.reply_text(f"{EM_FAIL} Укажите количество дней (>0)")
            return
        now = get_moscow_time()
        end_str = user_data.get('tariff_end_date')
        if end_str:
            try:
                end = datetime.fromisoformat(end_str)
            except (ValueError, TypeError):
                end = now
        else:
            end = now
        new_end = end + timedelta(days=amount)
        db.update_user(target_id, tariff_end_date=new_end.isoformat())
        await update.message.reply_text(f"{EM_OK} Подписка продлена до {new_end.strftime('%d.%m.%Y')} для {target_id}")
        try:
            await context.bot.send_message(target_id, f"Подписка продлена до {new_end.strftime('%d.%m.%Y')}")
        except Exception:
            pass
    else:
        await update.message.reply_text(f"{EM_FAIL} Неизвестная услуга: {service}")

