async def _do_republish(ad_id: int, context: ContextTypes.DEFAULT_TYPE, msg, user_id: int = None):
    ad = db.get_ad(ad_id)
    if not ad:
        await msg.reply_text(f"{EM_FAIL} Объявление #{ad_id} не найдено.")
        return
    await msg.reply_text(f"↻ Перевыгружаю #{ad_id} в MAX...")
    max_msg_id = await republish_ad_to_max(ad_id, context.bot)
    if max_msg_id:
        await msg.reply_text(f"{EM_OK} Объявление #{ad_id} отправлено в MAX. Сообщение ID: {max_msg_id}",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]]))
        if user_id:
            db.log_action(user_id, "admin_republish_max", f"Ad ID: {ad_id}, MAX msg: {max_msg_id}")
    else:
        await msg.reply_text(f"{EM_FAIL} Не удалось опубликовать #{ad_id} в MAX.\n\nПроверьте MAX_BOT_TOKEN и MAX_CHANNEL_ID.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]]))

