async def admin_stats(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    if not await is_admin(update.effective_user.id):
        await safe_edit_message(query, f"{EM_FAIL} У вас нет доступа")
        return
    
    stats = db.get_overall_stats()

    # Статистика закрепов
    try:
        cur = db.conn.cursor()
        cur.execute("SELECT COUNT(*) FROM ads WHERE pinned_until IS NOT NULL AND pinned_until > ?",
                    (get_moscow_time().isoformat(),))
        active_pins = cur.fetchone()[0]
        cur.execute("SELECT SUM(amount) FROM payments WHERE status IN ('confirmed','paid') AND service_type LIKE 'pin%'")
        pin_revenue = cur.fetchone()[0] or 0
        cur.execute("SELECT COUNT(*) FROM payments WHERE status IN ('confirmed','paid') AND service_type LIKE 'pin%'")
        pin_count = cur.fetchone()[0]
    except Exception:
        active_pins, pin_revenue, pin_count = 0, 0, 0

    text = (
        f"<b>Статистика системы</b>\n\n"
        f"👤 Пользователи: <b>{stats['total_users']}</b>\n"
        f"📋 Объявления: <b>{stats['total_ads']}</b>\n"
        f" • Активных: {stats['active_ads']}\n"
        f" • На модерации: {stats['moderation_ads']}\n\n"
        f"💰 Финансы:\n"
        f" • Всего платежей: {stats['total_payments']}\n"
        f" • Общая выручка: <b>{stats['total_revenue']} ₽</b>\n\n"
        f"📌 Закрепы:\n"
        f" • Сейчас активных: {active_pins}\n"
        f" • Продано закрепов: {pin_count}\n"
        f" • Выручка с закрепов: <b>{pin_revenue} ₽</b>\n\n"
        f"📊 Активность:\n"
        f" • Активных пользователей (7д): {stats['active_users_7d']}"
    )
    
    keyboard = [
        [InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_stats"),
         InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]
    ]
    
    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    db.log_action(update.effective_user.id, "admin_stats_view", "Viewed statistics")

async def admin_moderation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )

    try:
        if not await is_admin(update.effective_user.id):
            await safe_edit_message(query, f"{EM_FAIL} У вас нет доступа")
            return

        pending_ads = db.get_pending_moderation(20)

        if not pending_ads:
            text = f"{EM_OK} На модерации нет объявлений"
            keyboard = [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]]
        else:
            text = f"<b>Модерация</b> — {len(pending_ads)} объявл.\n\n"

            keyboard = []
            for ad in pending_ads[:10]:
                uname = f"@{ad['username']}" if ad.get('username') else ad.get('first_name','?')
                city_str = f" {EM_DOT} {ad['city']}" if ad.get('city') else ""
                text += (
                    f"<b>#{ad['id']}</b> {ad['title'][:35]}\n"
                    f"{uname}   {ad['price']} ₽{city_str}\n\n"
                )
                keyboard.append([
                    InlineKeyboardButton(f"#{ad['id']} {ad['title'][:22]}", callback_data=f"admin_view_ad:{ad['id']}"),
                ])
                keyboard.append([
                    InlineKeyboardButton(EM_OK + " Одобрить", callback_data=f"moderate_approve:{ad['id']}"),
                    InlineKeyboardButton(EM_FAIL + " Отклонить", callback_data=f"moderate_reject:{ad['id']}"),
                ])

            keyboard.append([
                InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_moderation"),
                InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back"),
            ])

        await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
        db.log_action(update.effective_user.id, "admin_moderation_view", f"Viewed {len(pending_ads)} pending ads")
    except Exception as e:
        logger.error(f"Ошибка в admin_moderation: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить очередь модерации.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="admin_panel")]])
        except Exception:
            pass


async def admin_view_moderation_ad(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Полный просмотр объявления из модерации — как видит покупатель, плюс кнопки решения"""
    query = update.callback_query
    await safe_answer(query, )

    if not await is_admin(update.effective_user.id):
        return

    ad_id = int(query.data.split(":")[1])
    ad = db.get_ad(ad_id)
    if not ad:
        await safe_answer(query, "Объявление не найдено", show_alert=True)
        return

    user_info = db.get_user(ad['user_id'])
    verify    = db.get_verification(ad['user_id'])
    rating    = db.get_seller_rating(ad['user_id'])
    uname     = f"@{user_info['username']}" if user_info and user_info.get('username') else (user_info.get('first_name','?') if user_info else '?')

    text = (
        f"<b>На модерации #{ad['id']}</b>  |  "
        f"от {uname} (ID: <code>{ad['user_id']}</code>)\n"
        f"──────────────────\n"
    ) + _format_ad_text(ad, seller=user_info, verify=verify, rating=rating, admin_mode=False)

    keyboard = [
        [InlineKeyboardButton(EM_OK + " Одобрить", callback_data=f"moderate_approve:{ad_id}"),
         InlineKeyboardButton(EM_FAIL + " Отклонить", callback_data=f"moderate_reject:{ad_id}")],
        [InlineKeyboardButton(EM_ARROW_L + " К списку", callback_data="admin_moderation")],
    ]

    try:
        if ad.get('photos'):
            if len(ad['photos']) == 1:
                resolved = await resolve_ad_photo(ad['photos'][0])
                if resolved is None:
                    raise ValueError("Фото недоступно (не удалось разрешить ссылку)")
                await query.message.reply_photo(
                    photo=resolved,
                    caption=text,
                    reply_markup=InlineKeyboardMarkup(keyboard),
                    parse_mode=ParseMode.HTML
                )
            else:
                resolved_photos = [await resolve_ad_photo(p) for p in ad['photos']]
                resolved_photos = [p for p in resolved_photos if p is not None]
                if not resolved_photos:
                    raise ValueError("Фото недоступны (не удалось разрешить ссылки)")
                media = [InputMediaPhoto(resolved_photos[0], caption=text, parse_mode=ParseMode.HTML)]
                for p in resolved_photos[1:]:
                    media.append(InputMediaPhoto(p))
                await query.message.reply_media_group(media=media)
                await query.message.reply_text("Действия:", reply_markup=InlineKeyboardMarkup(keyboard))
            await query.delete_message()
        else:
            await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"admin_view_moderation_ad error: {e}")
        await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)

async def moderate_ad_action(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    # Сразу отвечаем на callback — иначе кнопка зависает серой
    await safe_answer(query, )

    try:
        if not await is_admin(update.effective_user.id):
            await safe_answer(query, f"{EM_FAIL} Нет доступа", show_alert=True)
            return

        action, ad_id_str = query.data.split(":")
        ad_id = int(ad_id_str)
        admin_id = update.effective_user.id

        if action == "moderate_approve":
            # Защита от двойного одобрения: если объявление уже active — не публикуем повторно
            _existing = db.get_ad(ad_id)
            if _existing and _existing.get('status') == 'active':
                await safe_answer(query, f"{EM_OK} Объявление уже опубликовано", show_alert=True)
                return
            pub_result = await publish_ad_to_channel(ad_id, context)
            message_id = pub_result
            ad_info = db.moderate_ad(ad_id, 'active', admin_id, "Одобрено администратором", message_id)

            # Индексируем фото для поиска (pHash)
            try:
                _ad_for_idx = db.get_ad(ad_id)
                if _ad_for_idx and _ad_for_idx.get('photos'):
                    _photos = json.loads(_ad_for_idx['photos']) if isinstance(_ad_for_idx['photos'], str) else _ad_for_idx['photos']
                    if _photos:
                        asyncio.create_task(_index_ad_photo(ad_id, _photos[0], context.bot))
            except Exception as _ie:
                logger.warning(f"index photo after approve: {_ie}")

            if ad_info:
                user_id, title = ad_info['user_id'], ad_info['title']
                try:
                    ad_for_notify = db.get_ad(ad_id)
                    city = (ad_for_notify.get('city') or '').strip() if ad_for_notify else ''
                    city_ch = CITY_CHANNELS.get(city)
                    channels_list = f'• {ADMIN_CHANNEL_ID}'
                    if city_ch:
                        channels_list += f'\n• {city_ch} ({city})'
                    await context.bot.send_message(
                        chat_id=user_id,
                        text=(
                            f"{EM_OK} Ваше объявление одобрено!\n\n"
                            f"<b>{title}</b>\n\n"
                            f"Опубликовано в каналах:\n{channels_list}\n\n"
                            f"Теперь оно доступно в поиске и покупатели могут вам написать."
                        ),
                        parse_mode=ParseMode.HTML,
                        reply_markup=InlineKeyboardMarkup([
                            [InlineKeyboardButton(f"{EM_DIAMOND} Закрепить в топе — от 79 ₽",
                                                  callback_data=f"pin_ad:{ad_id}")],
                            [_miniapp_open_button()],

                        ])
                    )
                except Exception as e:
                    logger.error(f"Не удалось уведомить пользователя {user_id}: {e}")

                # Уведомить пользователей, у которых этот продавец в избранном
                try:
                    fav_cursor = db.conn.cursor()
                    fav_cursor.execute("""
                        CREATE TABLE IF NOT EXISTS favorite_sellers (
                            user_id INTEGER, seller_id INTEGER, added_at TEXT,
                            PRIMARY KEY(user_id, seller_id)
                        )
                    """)
                    fav_cursor.execute(
                        "SELECT user_id FROM favorite_sellers WHERE seller_id=?",
                        (user_id,)
                    )
                    followers = [r[0] for r in fav_cursor.fetchall()]
                    seller = db.get_user(user_id)
                    seller_name = get_anon_id(seller) if seller else 'Продавец'
                    for follower_id in followers:
                        if follower_id == user_id:
                            continue
                        try:
                            await context.bot.send_message(
                                chat_id=follower_id,
                                text=(
                                    f"{EM_DIAMOND} <b>Новое объявление от {seller_name}</b>\n\n"
                                    f"{title}\n\n"
                                    f"<i>Этот продавец у вас в избранном.</i>"
                                ),
                                reply_markup=InlineKeyboardMarkup([[
                                    InlineKeyboardButton(EM_ARROW_R + " Посмотреть", callback_data=f"view_ad:{ad_id}")
                                ]]),
                                parse_mode=ParseMode.HTML
                            )
                        except Exception:
                            pass
                except Exception as e:
                    logger.error(f"Ошибка уведомления подписчиков: {e}")

                db.log_action(admin_id, "ad_approved", f"Ad ID: {ad_id}")
            else:
                await safe_answer(query, "Объявление не найдено", show_alert=True)
                return

            # Показываем обновлённый список — всегда новым сообщением, чтобы не падать на фото
            pending_ads = db.get_pending_moderation(20)
            if not pending_ads:
                text = f"{EM_OK} <b>Модерация</b>\n\nВсе объявления проверены!"
                keyboard = [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]]
            else:
                text = f"<b>Модерация</b> — осталось {len(pending_ads)} объявл.\n\n"
                keyboard = []
                for ad in pending_ads[:10]:
                    uname = f"@{ad['username']}" if ad.get('username') else ad.get('first_name','?')
                    city_str = f" {EM_DOT} {ad['city']}" if ad.get('city') else ""
                    text += f"<b>#{ad['id']}</b> {ad['title'][:35]}\n{uname}   {ad['price']} ₽{city_str}\n\n"
                    keyboard.append([InlineKeyboardButton(f"#{ad['id']} {ad['title'][:22]}", callback_data=f"admin_view_ad:{ad['id']}")])
                    keyboard.append([
                        InlineKeyboardButton(EM_OK + " Одобрить", callback_data=f"moderate_approve:{ad['id']}"),
                        InlineKeyboardButton(EM_FAIL + " Отклонить", callback_data=f"moderate_reject:{ad['id']}"),
                    ])
                keyboard.append([
                    InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_moderation"),
                    InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back"),
                ])

            try:
                # Всегда отправляем новым сообщением — предыдущее может быть фото/медиагруппой
                await query.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
                try:
                    await query.message.delete()
                except Exception:
                    pass
            except Exception as e:
                logger.error(f"moderate_approve reply error: {e}")
            return

        elif action == "moderate_reject":
            context.user_data['moderating_ad'] = ad_id
            # Всегда отправляем новое сообщение — query.message может быть фото или медиагруппой
            try:
                await query.message.reply_text(
                    text=f"Отклонение объявления #{ad_id}\n\nУкажите причину отклонения (текстом):",
                    reply_markup=InlineKeyboardMarkup(
                        [[InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="admin_moderation")]]
                    )
                )
            except Exception as e:
                logger.error(f"moderate_reject send error: {e}")
            return

        await safe_answer(query, )
    except Exception as e:
        logger.error(f"Ошибка в moderate_ad_action: {e}")
        try:
            await safe_edit_message(query, "Не удалось выполнить действие модерации.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="admin_moderation")]])
        except Exception:
            pass
async def handle_moderation_reason(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not await is_admin(update.effective_user.id):
        return
    
    if 'moderating_ad' not in context.user_data:
        await update.message.reply_text(f"{EM_FAIL} Ошибка: не найдено объявление для модерации")
        return States.ADMIN_MENU
    
    reason = update.message.text
    ad_id = context.user_data['moderating_ad']
    
    # Отклоняем объявление с указанием причины
    ad_info = db.moderate_ad(ad_id, 'rejected', update.effective_user.id, reason)
    
    if ad_info:
        user_id, title = ad_info['user_id'], ad_info['title']
        
        try:
            await context.bot.send_message(
                chat_id=user_id,
                text=f"{EM_FAIL} Ваше объявление отклонено\n\n{title}\n\nПричина: {reason}\n\nИсправьте и создайте заново — это займёт минуту.",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("➕ Создать заново",
                                          web_app=WebAppInfo(url=f"{_miniapp_url()}/create"))],
                ]),
            )
        except Exception as e:
            logger.error(f"Не удалось уведомить пользователя {user_id}: {e}")
        
        await update.message.reply_text(f"{EM_OK} Объявление #{ad_id} отклонено с указанием причины")
        db.log_action(update.effective_user.id, "ad_rejected", f"Ad ID: {ad_id}, Reason: {reason[:50]}")
    else:
        await update.message.reply_text(f"{EM_FAIL} Объявление не найден")
    
    # Очищаем контекст
    if 'moderating_ad' in context.user_data:
        del context.user_data['moderating_ad']
    
    # Возвращаемся в меню модерации
    await admin_moderation(update, context)
    return States.ADMIN_MENU

async def admin_payments(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Показывает платежи, ожидающие проверки"""
    query = update.callback_query
    try:
        if query:
            await safe_answer(query, )

        if not await is_admin(update.effective_user.id):
            await safe_edit_message(query, f"{EM_FAIL} У вас нет доступа")
            return

        pending_payments = db.get_pending_payments(50)

        if not pending_payments:
            text = f"{EM_OK} Нет платежей на проверке"
            keyboard = [
                [InlineKeyboardButton(EM_DOT + " Архив платежей", callback_data="admin_payments_archive")],
                [InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_payments"),
                 InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]
            ]
        else:
            text = f"Ждут проверки: {len(pending_payments)}\n\n"
            keyboard = []
            for payment in pending_payments[:5]:
                text += (
                    f"{payment['id']}: {payment['tariff']} — {payment['amount']}₽\n"
                    f"  {payment['first_name']} (@{payment['username']})\n"
                    f"  {payment['created_at'][:16]}\n\n"
                )
                keyboard.append([
                    InlineKeyboardButton(f"{EM_OK} Подтвердить {payment['id']}", callback_data=f"payment_confirm:{payment['id']}"),
                    InlineKeyboardButton(f"{EM_FAIL} Отклонить {payment['id']}", callback_data=f"payment_reject:{payment['id']}")
                ])
                if payment.get('screenshot_file_id'):
                    keyboard.append([
                        InlineKeyboardButton(f"Чек #{payment['id']}", callback_data=f"payment_view_receipt:{payment['id']}")
                    ])

            if len(pending_payments) > 5:
                keyboard.append([InlineKeyboardButton(EM_ARROW_R + " Следующие 5", callback_data="admin_payments_next")])

            keyboard.append([InlineKeyboardButton(EM_DOT + " Архив платежей", callback_data="admin_payments_archive")])
            keyboard.append([
                InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_payments"),
                InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")
            ])

        await safe_edit_message(query, text, keyboard)
        db.log_action(update.effective_user.id, "admin_payments_view", f"Viewed {len(pending_payments)} pending payments")
    except Exception as e:
        logger.error(f"Ошибка в admin_payments: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить платежи.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="admin_panel")]])
        except Exception:
            pass


async def admin_payments_archive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Архив обработанных платежей (confirmed / rejected)"""
    query = update.callback_query
    await safe_answer(query, )

    if not await is_admin(update.effective_user.id):
        await safe_edit_message(query, f"{EM_FAIL} У вас нет доступа")
        return

    archived = db.get_archived_payments(30)

    if not archived:
        text = "Архив платежей пуст"
        keyboard = [[InlineKeyboardButton(EM_ARROW_L + " К платежам", callback_data="admin_payments")]]
    else:
        text = f"Архив платежей (последние {len(archived)})\n\n"
        for p in archived:
            status_icon = f"{EM_OK}" if p['status'] == 'confirmed' else f"{EM_FAIL}"
            date_str = (p.get('confirmed_at') or p['created_at'])[:16]
            text += (
                f"{status_icon} #{p['id']} {p['tariff']} — {p['amount']}₽\n"
                f"  {p['first_name']} (@{p['username']})\n"
                f"  {date_str}\n\n"
            )
        keyboard = [[InlineKeyboardButton(EM_ARROW_L + " К платежам", callback_data="admin_payments")]]

    await safe_edit_message(query, text, keyboard)

async def admin_view_receipt(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Отправляет скриншот чека выбранного платежа прямо в чат админа"""
    query = update.callback_query
    # НЕ вызываем query.answer() сразу — вызовем один раз в конце

    if not await is_admin(update.effective_user.id):
        await safe_answer(query, f"{EM_FAIL} У вас нет доступа", show_alert=True)
        return

    payment_id = int(query.data.split(":")[1])

    cursor = db.conn.cursor()
    cursor.execute(
        "SELECT p.*, u.first_name, u.username FROM payments p "
        "JOIN users u ON p.user_id = u.user_id WHERE p.id = ?",
        (payment_id,)
    )
    row = cursor.fetchone()

    if not row:
        await safe_answer(query, f"{EM_FAIL} Платеж не найден", show_alert=True)
        return

    p = dict(row)
    file_id = p.get('screenshot_file_id')

    if not file_id:
        await safe_answer(query, f"{EM_FAIL} Скриншот чека отсутствует", show_alert=True)
        return

    status_map = {'confirmed': f'{EM_OK} Подтверждён', 'rejected': f'{EM_FAIL} Отклонён', 'pending': f'{EM_DOT} Ожидает'}
    status_str = status_map.get(p['status'], p['status'])
    user_str = f"{p['first_name']} (@{p['username']})" if p.get('username') else p['first_name']

    caption = (
        f" Чек платежа #{p['id']}\n\n"
        f"{user_str}\n"
        f"{p['tariff']} — {p['amount']}₽\n"
        f"{p['created_at'][:16]}\n"
        f"Статус: {status_str}"
    )

    keyboard = []
    if p['status'] == 'pending':
        keyboard.append([
            InlineKeyboardButton(EM_OK + " Подтвердить", callback_data=f"payment_confirm:{payment_id}"),
            InlineKeyboardButton(EM_FAIL + " Отклонить", callback_data=f"payment_reject:{payment_id}")
        ])
    keyboard.append([InlineKeyboardButton(EM_ARROW_L + " К платежам", callback_data="admin_payments")])

    try:
        await query.message.reply_photo(
            photo=file_id,
            caption=caption,
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
        await safe_answer(query, )  # {EM_OK} успех — отвечаем один раз
    except Exception as e:
        logger.error(f"Ошибка при отправке чека #{payment_id}: {e}")
        await safe_answer(query, f"{EM_FAIL} Не удалось загрузить чек", show_alert=True)


async def moderate_payment_action(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    try:
        if not await is_admin(update.effective_user.id):
            await safe_answer(query, f"{EM_FAIL} У вас нет доступа", show_alert=True)
            return
        
        action, payment_id_str = query.data.split(":")
        payment_id = int(payment_id_str)
        admin_id = update.effective_user.id
        
        if action == "payment_confirm":
            try:
                payment_info = db.moderate_payment(payment_id, 'confirmed', admin_id, "Платеж подтвержден")
            except Exception as e:
                logger.error(f"Ошибка при подтверждении платежа {payment_id}: {e}", exc_info=True)
                await safe_answer(query, f"{EM_FAIL} Не удалось подтвердить платеж. Проверьте логи.", show_alert=True)
                return
            
            if payment_info:
                user_id, amount, tariff = payment_info['user_id'], payment_info['amount'], payment_info['tariff']
                
                # Получаем актуальную дату окончания подписки
                user_data = db.get_user(user_id)
                tariff_end_date = user_data.get('tariff_end_date', '')
                end_date_display = tariff_end_date[:10] if tariff_end_date else 'неизвестно'
                
                # Начисляем реферальное вознаграждение
                try:
                    referral_tx_id = db.process_referral_reward(user_id, amount)
                except Exception as e:
                    logger.error(f"Ошибка начисления реферального вознаграждения: {e}")
                    referral_tx_id = None
                
                # Уведомляем пользователя
                try:
                    await context.bot.send_message(
                        chat_id=user_id,
                        text=f"{EM_OK} Платёж подтверждён!\n\nСумма: {amount}₽\n\nСпасибо!"
                    )
                except Exception as e:
                    logger.error(f"Не удалось уведомить пользователя {user_id}: {e}")
                
                # Уведомляем реферера L1
                if referral_tx_id:
                    referrer_id = db.get_referrer(user_id)
                    if referrer_id:
                        try:
                            referrer_stats = db.get_referral_stats(referrer_id)
                            referred_info = db.get_user(user_id)
                            referred_name = f"@{referred_info['username']}" if referred_info and referred_info.get('username') else referred_info['first_name']
                            
                            await context.bot.send_message(
                                chat_id=referrer_id,
                                text=f"Новое реферальное начисление!\n\n"
                                     f"Ваш реферал {referred_name} совершил платёж\n"
                                     f"Сумма подписки: {amount}₽\n"
                                     f" Ваш процент: {REFERRAL_PERCENT}%\n"
                                     f"Начислено: {int(amount * REFERRAL_PERCENT / 100)}₽\n\n"
                                     f"Ваша статистика:\n"
                                     f"• Всего заработано: {referrer_stats['total_earned']}₽\n"
                                     f"• Текущий баланс: {referrer_stats['balance']}₽\n"
                                     f"• Приглашено пользователей: {referrer_stats['referrals_count']}\n\n"
                                     f" Накопленные средства можно использовать для оплаты своей подписки!"
                            )
                        except Exception as e:
                            logger.error(f"Не удалось уведомить реферера {referrer_id}: {e}")

                db.log_action(admin_id, "payment_confirmed", f"Payment ID: {payment_id}, Amount: {amount}₽")
            else:
                await safe_answer(query, f"{EM_FAIL} Платеж не найден", show_alert=True)
                return
        
        elif action == "payment_reject":
            await safe_answer(query, )
            context.user_data['moderating_payment'] = payment_id
            await safe_edit_message(query,
                text=f"Отклонение платежа #{payment_id}\n\nУкажите причину отклонения:",
                keyboard=[[InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="admin_payments")]]
            )
            return States.ADMIN_MODERATION_REASON
        
        else:
            await safe_answer(query, )
        
        # Показываем обновлённый список платежей
        pending_payments = db.get_pending_payments(50)
        if not pending_payments:
            text = f"{EM_OK} Нет платежей на проверке"
            keyboard = [
                [InlineKeyboardButton(EM_DOT + " Архив платежей", callback_data="admin_payments_archive")],
                [InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_payments"),
                 InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]
            ]
        else:
            text = f"Ждут проверки: {len(pending_payments)}\n\n"
            keyboard = []
            for payment in pending_payments[:5]:
                text += (
                    f"{payment['id']}: {payment['tariff']} — {payment['amount']}₽\n"
                    f"  {payment['first_name']} (@{payment['username']})\n"
                    f"  {payment['created_at'][:16]}\n\n"
                )
                keyboard.append([
                    InlineKeyboardButton(f"{EM_OK} Подтвердить {payment['id']}", callback_data=f"payment_confirm:{payment['id']}"),
                    InlineKeyboardButton(f"{EM_FAIL} Отклонить {payment['id']}", callback_data=f"payment_reject:{payment['id']}")
                ])
                if payment.get('screenshot_file_id'):
                    keyboard.append([
                        InlineKeyboardButton(f"Чек #{payment['id']}", callback_data=f"payment_view_receipt:{payment['id']}")
                    ])
            if len(pending_payments) > 5:
                keyboard.append([InlineKeyboardButton(EM_ARROW_R + " Следующие 5", callback_data="admin_payments_next")])
            keyboard.append([InlineKeyboardButton(EM_DOT + " Архив платежей", callback_data="admin_payments_archive")])
            keyboard.append([
                InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_payments"),
                InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")
            ])
        
        # Удаляем старое сообщение (может содержать фото чека) и отправляем новое
        try:
            await query.message.delete()
        except Exception as e:
            logger.error(f"Не удалось удалить сообщение при обработке платежа: {e}")
        
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=text,
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
    
    except Exception as e:
        logger.error(f"Критическая ошибка в moderate_payment_action: {e}", exc_info=True)
        try:
            await safe_answer(query, "Не удалось обработать платёж. Обновите страницу и попробуйте снова.", show_alert=True)
        except Exception:
            pass
        # Возвращаемся в меню платежей
        await admin_payments(update, context)

async def handle_payment_rejection(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    
    if not await is_admin(user.id):
        return
    
    if 'moderating_payment' not in context.user_data:
        await update.message.reply_text(f"{EM_FAIL} Ошибка: не найден платеж для модерации")
        return States.ADMIN_MENU
    
    reason = update.message.text
    payment_id = context.user_data['moderating_payment']
    
    payment_info = db.moderate_payment(payment_id, 'rejected', user.id, reason)
    
    if payment_info:
        user_id, amount, tariff = payment_info['user_id'], payment_info['amount'], payment_info['tariff']
        
        try:
            await context.bot.send_message(
                chat_id=user_id,
                text=f"{EM_FAIL} Ваш платеж отклонен\n\nТариф: {tariff}\nСумма: {amount}₽\n\nПричина: {reason}\n\nЕсли вы считаете это ошибкой, свяжитесь с поддержкой."
            )
        except Exception as e:
            logger.error(f"Не удалось уведомить пользователя {user_id}: {e}")
        
        await update.message.reply_text(f"{EM_OK} Платеж #{payment_id} отклонен с указанием причины")
        db.log_action(user.id, "payment_rejected", f"Payment ID: {payment_id}, Reason: {reason[:50]}")
    else:
        await update.message.reply_text(f"{EM_FAIL} Платеж не найден")
    
    # Очищаем контекст
    if 'moderating_payment' in context.user_data:
        del context.user_data['moderating_payment']
    
    # Показываем обновлённый список напрямую (без query, т.к. это message update)
    pending_payments = db.get_pending_payments(50)
    if not pending_payments:
        text = f"{EM_OK} Нет платежей на проверке"
        keyboard = [
            [InlineKeyboardButton(EM_DOT + " Архив платежей", callback_data="admin_payments_archive")],
            [InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_payments"),
             InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]
        ]
    else:
        text = f"Ждут проверки: {len(pending_payments)}\n\n"
        keyboard = []
        for payment in pending_payments[:5]:
            text += (
                f"{payment['id']}: {payment['tariff']} — {payment['amount']}₽\n"
                f"  {payment['first_name']} (@{payment['username']})\n"
                f"  {payment['created_at'][:16]}\n\n"
            )
            keyboard.append([
                InlineKeyboardButton(f"{EM_OK} Подтвердить {payment['id']}", callback_data=f"payment_confirm:{payment['id']}"),
                InlineKeyboardButton(f"{EM_FAIL} Отклонить {payment['id']}", callback_data=f"payment_reject:{payment['id']}")
            ])
            if payment.get('screenshot_file_id'):
                keyboard.append([
                    InlineKeyboardButton(f"Чек #{payment['id']}", callback_data=f"payment_view_receipt:{payment['id']}")
                ])
        if len(pending_payments) > 5:
            keyboard.append([InlineKeyboardButton(EM_ARROW_R + " Следующие 5", callback_data="admin_payments_next")])
        keyboard.append([InlineKeyboardButton(EM_DOT + " Архив платежей", callback_data="admin_payments_archive")])
        keyboard.append([
            InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_payments"),
            InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")
        ])
    await update.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
    return States.ADMIN_MENU

# РАССЫЛКА ДЛЯ АДМИНА - РЕАЛИЗОВАНА ДО 10 ФОТО
async def admin_broadcast_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    if not await is_admin(update.effective_user.id):
        await safe_edit_message(query, f"{EM_FAIL} У вас нет доступа")
        return
    
    await safe_edit_message(query,
        text="Рассылка сообщений\n\nОтправьте сообщение для рассылки (текст и/или до 10 фото):",
        keyboard=[[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]]
    )
    
    context.user_data['broadcast_data'] = {'photos': [], 'text': '', 'with_button': True}
    return States.ADMIN_BROADCAST

def _broadcast_toggle_row(bd: dict) -> list:
    """Строка-переключатель кнопки «Открыть Полку» для превью рассылки."""
    state = "вкл" if bd.get('with_button', True) else "выкл"
    return [InlineKeyboardButton(f"{EM_DOT} Кнопка «Открыть Полку»: {state}",
                                 callback_data="broadcast_toggle_button")]

def _broadcast_kb(variant: str, bd: dict) -> InlineKeyboardMarkup:
    """Клавиатуры превью рассылки. variant: confirm | photo | preview."""
    toggle = _broadcast_toggle_row(bd)
    if variant == 'photo':
        return InlineKeyboardMarkup([
            [InlineKeyboardButton(EM_ARROW_R + " Далее", callback_data="broadcast_preview")],
            [InlineKeyboardButton(EM_OK + " Отправить сейчас", callback_data="broadcast_confirm")],
            toggle,
            [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="admin_back")],
        ])
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(EM_OK + " Да, отправить", callback_data="broadcast_confirm")],
        toggle,
        [InlineKeyboardButton(EM_FAIL + " Отмена", callback_data="admin_back")],
    ])

async def handle_broadcast_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not await is_admin(update.effective_user.id):
        return States.ADMIN_MENU

    # Инициализируем broadcast_data если вдруг нет
    if not context.user_data.get('broadcast_data'):
        context.user_data['broadcast_data'] = {'photos': [], 'text': ''}

    if update.message.text:
        # Текстовое сообщение
        context.user_data['broadcast_data']['text'] = update.message.text
        context.user_data['broadcast_data']['photos'] = []
        context.user_data['broadcast_data']['_kb_variant'] = 'confirm'

        # Показываем превью и запрашиваем подтверждение
        text = f"Превью рассылки\n\n{update.message.text}\n\nОтправить всем пользователям?"

        await update.message.reply_text(
            text,
            reply_markup=_broadcast_kb('confirm', context.user_data['broadcast_data']))
        return States.ADMIN_BROADCAST_CONFIRM
    
    elif update.message.photo:
        # Фото с подписью или без
        photo = update.message.photo[-1].file_id
        caption = update.message.caption or ""
        
        # Инициализируем список фото если нужно
        if 'photos' not in context.user_data['broadcast_data']:
            context.user_data['broadcast_data']['photos'] = []
        
        # Добавляем фото (максимум 10)
        if len(context.user_data['broadcast_data']['photos']) < 10:
            context.user_data['broadcast_data']['photos'].append(photo)
            
            if caption and not context.user_data['broadcast_data']['text']:
                context.user_data['broadcast_data']['text'] = caption
            
            remaining = 10 - len(context.user_data['broadcast_data']['photos'])
            
            # Показываем превью и запрашиваем подтверждение
            preview_text = (
                f"Превью рассылки\n\n"
                f"{context.user_data['broadcast_data']['text'] if context.user_data['broadcast_data']['text'] else '[Без текста]'}\n\n"
                f" Загружено фото: {len(context.user_data['broadcast_data']['photos'])}/10\n"
                f"Осталось мест: {remaining}\n\n"
                f"Можно отправить еще фото или нажать 'Далее' для отправки"
            )
            
            context.user_data['broadcast_data']['_kb_variant'] = 'photo'

            await update.message.reply_text(
                preview_text,
                reply_markup=_broadcast_kb('photo', context.user_data['broadcast_data']))
        else:
            await update.message.reply_text(f"{EM_FAIL} Достигнут лимит в 10 фото. Нажмите 'Далее' для продолжения.")
    
    return States.ADMIN_BROADCAST

async def broadcast_preview(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    broadcast_data = context.user_data.get('broadcast_data', {})
    
    text = (
        f"Превью рассылки\n\n"
        f"{broadcast_data.get('text', '[Без текста]')}\n\n"
        f" Фото: {len(broadcast_data.get('photos', []))} шт\n\n"
        f"Отправить всем пользователям?"
    )
    
    broadcast_data['_kb_variant'] = 'preview'
    keyboard = _broadcast_kb('preview', broadcast_data)

    if broadcast_data.get('photos'):
        try:
            media_group = [InputMediaPhoto(broadcast_data['photos'][0], caption=text)]
            for photo in broadcast_data['photos'][1:]:
                media_group.append(InputMediaPhoto(photo))
            await query.message.reply_media_group(media=media_group)
            await query.message.reply_text("Выберите действие:", reply_markup=keyboard)
        except Exception as e:
            logger.error(f"broadcast preview photo error: {e}")
            await safe_edit_message(query, text, keyboard)
    else:
        await safe_edit_message(query, text, keyboard)

    return States.ADMIN_BROADCAST_CONFIRM

async def broadcast_toggle_button(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Переключатель кнопки «Открыть Полку» в рассылке (админ)."""
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return
    bd = context.user_data.get('broadcast_data')
    if not bd:
        return
    bd['with_button'] = not bd.get('with_button', True)
    try:
        await query.message.edit_reply_markup(
            reply_markup=_broadcast_kb(bd.get('_kb_variant') or 'preview', bd))
    except Exception:
        pass
    await safe_answer(query, "Кнопка «Открыть Полку»: "
                      + ("вкл" if bd['with_button'] else "выкл"), show_alert=False)

async def broadcast_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    if not await is_admin(update.effective_user.id):
        await safe_edit_message(query, f"{EM_FAIL} У вас нет доступа")
        return
    
    broadcast_data = context.user_data.get('broadcast_data', {})
    
    if not broadcast_data:
        await safe_edit_message(query, f"{EM_FAIL} Нет данных для рассылки")
        return States.ADMIN_MENU
    
    # Получаем всех пользователей
    users = db.get_all_users()
    total_users = len(users)
    
    # Отправляем сообщение о начале
    try:
        await query.edit_message_text(f"⏳ Начинаю рассылку для {total_users} пользователей...")
    except Exception:
        await query.message.reply_text(f"⏳ Начинаю рассылку для {total_users} пользователей...")
    
    sent_count = 0
    failed_count = 0
    
    with_button = broadcast_data.get('with_button', True)
    btn_kb = InlineKeyboardMarkup([[_miniapp_open_button()]]) if with_button else None

    for user in users:
        try:
            photos = broadcast_data.get('photos') or []
            if len(photos) == 1:
                # Одно фото — подпись + кнопка в одном сообщении
                await context.bot.send_photo(
                    chat_id=user['user_id'],
                    photo=photos[0],
                    caption=broadcast_data.get('text', ''),
                    parse_mode=ParseMode.HTML,
                    reply_markup=btn_kb,
                )
            elif photos:
                # Медиагруппа не держит кнопок — кнопка отдельным сообщением
                media_group = []
                for i, photo in enumerate(photos[:10]):  # Ограничиваем 10 фото
                    if i == 0:
                        # Первое фото с подписью
                        media_group.append(InputMediaPhoto(
                            photo,
                            caption=broadcast_data.get('text', '')
                        ))
                    else:
                        media_group.append(InputMediaPhoto(photo))

                await context.bot.send_media_group(
                    chat_id=user['user_id'],
                    media=media_group
                )
                if btn_kb:
                    await context.bot.send_message(
                        chat_id=user['user_id'],
                        text="Открыть приложение:",
                        reply_markup=btn_kb,
                    )
            else:
                # Отправляем текст
                await context.bot.send_message(
                    chat_id=user['user_id'],
                    text=broadcast_data.get('text', ''),
                    parse_mode=ParseMode.HTML,
                    reply_markup=btn_kb,
                )
            sent_count += 1
        except Exception as e:
            failed_count += 1
            logger.error(f"Не удалось отправить сообщение пользователю {user['user_id']}: {e}")
        
        # Небольшая задержка, чтобы не превысить лимиты Telegram
        await asyncio.sleep(0.1)
    
    # Очищаем данные рассылки
    if 'broadcast_data' in context.user_data:
        del context.user_data['broadcast_data']
    
    # Логируем рассылку
    db.log_action(update.effective_user.id, "broadcast_sent", 
                  f"Sent: {sent_count}, Failed: {failed_count}, Total: {total_users}")
    
    await safe_edit_message(query,
        text=f"{EM_OK} Рассылка завершена!\n\nСтатистика:\n• Отправлено: {sent_count}\n• Не отправлено: {failed_count}\n• Всего пользователей: {total_users}",
        keyboard=[[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_back")]]
    )
    
    return States.ADMIN_MENU

# Общие обработчики
async def cancel_action(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    
    # Очищаем данные создания объявления
    if 'creating_ad' in context.user_data:
        del context.user_data['creating_ad']
    if 'photo_limit' in context.user_data:
        del context.user_data['photo_limit']
    
    await show_main_menu(update, context)
    return ConversationHandler.END

async def back_to_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
