async def admin_promo_input_uses(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Ввод максимального количества использований"""
    try:
        max_uses = int(update.message.text.strip())
        
        if max_uses <= 0:
            raise ValueError
        
        code     = context.user_data.get('_pc_code', '')
        discount = context.user_data.get('_pc_discount', 0)
        duration = context.user_data.get('_pc_duration', 30)
        service_type = context.user_data.get('_pc_service_type', 'all')
        
        # Очищаем служебные ключи
        for k in ('_pc_code', '_pc_discount', '_pc_duration', '_promo_awaiting_uses', '_pc_service_type', '_pc_awaiting_service_type'):
            context.user_data.pop(k, None)
        
        if db.create_promocode(code, discount, duration, max_uses, service_type=service_type):
            crypto_link_info = ""
            if discount in CRYPTO_LINKS:
                crypto_link_info = f"\nКриптоссылка: Настроена для {discount}% скидки"
            else:
                crypto_link_info = f"\n! Криптоссылка: Будет использована стандартная (нет специальной для {discount}%)"
            
            st_labels = {'all': 'все услуги', 'pin': 'закреп объявления', 'sub': 'ПОЛКА ПЛЮС'}
            st_label = st_labels.get(service_type, service_type)
            
            text = (
                f"{EM_OK} Промокод создан!\n\n"
                f"Код: {code}\n"
                f"Скидка: {discount}%\n"
                f"Действует на: {st_label}\n"
                f"Длительность: {duration} дней\n"
                f"Макс. использований: {max_uses}\n"
                f"{crypto_link_info}"
            )
            
            keyboard = [[InlineKeyboardButton(EM_ARROW_L + " К промокодам", callback_data="admin_promocodes")]]
            await update.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
        else:
            await update.message.reply_text(f"{EM_FAIL} Ошибка при создании промокода")
        
        return States.ADMIN_MENU
        
    except ValueError:
        await update.message.reply_text(f"{EM_FAIL} Неверный формат. Введите положительное число:")
        return States.ADMIN_PROMO_CREATE_USES

