async def error_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    error_msg = str(context.error)
    if 'rate_limited' in error_msg or 'rate limit' in error_msg.lower():
        return
    logger.error(f"Ошибка: {context.error}", exc_info=context.error)
    import traceback as _tb
    logger.error("Полный трейс:\n" + "".join(_tb.format_exception(type(context.error), context.error, context.error.__traceback__)))

    if isinstance(context.error, sqlite3.DatabaseError) and 'malformed' in error_msg:
        logger.warning("Обнаружено повреждение БД — запускаю автоматическое восстановление")
        try:
            if update and update.effective_chat:
                await context.bot.send_message(chat_id=update.effective_chat.id,
                    text="⚠️ Обнаружено повреждение базы данных. Запускаю автоматическое восстановление и перезапуск...")
        except Exception:
            pass
        await _recover_database()
        return

    # Не спамим пользователя на каждый сетевой сбой: «Сервер долго отвечает»
    # выводим максимум раз в 10 минут на чат, остальное — тихо в лог.
    # Частые Timed out — следствие медленной сети хостинга, юзеру не помогает.
    if update and update.effective_chat:
        try:
            _chat_id = update.effective_chat.id
            _now_ts = _time.monotonic()
            _last = getattr(error_handler, '_last_warn', {})
            _last_ok = _last.get(_chat_id, 0)
            _is_timeout = 'timed out' in error_msg.lower() or 'timeout' in error_msg.lower()
            _is_net = _is_timeout or 'network' in error_msg.lower() or 'connection' in error_msg.lower()
            if not _is_net or _now_ts - _last_ok > 600:
                if _is_net:
                    error_handler._last_warn = _last
                    error_handler._last_warn[_chat_id] = _now_ts
                msg = "⚠️ Сервер долго отвечает. Попробуйте ещё раз." if _is_timeout else "Что-то пошло не так. Попробуйте ещё раз или вернитесь в /start"
                try:
                    await context.bot.send_message(chat_id=update.effective_chat.id, text=msg)
                except Exception:
                    pass
        except Exception:
            pass

