# Закрепы
BUMP_PRICE      = 99    # поднять объявление
PIN_PRICE       = 199   # закреп в канале / 24ч
URGENT_PRICE    = 49    # бейдж "Срочно" / 48ч

def get_price(key: str, default: int) -> int:
    """Читает цену из БД, возвращает default если не задана."""
    try:
        cur = db.conn.cursor()
        cur.execute("SELECT value FROM price_settings WHERE key=?", (key,))
        row = cur.fetchone()
        return row[0] if row else default
    except Exception:
        return default

def set_price(key: str, value: int):
    """Сохраняет цену в БД."""
    now = get_moscow_time().isoformat()
    db.conn.execute(
        "INSERT OR REPLACE INTO price_settings (key, value, updated_at) VALUES (?,?,?)",
        (key, value, now)
    )
    db.conn.commit()

# Ключи цен
PRICE_KEY_PIN_RF   = "price_pin_rf"
PRICE_KEY_PIN_CITY_BASE = "price_pin_city_base"  # базовый дефолт для городов
PRICE_KEY_SUBSCRIPTION   = "price_subscription"
PRICE_KEY_VERIFICATION   = "price_verification"
PRICE_KEY_AUTO_BUMP      = "price_auto_bump"
# Городской закреп — цена зависит от числа подписчиков канала (обновляется раз в сутки)
# Кэш: {channel_username: (subscribers_count, price)}
_city_channel_cache: dict = {}

def get_city_pin_price(channel: str) -> tuple:
    """Возвращает (цена, число_подписчиков) для городского канала из кэша."""
    if channel in _city_channel_cache:
        count, price = _city_channel_cache[channel]
        return price, count
    return 79, None  # дефолт пока кэш не заполнен

def _subs_to_price(count: int) -> int:
    """Градация цен по числу подписчиков."""
    if count >= 10000: return 149
    if count >= 2000:  return 119
    if count >= 500:   return 79
    return 49
URGENT_BADGE_PRICE = 129  # «Срочно» — визуальная плашка
# VERIFICATION_PRICE и AUTO_BUMP_PRICE заданы выше в конфиг-блоке (строки ~652, ~657)

async def save_search_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Сохранить поисковый запрос для уведомлений"""
    query = update.callback_query
    # НЕ вызываем query.answer() здесь — иначе Telegram не даст ответить второй раз с текстом
    try:
        search_query = query.data.split(":", 1)[1]
        user_id = update.effective_user.id

        saved = db.save_search(user_id, search_query)
        if saved:
            await safe_answer(query, f"{EM_OK} Уведомления по «{search_query}» включены!", show_alert=True)
        else:
            await safe_answer(query, "Этот поиск уже сохранён.", show_alert=True)
    except Exception as e:
        logger.error(f"Ошибка в save_search_callback: {e}")
        try:
            await safe_answer(query, "Не удалось сохранить поиск. Попробуйте ещё раз.", show_alert=True)
        except Exception:
            pass
async def my_saved_searches(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Список сохранённых поисков пользователя"""
    query = update.callback_query
    await safe_answer(query, )
    try:
        user_id = update.effective_user.id
        searches = db.get_user_saved_searches(user_id)

        if not searches:
            text = " Сохранённые поиски\n\nУ вас нет сохранённых поисков.\n\nПри поиске нажмите « Уведомить о новых», чтобы получать уведомления при появлении новых товаров."
            keyboard = [[InlineKeyboardButton(EM_DOT + " Поиск", callback_data="search"), InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]]
        else:
            text = f" Сохранённые поиски: {len(searches)}\n\nВы получаете уведомления при появлении новых объявлений:\n\n"
            for s in searches:
                text += f"• {s['query']}\n"
            keyboard = []
            for s in searches:
                keyboard.append([InlineKeyboardButton(f"{EM_FAIL} Удалить «{s['query']}»", callback_data=f"del_search:{s['query']}")])
            keyboard.append([InlineKeyboardButton(EM_DOT + " Новый поиск", callback_data="search"), InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")])

        await safe_edit_message(query, text, keyboard)
    except Exception as e:
        logger.error(f"Ошибка в my_saved_searches: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить сохранённые поиски.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
        except Exception:
            pass
async def delete_saved_search_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Удалить сохранённый поиск"""
    query = update.callback_query
    await safe_answer(query, )
    search_query = query.data.split(":", 1)[1]
    db.delete_saved_search(update.effective_user.id, search_query)
    await safe_answer(query, f" Поиск «{search_query}» удалён", show_alert=True)
    await my_saved_searches(update, context)

