async def review_handle_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Сохраняем отзыв"""
    text = update.message.text.strip()
    if text == '-':
        text = ''
    ad_id = context.user_data.get('review_ad_id')
    rating = context.user_data.get('review_rating')
    buyer_id = update.effective_user.id

    if not ad_id or not rating:
        await update.message.reply_text("Сессия истекла. Вернитесь к профилю продавца и попробуйте оставить отзыв снова.")
        return ConversationHandler.END

    ad = db.get_ad(ad_id)
    if not ad:
        await update.message.reply_text(f"{EM_FAIL} Объявление не найдено.")
        return ConversationHandler.END

    seller_id = ad['user_id']
    if seller_id == buyer_id:
        await update.message.reply_text(f"{EM_FAIL} Нельзя оставить отзыв на своё объявление.")
        return ConversationHandler.END

    saved = db.create_review(seller_id, buyer_id, ad_id, rating, text)
    stars = "★" * rating

    if saved:
        await update.message.reply_text(f"{EM_OK} Отзыв сохранён!\n\n{stars} {'— ' + text if text else ''}")
        # Уведомляем продавца
        seller_rating = db.get_seller_rating(seller_id)
        try:
            await context.bot.send_message(
                chat_id=seller_id,
                text=(
                    f"Новый отзыв!\n\n"
                    f"Оценка: {stars}\n"
                    f"{'Комментарий: ' + text if text else ''}\n\n"
                    f"Ваш рейтинг: {seller_rating['avg']} ★ ({seller_rating['count']} отзывов)"
                )
            )
        except Exception as _e:
            logger.debug(f"Ignored error: {_e}")
    else:
        await update.message.reply_text(f"{EM_FAIL} Вы уже оставили отзыв на это объявление.")

    for key in ('review_ad_id', 'review_rating'):
        context.user_data.pop(key, None)
    return ConversationHandler.END

async def show_seller_reviews(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Показать отзывы о продавце — красиво как на Авито"""
    query = update.callback_query
    await safe_answer(query, )
    try:
        seller_id = int(query.data.split(":")[1])
        viewer_id = update.effective_user.id
        # Кнопка «← Назад» возвращает туда, откуда пришли (объявление или профиль продавца)
        last_ad = context.user_data.get('last_viewed_ad_id')
        reviews_back = context.user_data.get('_seller_back') or (f'view_ad:{last_ad}' if last_ad else 'back_to_menu')

        reviews = db.get_seller_reviews(seller_id)
        rating  = db.get_seller_rating(seller_id)
        seller  = db.get_user(seller_id)
        seller_name = get_anon_id(seller) if seller else f"Продавец"
        verify  = db.get_verification(seller_id)
        is_verified = verify and verify.get('status') == 'verified'
        verified_tag = f" {EM_OK}" if is_verified else ""

        send_rating_chart = False
        if not reviews:
            text = (
                f"<b>Отзывы о {seller_name}</b>{verified_tag}\n\n"
                "У этого продавца пока нет отзывов.\n\n"
                "<i>Оставьте первый — это поможет другим покупателям!</i>"
            )
        else:
            # Звёздный рейтинг
            avg = rating['avg']
            cnt = rating['count']
            filled = "★" * round(avg)
            empty  = "☆" * (5 - round(avg))

            # Разбивка по звёздам
            breakdown = {5: 0, 4: 0, 3: 0, 2: 0, 1: 0}
            for r in reviews:
                breakdown[r['rating']] = breakdown.get(r['rating'], 0) + 1

            # ── Caption к графику (blockquote-стиль) ────────────────
            def _plural(n):
                if 11 <= n % 100 <= 19: return 'отзывов'
                r = n % 10
                if r == 1: return 'отзыв'
                if 2 <= r <= 4: return 'отзыва'
                return 'отзывов'

            full_s = int(round(avg))
            stars_header = '★' * full_s
            text = (
                f"<b>Отзывы о {seller_name}</b>{verified_tag}\n\n"
                f"<blockquote>"
                f"{stars_header} <b>{avg:.1f}</b> из 5 · {cnt} {_plural(cnt)}\n"
                f"{'Проверенный продавец' if is_verified else 'Продавец на площадке'}"
                f"</blockquote>"
            )
            # Флаг больше не нужен — картинку не отправляем
            send_rating_chart = False

            # ── Отдельные отзывы — каждый в blockquote ──────────────
            RU_MONTHS = ['','янв','фев','мар','апр','май','июн',
                         'июл','авг','сен','окт','ноя','дек']

            review_messages = []
            for r in reviews[:15]:
                r_stars = '★' * min(max(r['rating'], 1), 5)
                name = f"@{r['username']}" if r.get('username') else r.get('first_name', 'Покупатель')
                raw_date = r.get('created_at', '')
                try:
                    from datetime import datetime as _dt
                    d = _dt.fromisoformat(raw_date[:10])
                    date_str = f"{d.day} {RU_MONTHS[d.month]} {d.year}"
                except Exception:
                    date_str = raw_date[:10]
                review_text = r.get('text', '').strip() if r.get('text') else '—'
                short = review_text[:200] + ('…' if len(review_text) > 200 else '')
                safe = short.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
                review_messages.append(
                    f"<blockquote>"
                    f"{r_stars}\n"
                    f"<b>{name}</b> · {date_str}\n\n"
                    f"{safe}"
                    f"</blockquote>"
                )

        keyboard = []
        if viewer_id != seller_id:
            last_ad = context.user_data.get('last_viewed_ad_id')
            if last_ad:
                keyboard.append([InlineKeyboardButton(EM_DOT + " Написать отзыв", callback_data=f"leave_review:{last_ad}")])
        if viewer_id == seller_id and reviews:
            keyboard.append([InlineKeyboardButton(EM_WARN + " Обжаловать отзыв", callback_data=f"appeal_review_menu:{seller_id}")])
        keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data=reviews_back)])

        if send_rating_chart:
            # Первое сообщение — шапка с рейтингом
            await query.message.reply_text(text, parse_mode=ParseMode.HTML)
            # Каждый отзыв отдельным blockquote-сообщением
            for i, rm in enumerate(review_messages):
                is_last = (i == len(review_messages) - 1)
                await query.message.reply_text(
                    rm,
                    parse_mode=ParseMode.HTML,
                    reply_markup=InlineKeyboardMarkup(keyboard) if is_last else None,
                )
            await query.delete_message()
        else:
            await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"Ошибка в show_seller_reviews: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить отзывы.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
        except Exception:
            pass
