async def appeal_review_handle_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Получаем текст обжалования и отправляем на модерацию"""
    reason = update.message.text.strip()
    review_id = context.user_data.get('appeal_review_id')
    seller_id = update.effective_user.id

    if not review_id:
        await update.message.reply_text("Сессия истекла. Вернитесь к отзыву и попробуйте обжаловать снова.")
        return ConversationHandler.END

    saved = db.appeal_review(review_id, seller_id, reason)
    if saved:
        # Уведомляем админов
        seller = db.get_user(seller_id)
        for admin_id in ADMIN_USER_IDS:
            try:
                await context.bot.send_message(
                    chat_id=admin_id,
                    text=(
                        f"! Обжалование отзыва #{review_id}\n\n"
                        f"Продавец: {seller['first_name']} (@{seller.get('username','?')})\n"
                        f"Причина: {reason[:200]}\n\n"
                        f"Решите: удалить отзыв или оставить."
                    ),
                    reply_markup=InlineKeyboardMarkup([[
                        InlineKeyboardButton(EM_FAIL + " Удалить отзыв", callback_data=f"admin_appeal_delete:{review_id}"),
                        InlineKeyboardButton(EM_FAIL + " Отклонить жалобу", callback_data=f"admin_appeal_reject:{review_id}")
                    ]])
                )
            except Exception as e:
                logger.error(f"appeal admin notify: {e}")
        await update.message.reply_text(
            f"{EM_OK} Обжалование отправлено на рассмотрение модератору.\nМы уведомим вас о решении.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
        )
    else:
        await update.message.reply_text("Вы уже подали жалобу на этот отзыв. Ожидайте решения модератора.")

    context.user_data.pop('appeal_review_id', None)
    return ConversationHandler.END


async def admin_appeal_decision(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Администратор принимает решение по обжалованию"""
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return

    parts = query.data.split(":")
    action = parts[0]  # admin_appeal_delete or admin_appeal_reject
    review_id = int(parts[1])

    if action == "admin_appeal_delete":
        # Находим appeal_id по review_id
        cursor = db.conn.cursor()
        try:
            cursor.execute('SELECT id, seller_id FROM review_appeals WHERE review_id=? AND status="pending" LIMIT 1', (review_id,))
            row = cursor.fetchone()
            if row:
                appeal_id = dict(row)['id']
                seller_id = dict(row)['seller_id']
                db.decide_appeal(appeal_id, 'delete_review', update.effective_user.id)
                try:
                    await context.bot.send_message(chat_id=seller_id,
                        text=f"{EM_OK} Ваша жалоба рассмотрена — отзыв удалён.")
                except Exception as _e:
                    logger.debug(f"Ignored error: {_e}")
            await safe_edit_message(query, f"{EM_OK} Отзыв #{review_id} удалён по результатам обжалования.",
                [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]])
        except Exception as e:
            logger.error(f"admin_appeal_decision delete error: {e}")
            await safe_edit_message(query, f"{EM_FAIL} Ошибка при удалении отзыва.",
                [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]])
    else:  # reject
        cursor = db.conn.cursor()
        try:
            cursor.execute('SELECT id, seller_id FROM review_appeals WHERE review_id=? AND status="pending" LIMIT 1', (review_id,))
            row = cursor.fetchone()
            if row:
                appeal_id = dict(row)['id']
                seller_id = dict(row)['seller_id']
                db.decide_appeal(appeal_id, 'reject_appeal', update.effective_user.id)
                try:
                    await context.bot.send_message(chat_id=seller_id,
                        text=f"{EM_FAIL} Ваша жалоба рассмотрена — отзыв оставлен.")
                except Exception as _e:
                    logger.debug(f"Ignored error: {_e}")
            await safe_edit_message(query, f"{EM_FAIL} Жалоба на отзыв #{review_id} отклонена.",
                [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]])
        except Exception as e:
            logger.error(f"admin_appeal_decision reject error: {e}")
            await safe_edit_message(query, "Не удалось сохранить решение. Попробуйте ещё раз.",
                [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]])

# =====================================================================
#  АНАЛИТИКА ПРОСМОТРОВ (График по дням)
# =====================================================================

def make_views_chart_image(chart_data: list, title: str = "") -> Optional[bytes]:
    """Генерирует PNG-изображение графика просмотров через Pillow — тот же
    дизайн, что и в MAX-боте (единый вид в обоих ботах): столбцы — суммарные
    просмотры, две цветные линии поверх — разбивка по площадкам (TG/MAX)."""
    try:
        from PIL import Image, ImageDraw, ImageFont
        import io as _io

        if not chart_data:
            return None

        values = [d['views'] for d in chart_data]
        dates = [d['date'][5:10] for d in chart_data]
        total = sum(values)

        # Запас по высоте сверху: без него при малом количестве данных
        # (например, всего 1 просмотр за весь период) единственный
        # ненулевой столбец растягивается на 100% высоты графика,
        # упирается в самый верх, а подпись значения вылетает НАД
        # графиком и накладывается на заголовок.
        raw_max = max(values) if max(values) > 0 else 1
        max_val = max(raw_max + 1, int(raw_max * 1.2) + 1)

        W, H = 600, 300
        PAD_L, PAD_R, PAD_T, PAD_B = 55, 25, 55, 45
        chart_w = W - PAD_L - PAD_R
        chart_h = H - PAD_T - PAD_B

        ACCENT = "#3373FA"        # Telegram — фирменный синий (нижняя часть столбца)
        ACCENT_LIGHT = "#AEC6FF"  # MAX — светлый оттенок того же синего (верхняя часть)
        LIGHT_BG = "#f5f8ff"
        GRID = "#e0ebff"

        img = Image.new("RGB", (W, H), "#ffffff")
        draw = ImageDraw.Draw(img)

        # Шрифт берём из своих assets, а не полагаемся на системные пути —
        # базовый образ python:3.13-slim НЕ содержит пакет fonts-dejavu-core,
        # поэтому /usr/share/fonts/... на сервере не существует вообще.
        # ImageFont.truetype падал молча (никакой ошибки в логах), Pillow
        # откатывался на встроенный битмап-шрифт по умолчанию — а он не
        # поддерживает кириллицу совсем, отсюда квадратики вместо текста
        # на графике. Собственный .ttf в assets/ работает независимо от
        # того, что установлено в контейнере.
        _bundled_font_path = os.path.join(
            os.path.dirname(os.path.abspath(__file__)), "assets", "fonts", "DejaVuSans.ttf"
        )
        try:
            font = ImageFont.truetype(_bundled_font_path, 11)
            font_small = ImageFont.truetype(_bundled_font_path, 9)
            font_title = ImageFont.truetype(_bundled_font_path, 13)
        except Exception:
            try:
                font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 11)
                font_small = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 9)
                font_title = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 13)
            except Exception:
                logger.warning("make_views_chart_image: не найден ни свой, ни системный шрифт — кириллица на графике не отобразится")
                font = ImageFont.load_default()
                font_small = font
                font_title = font

        if not title:
            title = f"Просмотры за 14 дней — всего {total}"
        draw.text((PAD_L, 12), title, fill=ACCENT, font=font_title)

        all_zero = all(v == 0 for v in values)
        if all_zero:
            draw.text((W // 2 - 40, H // 2 + 10), "Нет данных", fill="#999999", font=font)
            buf = _io.BytesIO()
            img.save(buf, format="PNG", optimize=True)
            return buf.getvalue()

        row_h = chart_h / 4
        for i in range(4):
            y0 = PAD_T + row_h * i
            y1 = PAD_T + row_h * (i + 1)
            if i % 2 == 0:
                draw.rectangle([PAD_L, int(y0), W - PAD_R, int(y1)], fill=LIGHT_BG)

        if max_val <= 5:
            y_labels = list(range(max_val + 1))
        else:
            step_y = max(1, round(max_val / 4))
            y_labels = list(range(0, max_val + 1, step_y))
            if y_labels[-1] != max_val:
                y_labels.append(max_val)

        for val in y_labels:
            y = PAD_T + chart_h - int(chart_h * val / max_val)
            draw.line([(PAD_L, y), (W - PAD_R, y)], fill=GRID, width=1)
            draw.text((4, y - 7), str(val), fill=ACCENT, font=font_small)

        step = max(1, len(dates) // 7)
        for i, d in enumerate(dates):
            x = PAD_L + int(chart_w * i / max(len(dates) - 1, 1))
            if i % step == 0 or i == len(dates) - 1:
                draw.text((x - 12, H - PAD_B + 6), d, fill=ACCENT, font=font_small)

        # Легенда — верхний правый угол
        has_split = any('views_tg' in d or 'views_max' in d for d in chart_data)
        if has_split:
            legend_x = W - PAD_R - 140
            draw.rectangle([legend_x, 14, legend_x + 10, 24], fill=ACCENT)
            draw.text((legend_x + 15, 14), "Telegram", fill="#333333", font=font_small)
            draw.rectangle([legend_x + 75, 14, legend_x + 85, 24], fill=ACCENT_LIGHT)
            draw.text((legend_x + 90, 14), "MAX", fill="#333333", font=font_small)

        # Составные столбцы: снизу — Telegram, сверху — MAX, общая высота —
        # сумма (то же число, что подписано над столбцом). Раньше сверху
        # ещё рисовались отдельные линии (сплошная/пунктир) поверх тех же
        # столбцов — два разных визуальных языка для одних и тех же данных
        # одновременно только запутывали, особенно при малом количестве
        # данных. Составной столбец — один понятный способ показать и
        # сумму, и разбивку по площадкам.
        bar_w = max(8, int(chart_w / len(values)) - 3)
        for i, d in enumerate(chart_data):
            v_tg = d.get('views_tg', values[i])
            v_max = d.get('views_max', 0) if has_split else 0
            v_total = v_tg + v_max
            if v_total == 0:
                continue
            x = PAD_L + int(chart_w * i / max(len(values) - 1, 1)) - bar_w // 2
            h_tg = int(chart_h * v_tg / max_val)
            h_max = int(chart_h * v_max / max_val)
            y_bottom = PAD_T + chart_h
            if h_tg > 0:
                draw.rectangle([x, y_bottom - h_tg, x + bar_w, y_bottom], fill=ACCENT)
            if h_max > 0:
                draw.rectangle([x, y_bottom - h_tg - h_max, x + bar_w, y_bottom - h_tg], fill=ACCENT_LIGHT)
            label_y = y_bottom - h_tg - h_max - 14
            if label_y < PAD_T - 10:
                label_y = y_bottom - h_tg - h_max + 4
            draw.text((x - 2, label_y), str(v_total), fill=ACCENT, font=font)

        buf = _io.BytesIO()
        img.save(buf, format="PNG", optimize=True)
        return buf.getvalue()
    except Exception as e:
        logger.warning(f"make_views_chart_image Pillow error: {e}")
        return None


_SPARK_LEVELS = " ▁▂▃▄▅▆▇█"

def _sparkline(values: List[int], scale_max: int) -> str:
    """Строит однострочный спарклайн по 9-уровневой шкале Unicode-блоков
    (используется как текстовый фолбэк, если Pillow-график не удалось
    сгенерировать/отправить)."""
    if scale_max <= 0:
        return " " * len(values)
    out = []
    for v in values:
        level = round((v / scale_max) * (len(_SPARK_LEVELS) - 1))
        level = max(0, min(len(_SPARK_LEVELS) - 1, level))
        out.append(_SPARK_LEVELS[level])
    return "".join(out)


def build_ascii_chart(data: List[Dict], width: int = 14) -> str:
    """Текстовый ASCII-график — запасной вариант на случай, если PNG
    (make_views_chart_image) не сгенерировался или не отправился."""
    if not data:
        return "Нет данных"

    values = [d['views'] for d in data]
    max_val = max(values) if max(values) > 0 else 1
    chart_height = 6

    lines = []
    for row in range(chart_height, 0, -1):
        threshold = (row / chart_height) * max_val
        line = ""
        for v in values:
            if v >= threshold:
                line += "█"
            elif v >= threshold * 0.5:
                line += "▄"
            else:
                line += " "
        label = f"{int(threshold):>3}"
        lines.append(f"{label}|{line}")

    dates_line = " " + "".join([d['date'][8:10] for d in data])
    lines.append(dates_line)

    if any('views_tg' in d or 'views_max' in d for d in data):
        values_tg = [d.get('views_tg', 0) for d in data]
        values_max = [d.get('views_max', 0) for d in data]
        shared_max = max(max(values_tg, default=0), max(values_max, default=0), 1)
        lines.append("")
        lines.append(f"TG  |{_sparkline(values_tg, shared_max)}")
        lines.append(f"MAX |{_sparkline(values_max, shared_max)}")

    return "\n".join(lines)

def _rule_based_advice(ad: dict, total_views: int, contact_clicks: int, conv_rate: float) -> str:
    """Генерирует конкретные советы по объявлению на основе его реального содержимого."""
    tips = []
    photos   = len(ad.get("photos") or [])
    desc     = (ad.get("description") or "").strip()
    price    = int(ad.get("price") or 0)
    title    = (ad.get("title") or "").strip()
    category = (ad.get("category") or "").lower()
    condition= (ad.get("condition") or "").lower()
    city     = (ad.get("city") or "").strip()

    # ── Анализ заголовка ─────────────────────────────────────────────────────
    words_in_title = title.split()
    has_brand  = any(w[0].isupper() and len(w) > 2 for w in words_in_title[1:])
    has_size   = any(w.upper() in ("XS","S","M","L","XL","XXL","42","44","46","48","XS","40","41","42","43","44","45") for w in words_in_title)
    has_model  = len(words_in_title) >= 3

    if len(title) < 12:
        tips.append(f"{EM_DOT} Заголовок «{title}» слишком короткий — добавьте бренд, модель или размер. Например: «{title} Nike Air, размер 42»")
    elif not has_brand and "одежда" in category or "обувь" in category:
        tips.append(f"{EM_DOT} В заголовке нет бренда — покупатели часто ищут по бренду. Добавьте название производителя.")
    elif not has_model and len(title) < 25:
        tips.append(f"{EM_DOT} Добавьте в заголовок характеристику товара — это увеличивает показы в поиске.")

    # ── Анализ описания ──────────────────────────────────────────────────────
    desc_lower = desc.lower()
    if len(desc) < 20:
        tips.append(f"{EM_DOT} Описание почти пустое. Напишите: состояние, причину продажи, что входит в комплект.")
    elif len(desc) < 60:
        missing = []
        if "состояни" not in desc_lower and condition not in ("новое", "новый"):
            missing.append("состояние")
        if "достав" not in desc_lower and "самовывоз" not in desc_lower:
            missing.append("способ передачи")
        if missing:
            tips.append(f"{EM_DOT} В описании не указано: {', '.join(missing)}. Добавьте — это снизит количество уточняющих вопросов.")

    # Проверяем нет ли цены в описании (дублирование)
    if str(price) in desc and price > 0:
        tips.append(f"{EM_DOT} Цена уже указана в поле «Цена» — не нужно дублировать её в описании, это выглядит неаккуратно.")

    # ── Анализ фото ──────────────────────────────────────────────────────────
    if photos == 0:
        tips.append(f"{EM_DOT} Нет фото — объявления с фото получают в 4 раза больше откликов. Добавьте хотя бы 2–3 снимка.")
    elif photos == 1:
        tips.append(f"{EM_DOT} Только одно фото. Добавьте фото с разных ракурсов (этикетка, дефекты если есть, в использовании).")

    # ── Анализ цены по конверсии ─────────────────────────────────────────────
    if total_views >= 15 and contact_clicks == 0:
        if price > 3000:
            tips.append(f"{EM_DOT} {total_views} просмотров и ни одного обращения — при цене {price:,} ₽ покупатели ожидают больше фото и подробное описание.".replace(',', ' '))
        else:
            tips.append(f"{EM_DOT} {total_views} просмотров без обращений — попробуйте снизить цену на 10–15% или добавить фразу «торг уместен».")
    elif total_views >= 30 and conv_rate < 3:
        tips.append(f"{EM_DOT} Конверсия {conv_rate}% при {total_views} просмотрах — перепишите первое предложение описания, оно влияет на решение написать.")

    # ── Анализ состояния ─────────────────────────────────────────────────────
    if condition in ("б/у", "бу", "использованное") and "дефект" not in desc_lower and "царапин" not in desc_lower and photos >= 1:
        tips.append(f"{EM_DOT} Товар б/у — покупатели оценят честность: укажите есть ли дефекты или напишите «дефектов нет».")

    # ── Город ───────────────────────────────────────────────────────────────
    if not city:
        tips.append(f"{EM_DOT} Не указан город — покупатели из вашего региона не найдут объявление через городской фильтр.")

    # ── Если всё хорошо ──────────────────────────────────────────────────────
    if not tips:
        if conv_rate >= 5:
            tips.append(f"{EM_DOT} Объявление работает отлично! Конверсия {conv_rate}% выше средней по платформе (~3%).")
        elif total_views == 0:
            tips.append(f"{EM_DOT} Объявление ещё не получило просмотров — закрепите его в топ канала для быстрого старта.")
        else:
            tips.append(f"{EM_DOT} Объявление выглядит хорошо. Для увеличения охвата — закрепите его в основном или городском канале.")

    return "\n\n".join(tips[:4])


async def _groq_advice(ad: dict, total_views: int, contact_clicks: int, conv_rate: float) -> str:
    """Генерирует советы через Yandex GPT / Groq."""
    photos = len(ad.get("photos") or [])
    desc   = (ad.get("description") or "")[:300]
    prompt = (
        f"Ты эксперт по продажам на досках объявлений. Дай 3 конкретных совета как улучшить это объявление.\n\n"
        f"Заголовок: {ad.get('title','')}\n"
        f"Описание: {desc or 'не указано'}\n"
        f"Цена: {ad.get('price',0)} ₽\n"
        f"Категория: {ad.get('category','')}\n"
        f"Состояние: {ad.get('condition','')}\n"
        f"Фото: {photos} шт.\n"
        f"Просмотров: {total_views}\n"
        f"Обращений: {contact_clicks}\n"
        f"Конверсия: {conv_rate}%\n\n"
        f"Каждый совет — одна строка начинающаяся с {EM_DOT}. Только советы, без вступления. На русском языке."
    )
    result = await _llm_completion(
        messages=[{"role": "user", "content": prompt}],
        max_tokens=400, temperature=0.6,
    )
    return result


async def ad_advice_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    ""f"Кнопка «{EM_DOT} Советы» в аналитике — бесплатно для всех тарифов."""
    query = update.callback_query
    await safe_answer(query, )

    ad_id = int(query.data.split(":")[1])
    ad    = db.get_ad(ad_id)
    if not ad or ad["user_id"] != update.effective_user.id:
        await safe_answer(query, "Нет доступа", show_alert=True)
        return

    await safe_edit_message(query, f"{EM_DOT} Анализирую объявление...",
        [[InlineKeyboardButton(EM_ARROW_L + " К аналитике", callback_data=f"ad_analytics:{ad_id}")]])

    total_views    = ad.get("views", 0) or 0
    # Реальные просмотры поста в каналах (TG web + MAX)
    try:
        live = await get_live_channel_views(ad)
        live_sum = (live.get('tg') or 0) + (live.get('max') or 0)
        if live_sum > total_views:
            total_views = live_sum
    except Exception as e:
        logger.warning(f"ad_advice_callback live views: {e}")
    contact_clicks = db.get_ad_contact_clicks(ad_id)
    conv_rate      = round(contact_clicks / total_views * 100, 1) if total_views > 0 else 0

    # Пробуем Groq, иначе правила
    advice = await _groq_advice(ad, total_views, contact_clicks, conv_rate)
    if not advice:
        advice = _rule_based_advice(ad, total_views, contact_clicks, conv_rate)

    source = " (AI)" if advice else ""
    await safe_edit_message(query,
        f"<b>Советы по объявлению{source}</b>\n\n{advice}",
        [[InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data=f"ad_advice:{ad_id}")],
         [InlineKeyboardButton(EM_ARROW_L + " К аналитике", callback_data=f"ad_analytics:{ad_id}")]],
        parse_mode=ParseMode.HTML
    )


# Кэш просмотров TG-постов через веб-страницу t.me (публичный канал).
_tg_views_cache = {}          # ad_id -> (timestamp, views)
_tg_web_fail_until = 0.0      # monotonic: до этого времени НЕ дёргаем t.me (сбой сети)
_TG_WEB_FAIL_BACKOFF = 90     # сек не пробуем после сетевого сбоя (иначе бот виснет на таймаутах)
_TG_VIEWS_CACHE_TTL = 600     # секунд: держим просмотры в памяти 10 минут
# Публичный username TG-канала (для чтения просмотров через веб-страницу t.me —
# без MTProto, поэтому работает на любом хостинге, в т.ч. Amvera).
TG_CHANNEL_USERNAME = os.environ.get("TG_CHANNEL_USERNAME", "polkaudm").lstrip("@")


async def _get_tg_views_web(ad: dict) -> Optional[int]:
    """Получает просмотры TG-поста через публичную веб-страницу t.me.

    Работает только для ПУБЛИЧНОГО канала (пользователь с username).
    Не использует MTProto, поэтому доступно с любого хостинга, в т.ч. Amvera.
    Возвращает int просмотров или None.
    """
    global _tg_web_fail_until
    tg_msg_id = ad.get('channel_message_id')
    if isinstance(tg_msg_id, str) and tg_msg_id.startswith('mid.'):
        return None  # это MAX-пост, не TG
    if not tg_msg_id or not TG_CHANNEL_USERNAME:
        return None
    try:
        msg_id = int(tg_msg_id)
    except (TypeError, ValueError):
        return None
    # Негативный кэш: не долбим t.me, раз он недоступен
    if _time.monotonic() < _tg_web_fail_until:
        return None
    url = f"https://t.me/{TG_CHANNEL_USERNAME}/{msg_id}?embed=1&mode=tme"
    try:
        timeout = aiohttp.ClientTimeout(total=4)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.get(url, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Accept-Language": "en-US,en;q=0.9",
            }) as resp:
                text = await resp.text()
        # mode=tme отдаёт JSON: {"ok":true,"result":{"id":...,"views":...}}
        try:
            data = json.loads(text)
            views = (data.get("result") or {}).get("views")
            if views is not None:
                return int(views)
        except Exception:
            pass
        # Фолбэк: парсим HTML-страницу
        m = re.search(r'"views"\s*:\s*(\d+)', text)
        if m:
            return int(m.group(1))
        m = re.search(r'tgme_widget_message_views[^>]*>\s*([\d\s.]+)<', text)
        if m:
            try:
                return int(re.sub(r'[^\d]', '', m.group(1)))
            except Exception:
                return None
    except Exception as e:
        _tg_web_fail_until = _time.monotonic() + _TG_WEB_FAIL_BACKOFF
        logger.warning(f"_get_tg_views_web(ad {ad.get('id')}, msg {msg_id}): {type(e).__name__}: {e} "
                       f"(t.me недоступен, пауза {_TG_WEB_FAIL_BACKOFF}с)")
    return None


async def get_live_channel_views(ad: dict) -> Dict:
    """Достаёт на лету реальные просмотры поста объявления из каналов:
    - MAX: MAX Bot API get_message → stat.views (абсолютный счётчик)
    - TG:  MTProto (userbot-сессия) → message.views (абсолютный счётчик поста)

    Возвращает {'tg': int|None, 'max': int|None}. При сбое/отсутствии данных — None.
    """
    global _tg_web_fail_until
    result = {'tg': None, 'max': None}
    ad_id = ad.get('id')
    # ── MAX ────────────────────────────────────────────────────────────────
    try:
        mid = (ad.get('max_channel_message_id') or '').strip()
        if not mid:
            cmi = ad.get('channel_message_id')
            if isinstance(cmi, str) and cmi.startswith('mid.'):
                mid = cmi
        max_views = None
        # 1) По сохранённому mid
        if mid and max_client and MAX_CHANNEL_ID:
            raw = await max_client.get_message(MAX_CHANNEL_ID, str(mid))
            views = (raw or {}).get("stat") or {}
            if views.get("views") is not None:
                max_views = int(views["views"])
        # 2) Fallback: mid не сохранился/устарел — ищем пост в канале по заголовку
        if max_views is None and max_client and MAX_CHANNEL_ID and ad.get('title'):
            try:
                msgs = await max_client.get_channel_messages(MAX_CHANNEL_ID, limit=50) or []
                title_l = (ad['title'] or '').strip().lower()
                if title_l:
                    for m in msgs:
                        body = (m.get("body") or {})
                        text = (body.get("text") or "")[:300].replace("\n", " ").lower()
                        if text and title_l in text:
                            qv = ((m.get("stat") or {}).get("views"))
                            if qv is not None:
                                max_views = int(qv)
                                logger.info(f"get_live_channel_views(MAX): ad {ad_id} найден по заголовку, views={max_views}")
                                break
            except Exception as mex:
                logger.warning(f"get_live_channel_views(MAX fallback) ad {ad_id}: {mex}")
        if max_views is not None:
            result['max'] = max_views
    except Exception as e:
        logger.warning(f"get_live_channel_views(MAX) ad {ad_id}: {e}")
    # ── TG: веб-метод (публичный канал t.me, без MTProto) ─────────────────
    try:
        # Кэш: не дёргаем Telegram при каждом клике «Обновить»
        now = _time.monotonic()
        cached = _tg_views_cache.get(ad_id)
        if cached and (now - cached[0]) < _TG_VIEWS_CACHE_TTL:
            result['tg'] = cached[1]
        else:
            tg_msg_id = ad.get('channel_message_id')
            if isinstance(tg_msg_id, str) and tg_msg_id.startswith('mid.'):
                tg_msg_id = None  # это MAX-пост, не TG
            if tg_msg_id:
                web_views = await _get_tg_views_web(ad)
                if web_views is not None:
                    result['tg'] = web_views
                    _tg_views_cache[ad_id] = (now, result['tg'])
    except Exception as e:
        logger.warning(f"get_live_channel_views(TG) ad {ad_id}: {e}")
    return result


async def get_live_views_sum(ads: List[dict]) -> int:
    """Суммирует НАСТОЯЩИЕ просмотры (TG web + MAX) по списку объявлений.

    Используется в профиле/«Мои объявления»/карточке продавца, где раньше
    показывался внутренний счётчик clicks. Берёт максимум между старым
    счётчиком и реальными просмотрами (чтобы цифры никогда не убывали).
    Запрашивает каналы параллельно: при большом списке и недоступной сети
    последовательный вызов гасил обработчик на N×таймаут секунд.
    """
    if not ads:
        return 0
    try:
        results = await asyncio.wait_for(
            asyncio.gather(*(get_live_channel_views(ad) for ad in ads)),
            timeout=8,
        )
    except Exception as e:
        logger.warning(f"get_live_views_sum: gather: {e}")
        results = []
    total = 0
    for ad, live in zip(ads, results):
        live_sum = (live.get('tg') or 0) + (live.get('max') or 0)
        total += max(int(ad.get('views', 0) or 0), live_sum)
    return total


async def show_ad_analytics(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Показываем аналитику просмотров объявления"""
    query = update.callback_query
    await safe_answer(query, )

    try:
        ad_id = int(query.data.split(":")[1])
        user = update.effective_user
        ad = db.get_ad(ad_id)

        if not ad or ad['user_id'] != user.id:
            await safe_edit_message(query, "Объявление не найдено")
            return

        # Аналитика только для платных тарифов
        user_data = db.get_user(user.id)
        if user_data.get('tariff', 'Free') == 'Free':
            await safe_edit_message(query,
                "<b>Аналитика объявлений</b>\n\n"
                "Аналитика недоступна.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data=f"view_my_ad:{ad_id}")]])
            return
        
        chart_data = db.get_ad_views_chart(ad_id, days=14)
        total_views = ad['views']
        contact_clicks = db.get_ad_contact_clicks(ad_id)
        
        # Полные просмотры за всё время с разбивкой по площадкам
        totals = db.get_ad_views_totals(ad_id)
        if totals['views'] > total_views:
            total_views = totals['views']
        views_tg_total = totals['tg']
        views_max_total = totals['max']

        # Реальные просмотры постов из каналов (на лету): если удалось прочитать —
        # показываем достоверный счётчик поста канала, а не открытия карточки в боте.
        try:
            live = await get_live_channel_views(ad)
            if live.get('max') is not None:
                views_max_total = live['max']
            if live.get('tg') is not None:
                views_tg_total = live['tg']
            total_views = views_tg_total + views_max_total
        except Exception as e:
            logger.warning(f"show_ad_analytics: get_live_channel_views ad={ad_id}: {e}")
        
        # Считаем тренд
        first_week = sum(d['views'] for d in chart_data[:7])
        second_week = sum(d['views'] for d in chart_data[7:])
        if first_week > 0:
            trend = ((second_week - first_week) / first_week) * 100
            trend_icon = "" if trend >= 0 else ""
            trend_text = f"{trend_icon} {'+' if trend >= 0 else ''}{trend:.0f}% за неделю"
        else:
            trend_text = "Недостаточно данных для тренда"
        
        # Пиковый день
        peak = max(chart_data, key=lambda d: d['views'])
        peak_text = f"▼ Пик: {peak['views']} просм. ({peak['date']})" if peak['views'] > 0 else ""
        
        conv_rate = round(contact_clicks / total_views * 100, 1) if total_views > 0 else 0

        # Разбивка просмотров по площадкам за весь период
        # (используются totals из get_ad_views_totals выше)
        pass

        lines = [
            f"<b> Аналитика: {ad['title'][:40]}</b>\n",
            f" Просмотров: <b>{total_views}</b>",
            f"    Telegram: <b>{views_tg_total}</b> {EM_DOT} MAX: <b>{views_max_total}</b>",
            f" Кликов «Связаться»: <b>{contact_clicks}</b>",
        ]
        if total_views > 0:
            lines.append(f"Конверсия: <b>{conv_rate}%</b>")
        if peak_text:
            lines.append(peak_text)
        lines.append(f"\n{trend_text}")

        text = "\n".join(lines)

        keyboard = [
            [InlineKeyboardButton(EM_DOT + " Советы", callback_data=f"ad_advice:{ad_id}"),
             InlineKeyboardButton(EM_DIAMOND + " Закрепить", callback_data=f"pin_ad:{ad_id}")],
            [InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data=f"ad_analytics:{ad_id}")],
            [InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_my_ad:{ad_id}")]
        ]

        # Генерируем PNG-график просмотров (тот же дизайн, что в MAX-боте)
        chart_bytes = make_views_chart_image(chart_data)
        if chart_bytes:
            try:
                await query.message.reply_photo(
                    photo=io.BytesIO(chart_bytes),
                    caption=text,
                    reply_markup=InlineKeyboardMarkup(keyboard),
                    parse_mode=ParseMode.HTML
                )
                await query.delete_message()
            except Exception as e:
                logger.warning(f"chart reply_photo error: {e}, fallback to text")
                chart_txt = build_ascii_chart(chart_data)
                if chart_txt:
                    text += f"\n\n<code>{chart_txt}</code>"
                await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
        else:
            chart_txt = build_ascii_chart(chart_data)
            if chart_txt:
                text += f"\n\n<code>{chart_txt}</code>"
            await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"Ошибка в show_ad_analytics: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить аналитику.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="my_ads")]])
        except Exception:
            pass


