async def admin_reports(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Список объявлений с жалобами, сгруппированный по объявлению."""
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return

    groups = db.get_reports_grouped()

    if not groups:
        await safe_edit_message(
            query,
            f"{EM_OK} Жалоб нет — всё чисто.",
            [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]]
        )
        return

    text = f"{EM_WARN} <b>Жалобы</b> — {len(groups)} объявлений\n\n"
    keyboard = []
    for g in groups[:20]:
        title   = (g["title"] or f"#{g['ad_id']}")[:35]
        cnt     = g["report_count"]
        status  = g["ad_status"] or "?"
        status_icon = EM_OK if status == "active" else EM_FAIL
        text += f"{status_icon} <b>{title}</b>\n"
        text += f"   Жалоб: <b>{cnt}</b> · статус: {status}\n\n"
        keyboard.append([InlineKeyboardButton(
            f"{EM_WARN} {cnt}× {title[:28]}",
            callback_data=f"admin_report_view:{g['ad_id']}"
        )])

    keyboard.append([
        InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_reports"),
        InlineKeyboardButton(EM_ARROW_L + " Панель",  callback_data="admin_panel"),
    ])
    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)


async def admin_report_view(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Детальный просмотр жалоб на одно объявление + действия."""
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return

    ad_id = int(query.data.split(":")[1])
    ad    = db.get_ad(ad_id)
    if not ad:
        await safe_answer(query, "Объявление не найдено", show_alert=True)
        return

    # Все pending-жалобы на это объявление
    cursor = db.conn.cursor()
    cursor.execute(
        "SELECT r.reason, r.created_at, u.username, u.first_name "
        "FROM reports r LEFT JOIN users u ON r.reporter_id = u.user_id "
        "WHERE r.ad_id=? AND r.status='pending' ORDER BY r.created_at DESC",
        (ad_id,)
    )
    rows = [dict(r) for r in cursor.fetchall()]

    seller_id = ad.get("user_id")
    seller    = db.get_user(seller_id) if seller_id else {}
    seller_name = f"@{seller.get('username')}" if seller and seller.get("username") else (seller.get("first_name") or f"ID {seller_id}")

    text = (
        f"{EM_WARN} <b>Жалобы на объявление #{ad_id}</b>\n\n"
        f"<b>{ad['title'][:60]}</b>\n"
        f"Продавец: {seller_name}\n"
        f"Статус: {ad.get('status', '?')}\n"
        f"Жалоб: <b>{len(rows)}</b>\n\n"
    )
    for i, r in enumerate(rows[:10], 1):
        who  = f"@{r['username']}" if r.get("username") else (r.get("first_name") or "?")
        when = fmt_datetime(r.get("created_at", ""))
        text += f"{i}. {r['reason']}\n   — {who}, {when}\n"

    is_seller_banned = db.is_banned(seller_id) if seller_id else False
    if is_seller_banned:
        ban_btn = InlineKeyboardButton(EM_OK + " Разбанить продавца", callback_data=f"admin_unban:{seller_id}")
    else:
        ban_btn = InlineKeyboardButton(EM_FAIL + " Забанить продавца", callback_data=f"admin_ban:{seller_id}")
    keyboard = [
        [InlineKeyboardButton(EM_OK  + " Снять жалобы (оставить)", callback_data=f"admin_dismiss_report:{ad_id}"),
         InlineKeyboardButton(EM_FAIL + " Удалить объявление",      callback_data=f"admin_delete_ad:{ad_id}")],
        [ban_btn],
        [InlineKeyboardButton(EM_ARROW_L + " К списку жалоб",        callback_data="admin_reports")],
    ]
    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)


async def admin_dismiss_report_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Снять все жалобы с объявления (объявление остаётся, жалобы dismissed)."""
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return
    ad_id = int(query.data.split(":")[1])
    ad    = db.get_ad(ad_id)
    # Восстанавливаем объявление если оно было скрыто жалобами
    cursor = db.conn.cursor()
    if ad and ad.get("status") in ("inactive", "hidden"):
        new_expires = (get_moscow_time() + timedelta(days=30)).isoformat()
        cursor.execute("UPDATE ads SET status='active', expires_at=? WHERE id=?", (new_expires, ad_id))
    db.dismiss_reports(ad_id)
    db.conn.commit()
    db.log_action(update.effective_user.id, "admin_dismiss_reports", f"Reports dismissed for ad #{ad_id}")
    await safe_edit_message(
        query,
        f"{EM_OK} Жалобы на объявление #{ad_id} сняты.",
        [[InlineKeyboardButton(EM_ARROW_L + " К списку жалоб", callback_data="admin_reports")]]
    )


