async def share_ad(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    ad_id = int(query.data.split(":")[1])
    ad = db.get_ad(ad_id)
    if not ad:
        await safe_answer(query, "Объявление не найдено", show_alert=True)
        return
    import urllib.parse as _up
    bot_username = (await context.bot.get_me()).username
    share_url = f"https://t.me/{bot_username}?start=ad_{ad_id}"
    share_text = f"{ad['title']} за {ad['price']} руб."
    tg_share = f"https://t.me/share/url?url={_up.quote(share_url, safe='')}&text={_up.quote(share_text, safe='')}"
    text = (
        f" Поделиться объявлением\n\n"
        f"{ad['title']}\n"
        f"{ad['price']} ₽\n\n"
        f"Прямая ссылка:\n{share_url}\n\n"
        f"Чем больше людей увидят — тем быстрее продадите!"
    )
    keyboard = [
        [InlineKeyboardButton(EM_ARROW_R + " Поделиться", url=tg_share)],
        [InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data=f"view_my_ad:{ad_id}")]
    ]
    await safe_edit_message(query, text, keyboard)

