async def verify_seller_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Запуск верификации по email"""
    query = update.callback_query
    await safe_answer(query, )
    user_id = update.effective_user.id

    existing = db.get_verification(user_id)
    if existing and existing['status'] == 'verified':
        expires_at = existing.get('expires_at')
        if expires_at:
            now = get_moscow_time().isoformat()
            if expires_at > now:
                await safe_edit_message(query,
                    f"{EM_OK} <b>Вы уже верифицированный продавец!</b>\nДействует до: {expires_at[:10]}\n\nЗначок {EM_OK} отображается на всех ваших объявлениях.",
                    [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
                return ConversationHandler.END
        else:
            await safe_edit_message(query,
                f"{EM_OK} <b>Вы уже верифицированный продавец!</b>\n\nЗначок {EM_OK} отображается на всех ваших объявлениях.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
            return ConversationHandler.END

    if existing and existing['status'] == 'pending':
        await safe_edit_message(query,
            f"{EM_DOT} <b>Заявка уже на рассмотрении</b>\n\nОтвет придёт в течение 24 часов.",
            [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
        return ConversationHandler.END

    await safe_edit_message(
        query,
        f"{EM_DOT} <b>Верификация профиля</b>\n\n"
        "Верификация подтверждает вашу личность через email.\n\n"
        f"{EM_OK} <b>Что даёт верификация:</b>\n"
        f"• Значок {EM_OK} на всех объявлениях и в профиле\n"
        "• Покупатели видят, что вы реальный человек\n"
        "• На 40% больше откликов на объявления\n"
        "• Больше доверия от покупателей\n\n"
        "Введите ваш <b>email</b> для получения кода верификации:",
        parse_mode=ParseMode.HTML
    )

    context.user_data['_awaiting_email'] = True
    await query.message.reply_text(
        "Введите ваш email:",
        reply_markup=ReplyKeyboardMarkup(
            [[KeyboardButton(f"{EM_FAIL} Отмена")]],
            resize_keyboard=True,
            one_time_keyboard=True
        )
    )
    return States.VERIFY_EMAIL_INPUT


async def verify_handle_email_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Обрабатывает ввод email и отправляет код"""
    user = update.effective_user
    email = update.message.text.strip().lower()

    await update.message.reply_text(
        f"{EM_DOT} Проверяем email...",
        reply_markup=ReplyKeyboardRemove()
    )

    if not re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email):
        await update.message.reply_text(
            f"{EM_FAIL} <b>Ошибка верификации</b>\n\n"
            "Некорректный формат email. Попробуйте снова.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]]),
            parse_mode=ParseMode.HTML
        )
        context.user_data.pop('_awaiting_email', None)
        return ConversationHandler.END

    code = generate_verification_code()

    try:
        cur = db.conn.cursor()
        cur.execute('SELECT verified FROM email_verify_codes WHERE email=?', (email,))
        row = cur.fetchone()
        if row and row['verified']:
            await update.message.reply_text(
                f"{EM_OK} Этот email уже верифицирован.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
            )
            context.user_data.pop('_awaiting_email', None)
            return ConversationHandler.END
    except Exception:
        pass

    sent = await send_verification_email(email, code)
    if not sent:
        context.user_data.pop('_awaiting_email', None)
        await update.message.reply_text(
            f"{EM_FAIL} <b>Ошибка отправки</b>\n\n"
            "Не удалось отправить код на указанный email.\n"
            "Проверьте адрес или попробуйте позже.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]]),
            parse_mode=ParseMode.HTML
        )
        return ConversationHandler.END

    db.save_email_code(user.id, email, code)
    context.user_data.pop('_awaiting_email', None)
    context.user_data['_awaiting_code'] = True
    context.user_data['_verify_email'] = email

    smtp_note = ""
    if not SMTP_USER or not SMTP_PASS:
        smtp_note = f"\n\n{EM_WARN} SMTP не настроен — код: <code>{code}</code>"

    await update.message.reply_text(
        f"{EM_OK} <b>Код отправлен!</b>\n\n"
        f"Код верификации отправлен на <b>{email}</b>.\n"
        f"Пожалуйста, проверьте почту и введите полученный код:{smtp_note}",
        reply_markup=ReplyKeyboardMarkup(
            [[KeyboardButton(f"{EM_FAIL} Отмена")]],
            resize_keyboard=True,
            one_time_keyboard=True
        ),
        parse_mode=ParseMode.HTML
    )
    return States.VERIFY_CODE_INPUT


async def verify_handle_cancel_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Пользователь нажал Отмена при вводе email или кода"""
    context.user_data.pop('_awaiting_email', None)
    context.user_data.pop('_awaiting_code', None)
    context.user_data.pop('_verify_email', None)
    db.delete_email_code(update.effective_user.id)
    await update.message.reply_text(
        "Верификация отменена.",
        reply_markup=ReplyKeyboardRemove()
    )
    return ConversationHandler.END


# Оставляем для обратной совместимости (старый flow через Telegram Contact не используется)
async def verify_handle_phone(update: Update, context: ContextTypes.DEFAULT_TYPE):
    return await verify_handle_cancel_text(update, context)


async def verify_handle_code(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Проверяет введённый код верификации"""
    user = update.effective_user
    code_entered = update.message.text.strip()

    record = db.get_email_code(user.id)
    if not record:
        context.user_data.pop('_awaiting_code', None)
        context.user_data.pop('_verify_email', None)
        await update.message.reply_text(
            f"{EM_FAIL} <b>Код не найден</b>\n\n"
            "Запросите новый код через верификацию в профиле.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]]),
            parse_mode=ParseMode.HTML
        )
        return ConversationHandler.END

    if record['code'] != code_entered:
        await update.message.reply_text(
            f"{EM_FAIL} <b>Неверный код</b>\n\n"
            "Попробуйте ещё раз или нажмите «Отмена».",
            parse_mode=ParseMode.HTML
        )
        return None

    email = context.user_data.get('_verify_email', record.get('email', ''))
    context.user_data.pop('_awaiting_code', None)
    context.user_data.pop('_verify_email', None)
    db.delete_email_code(user.id)

    db.request_verification(user.id, 'email')
    db.approve_verification(user.id, 0, expires_at=None)  # 0 = system auto

    await update.message.reply_text(
        f"{EM_OK} <b>Верификация пройдена!</b>\n\n"
        f"Поздравляем, {user.first_name}! Теперь вы — верифицированный продавец.\n\n"
        f"Подтверждённый email: {email}\n\n"
        f"{EM_OK} Значок появился на всех ваших объявлениях и в профиле\n"
        f"Покупатели видят, что вы надёжный продавец\n"
        f"Удачных сделок!",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]]),
        parse_mode=ParseMode.HTML
    )
    return ConversationHandler.END

async def admin_approve_verify(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return
    target_id = int(query.data.split(":")[1])
    
    # Получаем метод верификации чтобы знать ставить ли срок
    verify = db.get_verification(target_id)
    method = verify.get('method', '') if verify else ''
    
    expires_at = None
    if method == 'paid':
        # Платная верификация — 1 год
        expires_at = (get_moscow_time() + timedelta(days=365)).isoformat()
    
    db.approve_verification(target_id, update.effective_user.id, expires_at=expires_at)
    
    expires_str = f"\nДействует до: {expires_at[:10]}" if expires_at else ""
    try:
        await context.bot.send_message(chat_id=target_id,
            text=f" Вы верифицированный продавец! Значок {EM_OK} теперь на всех ваших объявлениях.{expires_str}")
    except Exception as _e:
        logger.debug(f"Ignored error: {_e}")
    await safe_edit_message(query, f"{EM_OK} Пользователь {target_id} верифицирован.")

async def admin_reject_verify(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return
    target_id = int(query.data.split(":")[1])
    cursor = db.conn.cursor()
    cursor.execute('UPDATE seller_verifications SET status="rejected" WHERE user_id=?', (target_id,))
    db.conn.commit()
    try:
        await context.bot.send_message(chat_id=target_id,
            text=f"{EM_FAIL} Верификация отклонена. Свяжитесь с поддержкой.")
    except Exception as _e:
        logger.debug(f"Ignored error: {_e}")
    await safe_edit_message(query, f"{EM_FAIL} Верификация {target_id} отклонена.")

