async def templates_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Меню выбора шаблона при создании объявления — сгруппировано по категориям"""
    query = update.callback_query
    await safe_answer(query, )

    # Группируем по категории для читаемого вида
    CATEGORY_ORDER = [
        f"{EM_DOT} Техника", f"{EM_DOT} Одежда", f"{EM_DOT} Обувь", f"{EM_DOT} Для дома",
        f"{EM_DOT} Игры / Хобби", f"{EM_DOT} Книги", f"{EM_DOT} Детские товары", f"{EM_DOT} Красота / Уход",
    ]
    grouped: dict = {cat: [] for cat in CATEGORY_ORDER}
    for key, tpl in AD_TEMPLATES.items():
        cat = tpl.get("category", f"{EM_DOT} Другое")
        if cat in grouped:
            grouped[cat].append((key, tpl["label"]))

    keyboard = []
    for cat in CATEGORY_ORDER:
        items = grouped.get(cat, [])
        if not items:
            continue
        # Заголовок категории (неактивная кнопка)
        keyboard.append([InlineKeyboardButton(f"── {cat} ──", callback_data="noop")])
        row = []
        for key, label in items:
            row.append(InlineKeyboardButton(label, callback_data=f"use_template:{key}"))
            if len(row) == 2:
                keyboard.append(row); row = []
        if row:
            keyboard.append(row)

    keyboard.append([InlineKeyboardButton(EM_DOT + " Без шаблона", callback_data="create_ad"),
                     InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")])
    await safe_edit_message(query,
        "Выберите шаблон объявления\n\nШаблон заполнит название и описание — вам останется только указать цену и фото:",
        keyboard
    )

async def use_template(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Применяем шаблон — сохраняем в user_data и запускаем создание объявления"""
    query = update.callback_query
    await safe_answer(query, )
    key = query.data.split(":", 1)[1]
    tpl = AD_TEMPLATES.get(key)
    if not tpl:
        await safe_answer(query, f"{EM_FAIL} Шаблон не найден", show_alert=True)
        return
    context.user_data['template_title'] = tpl['title']
    context.user_data['template_description'] = tpl['description']
    context.user_data['template_category'] = tpl['category']
    await safe_edit_message(query,
        f"{EM_OK} Шаблон «{tpl['label']}» выбран!\n\n"
        f"Название: {tpl['title']}\n"
        f"Категория: {tpl['category']}\n\n"
        f"Нажмите «Создать объявление» — поля будут предзаполнены. "
        f"Вам останется только добавить цену, фото и контакты.",
        [[InlineKeyboardButton("+ Создать объявление", callback_data="create_ad")],
         [InlineKeyboardButton(EM_ARROW_R + " Другой шаблон", callback_data="templates_menu")]]
    )

