# =====================================================================
#  РАСШИРЕННАЯ АНАЛИТИКА ДЛЯ АДМИНА
# =====================================================================

async def admin_advanced_analytics(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Аналитика закрепов и активности"""
    query = update.callback_query
    await safe_answer(query, )
    if not await is_admin(update.effective_user.id):
        return

    try:
        cur = db.conn.cursor()
        now_iso = get_moscow_time().isoformat()

        # Закрепы сейчас активные
        cur.execute("SELECT COUNT(*) FROM ads WHERE pinned_until IS NOT NULL AND pinned_until > ?", (now_iso,))
        active_pins = cur.fetchone()[0]

        # Всего закрепов продано
        cur.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM payments WHERE status IN ('confirmed','paid') AND service_type LIKE 'pin%'")
        row = cur.fetchone(); pin_count, pin_revenue = row[0], row[1]

        # Закрепы за последние 7 дней
        week_ago = (get_moscow_time() - timedelta(days=7)).isoformat()
        cur.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM payments WHERE status IN ('confirmed','paid') AND service_type LIKE 'pin%' AND created_at >= ?", (week_ago,))
        row = cur.fetchone(); pin_week, rev_week = row[0], row[1]

        # Закрепы за 30 дней
        month_ago = (get_moscow_time() - timedelta(days=30)).isoformat()
        cur.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM payments WHERE status IN ('confirmed','paid') AND service_type LIKE 'pin%' AND created_at >= ?", (month_ago,))
        row = cur.fetchone(); pin_month, rev_month = row[0], row[1]

        # Топ объявлений по просмотрам
        cur.execute("SELECT id, title, views_count FROM ads WHERE status='active' ORDER BY views_count DESC LIMIT 5")
        top_ads = cur.fetchall()

        # Новые пользователи за 7 дней
        cur.execute("SELECT COUNT(*) FROM users WHERE created_at >= ?", (week_ago,))
        new_users_week = cur.fetchone()[0]

        # Объявлений добавлено за 7 дней
        cur.execute("SELECT COUNT(*) FROM ads WHERE created_at >= ?", (week_ago,))
        new_ads_week = cur.fetchone()[0]

    except Exception as e:
        logger.error(f"admin_advanced_analytics DB error: {e}")
        await safe_edit_message(query, "Ошибка получения аналитики.",
            [[InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]])
        return

    text = f"<b>Аналитика</b>\n\n"

    text += (
        f"📌 <b>Закрепы</b>\n"
        f" • Активных сейчас: <b>{active_pins}</b>\n"
        f" • За 7 дней: {pin_week} шт. / <b>{rev_week} ₽</b>\n"
        f" • За 30 дней: {pin_month} шт. / <b>{rev_month} ₽</b>\n"
        f" • Всего продано: {pin_count} шт. / <b>{pin_revenue} ₽</b>\n\n"
        f"📋 <b>За 7 дней</b>\n"
        f" • Новых пользователей: {new_users_week}\n"
        f" • Новых объявлений: {new_ads_week}\n\n"
    )

    if top_ads:
        text += "🔥 <b>Топ по просмотрам</b>\n"
        for i, row in enumerate(top_ads, 1):
            ad_id, title, views = row
            short = title[:30] + ("…" if len(title) > 30 else "")
            # Реальные просмотры постов каналов (TG web + MAX)
            try:
                ad = db.get_ad(ad_id)
                if ad:
                    live = await get_live_channel_views(ad)
                    live_sum = (live.get('tg') or 0) + (live.get('max') or 0)
                    if live_sum > (views or 0):
                        views = live_sum
            except Exception as e:
                logger.warning(f"admin top live views ad {ad_id}: {e}")
            text += f" {i}. {short} — {views or 0} просм.\n"

    keyboard = [
        [InlineKeyboardButton(EM_REFRESH + " Обновить", callback_data="admin_advanced_analytics")],
        [InlineKeyboardButton(EM_ARROW_L + " Панель", callback_data="admin_panel")]
    ]

    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)

# =====================================================================
#  АНОНИМНЫЙ ЧАТ (мост через бота)
# =====================================================================

async def init_chat_tables():
    cursor = db.conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS chat_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ad_id INTEGER NOT NULL,
            buyer_id INTEGER NOT NULL,
            seller_id INTEGER NOT NULL,
            status TEXT DEFAULT 'active',
            created_at TEXT,
            last_message_at TEXT,
            UNIQUE(ad_id, buyer_id)
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS chat_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id INTEGER NOT NULL,
            sender_id INTEGER NOT NULL,
            text TEXT,
            file_id TEXT,
            msg_type TEXT DEFAULT 'text',
            created_at TEXT
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS message_relay (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            message_id INTEGER NOT NULL,
            session_id INTEGER NOT NULL,
            recipient_id INTEGER NOT NULL,
            target_platform TEXT NOT NULL,
            delivered INTEGER DEFAULT 0,
            created_at TEXT
        )
    ''')

    # Миграция: users.anon_id — раньше эта колонка нигде не создавалась и не
    # заполнялась (только читалась в SELECT для списка "Мои диалоги"), из-за
    # чего у части пользователей вместо анонимного кода (вроде "MKSNRT")
    # показывались "??????". Добавляем колонку, если её ещё нет — сам код
    # генерируется лениво через ensure_anon_id() при первой необходимости.
    cursor.execute("PRAGMA table_info(users)")
    _users_cols = {r["name"] for r in cursor.fetchall()}
    if "anon_id" not in _users_cols:
        try:
            cursor.execute("ALTER TABLE users ADD COLUMN anon_id TEXT DEFAULT NULL")
        except Exception as _e:
            logger.error(f"Миграция users.anon_id: {_e}")

    # Миграция: отметки "прочитано" по каждой стороне диалога — раньше в
    # списке "Мои диалоги" не было никакого способа понять, есть ли в чате
    # непрочитанные сообщения, кроме как открыть каждый диалог по очереди.
    cursor.execute("PRAGMA table_info(chat_sessions)")
    _cs_cols = {r["name"] for r in cursor.fetchall()}
    for _col in ("buyer_last_read", "seller_last_read"):
        if _col not in _cs_cols:
            try:
                cursor.execute(f"ALTER TABLE chat_sessions ADD COLUMN {_col} TEXT DEFAULT NULL")
            except Exception as _e:
                logger.error(f"Миграция chat_sessions.{_col}: {_e}")

    db.conn.commit()


