def moderate_story(story_id: int, status: str, admin_id: int, reason: str = '') -> Optional[Dict]:
    """Одобряет или отклоняет историю.

    При одобрении срок жизни отсчитывается от ЭТОГО момента — автор
    получает полные 24 часа, а не остаток от ожидания в очереди.
    """
    cursor = db.conn.cursor()
    now = get_moscow_time()
    expires = (now + timedelta(hours=STORY_TTL_HOURS)).isoformat() if status == 'active' else None
    cursor.execute('''
        UPDATE stories SET status=?, reject_reason=?, moderated_at=?, moderated_by=?, expires_at=?
        WHERE id=?
    ''', (status, (reason or '')[:200], now.isoformat(), admin_id, expires, story_id))
    db.conn.commit()
    return get_story(story_id)


def expire_stories() -> Dict[str, int]:
    """Чистка: гасим просроченные, снимаем зависшие в модерации, чистим архив.

    Файлы удаляем здесь же, иначе папка загрузок растёт бесконечно.
    """
    cursor = db.conn.cursor()
    now = get_moscow_time()
    result = {'expired': 0, 'stale_pending': 0, 'purged': 0}

    cursor.execute("SELECT id, media FROM stories WHERE status='active' AND expires_at IS NOT NULL AND expires_at <= ?",
                   (now.isoformat(),))
    for row in cursor.fetchall():
        _remove_story_file(row['media'])
        result['expired'] += 1
    cursor.execute("UPDATE stories SET status='expired' WHERE status='active' AND expires_at IS NOT NULL AND expires_at <= ?",
                   (now.isoformat(),))

    stale_before = (now - timedelta(hours=STORY_PENDING_TTL_HOURS)).isoformat()
    cursor.execute("SELECT id, media FROM stories WHERE status='pending' AND created_at <= ?", (stale_before,))
    for row in cursor.fetchall():
        _remove_story_file(row['media'])
        result['stale_pending'] += 1
    cursor.execute("UPDATE stories SET status='rejected', reject_reason='истекла на модерации' "
                   "WHERE status='pending' AND created_at <= ?", (stale_before,))

    # Архив: реджекты и просроченные старше 30 дней — удаляем вместе с файлами
    old_before = (now - timedelta(days=30)).isoformat()
    cursor.execute("SELECT id, media FROM stories WHERE status IN ('rejected','expired') AND created_at <= ?",
                   (old_before,))
    for row in cursor.fetchall():
        _remove_story_file(row['media'])
        result['purged'] += 1
    cursor.execute("DELETE FROM story_views WHERE story_id IN "
                   "(SELECT id FROM stories WHERE status IN ('rejected','expired') AND created_at <= ?)",
                   (old_before,))
    cursor.execute("DELETE FROM stories WHERE status IN ('rejected','expired') AND created_at <= ?", (old_before,))
    db.conn.commit()
    return result


def _row_get(row, key, default=0):
    """Достаёт поле из sqlite3.Row без падений.

    У sqlite3.Row НЕТ метода .get(), и вызов row.get('n', 0) бросал
    AttributeError. Из-за этого счётчики статистики отдавали ошибку, а
    профиль ВСЕГДА показывал нули в объявлениях и избранном.
    """
    if row is None:
        return default
    try:
        value = row[key]
    except Exception:
        return default
    return default if value is None else value


def _prepare_upload_dir() -> str:
    """Готовит папку загрузок на ПОСТОЯННОМ томе.

    Было /app/uploads — эфемерная папка контейнера: при каждом деплое все фото
    объявлений и историй пропадали, и у всех, кроме автора (у него файлы
    оставались в кеше браузера), картинки превращались в «?».
    Постоянный том Amvera смонтирован в /data — там же лежит база.
    """
    upload_dir = os.environ.get('UPLOAD_DIR', '/data/uploads')
    try:
        os.makedirs(upload_dir, exist_ok=True)
    except Exception as e:
        logger.error(f"upload dir create {upload_dir}: {e}")
    # Если контейнер всё же сохранил старое — переносим файлы, чтобы не терять
    legacy = '/app/uploads'
    try:
        if os.path.isdir(legacy) and os.path.abspath(legacy) != os.path.abspath(upload_dir):
            moved = 0
            for name in os.listdir(legacy):
                src = os.path.join(legacy, name)
                dst = os.path.join(upload_dir, name)
                if os.path.isfile(src) and not os.path.exists(dst):
                    import shutil
                    shutil.copy2(src, dst)
                    moved += 1
            if moved:
                logger.info(f"upload dir: перенесено {moved} файлов из {legacy}")
    except Exception as e:
        logger.warning(f"upload dir migrate: {e}")
    return upload_dir


# ── Агрегатор находок: приём извне, дедупликация, оценка скидки ──────────────
FINDING_SOURCES = ('avito', 'yula', 'vk', 'telegram', 'other')
# Внешние находки живут столько же, сколько обычное объявление
FINDING_TTL_DAYS = 14


def recompute_market_medians(category: Optional[str] = None) -> int:
    """Пересчитывает медиану цены по категориям и скидку для находок.

    Медиана считается по ВСЕМ активным объявлениям категории (и находкам,
    и своим) — именно это даёт честную картину рынка. Без неё «скидка»
    была бы выдумкой.
    """
    cursor = db.conn.cursor()
    where = ("status='active' AND price > 0 AND category IS NOT NULL AND category <> ''")
    params: tuple = ()
    if category:
        where += " AND category = ?"
        params = (category,)
    try:
        cursor.execute(f"SELECT category, price FROM ads WHERE {where} ORDER BY category, price", params)
        rows = cursor.fetchall()
    except Exception as e:
        logger.error(f"median read: {e}")
        return 0
    if not rows:
        return 0

    grouped: Dict[str, List[int]] = {}
    for r in rows:
        grouped.setdefault(r['category'], []).append(int(r['price'] or 0))

    updated = 0
    for cat, prices in grouped.items():
        prices = [p for p in prices if p > 0]
        if len(prices) < 3:
            continue  # на двух объявлениях медиана бессмысленна
        mid = len(prices) // 2
        median = prices[mid] if len(prices) % 2 else (prices[mid - 1] + prices[mid]) // 2
        if median <= 0:
            continue
        try:
            cursor.execute("UPDATE ads SET market_median=? WHERE category=? AND status='active'",
                           (median, cat))
            cursor.execute('''
                UPDATE ads SET discount_percent =
                  CASE WHEN price > 0 AND price < ?
                       THEN CAST(ROUND((? - price) * 100.0 / ?) AS INTEGER)
                       ELSE NULL END
                WHERE category=? AND status='active'
            ''', (median, median, median, cat))
            updated += 1
        except Exception as e:
            logger.warning(f"median update {cat}: {e}")
    try:
        db.conn.commit()
    except Exception:
        pass
    logger.info(f"market medians: обновлено категорий {updated}")
    return updated


def ingest_findings(items: List[Dict], source: str) -> Dict:
    """Принимает находки от сборщика: дедуп, вставка, пересчёт скидок.

    Храним только публичное: заголовок, цена, город, категория, фото, ссылка.
    Никаких имён и телефонов — и по закону о персональных данных, и по совести.
    """
    if source not in FINDING_SOURCES:
        source = 'other'
    cursor = db.conn.cursor()
    now = get_moscow_time().isoformat()
    stats = {'accepted': 0, 'duplicate': 0, 'skipped': 0, 'ids': []}

    for raw in (items or [])[:500]:
        if not isinstance(raw, dict):
            stats['skipped'] += 1
            continue
        title = str(raw.get('title') or '').strip()[:200]
        url = str(raw.get('url') or '').strip()[:500]
        ext = str(raw.get('external_id') or '').strip()[:64]
        city = str(raw.get('city') or '').strip()[:100]
        cat = _miniapp_display_category(str(raw.get('category') or '').strip()[:100])
        try:
            price = int(raw.get('price') or 0)
        except (TypeError, ValueError):
            price = 0
        photos = raw.get('photos') or []
        if isinstance(photos, list):
            photos = [str(p) for p in photos if isinstance(p, str) and p.startswith('http')][:5]
        else:
            photos = []
        if not title or price <= 0 or not url.startswith('http'):
            stats['skipped'] += 1
            continue
        if not ext:
            # Идентификатор не прислали — сделаем из ссылки, чтобы дедуп работал
            ext = hashlib.md5(url.encode()).hexdigest()[:32]

        try:
            cursor.execute("SELECT id FROM ads WHERE source=? AND external_id=?", (source, ext))
            if cursor.fetchone():
                stats['duplicate'] += 1
                continue
            # Второй рубеж: тот же заголовок и цена в том же городе
            cursor.execute("SELECT id FROM ads WHERE source=? AND title=? AND price=? AND city=?",
                           (source, title, price, city))
            if cursor.fetchone():
                stats['duplicate'] += 1
                continue
            try:
                ago = int(raw.get('hours_ago')) if raw.get('hours_ago') is not None else None
            except (TypeError, ValueError):
                ago = None
            cursor.execute('''
                INSERT INTO ads (user_id, title, description, price, photos, category, city,
                                 status, created_at, published_at, source, source_url,
                                 external_id, parsed_at, sale_type, views, published_hours_ago,
                                 title_lower)
                VALUES (0, ?, '', ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, 'sale', 0, ?, ?)
            ''', (title, price, json.dumps(photos, ensure_ascii=False), cat, city,
                  now, now, source, url, ext, now, ago, title.lower()))
            stats['accepted'] += 1
            stats['ids'].append(cursor.lastrowid)
        except Exception as e:
            logger.warning(f"ingest item: {e}")
            stats['skipped'] += 1
    try:
        db.conn.commit()
    except Exception:
        pass
    if stats['accepted']:
        recompute_market_medians()
        # Медианы критериев пересчитываем ДО рассылки: иначе скидка
        # считалась бы по устаревшей выборке
        recompute_criterion_medians()
    return stats


async def api_ingest_findings(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/ingest — приём находок от сборщика (запускается у вас локально).

    Сбор идёт с домашнего IP, а не с сервера: Авито блокирует адреса
    дата-центров, и при блокировке лёг бы весь сервис вместе с ботом.
    """
    expected = os.environ.get('INGEST_TOKEN', '')
    if not expected:
        return _miniapp_err('ingest_disabled', 503)
    got = request.headers.get('X-Ingest-Token', '') or request.query.get('token', '')
    if not hmac.compare_digest(str(got), str(expected)):
        return _miniapp_err('forbidden', 403)
    try:
        body = await request.json()
    except Exception:
        return _miniapp_err('bad_json', 400)
    source = str((body or {}).get('source') or 'other').lower()
    items = (body or {}).get('items') or []
    if not isinstance(items, list):
        return _miniapp_err('bad_items', 400)
    stats = ingest_findings(items, source)
    _touch_collector(source)
    logger.info(f"ingest {source}: принято {stats['accepted']}, "
                f"дублей {stats['duplicate']}, пропущено {stats['skipped']}")
    # Рассылка уходит в ФОН. Раньше она выполнялась прямо в обработчике
    # запроса: при отправке 300 находок сервер прогонял тысячи запросов к
    # базе, и всё это время приложение не могло получить ответ — висело на
    # загрузке. Теперь отвечаем сразу, а рассылка идёт параллельно.
    pushed = 0
    if stats['accepted']:
        try:
            asyncio.create_task(notify_hunt_matches(stats.get('ids') or []))
        except Exception as e:
            logger.warning(f"hunt notify start: {e}")
    return _miniapp_json({'ok': True, 'source': source, 'pushed': pushed, **stats})


async def api_findings_stats(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/findings/stats — что собралось, по источникам и категориям."""
    cursor = db.conn.cursor()
    try:
        cursor.execute('''
            SELECT source, COUNT(*) AS total,
                   SUM(CASE WHEN discount_percent >= 20 THEN 1 ELSE 0 END) AS deals
            FROM ads WHERE status='active' AND source <> 'polka'
            GROUP BY source ORDER BY total DESC
        ''')
        by_source = [dict(r) for r in cursor.fetchall()]
        cursor.execute('''
            SELECT category, market_median, COUNT(*) AS total
            FROM ads WHERE status='active' AND market_median IS NOT NULL
            GROUP BY category ORDER BY total DESC LIMIT 20
        ''')
        by_category = [dict(r) for r in cursor.fetchall()]
        cursor.execute("SELECT COUNT(*) AS n FROM ads WHERE status='active' AND source <> 'polka'")
        total = _row_get(cursor.fetchone(), 'n', 0)
    except Exception as e:
        logger.error(f"findings stats: {e}")
        return _miniapp_err('load_failed', 500)
    return _miniapp_json({'total': total, 'by_source': by_source, 'by_category': by_category})


