def query_word_variants(word: str) -> tuple:
    """Все написания слова: и латиницей, и кириллицей.

    Возвращает кортеж, чтобы порядок был предсказуемым в тестах.
    """
    key = str(word or '').strip().lower()
    if not key or len(key) < 2:
        return ()
    variants = QUERY_SYNONYMS.get(key)
    if not variants:
        return (key,)
    # Само слово тоже оставляем: «айфон 13» должно находить и «айфон 13»
    return tuple(dict.fromkeys((key,) + tuple(variants)))


def _query_words_required(query: str) -> list:
    """Какие слова запроса обязательны, а какие — просто уточнение.

    Раньше требовались ВСЕ слова. Из-за этого критерий вида «Ботинки зимние
    Salomon 39 размер» не находил НИКОГДА: на Авито не бывает заголовков,
    где есть все пять слов сразу. Человек вводил запрос и получал тишину.

    Обязательными оставляем самые различающие слова: самое длинное (обычно
    бренд — «salomon», «iphone») и первое с цифрами (обычно модель или
    размер). Остальные слова считаются уточнением и не мешают.
    """
    words = [w for w in re.split(r'\s+', str(query or '').lower())
             if len(w) >= 2 and w not in HUNT_STOP_WORDS]
    if not words:
        return []
    # Бренд важнее длинного слова: в «Ботинки зимние Salomon 39 размер»
    # самое длинное — «ботинки», но различает товар именно «salomon».
    # Бренды почти всегда латиницей, поэтому её и предпочитаем.
    def is_brand(word: str) -> bool:
        letters = [c for c in word if c.isalpha()]
        if not letters:
            return False
        ascii_letters = [c for c in letters if c.isascii()]
        return len(ascii_letters) >= len(letters) * 0.7

    brands = [w for w in words if is_brand(w)]
    base = brands[0] if brands else max(words, key=len)
    required = [base]
    for w in words:
        if any(ch.isdigit() for ch in w) and w != base:
            required.append(w)
            break
    return required


def _criterion_where(crit: Dict, active_only: bool = True):
    """SQL-условие отбора под критерий.

    Каждое слово запроса должно быть в заголовке: так «iphone 13» не поймает
    «iphone 14», а «13 pro» найдёт нужную модель.

    active_only=False нужен для статистики по УЖЕ проданным лотам: у них
    status='sold', и с фильтром «только активные» выборка всегда пустая —
    из-за этого срок оборота не считался вовсе.
    """
    where = ["price > 0"]
    if active_only:
        where.insert(0, "status='active'")
    params: List = []
    if crit.get('category'):
        where.append("category LIKE ?")
        params.append(f"%{crit['category']}%")
    if crit.get('city'):
        where.append("city = ?")
        params.append(crit['city'])
    max_price = int(crit.get('max_price') or 0)
    if max_price > 0:
        where.append("price <= ?")
        params.append(max_price)
    for word in _query_words_required(crit.get('query')):
        variants = query_word_variants(word)
        if not variants:
            continue
        # Слово засчитывается в ЛЮБОМ написании: айфон / iphone
        where.append("(" + " OR ".join("COALESCE(title_lower, title) LIKE ?" for _ in variants) + ")")
        params.extend(f"%{v}%" for v in variants)
    # Аксессуары не участвуют и в медиане. Иначе по критерию «Айфон» медиана
    # считалась вместе с кабелями и чехлами (5 000 ₽), настоящие телефоны за
    # 40 000 ₽ отсекались как «дорогие», а кабель за 490 ₽ выглядел находкой.
    for bad in HUNT_ACCESSORY_WORDS:
        where.append("COALESCE(title_lower, title) NOT LIKE ?")
        params.append(f"%{bad}%")
    return ' AND '.join(where), params


def recompute_criterion_medians() -> int:
    """Медиана цены ПО КАЖДОМУ КРИТЕРИЮ.

    Медиана по категории для перекупа бесполезна: если критерий «iPhone 13»,
    то цена наушников и кабелей из той же категории ничего не говорит.
    """
    cursor = db.conn.cursor()
    try:
        cursor.execute("SELECT * FROM hunt_criteria WHERE active=1")
        crits = [dict(r) for r in cursor.fetchall()]
    except Exception as e:
        logger.error(f"criteria read: {e}")
        return 0
    updated = 0
    for crit in crits:
        where, params = _criterion_where(crit)
        try:
            cursor.execute(f"SELECT price FROM ads WHERE {where} ORDER BY price", params)
            prices = [int(r['price']) for r in cursor.fetchall() if r['price']]
        except Exception:
            continue
        if len(prices) < HUNT_MIN_SAMPLE:
            # На трёх объявлениях медиана — гадание. Лучше промолчать, чем
            # прислать перекупу выдуманную «скидку 60%».
            cursor.execute("UPDATE hunt_criteria SET median_price=NULL, sample_size=? WHERE id=?",
                           (len(prices), crit['id']))
            continue
        mid = len(prices) // 2
        median = prices[mid] if len(prices) % 2 else (prices[mid - 1] + prices[mid]) // 2
        cursor.execute("UPDATE hunt_criteria SET median_price=?, sample_size=? WHERE id=?",
                       (median, len(prices), crit['id']))
        updated += 1
    try:
        db.conn.commit()
    except Exception:
        pass
    return updated


# Слова, которые не описывают товар: по ним сравнивать бессмысленно
HUNT_STOP_WORDS = (
    'для', 'и', 'в', 'на', 'с', 'от', 'до', 'по', 'или', 'the', 'and', 'new',
    'новый', 'новая', 'новое', 'новые', 'оригинал', 'оригинальный', 'срочно',
    'продам', 'продаю', 'отдам', 'недорого', 'дешево', 'дёшево', 'торг',
    'состояние', 'отличное', 'хорошее', 'идеальное', 'рабочий', 'рабочая',
    'б/у', 'бу', 'шт', 'штук', 'комплект', 'подарок', 'вместе', 'только',
    'есть', 'можно', 'очень', 'самый', 'весь', 'все', 'опт', 'розница',
)


def _criterion_words(crit: Dict) -> set:
    """Слова самого критерия — они не описывают вид товара."""
    out = set()
    for w in re.split(r'\s+', str(crit.get('query') or '').lower()):
        out.update(query_word_variants(w))
    return out


def ad_key_words(title: str, crit: Dict = None, limit: int = 2) -> list:
    """Значимые слова товара: «iphone», «13» у «iPhone 13 128Gb».

    Одно слово слишком грубо: по «128gb» в выборку лезут любые телефоны с
    таким объёмом. Два слова дают бренд с моделью — рынок становится
    честным, и с ним можно сравнивать цену.
    """
    skip = _criterion_words(crit or {})
    words = []
    for raw in re.split(r'[^0-9a-zA-Zа-яёА-ЯЁ]+', str(title or '').lower()):
        w = raw.strip()
        if len(w) < 2 or w in skip or w in HUNT_STOP_WORDS:
            continue
        if w.isdigit() and len(w) < 2:
            continue
        words.append(w)
    # Длинные слова важнее («повербанк» > «для»), числа — это модель
    words.sort(key=lambda w: (-len(w), w))
    picked = []
    for w in words:
        if w not in picked:
            picked.append(w)
        if len(picked) >= limit:
            break
    return picked


def ad_key_word(title: str, crit: Dict = None) -> str:
    """Одно главное слово — оставлено для совместимости."""
    words = ad_key_words(title, crit, limit=1)
    return words[0] if words else ''


def median_for_ad(ad: Dict, crit: Dict = None, min_samples: int = 5) -> Optional[int]:
    """Медиана цен по ТАКИМ ЖЕ товарам. Сравниваем повербанк с повербанками.

    Сначала пробуем самое точное совпадение — по двум значимым словам
    (бренд + модель). Если таких мало, ослабляем до одного слова. Если и
    этого мало — возвращаем None: лучше промолчать, чем назвать
    выдуманный рынок, как было с повербанком за 1750 ₽ и «рынком 3500 ₽».

    Порог — ПЯТЬ объявлений: на трёх цифрах медиана случайна, и в первый
    момент, когда она появляется, бот принял бы за выгоду случайность.
    """
    title = ad.get('title') or ''
    cursor = db.conn.cursor()
    words = ad_key_words(title, crit, limit=2)
    if not words:
        return None
    # От точного к грубому: [w1+w2] -> [w1] -> [w2]
    attempts = [words]
    for w in words:
        attempts.append([w])
    for attempt in attempts:
        conds = " AND ".join("COALESCE(title_lower, title) LIKE ?" for _ in attempt)
        try:
            cursor.execute(
                f"SELECT price FROM ads WHERE status='active' AND price > 0 "
                f"AND {conds} AND id <> ? ORDER BY price",
                tuple(f"%{w}%" for w in attempt) + (ad.get('id') or 0,))
            prices = [int(r['price']) for r in cursor.fetchall() if r['price']]
        except Exception:
            return None
        if len(prices) >= min_samples:
            mid = len(prices) // 2
            return prices[mid] if len(prices) % 2 else (prices[mid - 1] + prices[mid]) // 2
    return None


def match_findings_for_user(crit: Dict, ad: Dict) -> Optional[int]:
    """Подходит ли находка под критерий. Возвращает скидку в % (0 = без скидки).

    Режим 'any' работает СРАЗУ, без накопленной статистики: иначе человек
    создаёт критерий, ждёт и не получает ничего, не понимая почему.
    """
    median = int(crit.get('median_price') or 0)
    price = int(ad.get('price') or 0)
    if price <= 0:
        return None
    max_price = int(crit.get('max_price') or 0)
    if max_price and price > max_price:
        return None
    title = str(ad.get('title') or '').lower()
    for word in _query_words_required(crit.get('query')):
        variants = query_word_variants(word)
        if not variants:
            continue
        if not any(v in title for v in variants):
            return None
    if crit.get('category') and str(crit['category']).lower() not in str(ad.get('category') or '').lower():
        return None
    if crit.get('city') and str(crit['city']) != str(ad.get('city') or ''):
        return None

    # Аксессуары и мусор отсекаем: «кабель для iPhone» — не айфон
    low_title = str(ad.get('title') or '').lower()
    for bad in HUNT_ACCESSORY_WORDS:
        if bad in low_title:
            return None
    # Цена в разы ниже медианы — это не выгода, а другая категория товара
    if median and price < median * HUNT_MIN_PRICE_SHARE:
        return None

    if (crit.get('mode') or 'any') == 'any':
        # Рынка не знаем — шлём: иначе будет тишина, а человек ждёт.
        if not median:
            return 0
        if price >= median:
            return None
        discount = int(round((median - price) * 100.0 / median))
        # Даже в «любых» нужна осмысленная выгода: минус 2% — не находка
        if discount < HUNT_MIN_DISCOUNT:
            return None
        return discount

    if not median or price >= median:
        return None
    discount = int(round((median - price) * 100.0 / median))
    if discount < int(crit.get('min_discount') or 15):
        return None
    return discount


async def _send_hunt_digest(crit: Dict, items: list) -> int:
    """Одна сводка вместо потока, когда находок слишком много.

    items: список (ad, crit, discount), уже отфильтрованный.
    """
    app = _get_bot_app()
    if not app:
        return 0
    user_id = int(crit['user_id'])
    fresh = []
    for ad, _c, discount in items:
        ago = ad.get('published_hours_ago')
        if ago is not None and int(ago) > HUNT_FRESH_HOURS:
            continue
        if ago is None and not HUNT_ALLOW_UNDATED:
            continue
        try:
            if db.is_search_notification_sent(user_id, ad['id']):
                continue
        except Exception:
            pass
        fresh.append((ad, discount))
    if not fresh:
        return 0
    # Лучшие — наверх: сначала самая большая выгода
    fresh.sort(key=lambda x: -x[1])
    top = fresh[:10]
    lines = [f"🔥 <b>Нашлось {len(fresh)} вариантов — «{crit.get('query')}»</b>", ""]
    for ad, discount in top:
        lines.append(f"• <b>{_money(ad['price'])} ₽</b> (−{discount}%) — "
                     f"{str(ad.get('title'))[:44]}")
    if len(fresh) > len(top):
        lines.append("")
        lines.append(f"…и ещё {len(fresh) - len(top)}. Все — в приложении.")
    lines.append("")
    lines.append("Открыть можно в приложении: Главная → Находки.")
    try:
        await app.bot.send_message(chat_id=user_id, text="\n".join(lines),
                                   parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.warning(f"hunt digest -> {user_id}: {e}")
        return 0
    # Помечаем все отправленные, чтобы не слать их повторно поштучно
    for ad, _d in fresh:
        try:
            db.mark_search_notification_sent(user_id, ad['id'])
        except Exception:
            pass
    return 1


async def notify_hunt_matches(ad_ids: List[int]):
    """Рассылает находки тем, чьи критерии они удовлетворяют.

    Использует готовые таблицы проекта: search_notifications_sent не даёт
    отправить одно и то же дважды.
    """
    if not ad_ids:
        return 0
    app = _get_bot_app()
    if not app:
        return 0
    cursor = db.conn.cursor()
    try:
        cursor.execute("SELECT * FROM hunt_criteria WHERE active=1")
        crits = [dict(r) for r in cursor.fetchall()]
    except Exception:
        return 0
    sent = 0
    # Ограничиваем объём: если пришло 300 находок, проверять все дорого,
    # а старые всё равно не нужны — свежие важнее.
    ad_ids = list(ad_ids)[:200]
    matched: Dict[int, list] = {}
    for ad_id in ad_ids:
        ad = db.get_ad(ad_id)
        if not ad or int(ad.get('price') or 0) <= 0:
            continue
        for crit in crits:
            discount = match_findings_for_user(crit, ad)
            if discount is not None:
                matched.setdefault(int(crit['id']), []).append((ad, crit, discount))
    for crit in crits:
        items = matched.get(int(crit['id'])) or []
        if len(items) > HUNT_DIGEST_AFTER:
            sent += await _send_hunt_digest(crit, items)
            continue
        for ad, crit, discount in items:
            user_id = int(crit['user_id'])
            try:
                if db.is_search_notification_sent(user_id, ad['id']):
                    continue
            except Exception:
                pass
            # Несвежее не присылаем: недельное объявление — не находка.
            # НО: если даты нет вовсе — присылаем. Проверено на живой выдаче
            # Авито: дату не проставляет БОЛЬШИНСТВО карточек (52 из 76), и
            # прежнее правило «нет даты — молчим» приводило к полной тишине.
            # От повторов защищает дедупликация, поэтому риск невелик.
            ago = ad.get('published_hours_ago')
            if ago is not None and int(ago) > HUNT_FRESH_HOURS:
                continue
            if ago is None:
                if not HUNT_ALLOW_UNDATED:
                    continue  # человек просил только подтверждённо свежее
                fresh = "дата не указана"
            else:
                hours = int(ago)
                fresh = "только что" if hours == 0 else f"{hours} ч назад"
            # Показываем просто цену и разницу с рынком. Никаких «наваров»,
            # «окупаемостей» и комиссий: человеку нужна цена, а не расчёты.
            # Рынок считаем по ТАКИМ ЖЕ товарам: повербанк с повербанками.
            # Если похожих мало — не выдумываем цифру, а молчим.
            median = median_for_ad(ad, crit)
            if not median or median <= int(ad['price']):
                continue
            diff = median - int(ad['price'])
            lines = [
                "🔥 <b>Новое объявление дешевле рынка</b>",
                "",
                f"<b>{str(ad.get('title'))[:70]}</b>",
                "",
                f"Цена: <b>{_money(ad['price'])} ₽</b>",
                f"Обычная цена: {_money(median)} ₽",
                f"Дешевле на <b>{_money(diff)} ₽</b> ({int(round(diff * 100.0 / median))}%)",
                "",
            ]
            lines.append(f"{ad.get('city') or ''} · опубликовано {fresh}")
            text = "\n".join(lines)
            kb = None
            if ad.get('source_url'):
                kb = InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_R + " Открыть на сайте",
                                         url=str(ad['source_url']))
                ]])
            try:
                await app.bot.send_message(chat_id=user_id, text=text,
                                           parse_mode=ParseMode.HTML, reply_markup=kb)
                try:
                    db.mark_search_notification_sent(user_id, ad['id'])
                except Exception:
                    pass
                sent += 1
            except Exception as e:
                logger.warning(f"hunt push -> {user_id}: {e}")
    if sent:
        try:
            cursor.execute("UPDATE hunt_criteria SET last_pushed_at=? WHERE active=1",
                           (get_moscow_time().isoformat(),))
            db.conn.commit()
        except Exception:
            pass
    return sent


def mark_listing_state(source: str, external_id: str, state: str) -> Optional[Dict]:
    """Обновляет судьбу лота: жив, пропал или продан.

    Авито не отдаёт «продано» в выдаче — узнаём повторной проверкой страницы.
    Отсюда считается, сколько лот провисел: «ушло за 3 часа» и есть ответ
    на вопрос перекупа «за сколько покупать».
    """
    cursor = db.conn.cursor()
    cursor.execute("SELECT * FROM ads WHERE source=? AND external_id=?", (source, external_id))
    row = cursor.fetchone()
    if not row:
        return None
    ad = dict(row)
    now = get_moscow_time().isoformat()
    if state == 'active':
        cursor.execute("UPDATE ads SET listing_state='active', last_seen_at=? WHERE id=?",
                       (now, ad['id']))
        db.conn.commit()
        return ad
    # Исчез: продано или снято — различить нельзя, сохраняем как сообщил сборщик
    hours = _hours_since(ad.get('parsed_at') or ad.get('created_at')) or 0
    cursor.execute("UPDATE ads SET listing_state=?, sold_at=?, sold_after_hours=?, "
                   "status='sold' WHERE id=?", (state, now, hours, ad['id']))
    db.conn.commit()
    ad['listing_state'] = state
    ad['sold_after_hours'] = hours
    return ad


async def api_ingest_status(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/ingest/status — сборщик сообщает судьбу лотов.

    Тело: {"source": "avito", "items": [{"external_id": "...", "state": "gone"}]}
    """
    expected = os.environ.get('INGEST_TOKEN', '')
    if not expected:
        return _miniapp_err('ingest_disabled', 503)
    got = request.headers.get('X-Ingest-Token', '') or request.query.get('token', '')
    if not hmac.compare_digest(str(got), str(expected)):
        return _miniapp_err('forbidden', 403)
    try:
        body = await request.json()
    except Exception:
        return _miniapp_err('bad_json', 400)
    source = str((body or {}).get('source') or 'other').lower()
    items = (body or {}).get('items') or []
    updated = gone = 0
    for item in (items if isinstance(items, list) else []):
        if not isinstance(item, dict):
            continue
        ext = str(item.get('external_id') or '').strip()
        state = str(item.get('state') or 'active')
        if not ext or state not in ('active', 'gone', 'sold'):
            continue
        try:
            result = mark_listing_state(source, ext, state)
        except Exception as e:
            logger.warning(f"listing state {ext}: {e}")
            continue
        if result:
            updated += 1
            if state != 'active':
                gone += 1
    _touch_collector(source)
    logger.info(f"ingest status {source}: обновлено {updated}, исчезло {gone}")
    return _miniapp_json({'ok': True, 'updated': updated, 'gone': gone})


# ── API критериев перекупа ───────────────────────────────────────────────────
def _criterion_public(crit: Dict) -> Dict:
    return {
        'id': crit.get('id'),
        'query': crit.get('query') or '',
        'category': crit.get('category') or '',
        'city': crit.get('city') or '',
        'max_price': crit.get('max_price') or 0,
        'min_discount': crit.get('min_discount') or 15,
        'median_price': crit.get('median_price'),
        'sample_size': crit.get('sample_size') or 0,
        # Медиана считается только от пяти наблюдений — показываем честно
        'ready': bool(crit.get('median_price')),
        'active': bool(crit.get('active')),
        'mode': crit.get('mode') or 'any',
    }


def get_user_criteria(user_id: int) -> List[Dict]:
    cursor = db.conn.cursor()
    cursor.execute("SELECT * FROM hunt_criteria WHERE user_id=? ORDER BY id DESC", (user_id,))
    return [dict(r) for r in cursor.fetchall()]


def add_criterion(user_id: int, query: str, category: str = '', city: str = '',
                  max_price: int = 0, min_discount: int = 15,
                  mode: str = 'any') -> Optional[int]:
    """Добавляет критерий. Пустой запрос или дубль — не создаём."""
    query = ' '.join(str(query or '').split())[:100]
    if len(query) < 2:
        return None
    cursor = db.conn.cursor()
    # Сравниваем в Python: LOWER() в SQLite не понимает кириллицу, из-за чего
    # «Пуховик» и «пуховик» считались разными критериями.
    cursor.execute("SELECT query, COALESCE(city,'') AS city FROM hunt_criteria "
                   "WHERE user_id=? AND active=1", (user_id,))
    for row in cursor.fetchall():
        if str(row['query'] or '').lower() == query.lower() and row['city'] == (city or ''):
            return None
    cursor.execute('''
        INSERT INTO hunt_criteria (user_id, query, category, city, max_price, min_discount,
                                   active, created_at, mode)
        VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?)
    ''', (user_id, query, category or '', city or '', int(max_price or 0),
          max(0, min(int(min_discount or 0), 90)), get_moscow_time().isoformat(),
          'deal' if str(mode) == 'deal' else 'any'))
    db.conn.commit()
    crit_id = cursor.lastrowid
    # Сразу считаем медиану, чтобы критерий начал работать не «когда-нибудь»
    recompute_criterion_medians()
    return crit_id


def remove_criterion(user_id: int, crit_id: int) -> bool:
    cursor = db.conn.cursor()
    cursor.execute("DELETE FROM hunt_criteria WHERE id=? AND user_id=?", (crit_id, user_id))
    db.conn.commit()
    return cursor.rowcount > 0


async def api_hunt_criteria(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET/POST/DELETE /api/hunt — критерии ловли для текущего пользователя."""
    viewer_id = _miniapp_viewer(request)
    method = request.method.upper()

    # Сборщику нужен список ВСЕХ активных критериев, чтобы обойти нужные
    # страницы — он авторизуется токеном, а не initData
    if method == 'GET' and request.query.get('for_collector'):
        expected = os.environ.get('INGEST_TOKEN', '')
        got = request.headers.get('X-Ingest-Token', '')
        if not expected or not hmac.compare_digest(str(got), str(expected)):
            return _miniapp_err('forbidden', 403)
        cursor = db.conn.cursor()
        cursor.execute("SELECT DISTINCT query, category, city FROM hunt_criteria WHERE active=1")
        rows = [dict(r) for r in cursor.fetchall()]
        return _miniapp_json({'items': rows})

    if not viewer_id:
        return _miniapp_err('unauthorized', 401)

    if method == 'GET':
        return _miniapp_json({
            'items': [_criterion_public(c) for c in get_user_criteria(viewer_id)],
            # Без этого человек не понимает, почему ничего не приходит
            'collector': collector_status(),
        })

    if method == 'POST':
        try:
            body = await request.json()
        except Exception:
            return _miniapp_err('bad_json', 400)
        raw_query = ' '.join(str((body or {}).get('query') or '').split())
        if len(raw_query) < 2:
            return _miniapp_json({'error': 'query_too_short',
                                  'detail': 'Напишите хотя бы два символа'}, status=400)
        crit_id = add_criterion(
            viewer_id,
            raw_query,
            category=str((body or {}).get('category') or ''),
            city=str((body or {}).get('city') or ''),
            max_price=int((body or {}).get('max_price') or 0),
            min_discount=int((body or {}).get('min_discount') or 0),
            mode=str((body or {}).get('mode') or 'any'),
        )
        if not crit_id:
            return _miniapp_json({'error': 'duplicate',
                                  'detail': 'Такой критерий уже есть — он в списке ниже'},
                                 status=409)
        # Сразу говорим человеку в боте, что критерий принят: иначе он ввёл
        # товар, услышал тишину и решил, что его обманули
        try:
            crit = next((c for c in get_user_criteria(viewer_id) if c['id'] == crit_id), None)
            if crit:
                await tell_criterion_created(viewer_id, crit)
        except Exception as e:
            logger.warning(f"criterion notice: {e}")
        return _miniapp_json({'ok': True, 'id': crit_id}, status=201)

    if method == 'DELETE':
        try:
            crit_id = int(request.query.get('id') or 0)
        except ValueError:
            crit_id = 0
        if not crit_id or not remove_criterion(viewer_id, crit_id):
            return _miniapp_err('not_found', 404)
        return _miniapp_json({'ok': True})

    return _miniapp_err('method_not_allowed', 405)


# Сколько дней держать находку. Дальше она либо продана, либо неактуальна.
HUNT_KEEP_DAYS = int(os.environ.get('HUNT_KEEP_DAYS', '7'))


def cleanup_all() -> Dict:
    """Чистит всё, что копится мусором. Данные пользователей не трогает.

    Что убираем и почему:
      • находки старше недели — объявление уже продано, искать поздно;
      • отметки об отправке старше месяца — нужны только чтобы не слать
        одно и то же дважды, дальше это балласт;
      • логи старше двух недель — забивают базу быстрее всего;
      • истории и их просмотры старше трёх дней — живут 24 часа, дальше мусор.

    НЕ трогаем: объявления доски, переписку, платежи, отзывы, подписки —
    это данные людей и деньги.
    """
    result = cleanup_findings()
    cursor = db.conn.cursor()
    now = get_moscow_time()
    removed = {}

    def _cut(table: str, days: int, column: str = 'created_at') -> int:
        cutoff = (now - timedelta(days=days)).isoformat()
        try:
            cursor.execute(f"DELETE FROM {table} WHERE {column} IS NOT NULL AND {column} < ?",
                           (cutoff,))
            n = cursor.rowcount or 0
            db.conn.commit()
            return n
        except Exception as e:
            logger.warning(f"cleanup {table}: {e}")
            return 0

    removed['отметки об отправке'] = _cut('search_notifications_sent', 30, 'sent_at')
    removed['логи'] = _cut('logs', 14)
    removed['просмотры историй'] = _cut('story_views', 3, 'viewed_at')
    removed['истории'] = _cut('stories', 3, 'created_at')

    total = sum(removed.values())
    if total:
        logger.info("Чистка базы: " + ", ".join(f"{k} {v}" for k, v in removed.items() if v))
    result['details'] = {k: v for k, v in removed.items() if v}
    result['removed_total'] = (result.get('removed') or 0) + total
    return result


def cleanup_findings() -> Dict:
    """Убирает старые находки из базы.

    Зачем: объявление, которому неделя, скорее всего уже продано — скидка по
    нему неактуальна, а в базе оно занимает место и замедляет запросы.
    Заодно медиана превращается в скользящее окно за последние дни: это
    точнее описывает рынок, чем среднее по древним объявлениям.

    Доску (source='polka') НЕ трогаем: это объявления живых людей.
    Отметки об отправке тоже оставляем — они крошечные и защищают
    от повторной присылки, если объявление появится снова.
    """
    cutoff = (get_moscow_time() - timedelta(days=HUNT_KEEP_DAYS)).isoformat()
    cursor = db.conn.cursor()
    removed = 0
    try:
        cursor.execute("DELETE FROM ads WHERE source IS NOT NULL AND source <> 'polka' "
                       "AND COALESCE(parsed_at, created_at) < ?", (cutoff,))
        removed = cursor.rowcount or 0
        db.conn.commit()
    except Exception as e:
        logger.warning(f"cleanup findings: {e}")
    if removed:
        logger.info(f"Чистка базы: удалено старых находок {removed} (старше {HUNT_KEEP_DAYS} дн.)")
        recompute_market_medians()
        recompute_criterion_medians()
    return {'removed': removed, 'keep_days': HUNT_KEEP_DAYS}


async def _findings_cleanup_loop():
    """Чистит базу раз в сутки."""
    while True:
        try:
            await asyncio.sleep(6 * 3600)
            cleanup_all()
        except Exception as e:
            logger.warning(f"findings cleanup loop: {e}")


async def _cleanup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Ручная чистка — на случай, если база распухла."""
    res = cleanup_all()
    cur = db.conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) AS n FROM ads WHERE source <> 'polka'")
        left = _row_get(cur.fetchone(), 'n', 0)
    except Exception:
        left = 0
    lines = [f"🧹 <b>Чистка базы</b>", "",
             f"Находки старше {res['keep_days']} дней: убрано <b>{res['removed']}</b>"]
    for name, count in (res.get('details') or {}).items():
        lines.append(f"{name}: убрано {count}")
    lines.append("")
    lines.append(f"Осталось находок в базе: {left}")
    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def tell_criterion_created(user_id: int, crit: Dict):
    """Сразу отвечаем человеку, что критерий принят и что будет дальше.

    Без этого он вводит товар и слышит тишину — выглядит как обман.
    """
    app = _get_bot_app()
    if not app:
        return
    query = crit.get('query') or ''
    city = f" · {crit['city']}" if crit.get('city') else ""
    cap = f"\nПотолок цены: {_money(crit['max_price'])} ₽" if crit.get('max_price') else ""
    text = (f"✅ <b>Ловлю «{query}»</b>{city}{cap}\n\n"
            f"Теперь ищу это на Авито и пришлю, как только найду подходящее.\n\n"
            f"Посмотреть, как идёт ловля, можно командой /hunt")
    try:
        await app.bot.send_message(chat_id=user_id, text=text, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.warning(f"criterion created notice -> {user_id}: {e}")


async def _hunt_feedback_loop():
    """Если по критерию долго ничего не нашлось — говорим об этом сами.

    Человек ввёл товар и ждёт. Молчание он читает как обман, поэтому через
    час объясняем: сбор идёт, но подходящего пока нет — и почему.
    """
    while True:
        try:
            await asyncio.sleep(1800)
            app = _get_bot_app()
            if not app:
                continue
            cur = db.conn.cursor()
            cur.execute("SELECT * FROM hunt_criteria WHERE active=1 AND told_empty_at IS NULL")
            crits = [dict(r) for r in cur.fetchall()]
            for crit in crits:
                if _hours_since(crit.get('created_at')) is None:
                    continue
                if (_hours_since(crit.get('created_at')) or 0) < 1:
                    continue  # даём сборщику время
                user_id = int(crit['user_id'])
                sent_any = 0
                try:
                    cur.execute("SELECT COUNT(*) AS n FROM search_notifications_sent WHERE user_id=?",
                                (user_id,))
                    sent_any = _row_get(cur.fetchone(), 'n', 0)
                except Exception:
                    pass
                if sent_any:
                    cur.execute("UPDATE hunt_criteria SET told_empty_at=? WHERE id=?",
                                (get_moscow_time().isoformat(), crit['id']))
                    db.conn.commit()
                    continue
                where, params = _criterion_where(crit, active_only=False)
                try:
                    cur.execute(f"SELECT COUNT(*) AS n FROM ads WHERE {where}", params)
                    matches = _row_get(cur.fetchone(), 'n', 0)
                except Exception:
                    matches = 0
                col = collector_status()
                if not col.get('alive'):
                    why = ("Сборщик объявлений сейчас не на связи — искать некому.\n"
                           "Напишите мне, если это длится долго.")
                elif matches:
                    why = (f"Похожих объявлений в базе: <b>{matches}</b>, но все старше "
                           f"{HUNT_FRESH_HOURS} ч или выше вашего потолка цены.")
                else:
                    why = ("Подходящих объявлений пока не появилось. Это нормально: "
                           "на узкий запрос в продаже может не быть неделями.")
                try:
                    await app.bot.send_message(
                        chat_id=user_id,
                        text=(f"🔎 <b>Ловлю «{crit.get('query')}» — пока пусто</b>\n\n{why}\n\n"
                              f"Продолжаю искать и пришлю сразу, как появится."),
                        parse_mode=ParseMode.HTML)
                    cur.execute("UPDATE hunt_criteria SET told_empty_at=? WHERE id=?",
                                (get_moscow_time().isoformat(), crit['id']))
                    db.conn.commit()
                except Exception as e:
                    logger.warning(f"hunt feedback -> {user_id}: {e}")
        except Exception as e:
            logger.warning(f"hunt feedback loop: {e}")


def hunt_report(user_id: int) -> str:
    """Простыми словами: идёт ли сбор и придёт ли что-то по критериям.

    Раньше человек должен был искать логи в панели Amvera. Это неправильно:
    ответ должен быть там, где он уже есть — в боте.
    """
    lines = ["🔎 <b>Ловля находок</b>", ""]
    col = collector_status()
    if col.get('alive'):
        mins = col.get('minutes') or 0
        lines.append(f"✅ Сборщик на связи — был {mins} мин назад")
    elif col.get('minutes') is None:
        lines.append("⚠️ Сборщик ещё не выходил на связь.")
        lines.append("   Запустите его на компьютере: <code>./start-local.sh</code>")
    else:
        hrs = int((col.get('minutes') or 0) // 60)
        lines.append(f"⚠️ Сборщик молчит {hrs} ч — проверьте, идёт ли он у вас.")

    cur = db.conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) AS n FROM ads WHERE source <> 'polka'")
        total = _row_get(cur.fetchone(), 'n', 0)
        cur.execute("SELECT COUNT(*) AS n FROM ads WHERE source <> 'polka' "
                    "AND parsed_at >= ?", ((get_moscow_time() - timedelta(hours=24)).isoformat(),))
        today = _row_get(cur.fetchone(), 'n', 0)
        lines.append(f"📦 Находок в базе: <b>{total}</b> (за сутки {today})")
    except Exception as e:
        logger.warning(f"hunt report counts: {e}")
    lines.append("")

    crits = get_user_criteria(user_id)
    if not crits:
        lines.append("Критериев нет. Добавьте: <code>/hunt iphone 13</code>")
        return "\n".join(lines)

    lines.append("<b>Ваши критерии</b>")
    for c in crits:
        where, params = _criterion_where(c, active_only=False)
        try:
            cur.execute(f"SELECT COUNT(*) AS n FROM ads WHERE {where}", params)
            matches = _row_get(cur.fetchone(), 'n', 0)
            cur.execute(
                f"SELECT COUNT(*) AS n FROM ads WHERE {where} AND status='active' "
                f"AND COALESCE(published_hours_ago, 0) <= ?", params + [HUNT_FRESH_HOURS])
            fresh = _row_get(cur.fetchone(), 'n', 0)
        except Exception:
            matches = fresh = 0
        sent = 0
        try:
            cur.execute("SELECT COUNT(*) AS n FROM search_notifications_sent WHERE user_id=?",
                        (user_id,))
            sent = _row_get(cur.fetchone(), 'n', 0)
        except Exception:
            pass
        mark = "✅" if fresh else "⏳"
        lines.append(f"{mark} <b>{c['query']}</b> — подходит {matches}, из них свежих {fresh}")
        if not fresh:
            if matches:
                lines.append("   свежих нет: подходящие есть, но старше суток")
            else:
                lines.append("   пока пусто — ждём, чтобы сборщик принёс такие объявления")
    lines.append("")
    lines.append(f"Всего отправлено вам: {sent}")
    return "\n".join(lines)


async def hunt_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ /hunt iphone 13 — критерий ловли. Без аргументов — список.

    Можно уточнить: /hunt iphone 13 | Ижевск | 45000
    """
    user = update.effective_user
    args = ' '.join(context.args or []).strip()

    if not args:
        await update.message.reply_text(hunt_report(user.id), parse_mode=ParseMode.HTML)
        return
        crits = get_user_criteria(user.id)
        col = collector_status()
        if not crits:
            await update.message.reply_text(
                "🔎 <b>Ловля находок</b>\n\n"
                "Напишите, что искать: <code>/hunt iphone 13</code>\n"
                "Бот будет присылать свежие объявления дешевле рынка.\n\n"
                "Можно уточнить город и потолок цены:\n"
                "<code>/hunt iphone 13 | Ижевск | 45000</code>",
                parse_mode=ParseMode.HTML)
            return
        lines = ["🔎 <b>Ваши критерии</b>\n"]
        if not col.get('alive'):
            lines.append("⚠️ <b>Сборщик не на связи.</b> Он работает на вашем "
                         "компьютере — пока он не запущен, объявления не придут.\n")
        for c in crits:
            city = f" · {c['city']}" if c.get('city') else ""
            cap = f" · до {_money(c['max_price'])} ₽" if c.get('max_price') else ""
            lines.append(f"• <b>{c['query']}</b>{city}{cap}")
            if c.get('median_price'):
                speed = _criterion_sell_speed(c)
                lines.append(f"   обычная цена {_money(c['median_price'])} ₽ "
                             f"(по {c.get('sample_size') or 0} шт)")
                # Показываем заработок на примере текущей обычной цены,
                # чтобы было видно, ради чего критерий вообще нужен
                example = hunt_profit(int(c['median_price'] * 0.8), c['median_price'])
                if example.get('ok'):
                    lines.append(f"   при цене на 20% ниже: навар ~{_money(example['profit'])} ₽")
                if speed:
                    lines.append(f"   похожие уходили за ~{speed} ч")
            else:
                lines.append(f"   собираем статистику: {c.get('sample_size') or 0} из "
                             f"{HUNT_MIN_SAMPLE} — присылаю любые подходящие")
            lines.append(f"   убрать: <code>/hunt -{c['id']}</code>")
        await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)
        return

    if args.startswith('-'):
        digits = re.sub(r'[^0-9]', '', args[1:])
        removed = remove_criterion(user.id, int(digits)) if digits else False
        await update.message.reply_text("Критерий убран." if removed else "Такого критерия нет.")
        return

    parts = [p.strip() for p in args.split('|')]
    query = parts[0][:100]
    city = parts[1][:100] if len(parts) > 1 else ''
    max_price = 0
    if len(parts) > 2:
        digits = re.sub(r'[^0-9]', '', parts[2])
        max_price = int(digits) if digits else 0

    crit_id = add_criterion(user.id, query, city=city, max_price=max_price)
    if not crit_id:
        await update.message.reply_text(
            "Такой критерий уже есть — или запрос слишком короткий.")
        return
    crit = next((c for c in get_user_criteria(user.id) if c['id'] == crit_id), None) or {}
    head = f"✅ Ловлю <b>{query}</b>" + (f" · {city}" if city else "") + "\n\n"
    if crit.get('median_price'):
        med = f"{crit['median_price']:,} ₽".replace(',', ' ')
        await update.message.reply_text(
            head + f"Медиана по этому запросу сейчас: <b>{med}</b>\n"
                   f"Посчитана по {crit.get('sample_size')} объявлениям.\n\n"
                   f"Пришлю, как только появится дешевле на {crit.get('min_discount') or 15}%.",
            parse_mode=ParseMode.HTML)
    elif (crit.get('mode') or 'any') == 'any':
        await update.message.reply_text(
            head + "Буду присылать всё подходящее сразу — статистику ждать не нужно.\n\n"
                   "Как наберётся достаточно объявлений, начну отсеивать дорогое "
                   "и показывать, сколько на этом заработать.",
            parse_mode=ParseMode.HTML)
    else:
        await update.message.reply_text(
            head + f"Копим статистику: нужно минимум {HUNT_MIN_SAMPLE} объявлений "
                   f"по этому запросу, чтобы медиана была честной.\n\n"
                   f"Пока их нет, присылать нечего — иначе скидка была бы выдуманной.",
            parse_mode=ParseMode.HTML)


async def api_ingest_checklist(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/ingest/checklist — что перепроверить на «продано».

    Авито не отдаёт статус в выдаче, поэтому сборщик периодически
    переоткрывает страницы лотов. Здесь он получает список: ссылку и id.
    """
    expected = os.environ.get('INGEST_TOKEN', '')
    if not expected:
        return _miniapp_err('ingest_disabled', 503)
    got = request.headers.get('X-Ingest-Token', '') or request.query.get('token', '')
    if not hmac.compare_digest(str(got), str(expected)):
        return _miniapp_err('forbidden', 403)
    source = str(request.query.get('source') or 'avito')
    try:
        limit = min(max(int(request.query.get('limit', 30) or 30), 1), 100)
    except ValueError:
        limit = 30
    # Берём то, что недавно нашли и ещё считаем живым: старое проверять
    # бессмысленно — оно и так осядет по сроку
    cursor = db.conn.cursor()
    try:
        cursor.execute('''
            SELECT external_id, source_url, title, price, parsed_at
            FROM ads
            WHERE source=? AND external_id IS NOT NULL AND source_url IS NOT NULL
              AND COALESCE(listing_state,'active')='active'
              AND parsed_at IS NOT NULL
            ORDER BY parsed_at DESC LIMIT ?
        ''', (source, limit))
        items = [dict(r) for r in cursor.fetchall()]
    except Exception as e:
        logger.error(f"checklist: {e}")
        return _miniapp_err('load_failed', 500)
    return _miniapp_json({'source': source, 'items': items})


def _remove_story_file(media: str):
    """Удаляет файл истории с диска (медиа лежит в UPLOAD_DIR)."""
    if not media:
        return
    try:
        name = os.path.basename(str(media))
        upload_dir = os.environ.get('UPLOAD_DIR', '/data/uploads')
        path = os.path.join(upload_dir, name)
        if name and os.path.isfile(path):
            os.remove(path)
    except Exception as e:
        logger.warning(f"story file remove: {e}")


# ── Аукционы: ставки, антиснайпинг, выкуп, завершение ───────────────────────
AUCTION_MIN_STEP = 10            # минимальный шаг ставки, ₽
AUCTION_ANTISNIPE_WINDOW = 300   # ставка в последние 5 минут…
AUCTION_ANTISNIPE_EXTEND = 300   # …продлевает лот на 5 минут
AUCTION_DURATIONS = (1, 3, 7)    # срок в днях, на выбор продавца
AUCTION_MAX_STEP_MULT = 10       # шаг не больше 10× стартовой цены


def _auction(ad_id: int) -> Optional[Dict]:
    cursor = db.conn.cursor()
    cursor.execute("SELECT * FROM ads WHERE id=? AND sale_type='auction'", (ad_id,))
    row = cursor.fetchone()
    return dict(row) if row else None


def min_next_bid(ad: Dict) -> int:
    """Минимальная допустимая ставка: стартовая для первой, текущая+шаг далее."""
    step = max(AUCTION_MIN_STEP, int(ad.get('bid_step') or 0))
    current = int(ad.get('current_bid') or 0)
    if current:
        return current + step
    return int(ad.get('start_price') or 0)


def auction_time_left(ad: Dict) -> int:
    """Секунд до конца лота (0 — время вышло)."""
    if not ad.get('ends_at'):
        return 0
    ends = _safe_isoparse(ad['ends_at'])
    return max(0, int((ends - get_moscow_time()).total_seconds()))


def get_bids(ad_id: int, limit: int = 30) -> List[Dict]:
    cursor = db.conn.cursor()
    cursor.execute('''
        SELECT b.*, u.username, u.first_name
        FROM bids b LEFT JOIN users u ON u.user_id = b.user_id
        WHERE b.ad_id=? ORDER BY b.amount DESC, b.id ASC LIMIT ?
    ''', (ad_id, limit))
    return [dict(r) for r in cursor.fetchall()]


def _current_leader_bid(ad_id: int) -> Optional[Dict]:
    cursor = db.conn.cursor()
    cursor.execute("SELECT * FROM bids WHERE ad_id=? AND status='active' "
                   "ORDER BY amount DESC, id ASC LIMIT 1", (ad_id,))
    row = cursor.fetchone()
    return dict(row) if row else None


def place_bid(ad_id: int, user_id: int, amount) -> Dict:
    """Ставит ставку. Возвращает {'ok': True, 'ad', 'outbid'} либо ошибку."""
    ad = _auction(ad_id)
    if not ad:
        return {'ok': False, 'error': 'not_auction'}
    if ad.get('status') != 'active':
        return {'ok': False, 'error': 'not_active'}
    if auction_time_left(ad) <= 0:
        return {'ok': False, 'error': 'ended'}
    if int(ad.get('user_id') or 0) == int(user_id):
        return {'ok': False, 'error': 'own_lot'}
    try:
        amount = int(amount)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'bad_amount'}

    minimum = min_next_bid(ad)
    if amount < minimum:
        return {'ok': False, 'error': 'too_low', 'minimum': minimum}
    buy_now = int(ad.get('buy_now_price') or 0)
    if buy_now and amount >= buy_now:
        return {'ok': False, 'error': 'use_buy_now', 'buy_now': buy_now}

    prev = _current_leader_bid(ad_id)
    now = get_moscow_time()
    cursor = db.conn.cursor()
    cursor.execute("UPDATE bids SET status='outbid' WHERE ad_id=? AND status='active'", (ad_id,))
    cursor.execute("INSERT INTO bids (ad_id, user_id, amount, status, created_at) "
                   "VALUES (?, ?, ?, 'active', ?)", (ad_id, user_id, amount, now.isoformat()))

    # Антиснайпинг: ставка в концовке продлевает лот, иначе все ждут
    # последней секунды и честной борьбы не выходит.
    extended = False
    ends_at = ad.get('ends_at')
    if ends_at:
        ends = _safe_isoparse(ends_at)
        left = int((ends - now).total_seconds())
        if left <= AUCTION_ANTISNIPE_WINDOW:
            ends = ends + timedelta(seconds=AUCTION_ANTISNIPE_EXTEND)
            ends_at = ends.isoformat()
            extended = True

    cursor.execute('''
        UPDATE ads SET current_bid=?, price=?, bids_count=COALESCE(bids_count,0)+1, ends_at=?
        WHERE id=?
    ''', (amount, amount, ends_at, ad_id))
    db.conn.commit()

    ad = _auction(ad_id)
    return {'ok': True, 'ad': ad, 'outbid': prev, 'extended': extended, 'amount': amount}


def buy_now(ad_id: int, user_id: int) -> Dict:
    """Мгновенный выкуп: закрывает лот сразу по цене выкупа."""
    ad = _auction(ad_id)
    if not ad:
        return {'ok': False, 'error': 'not_auction'}
    if ad.get('status') != 'active':
        return {'ok': False, 'error': 'not_active'}
    if auction_time_left(ad) <= 0:
        return {'ok': False, 'error': 'ended'}
    if int(ad.get('user_id') or 0) == int(user_id):
        return {'ok': False, 'error': 'own_lot'}
    price = int(ad.get('buy_now_price') or 0)
    if not price:
        return {'ok': False, 'error': 'no_buy_now'}

    now = get_moscow_time()
    cursor = db.conn.cursor()
    cursor.execute("UPDATE bids SET status='outbid' WHERE ad_id=? AND status='active'", (ad_id,))
    cursor.execute("INSERT INTO bids (ad_id, user_id, amount, status, created_at) "
                   "VALUES (?, ?, ?, 'won', ?)", (ad_id, user_id, price, now.isoformat()))
    cursor.execute('''
        UPDATE ads SET status='ended', winner_id=?, finished_at=?, price=?, current_bid=?,
                       bids_count=COALESCE(bids_count,0)+1
        WHERE id=?
    ''', (user_id, now.isoformat(), price, price, ad_id))
    db.conn.commit()
    return {'ok': True, 'ad': _auction(ad_id), 'amount': price, 'buy_now': True}


def validate_auction_params(body: Dict) -> Dict:
    """Проверяет параметры лота ДО создания объявления.

    Шаг по умолчанию — 5% от стартовой цены, но не меньше 10 ₽ и не больше
    10× стартовой: иначе либо ставки по рублю, либо шаг больше самого лота.
    """
    start = _miniapp_parse_price(body.get('start_price', 0))
    if start <= 0:
        return {'ok': False, 'error': 'bad_start_price'}
    raw_step = _miniapp_parse_price(body.get('bid_step', 0))
    step = int(raw_step) if raw_step else max(AUCTION_MIN_STEP, int(start * 0.05))
    step = max(AUCTION_MIN_STEP, min(int(step), int(start) * AUCTION_MAX_STEP_MULT))
    try:
        days = int(body.get('auction_days') or 3)
    except (TypeError, ValueError):
        days = 3
    if days not in AUCTION_DURATIONS:
        days = 3
    buy_now = _miniapp_parse_price(body.get('buy_now_price', 0)) or None
    if buy_now is not None and buy_now < start + step:
        return {'ok': False, 'error': 'bad_buy_now'}
    return {'ok': True, 'start_price': start, 'bid_step': step,
            'buy_now_price': buy_now, 'auction_days': days}


def set_auction_params(ad_id: int, start_price: int, bid_step: int,
                       buy_now_price: Optional[int], days: int):
    """Включает у объявления режим аукциона.

    price = стартовая цена, чтобы карточка в ленте показывала «от N ₽»
    до первых ставок. ends_at НЕ ставим — срок пойдёт от одобрения.
    """
    cursor = db.conn.cursor()
    cursor.execute('''
        UPDATE ads SET sale_type='auction', start_price=?, bid_step=?, buy_now_price=?,
                       auction_days=?, current_bid=0, bids_count=0, price=?
        WHERE id=?
    ''', (start_price, bid_step, buy_now_price, days, start_price, ad_id))
    db.conn.commit()


def get_my_bids(user_id: int, limit: int = 50) -> List[Dict]:
    """Мои ставки с состоянием лота — для раздела «Мои ставки»."""
    cursor = db.conn.cursor()
    cursor.execute('''
        SELECT b.id AS bid_id, b.amount, b.status AS bid_status, b.created_at AS bid_at,
               a.id AS ad_id, a.title, a.photos, a.status AS ad_status, a.sale_type,
               a.ends_at, a.current_bid, a.winner_id, a.user_id AS seller_id
        FROM bids b JOIN ads a ON a.id = b.ad_id
        WHERE b.user_id=?
        ORDER BY b.created_at DESC LIMIT ?
    ''', (user_id, limit))
    return [dict(r) for r in cursor.fetchall()]


def finish_auctions() -> List[Dict]:
    """Завершает лоты, у которых вышло время. Возвращает их для уведомлений.

    Победитель — лучшая ставка; чат победителя с продавцом создаём сразу,
    чтобы им не пришлось искать друг друга.
    """
    cursor = db.conn.cursor()
    now = get_moscow_time()
    cursor.execute('''
        SELECT * FROM ads
        WHERE sale_type='auction' AND status='active'
          AND ends_at IS NOT NULL AND ends_at <= ?
    ''', (now.isoformat(),))
    finished = []
    for row in [dict(r) for r in cursor.fetchall()]:
        cursor.execute("SELECT * FROM bids WHERE ad_id=? ORDER BY amount DESC, id ASC LIMIT 1",
                       (row['id'],))
        top = cursor.fetchone()
        if top:
            top = dict(top)
            cursor.execute("UPDATE bids SET status='won' WHERE id=?", (top['id'],))
            cursor.execute("UPDATE bids SET status='lost' WHERE ad_id=? AND id<>? "
                           "AND status IN ('active','outbid')", (row['id'], top['id']))
            cursor.execute('''
                UPDATE ads SET status='ended', winner_id=?, finished_at=?, price=?, current_bid=?
                WHERE id=?
            ''', (top['user_id'], now.isoformat(), top['amount'], top['amount'], row['id']))
            row['winner_id'] = top['user_id']
            row['top_bid'] = top['amount']
        else:
            cursor.execute("UPDATE ads SET status='ended_unsold', finished_at=? WHERE id=?",
                           (now.isoformat(), row['id']))
            row['top_bid'] = 0
        finished.append(row)
    if finished:
        db.conn.commit()
    return finished


async def _notify_auction(user_id: int, text: str, ad_id: Optional[int] = None):
    """Сообщение участнику аукциона через бота."""
    app = _get_bot_app()
    if not app or not user_id:
        return
    kb = None
    if ad_id:
        kb = InlineKeyboardMarkup([[
            InlineKeyboardButton(EM_ARROW_R + " Открыть лот", callback_data=f"view_ad:{ad_id}")
        ]])
    try:
        await app.bot.send_message(chat_id=user_id, text=text, parse_mode=ParseMode.HTML,
                                   reply_markup=kb)
    except Exception as e:
        logger.warning(f"auction notify -> {user_id}: {e}")


async def _notify_auction_finished(ad: Dict):
    """Уведомления по завершённому лоту: победителю, продавцу, наблюдавшим."""
    title = str(ad.get('title') or '')[:40]
    winner_id = ad.get('winner_id')
    seller_id = ad.get('user_id')
    top_bid = ad.get('top_bid') or ad.get('current_bid') or 0
    if winner_id:
        chat_id = None
        try:
            chat_id = get_or_create_chat(ad['id'], winner_id, seller_id)
        except Exception as e:
            logger.warning(f"auction chat: {e}")
        await _notify_auction(
            winner_id,
            f"{EM_OK} <b>Вы выиграли аукцион!</b>\n"
            f"«{title}» за {top_bid:,} ₽\n\n"
            f"Напишите продавцу, чтобы договориться о передаче.".replace(',', ' '),
            ad['id'],
        )
        await _notify_auction(
            seller_id,
            f"{EM_OK} <b>Ваш лот продан!</b>\n"
            f"«{title}» за {top_bid:,} ₽\n\n"
            f"Победитель уже получил уведомление.".replace(',', ' '),
            ad['id'],
        )
    else:
        await _notify_auction(
            seller_id,
            f"{EM_WARN} <b>Аукцион завершён без ставок</b>\n"
            f"«{title}»\n\nМожно выставить лот снова.".replace(',', ' '),
            ad['id'],
        )


async def _auctions_loop():
    """Раз в 30 секунд закрывает лоты с истёкшим временем."""
    while True:
        try:
            await asyncio.sleep(30)
            for ad in finish_auctions():
                await _notify_auction_finished(ad)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.warning(f"auctions loop: {e}")
            await asyncio.sleep(60)


def get_user_chats(user_id: int, limit: int = 20) -> List[Dict]:
    cursor = db.conn.cursor()
    cursor.execute('''
        SELECT cs.*, a.title, a.price,
               ub.first_name AS buyer_name, ub.anon_id AS buyer_anon,
               us.first_name AS seller_name, us.anon_id AS seller_anon,
               (SELECT sender_id FROM chat_messages cm
                WHERE cm.session_id = cs.id
                ORDER BY cm.created_at DESC, cm.id DESC LIMIT 1) AS last_sender_id
        FROM chat_sessions cs
        JOIN ads a ON cs.ad_id = a.id
        JOIN users ub ON cs.buyer_id = ub.user_id
        JOIN users us ON cs.seller_id = us.user_id
        WHERE (cs.buyer_id=? OR cs.seller_id=?) AND cs.status='active'
        ORDER BY cs.last_message_at DESC
        LIMIT ?
    ''', (user_id, user_id, limit))
    return [dict(r) for r in cursor.fetchall()]


async def start_chat_with_seller(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Экран продавца перед чатом — анон-ID, рейтинг, избранное, потом чат"""
    query = update.callback_query
    await safe_answer(query, )
    ad_id = int(query.data.split(':')[1])
    ad = db.get_ad(ad_id)
    if not ad:
        await safe_answer(query, "Объявление не найдено", show_alert=True)
        return

    buyer_id  = update.effective_user.id
    seller_id = ad['user_id']

    if buyer_id == seller_id:
        await safe_answer(query, "Это ваше объявление", show_alert=True)
        return

    # Фиксируем реальное обращение (кнопка "Написать продавцу" нажата)
    asyncio.create_task(track_contact_click(ad_id, buyer_id, context))

    seller_info = db.get_user(seller_id)
    seller_anon = get_anon_id(seller_info)

    # Верификация
    verify     = db.get_verification(seller_id)
    is_verified = verify and verify.get('status') == 'verified'
    badge      = f"  {EM_OK} Верифицирован" if is_verified else ""

    # Рейтинг
    rating = db.get_seller_rating(seller_id)
    if rating['count'] > 0:
        stars      = "★" * round(rating['avg']) + "☆" * (5 - round(rating['avg']))
        rating_str = f"{stars}  {rating['avg']} / 5  ({rating['count']} отз.)"
    else:
        rating_str = "☆☆☆☆☆  Нет отзывов"

    # Статистика продавца (публичная часть)
    cursor = db.conn.cursor()
    cursor.execute("SELECT COUNT(*) FROM ads WHERE user_id=? AND status='active'", (seller_id,))
    active_ads_count = cursor.fetchone()[0]

    # Дата регистрации
    reg_date = fmt_date(seller_info.get('registration_date','')) if seller_info else ''

    # Избранное
    already_fav = db.is_favorite_seller(buyer_id, seller_id)
    fav_label = f"{EM_FAIL} Убрать из избранного" if already_fav else f"{EM_HEART} Добавить продавца в избранное"
    fav_cb    = f"unfav_seller:{seller_id}" if already_fav else f"fav_seller:{seller_id}"

    text = (
        f"<b>Продавец {seller_anon}</b>{badge}\n"
        f"──────────────────\n"
        f"{rating_str}\n"
        f"▸ Активных объявлений: <b>{active_ads_count}</b>\n"
        f"◷ На платформе с {reg_date}\n"
        f"──────────────────\n"
        f"<b>{ad['title'][:50]}</b>\n"
        f"<b>{int(ad['price']):,} ₽</b>\n".replace(',', ' ')
    )

    # Кнопка чата через бота
    session_id = get_or_create_chat(ad_id, buyer_id, seller_id)
    chat_btn = InlineKeyboardButton(EM_DOT + " Написать продавцу", callback_data=f"open_chat_now:{ad_id}")

    keyboard = [
        [chat_btn],
        [InlineKeyboardButton(fav_label, callback_data=fav_cb)],
        [InlineKeyboardButton("★ Отзыв", callback_data=f"leave_review_seller:{seller_id}")],
        [InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_ad:{ad_id}")],
    ]

    await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)


async def open_chat_now(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Открываем чат после карточки продавца"""
    query = update.callback_query
    await safe_answer(query, )
    ad_id     = int(query.data.split(':')[1])
    ad        = db.get_ad(ad_id)
    if not ad:
        await safe_answer(query, "Объявление не найдено", show_alert=True)
        return

    buyer_id  = update.effective_user.id
    seller_id = ad['user_id']
    seller_info = db.get_user(seller_id)
    seller_anon = get_anon_id(seller_info)

    session_id = get_or_create_chat(ad_id, buyer_id, seller_id)
    context.user_data['active_chat'] = session_id

    cursor = db.conn.cursor()
    cursor.execute('SELECT COUNT(*) FROM chat_messages WHERE session_id=?', (session_id,))
    is_new = cursor.fetchone()[0] == 0

    await safe_edit_message(query,
        f"<b>Диалог с {seller_anon}</b>\n"
        f"──────────────────\n"
        f"{ad['title'][:50]}\n\n"
        f"Напишите сообщение — продавец получит его.\n"
        f"<i>Ваши личные данные не передаются.</i>",
        [[InlineKeyboardButton(EM_ARROW_R + " Все диалоги", callback_data="my_chats")],
         [InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_ad:{ad_id}")]])

    if is_new:
        buyer_anon  = ensure_anon_id(buyer_id)
        try:
            sent = await context.bot.send_message(
                chat_id=seller_id,
                text=(
                    f"<b>Новый диалог</b> — «{ad['title'][:40]}»\n"
                    f"Покупатель: {buyer_anon}\n\n"
                    f"Ответьте через «Мои диалоги»."
                ),
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_R + " Ответить", callback_data=f"open_chat:{session_id}"),
                    InlineKeyboardButton(EM_ARROW_R + " Мои диалоги", callback_data="my_chats")
                ]]),
                parse_mode=ParseMode.HTML
            )
            if sent is None:
                raise Exception("send_message вернул None")
        except Exception as e:
            logger.info(f"chat notify: первичная отправка не удалась ({e}), проверяю платформу получателя для фоллбэка")
            # Продавец может быть пользователем MAX (не Telegram) — тогда
            # send_message через Telegram Bot API закономерно падает с
            # "Chat not found", т.к. seller_id — это ID в системе MAX, а не
            # Telegram chat_id. Проверяем платформу и доставляем через MAX.
            #
            # ВАЖНО: "Chat not found" бывает по ДВУМ разным причинам, и без
            # логирования их не отличить:
            #  1) продавец реально на MAX, но platform в БД почему-то не
            #     обновился (баг данных) — тогда фоллбэк ниже не сработает;
            #  2) продавец реально в Telegram, но НИКОГДА не нажимал /start
            #     у бота — Telegram Bot API физически не даёт написать
            #     первым тому, кто не инициировал диалог сам. Это
            #     ограничение платформы, не баг кода, и MAX-фоллбэк тут
            #     не поможет в принципе (получатель не на MAX).
            seller_platform = (seller_info or {}).get('platform', 'telegram')
            logger.info(
                f"chat notify fallback check: seller_id={seller_id}, "
                f"seller_platform={seller_platform!r}, max_client={'есть' if max_client else 'НЕТ'}"
            )
            if seller_platform != 'telegram' and max_client:
                try:
                    max_text = (
                        f"Новый диалог — «{ad['title'][:40]}»\n"
                        f"Покупатель: {buyer_anon}\n\n"
                        f"Ответьте через «Мои диалоги» в боте."
                    )
                    await max_client.send_message(seller_id, max_text, parse_mode='HTML')
                    logger.info(f"chat notify: доставлено через MAX fallback, seller_id={seller_id}")
                except Exception as _max_notify_e:
                    logger.warning(f"chat notify (MAX fallback) failed: {_max_notify_e}")
            elif seller_platform == 'telegram':
                logger.warning(
                    f"chat notify: seller_id={seller_id} числится как platform='telegram', "
                    f"но send_message упал с Chat not found — либо это реально TG-пользователь, "
                    f"который никогда не нажимал /start у бота (ограничение Telegram API, не баг), "
                    f"либо platform в БД для него ошибочно не обновился на 'max'."
                )


async def handle_chat_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        session_id = context.user_data.get('active_chat')
        if not session_id:
            return

        session = get_chat_session(session_id)
        if not session:
            context.user_data.pop('active_chat', None)
            return

        sender_id = update.effective_user.id
        recipient_id = session['seller_id'] if sender_id == session['buyer_id'] else session['buyer_id']
        ad = db.get_ad(session['ad_id'])
        ad_title = ad['title'][:35] if ad else '?'

        file_id = ''
        msg_type = 'text'

        sender_info = db.get_user(sender_id)
        sender_anon = get_anon_id(sender_info)
        recipient = db.get_user(recipient_id)
        recipient_platform = (recipient or {}).get('platform', 'telegram')

        if update.message.text:
            text = update.message.text
            relay = f"<b>{sender_anon}</b>:\n{text}"
        elif update.message.photo:
            file_id = update.message.photo[-1].file_id
            text = update.message.caption or ''
            msg_type = 'photo'
            relay = f"<b>{sender_anon}</b>:\n\n{text}" if text else f"<b>{sender_anon}</b>"
        elif update.message.video:
            file_id = update.message.video.file_id
            text = update.message.caption or ''
            msg_type = 'video'
            relay = f"<b>{sender_anon}</b>:\n\n{text}" if text else f"<b>{sender_anon}</b>"
        elif update.message.voice:
            msg_type = 'voice'
            text = 'Голосовое сообщение'
            relay = f"<b>{sender_anon}</b> — голосовое"
        elif update.message.document:
            msg_type = 'document'
            text = f"Документ: {update.message.document.file_name or ''}"
            relay = f"<b>{sender_anon}</b>:\n\n{text}" if text else f"<b>{sender_anon}</b>"
        else:
            return

        msg_id = save_chat_message(session_id, sender_id, text=text, file_id=file_id, msg_type=msg_type)

        reply_kb = InlineKeyboardMarkup([[
            InlineKeyboardButton(EM_ARROW_R + " Ответить", callback_data=f"open_chat:{session_id}"),
            InlineKeyboardButton(EM_ARROW_R + " Мои диалоги", callback_data="my_chats")
        ]])
        try:
            if recipient_platform == 'telegram':
                ok = False
                if msg_type == 'photo':
                    sent = await context.bot.send_photo(chat_id=recipient_id, photo=file_id,
                        caption=relay, reply_markup=reply_kb, parse_mode=ParseMode.HTML)
                    ok = sent is not None
                else:
                    sent = await context.bot.send_message(chat_id=recipient_id, text=relay,
                        reply_markup=reply_kb, parse_mode=ParseMode.HTML)
                    ok = sent is not None
                if not ok:
                    raise Exception("send вернул None")
            else:
                raise Exception("получатель на другой платформе")
            await update.message.reply_text(f"{EM_OK} Отправлено",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_R + " Все диалоги", callback_data="my_chats"),
                    InlineKeyboardButton(EM_FAIL + " Закрыть чат", callback_data="close_chat")
                ]]))
        except Exception as e:
            logger.info(f"chat relay: первичная отправка не удалась ({e}), шлю напрямую через MAX API")
            if recipient_platform != 'telegram' and max_client:
                notify = f"<b>{sender_anon}</b> — «{ad_title}»:\n\n{text}"
                notify_kb = {"inline_keyboard": [[
                    {"text": EM_ARROW_R + " Ответить", "callback_data": f"open_chat:{session_id}"},
                    {"text": EM_ARROW_R + " Мои диалоги", "callback_data": "my_chats"}
                ]]}
                try:
                    await max_client.send_message(recipient_id, notify, parse_mode='HTML', reply_markup=notify_kb)
                except Exception as max_e:
                    logger.warning(f"chat relay: MAX send failed: {max_e}")
            await update.message.reply_text(f"{EM_OK} Отправлено",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_R + " Все диалоги", callback_data="my_chats"),
                    InlineKeyboardButton(EM_FAIL + " Закрыть чат", callback_data="close_chat")
                ]]))
    except Exception as e:
        logger.error(f"Ошибка в handle_chat_message: {e}")
        try:
            await update.message.reply_text(
                "Не удалось отправить сообщение. Попробуйте позже.",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_L + " Диалоги", callback_data="my_chats")
                ]])
            )
        except Exception:
            pass
async def open_chat(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    try:
        session_id = int(query.data.split(':')[1])
        session = get_chat_session(session_id)
        if not session:
            await safe_edit_message(query, "Диалог не найден")
            return

        context.user_data['active_chat'] = session_id
        user_id = update.effective_user.id
        ad = db.get_ad(session['ad_id'])
        other_id   = session['seller_id'] if user_id == session['buyer_id'] else session['buyer_id']
        other_info = db.get_user(other_id)
        other_info = db.get_user(other_id)
        other_anon = get_anon_id(other_info)

        read_col = 'buyer_last_read' if user_id == session['buyer_id'] else 'seller_last_read'
        db.conn.execute(
            f"UPDATE chat_sessions SET {read_col} = ? WHERE id = ?",
            (get_moscow_time().isoformat(), session_id)
        )
        db.conn.commit()

        # Показываем историю сообщений и режим ввода через бота
        cursor = db.conn.cursor()
        cursor.execute('SELECT * FROM chat_messages WHERE session_id=? ORDER BY created_at DESC LIMIT 8', (session_id,))
        msgs = list(reversed([dict(r) for r in cursor.fetchall()]))

        history = ''
        for m in msgs:
            who    = 'Вы' if m['sender_id'] == user_id else f"{other_anon}"
            ts     = m['created_at'][11:16] if m.get('created_at') else ''
            txt    = m.get('text') or ''
            mtype  = m.get('msg_type') or 'text'
            icon   = {'photo': '📷 ', 'video': '📹 ', 'voice': '🎵 ', 'document': '📄 '}.get(mtype, '')
            if mtype == 'voice':
                txt = 'Голосовое сообщение'
            elif mtype in ('photo', 'video', 'document') and txt:
                txt = f'{icon}{txt}'
            else:
                txt = f'{icon}{txt}'
            history += f"<b>{who}</b>  <i>{ts}</i>\n{txt}\n\n"

        _empty_msg = "<i>Сообщений нет — напишите первым!</i>\n\n"
        await safe_edit_message(query,
            f"<b>Диалог с {other_anon}</b>\n"
            f"──────────────────\n"
            f"{(ad['title'][:45] if ad else '?')}\n\n"
            f"{history or _empty_msg}"
            f"Напишите следующее сообщение:",
            [[InlineKeyboardButton(EM_ARROW_R + " Все диалоги", callback_data="my_chats")],
             [InlineKeyboardButton(EM_FAIL + " Закрыть чат", callback_data="close_chat")]])
    except Exception as e:
        logger.error(f"Ошибка в open_chat: {e}")
        try:
            await safe_edit_message(query, "Не удалось открыть диалог.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="my_chats")]])
        except Exception:
            pass
async def close_chat(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    context.user_data.pop('active_chat', None)
    await safe_edit_message(query, "Чат закрыт.",
        [[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])


async def my_chats(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await safe_answer(query, )
    try:
        user_id = update.effective_user.id
        chats = get_user_chats(user_id)

        if not chats:
            await safe_edit_message(query,
                "<b>Мои диалоги</b>\n\nПока нет диалогов.\n"
                "Напишите продавцу из карточки объявления.",
                [[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
            return

        text = f"<b>Мои диалоги</b>  {EM_DOT}  {len(chats)}\n──────────────────\n"
        keyboard = []
        for ch in chats[:10]:
            is_buyer   = user_id == ch['buyer_id']
            other_id   = ch['seller_id'] if is_buyer else ch['buyer_id']
            other_info = db.get_user(other_id)
            other_anon = get_anon_id(other_info)
            last       = fmt_datetime(ch.get('last_message_at','')) if ch.get('last_message_at') else ''
            role       = f"{EM_ARROW_R}" if is_buyer else f"{EM_ARROW_L}"
            title_short = (ch.get('title') or '?')[:28]

            # Непрочитанное — если последнее сообщение новее моей метки
            # "прочитано" для этого диалога (и оно не от меня самого).
            my_last_read = ch.get('buyer_last_read') if is_buyer else ch.get('seller_last_read')
            last_msg_at  = ch.get('last_message_at') or ''
            unread = bool(last_msg_at) and (not my_last_read or last_msg_at > my_last_read) and ch.get('last_sender_id') != user_id
            unread_mark = "🔴 " if unread else ""

            text += f"{unread_mark}{role} {other_anon}  {EM_DOT}  {title_short}  {EM_DOT}  {last}\n"

            keyboard.append([InlineKeyboardButton(
                    f"{unread_mark}{other_anon}  —  {title_short}", callback_data=f"open_chat:{ch['id']}"
                )])

        keyboard.append([InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")])
        await safe_edit_message(query, text, keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"Ошибка в my_chats: {e}")
        try:
            await safe_edit_message(query, "Не удалось загрузить диалоги.",
                [[InlineKeyboardButton(EM_ARROW_L + " Назад", callback_data="back_to_menu")]])
        except Exception:
            pass

