async def report_user_send(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Сохраняем жалобу на пользователя и уведомляем админов"""
    query = update.callback_query
    await safe_answer(query, )
    parts = query.data.split(":", 2)
    target_id, reason_code = int(parts[1]), parts[2]
    REASON_MAP = {code: label for code, label in USER_REPORT_REASONS}
    reason = REASON_MAP.get(reason_code, reason_code)
    reporter_id = update.effective_user.id

    saved = db.report_user(reporter_id, target_id, reason)
    if not saved:
        await safe_answer(query, "Вы уже жаловались на этого пользователя", show_alert=True)
        return

    report_count = db.get_user_report_count(target_id)
    target = db.get_user(target_id)
    target_name = target.get('first_name', f'#{target_id}') if target else f'#{target_id}'
    reporter = update.effective_user

    for admin_id in ADMIN_USER_IDS:
        try:
            flag = f"\n\n{EM_DOT} Уже 3+ жалобы на этого пользователя!" if report_count >= 3 else ""
            await context.bot.send_message(
                chat_id=admin_id,
                text=(
                    f"{EM_DOT} Жалоба на пользователя #{target_id}\n"
                    f"Имя: {target_name}\n"
                    f"Причина: {reason}\n"
                    f"От: {reporter.first_name} (@{reporter.username or 'нет'})\n"
                    f"Всего жалоб: {report_count}{flag}"
                ),
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_FAIL + " Заблокировать", callback_data=f"admin_ban:{target_id}"),
                    InlineKeyboardButton(EM_DOT + " Игнорировать", callback_data=f"admin_dismiss_user_report:{target_id}")
                ]])
            )
        except Exception as e:
            logger.error(f"report_user notify admin error: {e}")

    await safe_edit_message(
        query,
        f"{EM_OK} Жалоба принята. Разберёмся в течение 24 часов.\n\nСпасибо, что помогаете делать площадку безопасной.",
        [[InlineKeyboardButton(EM_ARROW_L + " К профилю продавца", callback_data=f"seller_profile:{target_id}")]]
    )

