async def admin_price_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Получаем новую цену от админа."""
    if not await is_admin(update.effective_user.id):
        return

    key   = context.user_data.get("admin_price_key")
    label = context.user_data.get("admin_price_label", key)

    if not key:
        return States.MAIN_MENU

    text = update.message.text.strip()
    try:
        new_price = int(text)
        if new_price <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text(
            f"{EM_FAIL} Введите целое число больше 0.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(EM_ARROW_L + " Отмена", callback_data="admin_prices")
            ]])
        )
        return States.ADMIN_PRICE_INPUT

    set_price(key, new_price)
    context.user_data.pop("admin_price_key", None)
    context.user_data.pop("admin_price_label", None)

    await update.message.reply_text(
        f"{EM_OK} <b>{label}</b> {EM_ARROW_R} <b>{new_price} ₽</b>",
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton(EM_ARROW_L + " К ценам", callback_data="admin_prices")
        ]])
    )
    return States.MAIN_MENU

