def _detect_carrier(track_num: str) -> str:
    """Определяет службу доставки по формату трек-номера."""
    t = track_num.strip().upper().replace(" ", "")

    # Почта России: 2 буквы + 9 цифр + 2 буквы (международный), или 14 цифр (внутренний)
    if re.match(r'^[A-Z]{2}\d{9}[A-Z]{2}$', t):
        return "pochta"
    if re.match(r'^\d{14}$', t):
        return "pochta"

    # СДЭК: 10–11 цифр (внутренний номер заказа)
    if re.match(r'^\d{10,11}$', t):
        return "cdek"

    # Boxberry: префикс BB или BX
    if t.startswith("BB") or t.startswith("BX"):
        return "boxberry"

    # DPD: 12 цифр
    if re.match(r'^\d{12}$', t):
        return "dpd"

    # Яндекс Доставка / Маркет
    if t.startswith(("YD", "YANDEX", "ORD-")):
        return "yandex"

    # Boxberry / Ozon Rocket: 7–9 цифр
    if re.match(r'^\d{7,9}$', t):
        return "boxberry"

    return "pochta"  # по умолчанию — Почта России


