#  MINI APP API SERVER (aiohttp)
# =====================================================================

def verify_telegram_init_data(init_data: str) -> Optional[int]:
    """Проверяет подпись initData от Telegram WebApp, возвращает user_id или None.

    По спеке Telegram data_check_string строится из ДЕКОДИРОВАННЫХ значений
    (как в aiogram: parse_qsl декодирует %XX и '+'→пробел), иначе подпись
    не сойдётся ни для одного реального initData (user-JSON всегда encoded).
    """
    try:
        import urllib.parse
        params = dict(urllib.parse.parse_qsl(init_data, keep_blank_values=True))
        received_hash = params.pop('hash', '')
        data_check = '\n'.join(f"{k}={v}" for k, v in sorted(params.items()))
        secret = hmac.new(b"WebAppData", TOKEN.strip().encode(), hashlib.sha256).digest()
        expected = hmac.new(secret, data_check.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(received_hash, expected):
            return None
        user = json.loads(params.get('user', '{}'))
        return user.get('id')
    except Exception as e:
        logger.error(f"initData verify: {e}")
        return None

def get_viewer_id(request: aiohttp_web.Request) -> Optional[int]:
    """Извлекает user_id из initData заголовка запроса"""
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    if not init_data:
        return None
    return verify_telegram_init_data(init_data)

async def api_get_chat(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/chat/{session_id} — загрузить диалог"""
    viewer_id = get_viewer_id(request)
    if not viewer_id:
        return aiohttp_web.json_response({'error': 'unauthorized'}, status=401)

    session_id = int(request.match_info['session_id'])
    session = get_chat_session(session_id)
    if not session:
        return aiohttp_web.json_response({'error': 'not found'}, status=404)

    if viewer_id not in (session['buyer_id'], session['seller_id']):
        return aiohttp_web.json_response({'error': 'forbidden'}, status=403)

    other_id = session['seller_id'] if viewer_id == session['buyer_id'] else session['buyer_id']
    other_user = db.get_user(other_id)
    other_name = other_user.get('first_name', f'#{other_id}') if other_user else f'#{other_id}'
    other_anon = get_anon_id(other_user) if other_user else str(other_id)
    verify = db.get_verification(other_id)
    other_verified = verify and verify.get('status') == 'verified'

    ad = db.get_ad(session['ad_id'])

    cursor = db.conn.cursor()
    cursor.execute('''
        SELECT id, sender_id, text, file_id, msg_type, created_at
        FROM chat_messages WHERE session_id=?
        ORDER BY created_at ASC
    ''', (session_id,))
    messages = [dict(r) for r in cursor.fetchall()]

    return aiohttp_web.json_response({
        'viewer_id': viewer_id,
        'other_name': other_name,
        'other_anon': other_anon,
        'other_verified': bool(other_verified),
        'ad_title': ad['title'][:50] if ad else '',
        'ad_price': ad['price'] if ad else None,
        'messages': messages,
    })

async def api_poll_messages(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/chat/{session_id}/poll?after={id} — новые сообщения"""
    viewer_id = get_viewer_id(request)
    if not viewer_id:
        return aiohttp_web.json_response({'error': 'unauthorized'}, status=401)

    session_id = int(request.match_info['session_id'])
    session = get_chat_session(session_id)
    if not session or viewer_id not in (session['buyer_id'], session['seller_id']):
        return aiohttp_web.json_response({'error': 'forbidden'}, status=403)

    after_id = int(request.rel_url.query.get('after', 0))
    cursor = db.conn.cursor()
    cursor.execute('''
        SELECT id, sender_id, text, file_id, msg_type, created_at
        FROM chat_messages WHERE session_id=? AND id > ?
        ORDER BY created_at ASC
    ''', (session_id, after_id))
    messages = [dict(r) for r in cursor.fetchall()]
    return aiohttp_web.json_response({'messages': messages})

async def api_send_message(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/chat/{session_id}/send — отправить сообщение"""
    viewer_id = get_viewer_id(request)
    if not viewer_id:
        return aiohttp_web.json_response({'error': 'unauthorized'}, status=401)

    session_id = int(request.match_info['session_id'])
    session = get_chat_session(session_id)
    if not session or viewer_id not in (session['buyer_id'], session['seller_id']):
        return aiohttp_web.json_response({'error': 'forbidden'}, status=403)

    try:
        body = await request.json()
    except Exception:
        return aiohttp_web.json_response({'error': 'bad json'}, status=400)

    text = (body.get('text') or '').strip()
    if not text or len(text) > 4000:
        return aiohttp_web.json_response({'error': 'invalid text'}, status=400)

    save_chat_message(session_id, viewer_id, text=text)

    # Уведомить получателя
    recipient_id = session['seller_id'] if viewer_id == session['buyer_id'] else session['buyer_id']
    ad = db.get_ad(session['ad_id'])
    sender_user = db.get_user(viewer_id)
    sender_anon = get_anon_id(sender_user) if sender_user else str(viewer_id)

    reply_kb = InlineKeyboardMarkup([[
        InlineKeyboardButton(EM_ARROW_R + " Ответить", callback_data=f"open_chat:{session_id}")
    ]])

    try:
        _app = _get_bot_app()
        if _app:
            await _app.bot.send_message(
                chat_id=recipient_id,
                text=(
                    f"{EM_DOT} <b>Новое сообщение</b>\n"
                    f"По объявлению «{ad['title'][:35] if ad else '?'}»\n\n"
                    f"<i>{text[:200]}</i>"
                ),
                reply_markup=reply_kb,
                parse_mode=ParseMode.HTML
            )
    except Exception as e:
        logger.error(f"api send notify: {e}")

    return aiohttp_web.json_response({'ok': True})


# ── Вложения в диалоге Mini App: фото / видео / голосовые ────────────────────
# file_id таких сообщений — локальный путь /api/ads/photos/<файл>: Mini App
# грузит файл сам, в отличие от бота, который хранит Telegram file_id.
CHAT_MEDIA_LIMITS = {
    'photo': 10 * 1024 * 1024,
    'voice': 10 * 1024 * 1024,
    # Платформа режет запрос на ~10 МБ, поэтому 25 МБ были фикцией:
    # держим 9 МБ — ровно столько же, сколько пускает клиент.
    'video': 9 * 1024 * 1024,
}


def _classify_chat_media(ctype: str, data: bytes) -> str:
    """Тип вложения для чата: photo | video | voice (пустая строка — не поддержано).

    Смотрим и content-type, и «магические» байты: браузеры и Telegram
    регулярно присылают пустой тип или application/octet-stream.
    """
    ctype = (ctype or '').lower()
    if ctype.startswith('video/') or data[4:12] in (b'ftypisom', b'ftypmp42', b'ftypqt  ', b'ftypM4V '):
        return 'video'
    if (ctype.startswith('audio/') or data[:4] == b'OggS' or data[:3] == b'ID3'
            or data[:2] in (b'\xff\xfb', b'\xff\xf3', b'\xff\xf2')):
        return 'voice'
    if ctype.startswith('image/'):
        return 'photo'
    if data[:3] == b'\xff\xd8\xff' or data[:8] == b'\x89PNG\r\n\x1a\n':
        return 'photo'
    if data[:4] == b'RIFF' and data[8:12] == b'WEBP':
        return 'photo'
    if data[:4] == b'\x1a\x45\xdf\xa3':   # webm/mkv — в чате это обычно видео
        return 'video'
    return ''


def _chat_media_ext(ctype: str, data: bytes, kind: str) -> str:
    """Расширение файла вложения."""
    if kind == 'photo':
        return _guess_photo_ext(ctype, data)
    if data[4:12] in (b'ftypqt  ',):
        return 'mov'
    if data[4:12] in (b'ftypisom', b'ftypmp42', b'ftypM4V '):
        return 'mp4'
    if data[:4] == b'\x1a\x45\xdf\xa3':
        return 'webm'
    if data[:4] == b'OggS':
        return 'ogg'
    if data[:3] == b'ID3' or data[:2] in (b'\xff\xfb', b'\xff\xf3'):
        return 'mp3'
    if kind == 'video':
        return 'mp4'
    return 'ogg'


def _media_content_type(ctype: str, data: bytes) -> str:
    """MIME по «магическим» байтам.

    Прокси отдавал всё как image/jpeg, из-за чего видео не проигрывалось:
    браузеру нужен video/mp4, а не картинка.
    """
    c = (ctype or '').lower()
    if c and c != 'application/octet-stream':
        return c
    if data[:4] == b'\x1a\x45\xdf\xa3':
        return 'video/webm'
    if data[4:12] in (b'ftypisom', b'ftypmp42', b'ftypmp41', b'ftypM4V '):
        return 'video/mp4'
    if data[4:12] == b'ftypqt  ':
        return 'video/quicktime'
    if data[:3] == b'\xff\xd8\xff':
        return 'image/jpeg'
    if data[:8] == b'\x89PNG\r\n\x1a\n':
        return 'image/png'
    if data[:4] == b'RIFF' and data[8:12] == b'WEBP':
        return 'image/webp'
    if data[:3] == b'GIF':
        return 'image/gif'
    if data[:4] == b'OggS':
        return 'video/ogg' if data[28:32] == b'theo' else 'audio/ogg'
    return 'application/octet-stream'


def _story_media_url(media) -> str:
    """Ссылка на медиа истории.

    Истории из Mini App хранят локальный путь, а созданные через бота —
    Telegram file_id: его заворачиваем в прокси, чтобы токен не утекал.
    """
    s = str(media or '')
    if not s or s.startswith('{'):
        return ''
    if s.startswith('/') or s.startswith('http'):
        return s
    return f"/api/photo/{s}"


async def api_chat_media_upload(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/chat/{session_id}/media — вложение в диалог (multipart, поле file).

    Сохраняет файл локально и создаёт сообщение с msg_type photo/video/voice.
    Получателю пересылаем НАСТОЯЩЕЕ вложение через бота, а не текстовую
    заглушку — иначе он видит только «пришло сообщение» без картинки.
    """
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        session_id = int(request.match_info['session_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    session = get_chat_session(session_id)
    if not session or viewer_id not in (session['buyer_id'], session['seller_id']):
        return _miniapp_err('forbidden', 403)

    try:
        form = await request.post()
    except Exception:
        return _miniapp_err('bad_multipart', 400)
    field = form.get('file') or form.get('media') or form.get('photo')
    if field is None:
        extra = form.getall('file', [])
        field = extra[0] if extra else None
    if field is None:
        return _miniapp_err('no_file', 400)

    data = field.file.read(CHAT_MEDIA_LIMITS['video'] + 1)
    if not data:
        return _miniapp_err('empty_file', 400)
    ctype = getattr(field, 'content_type', '') or ''
    kind = _classify_chat_media(ctype, data)
    if not kind:
        return _miniapp_json(
            {'error': 'unsupported_media', 'detail': 'поддерживаются фото, видео и голосовые'},
            status=415,
        )
    limit = CHAT_MEDIA_LIMITS[kind]
    if len(data) > limit:
        return _miniapp_json(
            {'error': 'too_large', 'detail': f'{kind}: до {limit // (1024 * 1024)} МБ'},
            status=413,
        )

    upload_dir = os.environ.get('UPLOAD_DIR', '/data/uploads')
    try:
        os.makedirs(upload_dir, exist_ok=True)
    except Exception:
        pass
    ext = _chat_media_ext(ctype, data, kind)
    name = f"c{viewer_id}_{int(_time.time())}_{kind[0]}.{ext}"
    path = os.path.join(upload_dir, name)
    try:
        with open(path, 'wb') as fh:
            fh.write(data)
    except Exception as e:
        logger.error(f"chat media save: {e}")
        return _miniapp_err('save_failed', 500)

    url = f"/api/ads/photos/{name}"
    try:
        msg_id = save_chat_message(session_id, viewer_id, text='', file_id=url, msg_type=kind)
    except Exception as e:
        logger.error(f"chat media save message: {e}")
        return _miniapp_err('save_failed', 500)

    # Уведомляем получателя настоящим вложением
    recipient_id = session['seller_id'] if viewer_id == session['buyer_id'] else session['buyer_id']
    ad = db.get_ad(session['ad_id'])
    sender_user = db.get_user(viewer_id)
    sender_anon = get_anon_id(sender_user) if sender_user else str(viewer_id)
    caption = (f"{EM_DOT} <b>{sender_anon}</b>\n"
               f"По объявлению «{ad['title'][:35] if ad else '?'}»")
    reply_kb = InlineKeyboardMarkup([[
        InlineKeyboardButton(EM_ARROW_R + " Ответить", callback_data=f"open_chat:{session_id}")
    ]])
    try:
        _app = _get_bot_app()
        if _app:
            with open(path, 'rb') as fh:
                if kind == 'photo':
                    await _app.bot.send_photo(chat_id=recipient_id, photo=fh, caption=caption,
                                              reply_markup=reply_kb, parse_mode=ParseMode.HTML)
                elif kind == 'video':
                    await _app.bot.send_video(chat_id=recipient_id, video=fh, caption=caption,
                                              reply_markup=reply_kb, parse_mode=ParseMode.HTML)
                else:
                    # У send_voice в Bot API нет caption — подпись отдельным сообщением
                    await _app.bot.send_voice(chat_id=recipient_id, voice=fh, reply_markup=reply_kb)
                    await _app.bot.send_message(chat_id=recipient_id, text=caption,
                                                parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"api chat media notify: {e}")

    try:
        cur = db.conn.cursor()
        cur.execute('SELECT id, sender_id, text, file_id, msg_type, created_at '
                    'FROM chat_messages WHERE id=?', (msg_id,))
        row = cur.fetchone()
        message = dict(row) if row else None
    except Exception:
        message = None
    return _miniapp_json({'ok': True, 'message': message}, status=201)


# ── API историй продавцов ────────────────────────────────────────────────────
def _story_public(story: Dict, with_views: bool = False) -> Dict:
    """История для клиента. reject_reason и просмотры — только автору."""
    data = {
        'id': story['id'],
        'user_id': story['user_id'],
        'media': _story_media_url(story['media']),
        'media_type': story['media_type'],
        'caption': story.get('caption') or '',
        'ad_id': story.get('ad_id'),
        'status': story.get('status'),
        'created_at': story.get('created_at'),
        'expires_at': story.get('expires_at'),
    }
    if with_views:
        data['reject_reason'] = story.get('reject_reason') or ''
        data['views'] = get_story_viewers(story['id'])
    return data


async def api_miniapp_stories(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/stories — рельс историй и состояние своих.

    Свои истории отдаём с просмотрами и причиной отклонения: автор должен
    понимать, почему история не появилась в ленте.
    """
    viewer_id = _miniapp_viewer(request) or 0
    try:
        authors = get_story_rail(viewer_id)
        # Истории из бота хранят file_id — отдаём их через прокси
        for author in authors:
            for story in author.get('stories', []):
                story['media'] = _story_media_url(story.get('media'))
    except Exception as e:
        logger.error(f"stories rail: {e}")
        return _miniapp_err('load_failed', 500)

    mine = {'stories': [], 'can_post': False, 'active': 0, 'pending': 0,
            'max_active': STORY_MAX_ACTIVE, 'max_pending': STORY_MAX_PENDING}
    if viewer_id:
        active = count_user_stories(viewer_id, ('active',))
        pending = count_user_stories(viewer_id, ('pending',))
        mine.update({
            'stories': [_story_public(s, with_views=True) for s in get_user_stories(viewer_id)],
            'active': active,
            'pending': pending,
            'can_post': active < STORY_MAX_ACTIVE and pending < STORY_MAX_PENDING,
        })
    return _miniapp_json({'authors': authors, 'mine': mine})


async def api_miniapp_story_create(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/stories — добавить историю (multipart: file, caption, ad_id).

    Создаётся в статусе pending: у нас пре-модерация для всех, в ленту
    история попадает только после одобрения администратором.
    """
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)

    active = count_user_stories(viewer_id, ('active',))
    pending = count_user_stories(viewer_id, ('pending',))
    if active >= STORY_MAX_ACTIVE:
        return _miniapp_json({'error': 'limit_active',
                              'detail': f'у вас уже {STORY_MAX_ACTIVE} историй'}, status=429)
    if pending >= STORY_MAX_PENDING:
        return _miniapp_json({'error': 'limit_pending',
                              'detail': 'предыдущие ещё на проверке, подождите'}, status=429)

    try:
        form = await request.post()
    except Exception:
        return _miniapp_err('bad_multipart', 400)
    field = form.get('file') or form.get('media') or form.get('photo')
    if field is None:
        extra = form.getall('file', [])
        field = extra[0] if extra else None
    if field is None:
        return _miniapp_err('no_file', 400)

    data = field.file.read(CHAT_MEDIA_LIMITS['video'] + 1)
    if not data:
        return _miniapp_err('empty_file', 400)
    ctype = getattr(field, 'content_type', '') or ''
    kind = _classify_chat_media(ctype, data)
    if kind == 'voice':
        return _miniapp_json({'error': 'unsupported_media',
                              'detail': 'для истории подойдут фото или видео'}, status=415)
    if not kind:
        return _miniapp_json({'error': 'unsupported_media',
                              'detail': 'поддерживаются фото и видео'}, status=415)
    limit = CHAT_MEDIA_LIMITS[kind]
    if len(data) > limit:
        return _miniapp_json({'error': 'too_large',
                              'detail': f'{kind}: до {limit // (1024 * 1024)} МБ'}, status=413)

    caption = (form.get('caption') or '')[:STORY_CAPTION_MAX]
    ad_id = None
    raw_ad = form.get('ad_id')
    if raw_ad:
        try:
            ad_id = int(raw_ad)
            ad = db.get_ad(ad_id)
            # привязывать можно только к своему объявлению
            if not ad or int(ad.get('user_id') or 0) != int(viewer_id):
                ad_id = None
        except (TypeError, ValueError):
            ad_id = None

    upload_dir = os.environ.get('UPLOAD_DIR', '/data/uploads')
    try:
        os.makedirs(upload_dir, exist_ok=True)
    except Exception:
        pass
    ext = _chat_media_ext(ctype, data, kind)
    name = f"s{viewer_id}_{int(_time.time())}.{ext}"
    path = os.path.join(upload_dir, name)
    try:
        with open(path, 'wb') as fh:
            fh.write(data)
    except Exception as e:
        logger.error(f"story save: {e}")
        return _miniapp_err('save_failed', 500)

    try:
        story_id = create_story(viewer_id, f"/api/ads/photos/{name}", kind, caption, ad_id)
    except Exception as e:
        logger.error(f"story create: {e}")
        return _miniapp_err('save_failed', 500)

    story = get_story(story_id)
    try:
        await _notify_story_moderation(story)
    except Exception as e:
        logger.warning(f"story moderation notify: {e}")

    return _miniapp_json({'ok': True, 'story': _story_public(story, with_views=True)}, status=201)


async def api_miniapp_story_view(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/stories/{story_id}/view — отметить историю просмотренной."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        story_id = int(request.match_info['story_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    mark_story_viewed(story_id, viewer_id)
    return _miniapp_json({'ok': True, 'views': get_story_viewers(story_id)})


async def api_miniapp_story_delete(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """DELETE /api/stories/{story_id} — автор удаляет свою историю."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        story_id = int(request.match_info['story_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    story = get_story(story_id)
    if not story:
        return _miniapp_err('not_found', 404)
    if int(story['user_id']) != int(viewer_id):
        return _miniapp_err('forbidden', 403)
    try:
        _remove_story_file(story['media'])
        cursor = db.conn.cursor()
        cursor.execute('DELETE FROM story_views WHERE story_id=?', (story_id,))
        cursor.execute('DELETE FROM stories WHERE id=?', (story_id,))
        db.conn.commit()
    except Exception as e:
        logger.error(f"story delete: {e}")
        return _miniapp_err('delete_failed', 500)
    return _miniapp_json({'ok': True})


# ── API аукционов ────────────────────────────────────────────────────────────
async def api_miniapp_findings(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/findings — находки, отсортированные по выгоде.

    Отдаём то, что заметно дешевле медианы по категории: именно за это
    подписчик и держится, а не за «свежую публикацию».
    """
    viewer_id = _miniapp_viewer(request)
    try:
        min_discount = max(0, int(request.query.get('min_discount', 10) or 10))
    except ValueError:
        min_discount = 10
    category = request.query.get('category', '')
    city = request.query.get('city', '')
    try:
        limit = min(max(int(request.query.get('limit', 20) or 20), 1), 100)
    except ValueError:
        limit = 20
    try:
        offset = max(int(request.query.get('offset', 0) or 0), 0)
    except ValueError:
        offset = 0

    # Лента = то, что бот УЖЕ прислал этому человеку. Источник истины —
    # таблица отправок: она заполняется там же, где уходит сообщение,
    # поэтому лента и чат всегда совпадают. Раньше лента собиралась по
    # своим правилам, и в неё попадали случайные товары вроде пудры за 100 ₽.
    # Лента показывает ВСЁ, что нашлось по критериям человека — включая то,
    # что бот не отправил в чат. Так видно, что поиск работает и сколько
    # вариантов есть, даже если сообщение ушло не про каждый.
    crits = [c for c in get_user_criteria(viewer_id) if c.get('active')]
    if not crits:
        return _miniapp_json({'items': [], 'has_more': False, 'need_criteria': True})

    where = ["a.status='active'", "a.source <> 'polka'"]
    params: List = []
    titles_cond, titles_params = [], []
    for crit in crits:
        word_cond, word_params = [], []
        for w in re.split(r'\s+', str(crit.get('query') or '').lower()):
            variants = query_word_variants(w)
            if not variants:
                continue
            word_cond.append("(" + " OR ".join("COALESCE(a.title_lower, a.title) LIKE ?"
                                               for _ in variants) + ")")
            word_params.extend(f"%{v}%" for v in variants)
        if word_cond:
            titles_cond.append("(" + " AND ".join(word_cond) + ")")
            titles_params.extend(word_params)
    if not titles_cond:
        return _miniapp_json({'items': [], 'has_more': False, 'need_criteria': True})
    where.append("(" + " OR ".join(titles_cond) + ")")
    params.extend(titles_params)
    for bad in HUNT_ACCESSORY_WORDS:
        where.append("COALESCE(a.title_lower, a.title) NOT LIKE ?")
        params.append(f"%{bad}%")
    if city:
        where.append("a.city = ?")
        params.append(city)
    try:
        cursor = db.conn.cursor()
        cursor.execute(
            f"SELECT a.*, (SELECT COUNT(*) FROM search_notifications_sent s2 "
            f" WHERE s2.ad_id = a.id AND s2.user_id = ?) AS was_sent "
            f"FROM ads a WHERE {' AND '.join(where)} "
            f"ORDER BY COALESCE(a.discount_percent, 0) DESC, a.id DESC LIMIT ? OFFSET ?",
            (viewer_id, *params, limit + 1, offset))
        rows = [dict(r) for r in cursor.fetchall()]
    except Exception as e:
        logger.error(f"findings list: {e}")
        return _miniapp_err('load_failed', 500)

    has_more = len(rows) > limit
    rows = rows[:limit]
    fav_counts, fav_mine = _miniapp_fav_map([a['id'] for a in rows], viewer_id)
    return _miniapp_json({
        'items': [_miniapp_serialize_ad(a, viewer_id, fav_counts, fav_mine) for a in rows],
        'has_more': has_more,
    })


async def api_miniapp_auctions(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/auctions — активные лоты.

    По умолчанию сначала те, что заканчиваются раньше: там таймер важнее
    всего, а «свежие» лоты и так видны в общей ленте.
    """
    viewer_id = _miniapp_viewer(request)
    order = "ends_at ASC" if (request.query.get('sort') or 'ending') == 'ending' \
        else "created_at DESC"
    try:
        cursor = db.conn.cursor()
        cursor.execute(f'''
            SELECT * FROM ads
            WHERE sale_type='auction' AND status='active'
              AND ends_at IS NOT NULL AND ends_at > ?
            ORDER BY {order} LIMIT 60
        ''', (get_moscow_time().isoformat(),))
        ads = [dict(r) for r in cursor.fetchall()]
    except Exception as e:
        logger.error(f"auctions list: {e}")
        return _miniapp_err('load_failed', 500)
    fav_counts, fav_mine = _miniapp_fav_map([a['id'] for a in ads], viewer_id)
    return _miniapp_json({
        'items': [_miniapp_serialize_ad(a, viewer_id, fav_counts, fav_mine) for a in ads],
    })


async def api_miniapp_place_bid(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/ads/{ad_id}/bid — сделать ставку."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        ad_id = int(request.match_info['ad_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    try:
        body = await request.json()
    except Exception:
        return _miniapp_err('bad_json', 400)

    res = place_bid(ad_id, viewer_id, (body or {}).get('amount'))
    if not res.get('ok'):
        code = res.get('error')
        status = 400
        if code in ('not_auction', 'not_active', 'ended'):
            status = 409
        elif code == 'own_lot':
            status = 403
        payload = {'error': code}
        if res.get('minimum'):
            payload['minimum'] = res['minimum']
        if res.get('buy_now'):
            payload['buy_now'] = res['buy_now']
        return _miniapp_json(payload, status=status)

    ad = res['ad']
    title = str(ad.get('title') or '')[:40]
    amount = f"{res['amount']:,}".replace(',', ' ')
    await _notify_auction(ad['user_id'],
                          f"{EM_DOT} <b>Новая ставка</b>\n«{title}» — {amount} ₽", ad_id)
    prev = res.get('outbid')
    if prev and int(prev['user_id']) != int(viewer_id):
        await _notify_auction(
            prev['user_id'],
            f"{EM_WARN} <b>Вашу ставку перебили</b>\n"
            f"«{title}» — теперь {amount} ₽\n\nУспейте поднять, пока идут торги.", ad_id)
    return _miniapp_json({
        'ok': True,
        'ad': _miniapp_serialize_ad(ad, viewer_id),
        'amount': res['amount'],
        'extended': bool(res.get('extended')),
    })


async def api_miniapp_buy_now(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/ads/{ad_id}/buy-now — выкупить лот сразу."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        ad_id = int(request.match_info['ad_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    res = buy_now(ad_id, viewer_id)
    if not res.get('ok'):
        code = res.get('error')
        status = 409 if code in ('not_auction', 'not_active', 'ended') else 400
        if code == 'own_lot':
            status = 403
        return _miniapp_json({'error': code}, status=status)
    await _notify_auction_finished({**res['ad'], 'top_bid': res['amount']})
    return _miniapp_json({
        'ok': True,
        'ad': _miniapp_serialize_ad(res['ad'], viewer_id),
        'amount': res['amount'],
    })


async def api_miniapp_ad_bids(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/ads/{ad_id}/bids — история ставок (имена анонимны)."""
    viewer_id = _miniapp_viewer(request)
    try:
        ad_id = int(request.match_info['ad_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    items = []
    for b in get_bids(ad_id, limit=30):
        user = db.get_user(b['user_id'])
        items.append({
            'amount': b['amount'],
            'created_at': b['created_at'],
            'status': b['status'],
            'is_me': bool(viewer_id and int(b['user_id']) == int(viewer_id)),
            'name': get_anon_id(user) if user else f"id{b['user_id']}",
        })
    return _miniapp_json({'items': items})


async def api_miniapp_my_bids(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/my-bids — мои ставки с понятным состоянием."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    items = []
    for row in get_my_bids(viewer_id):
        if row.get('ad_status') == 'ended':
            state = 'won' if int(row.get('winner_id') or 0) == int(viewer_id) else 'lost'
        elif row.get('ad_status') == 'ended_unsold':
            state = 'lost'
        elif row.get('bid_status') == 'active':
            state = 'leading'
        else:
            state = 'outbid'
        photos = row.get('photos') or []
        if isinstance(photos, str):
            try:
                photos = json.loads(photos)
            except Exception:
                photos = []
        items.append({
            'ad_id': row['ad_id'],
            'title': row.get('title') or '',
            'photo': (_miniapp_photo_urls(photos) or [''])[0],
            'amount': row['amount'],
            'current_bid': row.get('current_bid') or 0,
            'created_at': row.get('bid_at') or '',
            'ends_at': row.get('ends_at') or '',
            # остаток считает сервер: часы на устройстве могут расходиться
            'time_left': auction_time_left(row),
            'state': state,
        })
    return _miniapp_json({'items': items})


async def api_serve_html(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /chat — отдаёт мини-апп HTML"""
    html_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'chat_miniapp.html')
    if not os.path.exists(html_path):
        return aiohttp_web.Response(text='Mini App not found', status=404)
    with open(html_path, 'r', encoding='utf-8') as f:
        content = f.read()
    return aiohttp_web.Response(text=content, content_type='text/html', charset='utf-8')

_bot_app_ref = None
def _get_bot_app():
    return _bot_app_ref

# ── Мост к MAX-боту ──────────────────────────────────────────────────────
# Оба бота (TG и MAX) работают в одном процессе (см. run_bots.py), но наружу
# в контейнере открыт только порт TG-бота (containerPort в amvera.yml).
# Поэтому вебхуки PayAnyWay для покупок, сделанных в MAX-боте, физически
# приходят на HTTP-сервер ЭТОГО (TG) бота. Чтобы такие платежи правильно
# уведомляли пользователя и закрепляли объявление через MAX Bot API (а не
# через Telegram Bot API), run_bots.py передаёт сюда ссылку на модуль
# polka_max_bot.py через set_max_bot_module().
_max_bot_module = None

_tg_bot_instance = None
def set_tg_bot_instance(bot):
    global _tg_bot_instance
    _tg_bot_instance = bot

def set_max_bot_module(module):
    """Вызывается из run_bots.py после импорта обоих ботов."""
    global _max_bot_module
    _max_bot_module = module
    logger.info("PAW bridge: модуль MAX-бота подключён к TG webhook-серверу")

# ── Кросс-платформенные фото объявлений ──────────────────────────────────
# Объявление, созданное через MAX-бота, хранит фото в поле photos не как
# обычный Telegram file_id, а как JSON-блок с полями MAX API (url/token/…) —
# см. max_compat.py: Bot._normalize_message кладёт туда json.dumps(payload).
# Если такой JSON-блок скормить напрямую в Telegram Bot API как photo=...,
# Telegram пытается распарсить всю JSON-строку как URL и падает с
# "Invalid file http url specified: wrong port number specified in the url".
# Эта функция распознаёт такой случай, достаёт из него прямую ссылку
# (если она есть) или скачивает байты через MAX-бота и отдаёт их Telegram
# уже как обычный файл.
async def resolve_ad_photo(photo_ref: str):
    """Возвращает объект, пригодный для photo=/InputMediaPhoto() в PTB:
    исходную строку (обычный TG file_id/URL) или BytesIO с байтами фото."""
    if not photo_ref or not isinstance(photo_ref, str) or not photo_ref.startswith("{"):
        return photo_ref  # обычный TG file_id — как есть

    # Похоже на JSON-блок из MAX — пробуем достать прямую ссылку
    try:
        payload = json.loads(photo_ref)
    except Exception:
        return photo_ref  # не JSON — отдаём как есть, пусть Telegram сам решает

    direct_url = None
    if isinstance(payload, dict):
        for key in ("url", "file_path", "filePath", "link", "download_url"):
            val = payload.get(key)
            if isinstance(val, str) and val.startswith("http"):
                direct_url = val
                break

    if direct_url:
        return direct_url  # чистый URL — Telegram сам скачает

    # Прямой ссылки нет — просим MAX-бота скачать байты через его API
    if _max_bot_module is not None:
        try:
            photo_bytes = await _max_bot_module.bot.get_photo_bytes(photo_ref)
            if photo_bytes:
                return io.BytesIO(photo_bytes)
        except Exception as e:
            logger.warning(f"resolve_ad_photo: не удалось скачать через MAX-бота: {e}")

    return None  # нечего показать — вызывающий код должен обработать None


async def _dispatch_max_paw_order(order_id: str) -> bool:
    """
    Передаёт обработку оплаченного счёта PayAnyWay в модуль MAX-бота,
    если order_id принадлежит MAX-боту (содержит метку '_max_').
    Возвращает True, если платёж был передан на обработку.
    """
    if _max_bot_module is None:
        logger.error(f"PAW webhook: заказ {order_id} относится к MAX-боту, "
                     f"но модуль MAX-бота не подключён (set_max_bot_module не вызван)")
        return False

    max_app_ref = getattr(_max_bot_module, "_bot_app_ref", None)
    if max_app_ref is None:
        logger.error(f"PAW webhook: MAX-бот ещё не инициализирован (_bot_app_ref пуст), "
                     f"заказ {order_id} не обработан")
        return False

    max_bot_obj = max_app_ref.bot
    max_job_queue = getattr(max_app_ref, "job_queue", None)

    try:
        if order_id.startswith("sub_"):
            await _max_bot_module._process_paw_paid_sub(order_id, max_bot_obj)
        elif order_id.startswith("pin_"):
            await _max_bot_module._process_paw_paid_pin(order_id, max_bot_obj, job_queue=max_job_queue)
        else:
            logger.warning(f"PAW webhook: неизвестный тип MAX-заказа {order_id}")
            return False
        return True
    except Exception as e:
        logger.error(f"PAW webhook: ошибка обработки MAX-заказа {order_id}: {e}", exc_info=True)
        return False



async def api_check_promo(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/check_promo?code=КОД&plan=standard|pro"""
    cors = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
    }
    if request.method == 'OPTIONS':
        return aiohttp_web.Response(status=200, headers=cors)

    code = request.rel_url.query.get('code', '').strip().upper()
    plan = request.rel_url.query.get('plan', 'standard').lower()

    if not code:
        return aiohttp_web.json_response({'valid': False, 'error': 'Введите промокод'}, headers=cors)

    promo = db.get_promocode(code)
    if not promo:
        return aiohttp_web.json_response({'valid': False, 'error': 'Промокод недействителен или истёк'}, headers=cors)

    discount = promo['discount_percent']
    tariff_key = 'Free'
    base_price = 0  # тарифов нет, монетизация через закрепы
    discounted_price = round(base_price * (1 - discount / 100))

    crypto_url   = resolve_crypto_url(discount, discounted_price, plan)

    return aiohttp_web.json_response({
        'valid': True,
        'code': code,
        'discount': discount,
        'price': discounted_price,
        'base_price': base_price,
        'duration_days': promo.get('duration_days', 30),
        'crypto_url': crypto_url,
    }, headers=cors)


async def api_health(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """Эндпоинт проверки работоспособности сервера"""
    return aiohttp_web.Response(
        text='{"status":"ok","server":"polka-bot"}',
        content_type="application/json"
    )


# ═══════════════════════════════════════════════════════════════════════
#  CRYPTO BOT WEBHOOK — автоматическая активация подписки
# ═══════════════════════════════════════════════════════════════════════

async def _activate_service_from_invoice(invoice_id: int, bot, job_queue=None) -> bool:
    """
    Активирует услугу по оплаченному счёту Crypto Bot:
    - plan = 'bump'  → поднимает объявление (обновляет created_at)
    - plan = 'pin'   → закрепляет объявление в канале на 24 часа
    """
    cursor = db.conn.cursor()
    cursor.execute("SELECT * FROM crypto_invoices WHERE invoice_id=?", (invoice_id,))
    row = cursor.fetchone()
    if not row:
        logger.warning(f"CryptoBot: invoice {invoice_id} not found in DB")
        return False

    inv = dict(row)
    if inv["status"] == "paid":
        logger.info(f"CryptoBot: invoice {invoice_id} already processed")
        return False

    user_id     = inv["user_id"]
    plan        = inv["plan"]
    rub_amount  = inv["amount_rub"]
    usdt_amount = inv.get("amount_crypto", "?")
    now_iso     = get_moscow_time().isoformat()

    cursor.execute("UPDATE crypto_invoices SET status='paid', paid_at=? WHERE invoice_id=?", (now_iso, invoice_id))
    db.conn.commit()

    payload = inv.get("payload", "")
    parts = payload.split(":")

    if plan == "subscription":
        end_date = compute_premium_extension(user_id)
        db.update_user(user_id, tariff='Premium', tariff_end_date=end_date,
                       daily_ads_count=0, photo_search_count=0, ai_gen_count=0)
        try:
            db.process_referral_reward(user_id, rub_amount)
        except Exception as _rre:
            logger.warning(f"CryptoBot sub: referral reward error for user={user_id}: {_rre}")
        try:
            await bot.send_message(
                chat_id=user_id,
                text=f"{EM_OK} <b>ПОЛКА ПЛЮС активен!</b>\n\n"
                     f"Действует до: <b>{format_date_ru(end_date)}</b> (МСК)\n"
                     f"Срок действия: {SUBSCRIPTION_DAYS} дней.",
                parse_mode=ParseMode.HTML,
            )
        except Exception as _e:
            logger.warning(f"CryptoBot sub notify: {_e}")
        logger.info(f"CryptoBot: subscription активирован user={user_id} до {end_date}")
        return True

    # Парсим ad_id из payload: "bump:{user_id}:{ad_id}" или "pin:{user_id}:{ad_id}:{pin_type}"
    try:
        ad_id = int(parts[2])
    except Exception:
        logger.error(f"CryptoBot: cannot parse payload '{payload}'")
        return False

    ad = db.get_ad(ad_id)
    if not ad:
        logger.error(f"CryptoBot: ad {ad_id} not found")
        return False

    if plan == "bump":
        # Поднять: обновляем created_at
        cursor.execute("UPDATE ads SET created_at=?, expires_at=datetime(?, '+30 days') WHERE id=?",
                       (now_iso, now_iso, ad_id))
        db.conn.commit()
        try:
            await bot.send_message(chat_id=user_id,
                text=(f"↑ <b>Объявление поднято!</b>\n\n"
                      f"«{ad['title'][:60]}» снова в топе выдачи."),
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_my_ad:{ad_id}")
                ]]))
        except Exception as _e:
            logger.warning(f"CryptoBot bump notify: {_e}")
        logger.info(f"CryptoBot: bump активирован ad={ad_id} user={user_id}")
        return True

    if plan == "pin":
        pin_type    = parts[3] if len(parts) > 3 else "main"
        # Читаем часы из payload: "pin:{user_id}:{ad_id}:{pin_type}:{price}:{hours}:{promo}"
        try:
            pin_hours_val = int(parts[5]) if len(parts) > 5 else 24
        except (IndexError, ValueError):
            pin_hours_val = 24
        # Промокод (если есть)
        promo_code_val = parts[6] if len(parts) > 6 else ""

        # ВАЖНО: city/target_chat нужно знать ДО апдейта БД и до пина —
        # раньше target_chat использовался здесь до того, как был вообще
        # определён (NameError на каждой активации закрепа через CryptoBot).
        city        = (ad.get("city") or "").strip()
        is_city     = (pin_type == "city")
        target_chat = CITY_CHANNELS.get(city, ADMIN_CHANNEL_ID) if is_city else ADMIN_CHANNEL_ID
        ch_label    = f"{city} (городской канал)" if is_city else "Основной канал"

        # Продлеваем от остатка, если закреп этого типа уже активен —
        # иначе уже оплаченное время сгорает при повторной покупке.
        now_msk = get_moscow_time()
        base_dt = now_msk
        existing_field = 'pinned_until_city' if is_city else 'pinned_until'
        existing_val = ad.get(existing_field)
        if existing_val:
            try:
                existing_dt = _safe_isoparse(existing_val)
                if existing_dt and existing_dt > now_msk:
                    base_dt = existing_dt
            except Exception:
                pass
        pinned_until = (base_dt + timedelta(hours=pin_hours_val)).isoformat()

        if is_city:
            cursor.execute("UPDATE ads SET pinned_until_city=?, pinned_chat_id_city=? WHERE id=?",
                           (pinned_until, str(target_chat), ad_id))
        else:
            cursor.execute("UPDATE ads SET pinned_until=?, pinned_chat_id=? WHERE id=?",
                           (pinned_until, str(target_chat), ad_id))
        db.conn.commit()

        # Для городского канала пинить нужно city_channel_message_id,
        # а не channel_message_id (тот относится к основному каналу).
        msg_id_to_pin = ad.get("city_channel_message_id") if is_city else ad.get("channel_message_id")

        _pin_ok = False
        _pin_err_msg = ""
        if msg_id_to_pin:
            try:
                await bot.pin_chat_message(chat_id=target_chat,
                    message_id=msg_id_to_pin, disable_notification=True)
                if job_queue:
                    delay = _safe_isoparse(pinned_until) - now_msk
                    if delay.total_seconds() < 0:
                        delay = timedelta(seconds=5)
                    job_queue.run_once(unpin_ad_callback, when=delay,
                        data={"ad_id": ad_id, "message_id": msg_id_to_pin, "chat_id": target_chat},
                        name=f"unpin_ad_{ad_id}_{'city' if is_city else 'main'}")
                _pin_ok = True
            except Exception as _pe:
                _pin_err_msg = str(_pe)
                logger.error(f"CryptoBot pin error: {_pe}")
        else:
            _pin_err_msg = "message_id отсутствует — объявление не опубликовано в целевом канале"

        try:
            await bot.send_message(chat_id=user_id,
                text=(f"✦ <b>Объявление закреплено!</b>\n\n"
                      f"«{ad['title'][:60]}»\n"
                      f"Канал: {ch_label}\n"
                      f"Закреплено на {pin_hours_val} ч."),
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_my_ad:{ad_id}")
                ]]))
        except Exception as _e:
            logger.warning(f"CryptoBot pin notify: {_e}")

        logger.info(f"CryptoBot: закреп активирован ad={ad_id} user={user_id} на {pin_hours_val}ч (chat={target_chat}, ok={_pin_ok}, err={_pin_err_msg})")

        # Уведомление администраторам
        _crypto_price = int(inv.get("amount_rub", 0))
        try:
            await _notify_admins_pin(
                bot, ad_id, user_id, pin_hours_val, ch_label, _crypto_price,
                success=_pin_ok, method="crypto",
                error_msg=_pin_err_msg if not _pin_ok else ""
            )
        except Exception as _ne:
            logger.warning(f"CryptoBot _notify_admins_pin: {_ne}")

        # Помечаем промокод как использованный (если был)
        if promo_code_val:
            try:
                promo = db.get_promocode(promo_code_val)
                if promo:
                    db.use_promocode(promo["id"], user_id)
            except Exception as _pre:
                logger.warning(f"CryptoBot promo use_promocode: {_pre}")

        return True

    logger.error(f"CryptoBot: неизвестный plan='{plan}' invoice={invoice_id}")
    return False

# Алиас для обратной совместимости
_activate_subscription_from_invoice = _activate_service_from_invoice
async def api_cryptobot_webhook(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """
    POST /cryptobot/webhook
    Принимает уведомления от Crypto Pay API об оплате счёта.
    Документация: https://help.crypt.bot/crypto-pay-api#webhooks
    """
    # Верификация подписи
    try:
        body_bytes = await request.read()
        # Парсим и сериализуем компактно — JS-пример делает JSON.stringify(body)
        canonical  = json.dumps(json.loads(body_bytes), separators=(',', ':'))
        signature  = request.headers.get("Crypto-Pay-API-Signature", "")
        secret     = hashlib.sha256(CRYPTO_BOT_TOKEN.encode()).digest()
        expected   = hmac.new(secret, canonical.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature.lower()):
            logger.warning("CryptoBot webhook: invalid signature")
            return aiohttp_web.Response(status=401, text="Invalid signature")
    except Exception as _e:
        logger.error(f"CryptoBot webhook signature check error: {_e}")
        return aiohttp_web.Response(status=400, text="Bad request")

    try:
        payload = json.loads(body_bytes)
        update_type = payload.get("update_type")
        if update_type != "invoice_paid":
            return aiohttp_web.Response(text="ok")

        invoice = payload.get("payload", {})
        inv_id  = invoice.get("invoice_id")
        status  = invoice.get("status")

        if status == "paid" and inv_id:
            bot       = _bot_app_ref.bot if _bot_app_ref else None
            jq        = _bot_app_ref.job_queue if _bot_app_ref else None
            if bot:
                await _activate_subscription_from_invoice(int(inv_id), bot, job_queue=jq)
            else:
                logger.error("CryptoBot webhook: bot reference not available")

    except Exception as _e:
        logger.error(f"CryptoBot webhook processing error: {_e}", exc_info=True)

    return aiohttp_web.Response(text="ok")


async def check_payment_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Единая кнопка «↺ Проверить оплату» — проверяет оплату через CryptoBot.
    Формат callback_data: check_payment:{crypto_invoice_id}
    """
    query = update.callback_query
    await safe_answer(query, "⌛ Проверяем оплату...")

    parts = query.data.split(":")
    crypto_id = int(parts[1]) if len(parts) > 1 and parts[1] != "0" else 0
    logger.info(f"check_payment: crypto_id={crypto_id} user={update.effective_user.id}")
    activated = False

    # ── 1. Проверяем CryptoBot ────────────────────────────────────────────────
    if crypto_id and crypto_bot_api:
        try:
            resp  = await crypto_bot_api.get_invoice(crypto_id)
            items = resp.get("result", {}).get("items", []) if resp.get("ok") else []
            if items and items[0].get("status") == "paid":
                activated = await _activate_subscription_from_invoice(
                    crypto_id, context.bot, job_queue=context.job_queue
                )
                if not activated:
                    cursor = db.conn.cursor()
                    cursor.execute("SELECT status FROM crypto_invoices WHERE invoice_id=?", (crypto_id,))
                    _inv_row = cursor.fetchone()
                    if _inv_row and _inv_row["status"] == "paid":
                        activated = True  # уже была активирована ранее через вебхук
        except Exception as _e:
            logger.error(f"check_payment crypto error: {_e}")

    # ── 2. Ответ пользователю ─────────────────────────────────────────────────
    if activated:
        ud = db.get_user(update.effective_user.id)
        end_str  = (ud.get("tariff_end_date", "") or "")[:10] if ud else ""
        end_info = f" до <b>{end_str}</b>" if end_str else ""

        # Определяем — закреп или подписка
        cursor = db.conn.cursor()
        is_pin = False
        if crypto_id:
            cursor.execute("SELECT plan FROM crypto_invoices WHERE invoice_id=?", (crypto_id,))
            r = cursor.fetchone()
            if r and (r["plan"] == "pin" or r["plan"].startswith("pin_") or r["plan"].startswith("pinc_")):
                is_pin = True

        if is_pin:
            _pin_kb = [[InlineKeyboardButton(EM_ARROW_L + " Главное меню", callback_data="back_to_menu")]]
            ok_text = f"{EM_OK} <b>Оплата подтверждена! Объявление закреплено.</b>"
        else:
            _pin_kb = [[InlineKeyboardButton(EM_ARROW_L + " Главное меню", callback_data="back_to_menu")]]
            ok_text = f"{EM_OK} <b>Оплата подтверждена! Подписка активирована{end_info}.</b>"

        await query.message.reply_text(
            ok_text, parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(_pin_kb)
        )
    else:
        await query.message.reply_text(
            f"{EM_DOT} Оплата ещё не поступила.\n\n"
            f"Попробуйте позже или напишите администратору.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(EM_REFRESH + " Проверить снова",
                                     callback_data=query.data)
            ]])
        )


async def check_crypto_payment_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Пользователь нажал «{EM_REFRESH} Проверить оплату» для крипто-счёта.
    Запрашивает статус через Crypto Bot API и активирует подписку если оплачено.
    """
    query = update.callback_query

    try:
        inv_id = int(query.data.split(":")[1])
    except (IndexError, ValueError):
        await safe_answer(query, "Ошибка: неверный invoice_id", show_alert=True)
        return

    if not crypto_bot_api:
        await safe_answer(query, "Crypto Bot API не настроен", show_alert=True)
        return

    await safe_answer(query, "⌛ Проверяем оплату...")

    try:
        resp = await crypto_bot_api.get_invoice(inv_id)
        if not resp.get("ok"):
            await query.message.reply_text("! Не удалось получить статус от Crypto Bot. Попробуйте позже.")
            return

        items = resp.get("result", {}).get("items", [])
        if not items:
            await safe_answer(query, f"{EM_FAIL} Счёт не найден в Crypto Bot", show_alert=True)
            return

        invoice = items[0]
        status  = invoice.get("status")

        if status == "paid":
            activated = await _activate_subscription_from_invoice(
                inv_id, context.bot, job_queue=context.job_queue
            )
            if activated:
                # Определяем тип инвойса по plan/payload из БД
                _inv_cursor = db.conn.cursor()
                _inv_cursor.execute("SELECT plan, payload FROM crypto_invoices WHERE invoice_id=?", (inv_id,))
                _inv_row = _inv_cursor.fetchone()
                _inv_plan = dict(_inv_row)["plan"] if _inv_row else ""
                _inv_payload = dict(_inv_row)["payload"] if _inv_row else ""
                if _inv_plan == "pin":
                    try:
                        _pp = _inv_payload.split(":")
                        _pad_id = int(_pp[2])
                        _phours = int(_pp[5]) if len(_pp) > 5 else 24
                        ok_text = f"{EM_OK} <b>Оплата подтверждена! Объявление закреплено на {_phours} ч.</b>"
                        ok_kb = [[InlineKeyboardButton(EM_ARROW_L + " К объявлению", callback_data=f"view_my_ad:{_pad_id}")]]
                    except Exception:
                        ok_text = f"{EM_OK} <b>Оплата подтверждена! Объявление закреплено.</b>"
                        ok_kb = [[InlineKeyboardButton(EM_ARROW_L + " Главное меню", callback_data="back_to_menu")]]
                else:
                    ud = db.get_user(update.effective_user.id)
                    end_str = (ud.get("tariff_end_date", "") or "")[:10] if ud else ""
                    end_info = f" до <b>{end_str}</b>" if end_str else ""
                    ok_text = f"{EM_OK} <b>Оплата подтверждена! Подписка активирована{end_info}.</b>"
                    ok_kb = [[InlineKeyboardButton(EM_ARROW_L + " Главное меню", callback_data="back_to_menu")]]
                await query.message.reply_text(ok_text, parse_mode="HTML",
                    reply_markup=InlineKeyboardMarkup(ok_kb))
            else:
                # Уже была активирована ранее
                await safe_answer(query, f"{EM_OK} Уже активировано!", show_alert=True)

        elif status == "active":
            # Ещё не оплачен — только кнопка проверить снова
            kb = [[InlineKeyboardButton(EM_REFRESH + " Проверить снова", callback_data=f"check_crypto:{inv_id}")]]
            await query.message.reply_text(
                f"{EM_DOT} Оплата ещё не поступила. Проверьте снова через минуту.",
                reply_markup=InlineKeyboardMarkup(kb)
            )

        elif status == "expired":
            # Счёт истёк — создаём новый
            cursor = db.conn.cursor()
            cursor.execute("SELECT * FROM crypto_invoices WHERE invoice_id=?", (inv_id,))
            row = cursor.fetchone()
            if row:
                inv         = dict(row)
                old_promo   = inv.get("promo_code", "") or ""
                old_disc    = inv.get("promo_discount", 0) or 0
                new_inv = await create_crypto_invoice(
                    user_id      = update.effective_user.id,
                    plan         = inv["plan"],
                    tariff_label = inv["tariff"],
                    rub_price    = inv["amount_rub"],
                    discount     = old_disc,
                    promo_code   = old_promo,
                )
                if new_inv:
                    context.user_data["crypto_invoice_id"] = new_inv["invoice_id"]
                    await query.message.reply_text(
                        f"! Предыдущий счёт истёк. Новый счёт создан.\n\n"
                        f"≈ <b>{new_inv['amount_usdt']} USDT</b>",
                        parse_mode="HTML",
                        reply_markup=InlineKeyboardMarkup([
                            [InlineKeyboardButton(EM_DIAMOND + " Оплатить", url=new_inv["pay_url"])],
                            [InlineKeyboardButton(EM_REFRESH + " Проверить оплату",
                                                  callback_data=f"check_crypto:{new_inv['invoice_id']}")],
                        ])
                    )
                else:
                    await safe_answer(query, "Не удалось создать новый счёт. Попробуйте снова.", show_alert=True)
            else:
                await safe_answer(query, "Счёт истёк. Вернитесь к выбору тарифа.", show_alert=True)
        else:
            await safe_answer(query, f"Статус счёта: {status}", show_alert=True)

    except Exception as _e:
        logger.error(f"check_crypto_payment_callback error: {_e}", exc_info=True)
        await safe_answer(query, "Ошибка при проверке. Попробуйте позже.", show_alert=True)


# ── Крипто-оплата закрепления ─────────────────────────────────────────────────

async def create_pin_crypto_invoice(
    user_id: int,
    ad_id: int,
    pin_type: str,
    price_rub: int,
    pin_hours: int = 24,
    promo_code: str = "",
) -> Optional[dict]:
    """
    Создаёт крипто-счёт Crypto Bot для оплаты закрепления объявления.
    """
    if not crypto_bot_api:
        return None
    try:
        usdt_amount = round(price_rub * CRYPTO_RUB_TO_USDT, 2)
        usdt_amount = max(usdt_amount, 1.00)  # минимум 1 USDT (требование CryptoBot API)
        pin_label   = "вся Удмуртия" if pin_type == "rf" else "городской канал"
        desc        = f"Закреп объявления #{ad_id} — {pin_label} {pin_hours}ч ({price_rub} ₽)"
        # payload: pin:{user_id}:{ad_id}:{pin_type}:{price_rub}:{pin_hours}:{promo_code}
        payload_str = f"pin:{user_id}:{ad_id}:{pin_type}:{price_rub}:{pin_hours}:{promo_code}"

        resp = await crypto_bot_api.create_invoice(
            amount        = usdt_amount,
            asset         = "USDT",
            description   = desc,
            payload       = payload_str,
            paid_btn_name = "callback",
            paid_btn_url  = f"{SERVER_URL}/cryptobot/paid",
        )
        if not resp.get("ok"):
            logger.error(f"CryptoBot pin invoice error: {resp}")
            return None

        result  = resp["result"]
        inv_id  = result["invoice_id"]
        pay_url = result["pay_url"]

        # Сохраняем в ту же таблицу
        cursor = db.conn.cursor()
        cursor.execute(
            """INSERT OR REPLACE INTO crypto_invoices
               (invoice_id, user_id, plan, tariff, amount_rub, amount_crypto,
                asset, status, payload, pay_url, created_at)
               VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
            (inv_id, user_id, "pin", f"pin_{ad_id}_{pin_type}", price_rub,
             str(usdt_amount), "USDT", "active", payload_str, pay_url,
             get_moscow_time().isoformat()),
        )
        db.conn.commit()
        return {"invoice_id": inv_id, "pay_url": pay_url, "amount_usdt": usdt_amount}
    except Exception as _e:
        logger.error(f"create_pin_crypto_invoice error: {_e}", exc_info=True)
        return None


