@aiohttp_web.middleware
async def _request_logging_middleware(request: aiohttp_web.Request, handler):
    """
    Логирует АБСОЛЮТНО ЛЮБОЙ входящий HTTP-запрос (метод, путь, query, IP),
    даже если он не совпал ни с одним маршрутом (404). Нужно, чтобы точно
    видеть, доходят ли вообще запросы от PayAnyWay до сервера — если в логах
    нет даже строки "HTTP IN", значит проблема не в коде, а в том, что
    запрос не доходит до контейнера вообще (неверный URL в личном кабинете
    PayAnyWay/moneta.ru, DNS, firewall и т.п.).
    """
    peer = request.remote or "?"
    logger.info(f"HTTP IN: {request.method} {request.path}?{request.query_string} from {peer}")
    try:
        response = await handler(request)
        logger.info(f"HTTP OUT: {request.method} {request.path} -> {response.status}")
        return response
    except aiohttp_web.HTTPException as _he:
        logger.info(f"HTTP OUT: {request.method} {request.path} -> {_he.status} (HTTPException)")
        raise
    except Exception as _e:
        logger.error(f"HTTP ERROR: {request.method} {request.path}: {_e}", exc_info=True)
        raise


async def api_views_diag(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/views_diag — диагностика чтения просмотров постов канала через MTProto (userbot).

    Проверяет, жива ли userbot-сессия и видит ли просмотры постов объявлений
    (включая приватный канал). Открыть: {SERVER_URL}/api/views_diag
    """
    cors = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
    }
    if request.method == 'OPTIONS':
        return aiohttp_web.Response(status=200, headers=cors)

    lines = ["<h3>Диагностика просмотров постов (веб-метод t.me + MAX API)</h3>", "<pre>"]

    def _fmt(v):
        return '' if v is None else str(v)

    API_ID = int(os.environ.get('TG_API_ID', 9642082))
    API_HASH = os.environ.get('TG_API_HASH', '948864143b1ec7c40df8e843f2783ccc')

    # ── Проверка доступности IP-адресов Telegram с хостинга ────────────────────
    # Часть IP заблокирована DPI (Connection reset), часть работает. Находим рабочие.
    lines.append("\n--- Доступность IP Telegram (TCP 443/80/5222) ---")
    try:
        import socket as _sock
        _DC_IPS = [
            "149.154.167.220", "149.154.167.221", "149.154.167.222",
            "149.154.175.50",  "149.154.175.51",  "149.154.164.50",
            "91.108.4.220",    "91.108.56.130",   "149.154.166.138",
        ]
        for _ip in _DC_IPS:
            _oks = []
            for _p in (443, 80, 5222):
                s = _sock.socket(_sock.AF_INET, _sock.SOCK_STREAM)
                s.settimeout(3)
                try:
                    s.connect((_ip, _p))
                    _oks.append(f"{_p}")
                except Exception:
                    pass
                finally:
                    s.close()
            lines.append(f"  {_ip}: открыты порты {', '.join(_oks) if _oks else 'НЕТ'}")
    except Exception as e:
        lines.append(f"  сканирование IP: ошибка {e}")

    # ── Проверка веб-метода просмотров (публичный канал, без MTProto) ──────
    lines.append(f"\n--- Веб-метод просмотров t.me/{TG_CHANNEL_USERNAME} (без MTProto) ---")
    try:
        _wb_msg_id = None
        try:
            cur = db.conn.cursor()
            row = cur.execute(
                "SELECT channel_message_id FROM ads WHERE id = 80"
            ).fetchone()
            if row and row['channel_message_id']:
                _v = str(row['channel_message_id'])
                if not _v.startswith('mid.'):
                    _wb_msg_id = int(_v)
        except Exception as e:
            lines.append(f"  ошибка чтения channel_message_id: {e}")
        if not _wb_msg_id:
            lines.append("  нет числового TG channel_message_id (ad 80)")
        else:
            lines.append(f"  тестирую https://t.me/{TG_CHANNEL_USERNAME}/{_wb_msg_id}?embed=1&mode=tme")
            views = await _get_tg_views_web({'id': 80, 'channel_message_id': _wb_msg_id})
            if views is not None:
                lines.append(f"  ✅ ПОЛУЧЕНО: views = {views}")
            else:
                lines.append(f"  ❌ не удалось получить views (сеть блокирует t.me или пост не найден)")
    except Exception as e:
        lines.append(f"  веб-метод ошибка: {e}")

    # ── Проверка просмотров MAX-поста через MAX Bot API ───────────────────────
    lines.append("\n--- MAX Bot API (get_message) ---")
    if not max_client:
        lines.append("  max_client НЕТ (MAX_BOT_TOKEN не задан)")
    else:
        try:
            max_chat = MAX_CHANNEL_ID
            max_msg = None
            try:
                cur = db.conn.cursor()
                row = cur.execute(
                    "SELECT max_channel_message_id FROM ads WHERE id = 80"
                ).fetchone()
                if row and row['max_channel_message_id']:
                    max_msg = row['max_channel_message_id']
            except Exception as e:
                lines.append(f"  ошибка чтения max_channel_message_id: {e}")
            lines.append(f"  MAX_CHANNEL_ID={max_chat!r}, max_channel_message_id(ad 80)={max_msg!r}")
            if max_msg:
                try:
                    raw = await max_client.get_message(max_chat, str(max_msg))
                    lines.append(f"  get_message вернул: {str(raw)[:600]}")
                except Exception as e:
                    lines.append(f"  get_message ошибка: {type(e).__name__}: {e}")
            else:
                lines.append("  у ad 80 нет max_channel_message_id — ищем любой")
                try:
                    cur = db.conn.cursor()
                    row2 = cur.execute(
                        "SELECT id, title, max_channel_message_id FROM ads "
                        "WHERE max_channel_message_id IS NOT NULL AND max_channel_message_id != '' LIMIT 3"
                    ).fetchall()
                    for r in row2:
                        try:
                            raw = await max_client.get_message(max_chat, str(r['max_channel_message_id']))
                            lines.append(f"  ad {r['id']} msg {r['max_channel_message_id']}: {str(raw)[:300]}")
                        except Exception as e:
                            lines.append(f"  ad {r['id']} msg {r['max_channel_message_id']}: ошибка {type(e).__name__}: {e}")
                except Exception as e:
                    lines.append(f"  поиск объявлений с max_channel_message_id: {e}")
        except Exception as e:
            lines.append(f"  MAX-блок ошибка: {type(e).__name__}: {e}")

    lines.append("</pre>")
    lines.append("<p>Веб-метод (t.me) показывает реальные просмотры поста публичного канала. "
                 "MAX-блок показывает, что реально возвращает MAX API get_message.</p>")
    return aiohttp_web.Response(text="\n".join(lines), content_type="text/html", headers=cors)


# =====================================================================
#  MINI APP ADS API — единый API Telegram Mini App на СУЩЕСТВУЮЩЕЙ БД
# ---------------------------------------------------------------------
#  Принципы (ТЗ на доработку):
#  • одна БД (polka.db): таблицы ads / users / favorites / chats;
#  • переиспользование search_ads_filtered / create_ad / get_ad /
#    update_ad / get_user_ads / increment_ad_views / notify_admin_new_ad /
#    get_or_create_chat / save_chat_message;
#  • авторизация ТОЛЬКО через проверенный Telegram initData
#    (заголовок X-Telegram-Init-Data); user_id из frontend НЕ доверяем;
#  • фото хранятся как Telegram file_id — та же система, что у бота;
#  • Mini App НЕ публикует в каналы — это делает существующая модерация.
# =====================================================================

MINIAPP_PHOTO_STORAGE_CHAT_ENV = "PHOTO_STORAGE_CHAT_ID"
MINIAPP_MAX_PHOTOS = 5
MINIAPP_MAX_PHOTO_BYTES = 10 * 1024 * 1024


@aiohttp_web.middleware
async def _miniapp_cors_middleware(request: aiohttp_web.Request, handler):
    """CORS для Mini App frontend (/api/*). Preflight OPTIONS закрываем тут."""
    if request.path.startswith('/api/'):
        if request.method == 'OPTIONS':
            return aiohttp_web.Response(status=204, headers=_miniapp_cors_headers())
        try:
            response = await handler(request)
        except aiohttp_web.HTTPException as exc:
            exc.headers.update(_miniapp_cors_headers())
            raise
        response.headers.update(_miniapp_cors_headers())
        return response
    return await handler(request)


def _miniapp_cors_headers() -> dict:
    return {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, POST, PATCH, DELETE, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, X-Telegram-Init-Data',
    }


def _miniapp_json(data: dict, status: int = 200) -> aiohttp_web.Response:
    return aiohttp_web.json_response(data, status=status, headers=_miniapp_cors_headers())


def _miniapp_err(code: str, status: int) -> aiohttp_web.Response:
    return _miniapp_json({'error': code}, status=status)


def _miniapp_viewer(request: aiohttp_web.Request) -> Optional[int]:
    """user_id из проверенного initData (или None для публичных ручек)."""
    return get_viewer_id(request)


def _miniapp_init_user(init_data: str) -> Optional[dict]:
    """Разбирает user-объект из initData (после успешной проверки подписи)."""
    try:
        import urllib.parse as _up
        params = dict(p.split('=', 1) for p in init_data.split('&') if '=' in p)
        return json.loads(_up.unquote(params.get('user', '{}')))
    except Exception:
        return None


def _miniapp_ensure_user(user_id: int, init_data: str = '') -> Optional[dict]:
    """Гарантирует строку пользователя в существующей таблице users."""
    user = db.get_user(user_id)
    if user:
        return user
    tg = _miniapp_init_user(init_data) if init_data else None
    try:
        db.create_user({
            'user_id': user_id,
            'username': (tg or {}).get('username', ''),
            'first_name': (tg or {}).get('first_name', ''),
        })
    except Exception as e:
        logger.error(f"miniapp ensure_user: {e}")
    return db.get_user(user_id)


def _miniapp_display_category(raw: Optional[str]) -> str:
    raw = (raw or '').strip()
    if raw.startswith('· '):
        return raw[2:].strip()
    return raw


def _miniapp_format_price(value) -> str:
    try:
        return f"{int(value or 0):,}".replace(",", " ") + " ₽"
    except Exception:
        return "0 ₽"


def _miniapp_parse_price(value) -> int:
    if isinstance(value, bool):
        return 0
    if isinstance(value, (int, float)):
        return max(0, int(value))
    digits = ''.join(ch for ch in str(value or '') if ch.isdigit())
    return int(digits) if digits else 0


def _miniapp_photo_urls(photos) -> list:
    """Прокси-URL для фото объявления.

    В photos лежит одно из двух: либо Telegram file_id (объявления,
    созданные ботом), либо уже готовый путь /api/ads/photos/<name>
    (объявления, созданные в Mini App — она сама грузит файлы).
    Готовые пути и абсолютные URL отдаём как есть, file_id оборачиваем
    в /api/photo/.

    Раньше оборачивалось всё подряд, и для Mini App получался
    /api/photo//api/ads/photos/x.jpg — aiohttp-паттерн {file_id} не
    матчит слэши, запрос уходил в SPA-фолбэк и в <img> приезжал
    index.html. Фото объявлений из Mini App не отображались вообще.
    """
    urls = []
    for p in photos or []:
        if not isinstance(p, str) or not p or p.startswith('{'):
            continue
        if p.startswith('/') or p.startswith('http://') or p.startswith('https://'):
            urls.append(p)
        else:
            urls.append(f"/api/photo/{p}")
    return urls


def _miniapp_fav_map(ad_ids: list, viewer_id: Optional[int]) -> dict:
    """Пакетно: {ad_id: favorites_count} и множество избранного вьюера."""
    counts: dict = {}
    mine: set = set()
    if not ad_ids:
        return counts, mine
    try:
        cur = db.conn.cursor()
        qmarks = ','.join('?' for _ in ad_ids)
        cur.execute(
            f"SELECT ad_id, COUNT(*) AS c FROM favorites WHERE ad_id IN ({qmarks}) GROUP BY ad_id",
            tuple(ad_ids),
        )
        for row in cur.fetchall():
            counts[row['ad_id']] = row['c']
        if viewer_id:
            cur.execute(
                f"SELECT ad_id FROM favorites WHERE user_id=? AND ad_id IN ({qmarks})",
                (viewer_id, *ad_ids),
            )
            mine = {row['ad_id'] for row in cur.fetchall()}
    except Exception as e:
        logger.error(f"miniapp fav_map: {e}")
    return counts, mine


def _miniapp_serialize_ad(ad: dict, viewer_id: Optional[int] = None,
                          fav_counts: Optional[dict] = None,
                          fav_mine: Optional[set] = None,
                          with_rating: bool = False) -> dict:
    photos = ad.get('photos') or []
    if isinstance(photos, str):
        try:
            photos = json.loads(photos)
        except Exception:
            photos = []
    seller = db.get_user(ad.get('user_id')) or {}
    verify = None
    try:
        verify = db.get_verification(ad.get('user_id'))
    except Exception:
        verify = None
    # Рейтинг считаем только по запросу (карточка товара): в ленте это лишний
    # SELECT на каждое объявление — 20 позиций дали бы 20 дополнительных запросов.
    rating = None
    if with_rating:
        try:
            rating = db.get_seller_rating(ad.get('user_id'))
        except Exception:
            rating = None
    ad_id = ad.get('id')
    fav_count = (fav_counts or {}).get(ad_id, 0)
    if not fav_counts:
        try:
            cur = db.conn.cursor()
            cur.execute("SELECT COUNT(*) AS c FROM favorites WHERE ad_id=?", (ad_id,))
            row = cur.fetchone()
            fav_count = row['c'] if row else 0
        except Exception:
            fav_count = 0
    is_fav = ad_id in (fav_mine or set())
    if viewer_id and fav_mine is None:
        try:
            cur = db.conn.cursor()
            cur.execute("SELECT 1 FROM favorites WHERE user_id=? AND ad_id=?", (viewer_id, ad_id))
            is_fav = cur.fetchone() is not None
        except Exception:
            is_fav = False
    return {
        'id': ad_id,
        'title': ad.get('title', ''),
        'description': ad.get('description', ''),
        'price': ad.get('price', 0),
        'price_display': _miniapp_format_price(ad.get('price', 0)),
        'photos': photos,
        'photo_urls': _miniapp_photo_urls(photos),
        'category': _miniapp_display_category(ad.get('category', '')),
        'category_raw': ad.get('category', ''),
        'condition': ad.get('condition', ''),
        'city': ad.get('city', ''),
        'delivery': ad.get('delivery', ''),
        'size': ad.get('size', ''),
        'status': ad.get('status', ''),
        'views': ad.get('views', 0),
        'favorites_count': fav_count,
        'created_at': ad.get('created_at', ''),
        'published_at': ad.get('published_at', ''),
        'seller': {
            'id': get_anon_id(seller) if seller else str(ad.get('user_id')),
            'name': (seller.get('first_name') or 'Продавец') if seller else 'Продавец',
            'username': (seller.get('username') or '') if seller else '',
            'verified': bool(verify and verify.get('status') == 'verified'),
            'rating': (rating or {}).get('avg') or None,
            'reviews_count': (rating or {}).get('count') or 0,
        },
        'is_favorite': bool(is_fav),
        'is_owner': bool(viewer_id and ad.get('user_id') == viewer_id),
        # Находки из внешних источников: источник, ссылка и выгода
        'source': ad.get('source') or 'polka',
        'source_url': ad.get('source_url') or '',
        'discount_percent': ad.get('discount_percent'),
        'market_median': ad.get('market_median'),
        **_miniapp_auction_fields(ad, viewer_id),
    }


def _miniapp_auction_fields(ad: dict, viewer_id: Optional[int] = None) -> dict:
    """Поля аукциона для клиента. Для обычных объявлений — пустой словарь.

    Отдаём минимальную следующую ставку и остаток времени: без них
    интерфейс не сможет показать кнопку «Сделать ставку» и таймер.
    """
    if (ad.get('sale_type') or 'sale') != 'auction':
        return {'sale_type': 'sale'}
    return {
        'sale_type': 'auction',
        'start_price': ad.get('start_price') or 0,
        'bid_step': ad.get('bid_step') or AUCTION_MIN_STEP,
        'buy_now_price': ad.get('buy_now_price') or 0,
        'current_bid': ad.get('current_bid') or 0,
        'bids_count': ad.get('bids_count') or 0,
        'ends_at': ad.get('ends_at') or '',
        'time_left': auction_time_left(ad),
        'min_next_bid': min_next_bid(ad),
        'winner_id': ad.get('winner_id'),
        'is_winner': bool(viewer_id and ad.get('winner_id') == viewer_id),
    }


def _miniapp_ad_id(request: aiohttp_web.Request) -> Optional[int]:
    try:
        return int(request.match_info['ad_id'])
    except (KeyError, ValueError, TypeError):
        return None


