# ── Лента / поиск ─────────────────────────────────────────────────────

async def api_miniapp_ads_list(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/ads — лента и поиск по существующей БД (status=active).

    Параметры: q, category, city, price_min, price_max, condition, delivery,
    sort (date_desc|date_asc|price_asc|price_desc|views_desc),
    limit (<=100), offset.
    """
    viewer_id = _miniapp_viewer(request)
    q = request.query.get('q', '')
    category = request.query.get('category', '')
    city = request.query.get('city', '')
    try:
        price_min = int(request.query.get('price_min', 0) or 0)
    except ValueError:
        price_min = 0
    try:
        price_max = int(request.query.get('price_max', 0) or 0)
    except ValueError:
        price_max = 0
    condition = request.query.get('condition', '')
    delivery = request.query.get('delivery', '')
    sort = request.query.get('sort', 'date_desc')
    try:
        limit = min(max(int(request.query.get('limit', 20) or 20), 1), 100)
    except ValueError:
        limit = 20
    try:
        offset = max(int(request.query.get('offset', 0) or 0), 0)
    except ValueError:
        offset = 0
    try:
        raw = db.search_ads_filtered(
            query=q, category=category, price_min=price_min, price_max=price_max,
            city=city, condition=condition, delivery=delivery, sort_by=sort,
            limit=limit + offset + 1,
        )
    except Exception as e:
        logger.error(f"miniapp ads_list: {e}")
        return _miniapp_err('search_failed', 500)
    has_more = len(raw) > limit + offset
    page = raw[offset:offset + limit]
    ids = [a['id'] for a in page]
    fav_counts, fav_mine = _miniapp_fav_map(ids, viewer_id)
    items = [_miniapp_serialize_ad(a, viewer_id, fav_counts, fav_mine) for a in page]
    return _miniapp_json({'items': items, 'has_more': has_more, 'limit': limit, 'offset': offset})


async def api_miniapp_ad_get(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/ads/{id} — карточка объявления + учёт просмотра (1 вызов = 1 показ)."""
    viewer_id = _miniapp_viewer(request)
    ad_id = _miniapp_ad_id(request)
    if ad_id is None:
        return _miniapp_err('not_found', 404)
    ad = db.get_ad(ad_id)
    if not ad:
        return _miniapp_err('not_found', 404)
    if ad.get('status') != 'active' and ad.get('user_id') != viewer_id:
        return _miniapp_err('not_found', 404)
    try:
        db.increment_ad_views(ad_id, viewer_id)
        ad = db.get_ad(ad_id) or ad
    except Exception as e:
        logger.error(f"miniapp ad views {ad_id}: {e}")
    return _miniapp_json({'ad': _miniapp_serialize_ad(ad, viewer_id, with_rating=True)})


# ── Создание ──────────────────────────────────────────────────────────

_MINIAPP_AD_REQUIRED = ('title', 'category', 'city', 'contact_info')


async def api_miniapp_ads_create(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/ads — создание через Mini App → create_ad + модерация.

    Тело JSON: title, description, price (число или "4 200 ₽"), category,
    city, condition, delivery, size, contact_info, photos [file_id...].
    """
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        body = await request.json()
    except Exception:
        return _miniapp_err('bad_json', 400)
    if not isinstance(body, dict):
        return _miniapp_err('bad_json', 400)
    for field in _MINIAPP_AD_REQUIRED:
        if not str(body.get(field) or '').strip():
            return _miniapp_err(f'missing_{field}', 400)
    title = str(body.get('title', '')).strip()
    if not (3 <= len(title) <= 200):
        return _miniapp_err('bad_title', 400)
    photos = body.get('photos') or []
    if not isinstance(photos, list) or len(photos) > MINIAPP_MAX_PHOTOS:
        return _miniapp_err('bad_photos', 400)
    photos = [str(p) for p in photos if isinstance(p, str) and p][:MINIAPP_MAX_PHOTOS]
    # Аукцион: параметры проверяем ДО создания объявления, чтобы при ошибке
    # не оставалось битой записи
    auction = None
    if str(body.get('sale_type') or '') == 'auction':
        auction = validate_auction_params(body)
        if not auction.get('ok'):
            return _miniapp_err(auction.get('error') or 'bad_auction', 400)
    description = str(body.get('description') or '')[:4000]
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    _miniapp_ensure_user(viewer_id, init_data)
    try:
        ad_id = db.create_ad({
            'user_id': viewer_id,
            'title': title,
            'description': description,
            'price': _miniapp_parse_price(body.get('price', 0)),
            'photos': photos,
            'contact_info': str(body.get('contact_info', ''))[:500],
            'category': str(body.get('category', ''))[:100],
            'condition': str(body.get('condition', ''))[:50],
            'size': str(body.get('size', ''))[:50],
            'city': str(body.get('city', ''))[:100],
            'delivery': str(body.get('delivery', ''))[:100],
            'gender': str(body.get('gender', ''))[:50],
            'address': str(body.get('address', ''))[:300],
        })
    except Exception as e:
        logger.error(f"miniapp ads_create: {e}")
        return _miniapp_err('create_failed', 500)
    if auction:
        try:
            set_auction_params(ad_id, auction['start_price'], auction['bid_step'],
                               auction['buy_now_price'], auction['auction_days'])
        except Exception as e:
            logger.error(f"miniapp auction params: {e}")
    try:
        db.update_user(viewer_id,
                       daily_ads_count=(db.get_user(viewer_id) or {}).get('daily_ads_count', 0) + 1)
    except Exception:
        pass
    try:
        db.log_action(viewer_id, "ad_created_miniapp", f"Ad ID: {ad_id}")
    except Exception:
        pass
    bot = _miniapp_bot()
    if bot:
        try:
            await notify_admin_new_ad(ad_id, _MiniappCtxShim(bot))
        except Exception as e:
            logger.error(f"miniapp notify admin {ad_id}: {e}")
        try:
            if photos:
                asyncio.create_task(_index_ad_photo(ad_id, photos[0], bot))
        except Exception:
            pass
    await _miniapp_notify_user(
        viewer_id,
        f"Ваше объявление <b>«{title[:60]}»</b> отправлено на модерацию.\n"
        f"После проверки оно появится в ленте.",
    )
    ad = db.get_ad(ad_id)
    return _miniapp_json({'ok': True, 'ad': _miniapp_serialize_ad(ad, viewer_id)}, status=201)


def _guess_photo_ext(ctype: str, data: bytes) -> str:
    """Расширение для сохранённого файла.

    Определяем по «магическим» байтам, а не по content-type: браузеры и
    Telegram часто присылают пустой тип или application/octet-stream.
    """
    if data[:3] == b'\xff\xd8\xff':
        return 'jpg'
    if data[:8] == b'\x89PNG\r\n\x1a\n':
        return 'png'
    if data[:6] in (b'GIF87a', b'GIF89a'):
        return 'gif'
    if data[:4] == b'RIFF' and data[8:12] == b'WEBP':
        return 'webp'
    if data[4:12] in (b'ftypheic', b'ftypheix', b'ftyphevc', b'ftypmif1', b'ftypmsf1'):
        return 'heic'
    if ctype == 'image/png':
        return 'png'
    if ctype == 'image/webp':
        return 'webp'
    if ctype == 'image/gif':
        return 'gif'
    return 'jpg'


async def api_miniapp_photos_upload(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/ads/photos — загрузка фото (multipart, поле photos).

    Файл сохраняется в UPLOAD_DIR, а наружу отдаём ссылку /api/ads/photos/<fn> —
    фото резолвятся через тот же сервер, что и /api/photo. Так работает
    даже без приватного чато-хранилища.
    """
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        form = await request.post()
    except Exception:
        return _miniapp_err('bad_multipart', 400)
    files = form.getall('photos', [])
    if not files:
        single = form.get('photo')
        files = [single] if single is not None else []
    files = files[:MINIAPP_MAX_PHOTOS]
    if not files:
        return _miniapp_err('no_photos', 400)
    upload_dir = os.environ.get('UPLOAD_DIR', '/data/uploads')
    try:
        os.makedirs(upload_dir, exist_ok=True)
    except Exception:
        pass
    urls: list = []
    skipped: list = []
    import io as _io
    try:
        from PIL import Image as _PILImage
    except ImportError:
        _PILImage = None
    for idx, field in enumerate(files):
        try:
            ctype = getattr(field, 'content_type', '') or ''
            # content-type может быть пустым или application/octet-stream
            # (так бывает при съёмке на iPhone) — тип не отбраковываем,
            # решает попытка декодирования ниже. Отбрасываем только явно
            # не-картиночные типы (pdf, видео и т.п.).
            if ctype and not (ctype.startswith('image/') or ctype == 'application/octet-stream'):
                skipped.append(f'{ctype}: не изображение')
                continue
            data = field.file.read(MINIAPP_MAX_PHOTO_BYTES + 1)
            if not data:
                skipped.append('пустой файл')
                continue
            if len(data) > MINIAPP_MAX_PHOTO_BYTES:
                skipped.append(f'больше {MINIAPP_MAX_PHOTO_BYTES // (1024 * 1024)} МБ')
                continue
            ext = _guess_photo_ext(ctype, data)
            if _PILImage:
                try:
                    im = _PILImage.open(_io.BytesIO(data))
                    im.load()
                    # Учитываем поворот из EXIF: без этого фото с телефона
                    # висело боком (камера пишет поворот в метаданные).
                    try:
                        from PIL import ImageOps as _ImageOps
                        im = _ImageOps.exif_transpose(im)
                    except Exception:
                        pass
                    im.thumbnail((1400, 1400))
                    if im.mode in ('RGBA', 'P', 'LA', 'CMYK'):
                        im = im.convert('RGB')
                    buf = _io.BytesIO()
                    im.save(buf, format='JPEG', quality=85)
                    data = buf.getvalue()
                    ext = 'jpg'
                except Exception as _e:
                    # Не смогли декодировать (например HEIC без pillow-heif).
                    # Раньше файл молча пропадал — теперь сохраняем как есть,
                    # чтобы фото пользователя не терялось.
                    logger.warning(f"miniapp photo: не удалось перекодировать ({_e}), сохраняю исходник")
            # ВНИМАНИЕ: имя time занято datetime.time (см. импорт в начале),
            # модуль времени доступен как _time. Раньше здесь стояло
            # time.time() — это падало с AttributeError на каждом фото,
            # и загрузка не работала вообще.
            name = f"u{viewer_id}_{int(_time.time())}_{idx}.{ext}"
            path = os.path.join(upload_dir, name)
            with open(path, 'wb') as fh:
                fh.write(data)
            urls.append(f"/api/ads/photos/{name}")
        except Exception as e:
            logger.error(f"miniapp photo upload: {e}")
            skipped.append('ошибка обработки')
    if not urls:
        # Отдаём причину, а не безликое upload_failed: иначе в интерфейсе
        # всегда «Не удалось загрузить фото» и непонятно, что чинить.
        logger.warning(f"miniapp photo upload: ничего не сохранено, причины: {skipped}")
        return _miniapp_json(
            {'error': 'upload_failed', 'detail': '; '.join(skipped) or 'файлы не получены'},
            status=422,
        )
    try:
        _miniapp_settings_set(f"photo_map:{viewer_id}", json.dumps(
            {u: os.path.join(upload_dir, os.path.basename(u)) for u in urls}))
    except Exception:
        pass
    return _miniapp_json({'ok': True, 'urls': urls}, status=201)


async def api_miniapp_message_edit(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """PATCH /api/chat/{session_id}/messages/{msg_id} — редактирование.

    Разрешено только автору и только если получатель ещё не прочитал.
    """
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        session_id = int(request.match_info['session_id'])
        msg_id = int(request.match_info['msg_id'])
    except (KeyError, ValueError):
        return _miniapp_err('not_found', 404)
    session = get_chat_session(session_id)
    if not session or viewer_id not in (session['buyer_id'], session['seller_id']):
        return _miniapp_err('forbidden', 403)
    try:
        body = await request.json()
    except Exception:
        return _miniapp_err('bad_json', 400)
    text = str((body or {}).get('text', '')).strip()
    if not text or len(text) > 4000:
        return _miniapp_err('invalid_text', 400)
    try:
        cur = db.conn.cursor()
        cur.execute('SELECT sender_id FROM chat_messages WHERE id=? AND session_id=?', (msg_id, session_id))
        row = cur.fetchone()
        if not row or row['sender_id'] != viewer_id:
            return _miniapp_err('forbidden', 403)
        cur.execute('UPDATE chat_messages SET text=? WHERE id=?', (text, msg_id))
        db.conn.commit()
    except Exception as e:
        logger.error(f"miniapp message_edit: {e}")
        return _miniapp_err('update_failed', 500)
    return _miniapp_json({'ok': True})


