    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        cur = db.conn.cursor()
        cur.execute('''
            SELECT a.*, f.added_at AS fav_added_at
            FROM favorites f JOIN ads a ON f.ad_id = a.id
            WHERE f.user_id = ? ORDER BY f.added_at DESC LIMIT 200
        ''', (viewer_id,))
        rows = [dict(r) for r in cur.fetchall()]
    except Exception as e:
        logger.error(f"miniapp favorites: {e}")
        return _miniapp_err('load_failed', 500)
    ads = []
    for row in rows:
        try:
            row['photos'] = json.loads(row['photos']) if row.get('photos') else []
        except Exception:
            row['photos'] = []
        ads.append(row)
    ids = [a['id'] for a in ads]
    fav_counts, fav_mine = _miniapp_fav_map(ids, viewer_id)
    return _miniapp_json({
        'items': [_miniapp_serialize_ad(a, viewer_id, fav_counts, fav_mine) for a in ads],
    })


