# ── Чаты Mini App (список + старт; диалог/полл/отправка уже есть) ──────

async def api_miniapp_chats(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/chats — диалоги пользователя из chat_sessions."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        cur = db.conn.cursor()
        cur.execute('''
            SELECT cs.id, cs.ad_id, cs.buyer_id, cs.seller_id, cs.last_message_at,
                   a.title AS ad_title, a.price AS ad_price,
                   (SELECT m.text FROM chat_messages m
                    WHERE m.session_id = cs.id ORDER BY m.id DESC LIMIT 1) AS last_text,
                (SELECT m.created_at FROM chat_messages m
                    WHERE m.session_id = cs.id ORDER BY m.id DESC LIMIT 1) AS last_time
            FROM chat_sessions cs
            LEFT JOIN ads a ON a.id = cs.ad_id
            WHERE (cs.buyer_id = ? OR cs.seller_id = ?) AND cs.status = 'active'
            ORDER BY cs.last_message_at DESC LIMIT 50
        ''', (viewer_id, viewer_id))
        rows = [dict(r) for r in cur.fetchall()]
    except Exception as e:
        logger.error(f"miniapp chats: {e}")
        return _miniapp_err('load_failed', 500)
    items = []
    for row in rows:
        other_id = row['seller_id'] if viewer_id == row['buyer_id'] else row['buyer_id']
        other = db.get_user(other_id) or {}
        items.append({
            'id': row['id'],
            'ad_id': row['ad_id'],
            'ad_title': row['ad_title'] or '',
            'ad_price': row['ad_price'],
            'user': get_anon_id(other) if other else str(other_id),
            'last_text': row['last_text'] or '',
            'time': (row['last_time'] or row['last_message_at'] or '')[:16],
            'unread': 0,
        })
    return _miniapp_json({'items': items})


async def api_miniapp_chat_start(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """POST /api/chats/start {ad_id} — «Связаться с продавцом».

    Использует get_or_create_chat; продавцу уходит уведомление в бота
    (бот остаётся каналом уведомлений — ТЗ §5, §27).
    """
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    try:
        body = await request.json()
    except Exception:
        return _miniapp_err('bad_json', 400)
    try:
        ad_id = int((body or {}).get('ad_id', 0))
    except (ValueError, TypeError):
        return _miniapp_err('bad_ad_id', 400)
    ad = db.get_ad(ad_id)
    if not ad or ad.get('status') != 'active':
        return _miniapp_err('not_found', 404)
    seller_id = ad['user_id']
    if seller_id == viewer_id:
        return _miniapp_err('own_ad', 400)
    try:
        session_id = get_or_create_chat(ad_id, viewer_id, seller_id)
    except Exception as e:
        logger.error(f"miniapp chat_start {ad_id}: {e}")
        return _miniapp_err('create_failed', 500)
    try:
        bot = _miniapp_bot()
        if bot:
            buyer = db.get_user(viewer_id) or {}
            kb = InlineKeyboardMarkup([[
                InlineKeyboardButton("Ответить", callback_data=f"open_chat:{session_id}")
            ],
                [_miniapp_open_button()],
            ])
            await bot.send_message(
                chat_id=seller_id,
                text=(f"{EM_DOT} <b>Новый отклик</b>\n"
                      f"По объявлению «{(ad.get('title') or '')[:35]}»\n"
                      f"От: {get_anon_id(buyer)}"),
                reply_markup=kb,
                parse_mode=ParseMode.HTML,
            )
    except Exception as e:
        logger.error(f"miniapp chat_start notify: {e}")
    return _miniapp_json({'ok': True, 'chat': {'id': session_id}}, status=201)


# ── Профиль / фильтры / фото ──────────────────────────────────────────

async def api_miniapp_me(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/me — профиль существующего Telegram-пользователя."""
    viewer_id = _miniapp_viewer(request)
    if not viewer_id:
        return _miniapp_err('unauthorized', 401)
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    user = _miniapp_ensure_user(viewer_id, init_data) or {}
    try:
        cur = db.conn.cursor()
        cur.execute("SELECT COUNT(*) AS c FROM ads WHERE user_id=? AND status='active'",
                    (viewer_id,))
        active_count = _row_get(cur.fetchone(), 'c', 0)
        cur.execute("SELECT COUNT(*) AS c FROM ads WHERE user_id=? AND status='moderation'",
                    (viewer_id,))
        moderation_count = _row_get(cur.fetchone(), 'c', 0)
        cur.execute("SELECT COUNT(*) AS c FROM favorites WHERE user_id=?", (viewer_id,))
        fav_count = _row_get(cur.fetchone(), 'c', 0)
    except Exception:
        active_count, moderation_count, fav_count = 0, 0, 0
    verify = None
    try:
        verify = db.get_verification(viewer_id)
    except Exception:
        verify = None
    return _miniapp_json({'user': {
        'id': get_anon_id(user) if user else str(viewer_id),
        'telegram_id': viewer_id,
        'name': (user.get('first_name') or 'Пользователь') if user else 'Пользователь',
        'username': (user.get('username') or '') if user else '',
        'verified': bool(verify and verify.get('status') == 'verified'),
        'active_ads': active_count,
        'moderation_ads': moderation_count,
        'favorites': fav_count,
        'since': (user.get('registration_date') or '')[:10] if user else '',
        # Нужен фронту, чтобы увести пользователя в бота за видео:
        # Mini App не может открыть чат сама, только по ссылке t.me
        'bot_username': BOT_USERNAME,
    }})


async def api_miniapp_filters(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/filters — города и категории из активных объявлений + счётчики.

    Счётчики нужны Mini App, чтобы рисовать чипы быстрого выбора вида
    «Одежда 12» / «Ижевск 30». Сортировка по популярности, чтобы в начало
    попадало то, чего реально много.
    """
    try:
        cur = db.conn.cursor()
        cur.execute("""
            SELECT city, COUNT(*) AS n FROM ads
            WHERE status='active' AND city<>''
            GROUP BY city ORDER BY n DESC, city
        """)
        cities = [{'value': r['city'], 'label': r['city'], 'count': r['n']} for r in cur.fetchall()]
        cur.execute("""
            SELECT category, COUNT(*) AS n FROM ads
            WHERE status='active' AND category<>''
            GROUP BY category ORDER BY n DESC, category
        """)
        raw_cats = cur.fetchall()
    except Exception as e:
        logger.error(f"miniapp filters: {e}")
        return _miniapp_err('load_failed', 500)
    categories = [{'value': r['category'],
                   'label': _miniapp_display_category(r['category']),
                   'count': r['n']} for r in raw_cats]
    return _miniapp_json({'cities': cities, 'categories': categories})


async def api_miniapp_photo(request: aiohttp_web.Request) -> aiohttp_web.Response:
    """GET /api/photo/{file_id} — прокси фото объявлений.

    file_id резолвится сервером через Bot API и отдаётся байтами —
    токен бота во frontend НЕ утекает.
    """
    file_id = request.match_info.get('file_id', '')
    if not file_id or len(file_id) > 256:
        return _miniapp_err('not_found', 404)
    if file_id.startswith('{'):
        # MAX JSON-блок: отдаём прямую ссылку редиректом либо байты.
        try:
            resolved = await resolve_ad_photo(file_id)
        except Exception:
            return _miniapp_err('not_found', 404)
        if isinstance(resolved, str) and resolved.startswith('http'):
            raise aiohttp_web.HTTPFound(resolved)
        data = resolved.getvalue() if hasattr(resolved, 'getvalue') else resolved
        if not data:
            return _miniapp_err('not_found', 404)
        return aiohttp_web.Response(body=data, content_type=_media_content_type('', data),
                                    headers={**_miniapp_cors_headers(),
                                             'Cache-Control': 'public, max-age=86400'})
    bot = _miniapp_bot()
    if not bot:
        return _miniapp_err('bot_unavailable', 503)
    last_err = None
    for attempt in range(3):
        try:
            tg_file = await bot.get_file(file_id)
            # ВАЖНО: скачиваем средствами бота, а не отдельным aiohttp-запросом.
            # HTTPXRequest бота учитывает BOT_PROXY, а прямой запрос шёл без
            # прокси — при закрытом api.telegram.org фото не открывались
            # вообще (get_file проходил, а скачивание отдавало 404).
            data = bytes(await tg_file.download_as_bytearray())
            if data:
                return aiohttp_web.Response(
                    body=data,
                    content_type=_media_content_type('', data),
                    headers={**_miniapp_cors_headers(),
                             'Cache-Control': 'public, max-age=86400'},
                )
            last_err = 'пустой файл'
        except Exception as e:
            last_err = e
            logger.warning(f"miniapp photo attempt {attempt+1}: {e}")
            if attempt < 2:
                await asyncio.sleep(1 + attempt)
    logger.error(f"miniapp photo: не удалось отдать {file_id[:24]}… ({last_err})")
    try:
        import io as _io
        from PIL import Image as _PILImage, ImageDraw as _ImageDraw
        img = _PILImage.new('RGB', (400, 300), color=(30, 32, 40))
        draw = _ImageDraw.Draw(img)
        draw.text((200, 150), 'Фото недоступно', fill=(142, 142, 147), anchor='mm')
        buf = _io.BytesIO()
        img.save(buf, format='PNG')
        return aiohttp_web.Response(body=buf.getvalue(), content_type='image/png',
                                    headers={**_miniapp_cors_headers(),
                                             'Cache-Control': 'public, max-age=300'})
    except Exception:
        return _miniapp_err('not_found', 404)
    return aiohttp_web.Response(body=data, content_type=ctype,
                                headers={**_miniapp_cors_headers(),
                                         'Cache-Control': 'public, max-age=86400'})


def create_api_app() -> aiohttp_web.Application:
    # client_max_size: у aiohttp по умолчанию 1 МБ на ТЕЛО запроса, и это
    # молча ломало загрузку фото — любой снимок с телефона больше мегабайта
    # отбивался HTTPRequestEntityTooLarge, а обработчик отвечал bad_multipart.
    # Ставим лимит с запасом на 5 фото по 10 МБ плюс накладные расходы multipart.
    _max_body = MINIAPP_MAX_PHOTOS * MINIAPP_MAX_PHOTO_BYTES + 2 * 1024 * 1024
    app = aiohttp_web.Application(
        client_max_size=_max_body,
        middlewares=[_request_logging_middleware, _miniapp_cors_middleware],
    )
    app.router.add_get('/', api_root)
    app.router.add_get('/health', api_health)
    app.router.add_get('/api/views_diag', api_views_diag)
    app.router.add_get('/chat', api_serve_html)
    app.router.add_get('/api/check_promo', api_check_promo)
    app.router.add_options('/api/check_promo', api_check_promo)
    app.router.add_get('/api/chat/{session_id}', api_get_chat)
    app.router.add_get('/api/chat/{session_id}/poll', api_poll_messages)
    app.router.add_post('/api/chat/{session_id}/send', api_send_message)
    app.router.add_post('/api/chat/{session_id}/media', api_chat_media_upload)
    # ── Истории ──────────────────────────────────────────────────────────────
    app.router.add_get('/api/stories', api_miniapp_stories)
    app.router.add_post('/api/stories', api_miniapp_story_create)
    app.router.add_post('/api/stories/{story_id}/view', api_miniapp_story_view)
    app.router.add_delete('/api/stories/{story_id}', api_miniapp_story_delete)
    # ── Аукционы ─────────────────────────────────────────────────────────────
    # ── Агрегатор находок ────────────────────────────────────────────────────
    app.router.add_post('/api/ingest', api_ingest_findings)
    app.router.add_post('/api/ingest/status', api_ingest_status)
    app.router.add_get('/api/ingest/checklist', api_ingest_checklist)
    app.router.add_route('*', '/api/hunt', api_hunt_criteria)
    app.router.add_get('/api/findings/stats', api_findings_stats)
    app.router.add_get('/api/findings', api_miniapp_findings)
    app.router.add_get('/api/auctions', api_miniapp_auctions)
    app.router.add_get('/api/my-bids', api_miniapp_my_bids)
    app.router.add_get('/api/ads/{ad_id}/bids', api_miniapp_ad_bids)
    app.router.add_post('/api/ads/{ad_id}/bid', api_miniapp_place_bid)
    app.router.add_post('/api/ads/{ad_id}/buy-now', api_miniapp_buy_now)
    # ── Crypto Bot webhook ────────────────────────────────────────────────────
    app.router.add_post('/cryptobot/webhook', api_cryptobot_webhook)
    # Заглушка для paid_btn_url (пользователи после оплаты попадают сюда)
    app.router.add_get('/cryptobot/paid', api_cryptobot_paid_page)
    # ── PayAnyWay СБП webhook ─────────────────────────────────────────────────
    # PayAnyWay может слать уведомления как POST так и GET — регистрируем оба
    app.router.add_post('/api/payanyway', api_payanyway_webhook)
    app.router.add_get('/api/payanyway', api_payanyway_webhook)
    app.router.add_get('/api/payanyway/success', api_payanyway_success)
    app.router.add_get('/api/payanyway/fail', api_payanyway_fail)
    # ── MAX cross-post webhook ───────────────────────────────────────────────────
    app.router.add_post('/api/max-publish', api_max_publish_webhook)
    # ── Mini App Ads API (единая БД: ads/users/favorites) ────────────────────
    app.router.add_get('/api/ads', api_miniapp_ads_list)
    app.router.add_post('/api/ads', api_miniapp_ads_create)
