    async def _webapp_pay_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE):
        """Пользователь подтвердил покупку/продление — автоактивация."""
        query = update.callback_query
        await safe_answer(query, )
        context.user_data.pop('pending_payment', None)
        await query.message.reply_text(
            f"{EM_OK} Оплата обрабатывается. Подписка активируется <b>автоматически</b> после подтверждения транзакции.",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]])
        )

    async def _webapp_pay_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE):
        """Пользователь отменил оплату."""
        query = update.callback_query
        await safe_answer(query, )
        context.user_data.pop('pending_payment', None)
        await query.message.reply_text("Оплата отменена. Вы можете вернуться в меню.", reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton(EM_ARROW_L + " Меню", callback_data="back_to_menu")]
        ]))

    application.add_handler(CallbackQueryHandler(_webapp_pay_confirm,     pattern="^webapp_pay_confirm$"))
    application.add_handler(CallbackQueryHandler(_webapp_pay_cancel,      pattern="^webapp_pay_cancel$"))

